INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11461, 'plPL', 'DEPRECATED', '', '', '', '', '', '', '', '', 0),
(11559, 'plPL', 'Handel z Zimopłetwymi', 'Skoro już potrafisz rozmawiać z Zimopłetwymi, pora, żeby cię poznali. Jednym z najlepszych sposobów jest zrobienie z nimi interesu.$B$BMurloki cenią małże ponad wszystko inne, a ich jedynym ocalałym kupcem jest Ahlurglgr. Na twoim miejscu uzbierałbym garść małży Zimopłetwych i dał mu je w prezencie.$B$BMałże znajdziesz wszędzie na dnie rowu, a także po jego drugiej stronie, w wiosce Zimopłetwych i w ich pieczarach.', 'Zbierz 5 małży Zimopłetwych i dostarcz je Ahlurglgrowi w Ustroniu Zimopłetwych.', '', 'Wróć do Ahlurglgra w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11560, 'plPL', 'O nie, kijanki!', 'Dobrze, że już jesteś!$B$BKiedy osuwisko w wiosce po drugiej stronie wody odsłoniło pieczary, wyszedł z nich złowrogi homaroid zwany Claximusem i porwał kijanki Zimopłetwych.$B$BWszystkim murlokom, które poszły za nim do środka, coś się stało, a kiedy wyszły, były już pod jego władzą.$B$B$N, musisz przepłynąć na drugą stronę i uratować kijanki Zimopłetwych z wioski i pieczar.$B$BPrzyszłość plemienia Zimopłetwych zależy od ciebie!', 'Król Mrgl-Mrgl poprosił cię o uratowanie 20 kijanek Zimopłetwych. Gdy to zrobisz, wróć do niego do Ustronia Zimopłetwych.', '', 'Wróć do króla Mrgl-Mrgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', 'Uratowane kijanki Zimopłetwych', '', '', '', 0),
(11561, 'plPL', 'Oni!', 'Nasi bracia i siostry zza wody są teraz naszymi śmiertelnymi wrogami. Porwali nasze kijanki, wypędzili nas z wioski i zabili więcej naszych, niż potrafię zliczyć.$B$BUdowodnij, ile jesteś $gwart:warta;, $N! Przepłyń przez rozpadlinę i wybij ich!$B$BMimo przychylności, jaką okazał ci nowy król, dopiero wtedy zastanowimy się, czy cię tu przyjąć. Jeśli zawiedziesz, równie dobrze możesz odejść od razu i nigdy nie wracać!', 'Brglmurgl z Ustronia Zimopłetwych poprosił cię o zabicie 15 murloków Zimopłetwych. Mogą to być dowolni wojownicy, wyrocznie i brzegowi napastnicy.', '', 'Wróć do Brglmurgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', 'Zabite murloki Zimopłetwych', '', '', '', 0),
(11562, 'plPL', 'Szantażuje mnie mój sprzątacz', 'Muszę wyznać coś wstydliwego: ktoś mnie szantażuje!$B$BMrmrglmr zgodził się wyczyścić kilka moich rzeczy i dostał w swoje łapy mój zapasowy strój murloka. Grozi, że wyjawi innym murlokom, kim naprawdę jestem.$B$BNie muszę ci tłumaczyć, jaka byłaby to katastrofa! Poza tym mam plan, do którego ten strój będzie nam potrzebny.$B$BProszę cię, $N, idź do Mrmrglmra na drugim, północnym końcu Ustronia i zrób wszystko, czego od ciebie zażąda.', 'Król Mrgl-Mrgl poprosił cię, żebyś $gporozmawiał:porozmawiała; z Mrmrglmrem w północno-zachodniej części Ustronia Zimopłetwych.', '', '', '', '', '', '', 0),
(11563, 'plPL', 'Grmmurggll Mrllggrl Glrggl!!!', 'Gdyby twoje żałosne oczka na coś się zdały, $gzobaczyłbyś:zobaczyłabyś;, że orki z zatoki na północy wyrzynają nas w pień!$B$BSkoro twój ukochany król nocny elf chce odzyskać zapasowy strój, to chyba wyświadczysz mi przysługę i przyniesiesz głowę króla orek, Glrggla: tego, który płynie pod prąd przeznaczenia, niweczącego nadzieję na życie wszystkich, którzy usłyszą syreni śpiew śmierci nad falami!$B$BPośpiesz się, murloki Zimopłetwych giną, nawet teraz, gdy tracimy czas na gadanie!', 'Mrmrglmr chce, żebyś $gwrócił:wróciła; do niego do Ustronia Zimopłetwych z głową Glrggla.', '', 'Wróć do Mrmrglmra w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11564, 'plPL', 'Soczysty gulasz z orki', 'Podobno, $N, wybierasz się na króla orek, Glrggla.$B$BWszystko pięknie, ale jeśli chcesz skosztować gulaszu, dla którego warto żyć, przynieś mi soczysty tłuszcz orek pływających w Zatoce Połysku.$B$BPośpiesz się... mam przy tym truchle sporo krojenia, a chyba chcesz zebrać owoce swoich trudów.', 'Tasak Bmurglbrm zlecił ci zdobycie 7 porcji soczystego tłuszczu orki. Wróć z nimi do niego do Ustronia Zimopłetwych.', '', 'Wróć do Tasaka Bmurglbrma w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11565, 'plPL', 'Zapasowy strój', 'No dobrze, sekret twojego króla jest u mnie bezpieczny, dopóki będzie nam pomagał przeciw naszym wrogom.$B$BMasz, zanieś mu to. Ładnie to wyczyściłem, choć nie mam pojęcia, po co mu drugie przebranie.$B$BMoże ma wobec ciebie jakieś plany?', 'Zwróć królowi Mrgl-Mrglowi jego zapasowy strój w Ustroniu Zimopłetwych.', '', 'Wróć do króla Mrgl-Mrgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11566, 'plPL', 'Poddaję się... akurat!', 'Pora położyć kres tej nienaturalnej sytuacji, $N. Żeby murloki Zimopłetwych miały jakąkolwiek przyszłość, Claximus musi zginąć!$B$BWeź mój zapasowy strój murloka i wejdź do Pieczar Zimopłetwych pod pozorem kapitulacji. Z białą flagą w ręku murloki cię nie zaatakują.$B$BZnajdziesz go w najdalszym południowo-zachodnim zakątku pieczar. Gdy podejdziesz dość blisko, rozpraw się z Claximusem. Przynieś mi jego szczypce na dowód, że ten ponury czyn został dokonany.', 'Król Mrgl-Mrgl z Ustronia Zimopłetwych poprosił cię o przyniesienie szczypiec Claximusa.', '', 'Wróć do króla Mrgl-Mrgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11569, 'plPL', 'Klucznik Urmgrgl', 'Muszę się wydostać z tych pieczar! Z Mrozarry nad nami sączy się tu jakaś magia i miesza wszystkim w głowach.$B$BNie zamierzam dać się kontrolować jak ci tutaj!$B$BKlucznik Urmgrgl jest w jaskini niżej, na południe stąd. Ma klucz do mojej klatki. Odbierz mu go i przynieś tutaj, żebym mógł otworzyć klatkę i się stąd wydostać.$B$BPośpiesz się!', 'Glrglrglr w Pieczarach Zimopłetwych poprosił cię o zdobycie klucza Urmgrgla.', '', 'Wróć do Glrglrglra w Pieczarach Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11570, 'plPL', 'Ucieczka z Pieczar Zimopłetwych', 'Zamek w mojej klatce nie wygląda na zbyt solidny, ale nie jestem na tyle głupi, żeby próbować uciekać bez pomocy.$B$BPomożesz mi bezpiecznie wydostać się z tych pieczar? Nie ma czasu do stracenia.$B$BKiedy wrócisz do Ustronia, daj znać królowi, że nic mi nie jest. Na pewno cię wynagrodzi.', 'Odprowadź Lurgglbra w bezpieczne miejsce, a potem przekaż dobre wieści królowi Mrgl-Mrglowi w Ustroniu Zimopłetwych.', 'Odprowadź Lurgglbra w bezpieczne miejsce', 'Wróć do króla Mrgl-Mrgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11571, 'plPL', 'Nauka porozumiewania się', 'Żeby pomóc, musisz nauczyć się mówić w narzeczu Zimopłetwych. Osiągniemy to dzięki siłom natury i magii.$B$BWeź tę pustą muszlę. Na dnie podwodnego rowu poniżej żyje Parząca, żywiołak powietrza i wodnej furii.$B$BGdy ją pokonasz, użyj muszli na jej szczątkach, żeby schwytać jej magiczną parę. Przynieś mi pełną konchę, a przeleję w ciebie moją znajomość języka Zimopłetwych.$B$BNa szczęście pewien przyjaciel nauczył mnie zaklęcia oddychania pod wodą. Rzucę je na ciebie.', 'Król Mrgl-Mrgl dał ci konchę, której masz użyć na szczątkach Parzącej. Zanieś mu napełnioną konchę króla do Ustronia Zimopłetwych.', '', 'Wróć do króla Mrgl-Mrgla w Ustroniu Zimopłetwych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11574, 'plPL', 'O włos od zguby', 'Powiedziałam im wszystko, co pamiętam. Dlaczego mi nie wierzą?$b$bZbierałam zioła przy rozpadlinie. Pojawili się znikąd, mroczni czarodzieje z magicznymi bestiami – zostałam otoczona!$b$bNade mną pojawiła się magiczna skrzynia, otworzyła się i wciągnęła mnie do środka. Kiedy zaczęła się już wokół mnie zamykać, na grzbietach czerwonych smokowców nadlecieli moi wybawcy. Aż zapierało dech!$b$bNigdy im nie podziękowałam za ratunek. Proszę, odszukaj ich i przekaż im moją wdzięczność.', 'Endorah chce, żebyś $gudał:udała; się na Bursztynowy Występ na północ od Warowni Wojennej Pieśni i $gpodziękował:podziękowała; tamtejszym za jej ocalenie.', '', '', '', '', '', '', 0),
(11575, 'plPL', 'W ostatniej chwili', 'Powiedziałam im wszystko, co pamiętam. Dlaczego mi nie wierzą?$b$bZbierałam zioła przy rozpadlinie. Pojawili się znikąd, mroczni czarodzieje z magicznymi bestiami. Zostałam otoczona!$b$bNade mną pojawił się ogromny magiczny sześcian. Otworzył się i wciągnął mnie do środka. Przysięgam, że to prawda!$b$bKiedy zaczął się już wokół mnie zamykać, na grzbietach smokowców nadlecieli moi wybawcy – to było niesamowite! Moi porywacze się rozpierzchli, a ja zdołałam uciec.$b$bNigdy im nie podziękowałam za ratunek. Proszę, jeśli ich spotkasz, przekaż im moją wdzięczność.', 'Midge z Twierdzy Walecznych chce, żebyś $gudał:udała; się na Bursztynowy Występ na północy i $gpodziękował:podziękowała; tamtejszym za jej ocalenie.', '', '', '', '', '', '', 0),
(11576, 'plPL', 'Obserwacja rozpadliny: Anomalia Rozłupanego Klifu', 'Witaj. Jestem Garren z Dalaranu.$b$bJeszcze niedawno rozpadlina była spokojnym miejscem – przynajmniej pod względem geotermalnym.$b$bOstatnio jednak z niepokojącą częstotliwością występują trzęsienia ziemi, a w gruncie pojawiły się blizny, które odsłaniają niezwykłe pola energii chaotycznej mocy.$b$bMoim zadaniem jest nanoszenie tych anomalii na mapy i ich obserwacja. Moje przyrządy wskazują, że kolejna pojawiła się na urwisku na południowym zachodzie.$b$bWeź ze sobą to urządzenie i użyj go, gdy znajdziesz nowe zaburzenie.', 'Garren z Bursztynowego Występu chce, żebyś $gużył:użyła; arkanometru przy Anomalii Rozłupanego Klifu.', '', 'Wróć do bibliotekarza Garrena na Bursztynowym Występie w Boreańskiej Tundrze.', 'Pomiar Anomalii Rozłupanego Klifu wykonany', '', '', '', 0),
(11582, 'plPL', 'Obserwacja rozpadliny: Rozdarta Przepaść', 'Czujesz to?! To był tylko wstrząs wtórny... szkoda, że nie było cię tu kilka minut temu!$b$bObawiam się, że znów muszę skorzystać z twoich usług. Moje przyrządy wskazują ogromne zaburzenie tuż na zachód stąd, głęboko pod powierzchnią wody.$b$bTak jak poprzednio, weź arkanometr i zbierz dane o anomalii.$b$bRzucę zaklęcie, dzięki któremu będziesz $gmógł:mogła; oddychać pod wodą. Jeśli przestanie działać, zanim ją znajdziesz, przyjdź do mnie, a odnowię je.', 'Garren z Bursztynowego Występu chce, żebyś $gużył:użyła; arkanometru przy anomalii w Rozdartej Przepaści i $gwrócił:wróciła; do niego z odczytami.', '', 'Wróć do bibliotekarza Garrena na Bursztynowym Występie w Boreańskiej Tundrze.', 'Pomiar w Rozdartej Przepaści wykonany', '', '', '', 0),
(11585, 'plPL', 'Czuwanie Piekłorycza', 'Throm-ka, $N! Witaj w Warowni Wojennej Pieśni. Serce rośnie mi z dumy, gdy widzę, że tak zasłużony bohater Hordy odpowiedział na wezwanie!$B$BTa nie do zdobycia forteca jest świadectwem nieustępliwości Hordy. Stoczyliśmy wiele walk, by zdobyć ten przyczółek w Północnej Grani. To stąd zaczyna się nasza droga do Lodowej Korony i to pod przywództwem syna Piekłorycza odniesiemy zwycięstwo!$B$BGarosz czeka na ciebie na dole.$B$BLok\'tar ogar!', 'Porozmawiaj z Garoszem Piekłoryczem w Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11586, 'plPL', 'Czuwanie Piekłorycza', 'Throm-ka, $N! Witaj w Warowni Wojennej Pieśni. Serce rośnie mi z dumy, gdy widzę, że tak zasłużony bohater Hordy odpowiedział na wezwanie!$B$BTa nie do zdobycia forteca jest świadectwem nieustępliwości Hordy. Stoczyliśmy wiele walk, by zdobyć ten przyczółek w Północnej Grani. To stąd zaczyna się nasza droga do Lodowej Korony i to pod przywództwem syna Piekłorycza odniesiemy zwycięstwo!$B$BGarosz czeka na ciebie na dole.$B$BLok\'tar ogar!', 'Porozmawiaj z Garoszem Piekłoryczem w Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11587, 'plPL', 'Ucieczka z więzienia', 'Witaj. Jestem Donathan, wierny przedstawiciel Dalaranu.$b$bWybacz mi obcesowość, ale jesteśmy w samym środku kryzysu. W całym Azeroth porywani są magowie, a ja mam upoważnienie, by wcielić do służby każdego, kto może pomóc w rozwikłaniu tej zagadki.$b$bNasze śledztwo zaczyna się w obozie tuż na południe od naszego. Wzywam cię, byś $guwolnił:uwolniła; jednego z przetrzymywanych tam magów. Musisz zdobyć klucz od któregoś z łowców magów i otworzyć nim tajemne więzienie.', 'Bibliotekarz Donathan z Bursztynowego Występu chce, żebyś $godebrał:odebrała; klucz do więzienia Berylu jednemu z łowców magów z Berylu na Cyplu Berylu i $guwolnił:uwolniła; nim uwięzionego maga z tajemnego więzienia.', '', 'Wróć do bibliotekarza Donathana na Bursztynowym Występie w Boreańskiej Tundrze.', 'Uratowani tajemni więźniowie', '', '', '', 0),
(11590, 'plPL', 'Porwanie', '$n, mamy problem.$b$bWłaśnie się dowiedziałem, że zaginęła jedna z naszych arcymagiń, która była w drodze z Dalaranu. Oczywiście podejrzewamy, że za jej zniknięciem stoją łowcy magów.$b$bCzas najwyraźniej nagli. Musimy natychmiast się dowiedzieć, co się stało z lady Evanor, jeśli mamy mieć jakąkolwiek nadzieję na jej ratunek.$b$bWeź to urządzenie. Wróć na Cypel Berylu i użyj go na czarowniku z Berylu, gdy będzie bliski śmierci. Powinno go spętać na tyle długo, żebyś $gzdążył:zdążyła; go tu przyprowadzić na przesłuchanie.', 'Donathan chce, żebyś $gużył:użyła; tajemnego wiązacza na rannym czarowniku z Berylu na Cyplu Berylu i $gwrócił:wróciła; z nim na Bursztynowy Występ.', '', 'Wróć do bibliotekarza Donathana na Bursztynowym Występie w Boreańskiej Tundrze.', 'Schwytany czarownik z Berylu', '', '', '', 0),
(11591, 'plPL', 'Zgłoś się do Karawany Steeljawa', 'Ten tępy kundel Steeljaw próbował poprowadzić naszą karawanę z zaopatrzeniem na skróty przez cmentarz taunka!$B$BA dopiero co nawiązaliśmy z nimi stosunki!$B$BTeraz karawana leży w gruzach, opanowana przez duchy taunka, które powstały z grobów, gdy je tratował.$B$BRuszaj na południe i zobacz, czy da się jeszcze coś uratować, $N. Wysłałem tam z nim siepaczkę Gniewopięść i kilku innych do pomocy.$B$BMoże i ty pomożesz?', 'Porozmawiaj z siepaczką Gniewopięść przy Karawanie Steeljawa.', '', '', '', '', '', '', 0),
(11592, 'plPL', 'Uderzamy!', 'Jeden z waszych orków, niejaki Steeljaw, chciał oszczędzić trochę czasu i poszedł na skróty przez nasze cmentarzysko. Lepiej, żeby wasza Horda nie zachowywała się tak na co dzień, bo taunka staną się waszą zgubą!$B$BAle wyglądasz na kogoś, kto chce naprawić tę sytuację. Dobrze!$B$BPrzeklęty duch Steeljawa nawiedza teraz to miejsce i niepokoi szczątki moich przodków. Musimy z nim skończyć!$B$BJeśli przeżyjemy, powiedz o tym waszemu nadrządcy Bor\'gorokowi na posterunku na północy.$B$BJesteś ze mną?', 'Pomóż biegaczowi Dumne Kopyto i jego łupieżcom z Wojennej Pieśni przetrwać natarcie na Karawanę Steeljawa i dobij ducha dowódcy sił Steeljawa.$B$BJeśli ci się uda, zgłoś się do nadrządcy Bor\'goroka na Posterunku Bor\'gorok.', 'Udało się wesprzeć natarcie biegacza Dumne Kopyto.', 'Wróć do nadrządcy Bor\'goroka na Posterunku Bor\'gorok w Boreańskiej Tundrze.', '', '', '', '', 0),
(11593, 'plPL', 'Czcigodni polegli', 'Nasi polegli zasługują na pogrzeb bohaterów, ale nie możemy ich chować tutaj, na świętej ziemi taunka.$B$BNie będę cię prosić, żebyś $gciągnął:ciągnęła; tu ich ciała, ale weź to i idź dalej w głąb cmentarza. Kiedy natkniesz się na naszych martwych strażników i robotników karawany, spal ich.$B$BOddaj cześć naszym poległym, $N!', 'Siepaczka Gniewopięść przy Karawanie Steeljawa poprosiła cię, żebyś $gużył:użyła; pochodni Gniewopięści do spalenia łącznie 10 martwych strażników i robotników karawany.', '', 'Wróć do siepaczki Gniewopięść przy Karawanie Steeljawa w Boreańskiej Tundrze.', 'Spaleni polegli strażnicy i robotnicy karawany', '', '', '', 0),
(11594, 'plPL', 'Daj im spoczynek', 'Przez głupotę dowódcy sił Steeljawa narobił się ten bałagan. Co on sobie myślał, prowadząc karawanę przez kurhan taunka?$B$BCo się stało, to się nie odstanie. Teraz to my musimy uporać się ze skutkami.$B$BNadrządca Bor\'gorok poprosił mnie, żebym pomogła biegaczowi Dumne Kopyto, jak tylko mogę. Biegacz poprosił, żebyśmy dali spoczynek duchom jego przodków.$B$BCo ty na to? Czy jesteś $gdość twardy:dość silna;, by poradzić sobie z tak prostym zadaniem?', 'Daj spoczynek 20 duchom taunka – upiornym mędrcom lub powstałym biegaczom – a potem zgłoś się do siepaczki Gniewopięść przy Karawanie Steeljawa.', '', 'Wróć do siepaczki Gniewopięść przy Karawanie Steeljawa w Boreańskiej Tundrze.', 'Duchy taunka, którym dano spoczynek', '', '', '', 0),
(11595, 'plPL', 'Obrona Warowni Wojennej Pieśni', 'Piekłorycz dźwiga na barkach ciężar całej Hordy. Nie pozwól, by jego temperament odwiódł cię od twoich obowiązków, $N.$B$B<Zaurzykieł kiwa głową.>$B$BCzy myślisz, że zapomniałbym imię bohatera Orgrimmaru? Nie co dzień mam przyjemność nabijać głowę Nefariana na pal!$B$BPlaga rozpoczęła natarcie na tę fortecę. Nasi żołnierze trzymają linię, ale rozpaczliwie potrzebują wsparcia. Zgłoś się do Razgora. Stacjonuje tuż przed Warownią Wojennej Pieśni.', 'Zgłoś się do nadrządcy Razgora w chacie po południowej stronie Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11596, 'plPL', 'Obrona Warowni Wojennej Pieśni', 'Nie pozwól, by Piekłorycz odwiódł cię od twoich obowiązków żołnierza Hordy, $N. Dźwiga straszliwe brzemię na tych zamarzniętych pustkowiach: od wyniku jego natarcia zależy zwycięstwo nad Plagą albo zagłada wszelkiego życia w Azeroth. Właśnie dlatego potrzebujemy twojej siły i mądrości.$B$BPlaga rozpoczęła natarcie na tę fortecę. Nasi żołnierze trzymają linię, ale rozpaczliwie potrzebują wsparcia. Zgłoś się do Razgora. Stacjonuje tuż przed Warownią Wojennej Pieśni.', 'Zgłoś się do nadrządcy Razgora w chacie po południowej stronie Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11597, 'plPL', 'Obrona Warowni Wojennej Pieśni', 'Wygląda na to, że zawsze spotykamy się w najgorszych okolicznościach, $gWładco:Władczyni; Skarabeusza. Czy przy naszym ostatnim spotkaniu nie $gratowałeś:ratowałaś; przypadkiem świata przed pewną zagładą?$B$B<Zaurzykieł chichocze.>$B$BTwoja pomoc jest w Północnej Grani bardzo mile widziana, cokolwiek powie młody wódz.$B$BGdybyśmy mieli choć tuzin żołnierzy o twojej potędze, siedzielibyśmy teraz w Orgrimmarze, pochyleni nad ciepłym ogniskiem.$B$BZgłoś się do nadrządcy Razgora, tuż przed głównym wejściem do Warowni Wojennej Pieśni, od południa.', 'Zgłoś się do nadrządcy Razgora w chacie po południowej stronie Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11598, 'plPL', 'Odbicie Kamieniołomu Kamienia Mocy', 'Warownię Wojennej Pieśni ze wszystkich stron chronią trzy metry stali i kamienia, ale ten kamieniołom jest miękki i aż się prosi o atak nerubian.$B$B<Razgor wskazuje na zachód.>$B$BZa tym kamieniołomem stoją tysiące żołnierzy Plagi i czekają na rozkaz do ataku. Jeśli nerubianie przełamią naszą wewnętrzną obronę, zaleją nas nieumarłe legiony Arthasa.$B$BNie możemy do tego dopuścić – dlatego przejdziesz do natarcia i wyrżniesz nerubian w kamieniołomie.$B$BNa krew i grom, żołnierzu! Zabierz ze sobą jedno i drugie.', 'Nadrządca Razgor z Warowni Wojennej Pieśni chce, żebyś $gzabił:zabiła; 15 nerubian Nerub\'ar.', '', 'Wróć do nadrządcy Razgora w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', 'Zabici nerubianie Nerub\'ar', '', '', '', 0),
(11599, 'plPL', 'Thassarian, mój brat', 'Niedawno dostałam wiadomość od Williama Allertona, przyjaciela rodziny, że mój brat zaciągnął się tutaj, w Twierdzy Walecznych, tego samego dnia co on. Rzecz w tym... że mój brat nie żyje od lat.$B$BSprzedałam wszystko, co miałam, żeby przyjechać i szukać Thassariana, a tutejsi urzędnicy zbywają mnie na każdym kroku. Grozili mi nawet aresztem, jeśli nie przestanę węszyć.$B$BPotrzebuję kogoś, kto ma dobre układy u przełożonych... kogoś takiego jak ty. Jeśli możesz mi pomóc, słyszałam, że William stacjonuje w kopalni w Dalekich Włościach.', 'Poszukaj Williama Allertona w kopalni w Dalekich Włościach.', '', '', '', '', '', '', 0),
(11600, 'plPL', 'Świętej pamięci William Allerton', 'Gardło Williama zostało przecięte czymś ostrym.$B$BDokładniejsze oględziny ujawniają tylko jeden trop, który można zanieść Leryssie – kartę werbunkową z nazwiskiem Williama Allertona.', 'Zanieś kartę werbunkową Leryssie w Twierdzy Walecznych w Boreańskiej Tundrze.', '', 'Wróć do Leryssy w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11601, 'plPL', 'Zgubione, znalezione', 'Biedny pan Allerton może jeszcze pomóc nam odnaleźć mojego brata.$B$B<Leryssa odsłania opasłą księgę, przypominającą wojskowy rejestr rekrutów.>$B$BPożyczyłam ją, jasne? Zobaczmy, czy na tej karcie werbunkowej jest data?$B$BWilliam widział Thassariana w kolejce do werbunku. Ich wpisy muszą być blisko siebie... jest!$B$BPrzydzielono go do... Oddziału S? Wszystkie inne oddziały wojskowe noszą nazwy miast Przymierza.$B$BKto jest w tym oddziale? Gdzie ich rozmieszczono? Potrzebujemy plotek. Sprawdź, czy karczmarz coś słyszał.', 'Porozmawiaj z Jamesem Deaconem w karczmie w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11602, 'plPL', 'Odcięcie źródła', 'Zwiad powietrzny nad kamieniołomem donosi, że nerubianie składają jaja na rusztowaniach wokół podstawy. Sprytne z nich bestie... Trzymają jaja wysoko i sucho, z dala od centrum walk.$B$BBędziesz $gmusiał:musiała; wrócić tam i wytropić ich jaja. Znajdź je, rozbij i zniszcz.$B$BKażde zniszczone jajo to dwudziestu nerubian mniej, którzy mogliby żerować na naszych trupach.$B', 'Nadrządca Razgor z Warowni Wojennej Pieśni chce, żebyś $gzniszczył:zniszczyła; 10 worków jaj Nerub\'ar.', '', 'Wróć do nadrządcy Razgora w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', 'Zniszczone worki jaj Nerub\'ar', 0),
(11603, 'plPL', 'Prawda w winie', 'Wojsko było dla starego Colburna wszystkim. Po przejściu na emeryturę wciąż trzymał się go jak koła ratunkowego.$B$BZna nazwę każdego generała, oddziału, brygady, pododdziału... co tylko chcesz. To człowiek, którego potrzebujesz.$B$BKłopot w tym, że ma zranioną duszę. Nie porozmawia z nikim, dopóki nie dostanie wina z Kul Tiras. Przypomina mu czasy, kiedy służył w piechocie morskiej.$B$BOd miesięcy nie dostałem żadnej dostawy. Ostatni statek handlowy z Kul Tiras zatonął na północny wschód stąd. Zobacz, czy uda ci się wyłowić butelkę dla Colburna.', 'Wyłów butelkę wina z Kul Tiras z zatopionego wraku na północny wschód od Twierdzy Walecznych i zanieś ją staremu Colburnowi w karczmie w Twierdzy Walecznych.', '', 'Wróć do starego Colburna w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11604, 'plPL', 'Dezerter', 'Oddział S... Oddział S... hmmmf... bez sensu... powinien nosić nazwę jakiegoś miasta...$B$BOddział Mrocznych Włości posłano na Smocze Pustkowia. Chłopaków z oddziału Złotych Włości – do Fiordu. Gdzie ja to słyszałem...$B$BA, tak... dezerter! W areszcie przy koszarach siedzi taki jeden tchórz. Wsadzili go tam niedawno. Ciągle powtarzał, że „S” to skrót od „samobójczy”.$B$BPoszukaj dezertera. Może mieć dla ciebie jakieś informacje.', 'Znajdź areszt w Wewnętrznej Warowni w Twierdzy Walecznych i porozmawiaj z dezerterem.', '', '', '', '', '', '', 0),
(11605, 'plPL', 'Czcigodni przodkowie', '<Gdy przyglądasz się kamiennemu posągowi, w twojej głowie rozbrzmiewa odległy głos.>$B$BNie lękaj się, $gnieznajomy:nieznajoma;. Jestem starszy Atkanok, dawny przodek ludu kiełzarów, za życia wprawny rzemieślnik, a od stuleci strażnik tego kamieniołomu.$B$BKamieniołom został opanowany, wiele posągów zostało niedokończonych, a duchy przodków błąkają się po świecie. Pomożesz mi naprawić tę krzywdę?$B$BNajpierw muszę poznać imiona tych błąkających się przodków. Szukaj tablic przy ich posągach.', 'Starszy Atkanok przed Kamieniołomem Zimnej Skały chce, żebyś $gustalił:ustaliła;, do kogo należą posągi starszego Kesuka, starszego Saganiego i starszego Takreta.', '', 'Wróć do starszego Atkanoka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', 'Rozpoznano starszego Kesuka', 'Rozpoznano starszego Saganiego', 'Rozpoznano starszego Takreta', '', 0),
(11606, 'plPL', 'Cierpliwość to cnota, której nie potrzebujemy', 'Możemy zabić wszystkich nerubian, jakich zobaczymy, i zniszczyć wszystkie jaja, jakie znajdziemy, ale te stwory nie przestaną nadciągać, dopóki nie wysadzimy ich tuneli i przejść. Oczywiście nie zrobimy tego bez ciężkiej amunicji. Niestety, większość naszych zapasów zużywają gobliny i kowale na nasze czołgi oblężnicze i uzbrojenie.$B$BTak się składa, że całkiem spory zapas tego towaru mamy w Kamieniołomie Kamienia Mocy – pod całym tym nerubiańskim świństwem. Musisz tylko pójść i mi go przynieść.', 'Kwatermistrz Holgoth z Warowni Wojennej Pieśni chce, żebyś $godzyskał:odzyskała; 15 skrzyń amunicji Wojennej Pieśni.', '', 'Wróć do kwatermistrza Holgotha w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11607, 'plPL', 'Zagubione duchy', 'Podczas napaści na kamieniołom zginęli pracujący tu szamani i rzemieślnicy. Ta przemoc pogrążyła świat duchów w kompletnym chaosie i nie zdołamy poprowadzić przodków do domu, jeśli nie znajdziemy sposobu, by ukoić duchy zamordowanych.$B$BSami napastnicy nie zwracają na duchy uwagi, ale ich towarzysze, ogary z Berylu, wyczuwają duchy i trzymają je w niewoli.$B$BZabijaj ogary z Berylu, a pozostałą po nich surową energią skrusz więzy duchów niewinnych.', 'Starszy Atkanok z obrzeży Kamieniołomu Zimnej Skały chce, żebyś $guwolnił:uwolniła; duchy 3 rzemieślników z Kaskali i 3 szamanów z Kaskali.', '', 'Wróć do starszego Atkanoka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', 'Uwolnione duchy rzemieślników z Kaskali', 'Uwolnione duchy szamanów z Kaskali', '', '', 0),
(11608, 'plPL', 'Zakopać te karaluchy!', 'Północ, południe, wschód i zachód. Tymi kierunkami masz się przejmować. Wokół tej fortecy, w Kamieniołomie Kamienia Mocy, leżą cztery doskonale rozmieszczone zapadliska Nerub\'ar.$B$B<Holgoth wręcza ci wiązkę.>$B$BBardzo uważaj z tą paczką, $N. Jeden nieostrożny ruch i będzie z ciebie psia karma.$B$BW wiązce są bomby głębinowe z seaforium. Dotrzyj do każdego z zapadlisk Nerub\'ar i podłóż bombę w samym jego środku. Jeśli wszystko pójdzie dobrze, tunele się zawalą.$B$BRuszaj się!', 'Kwatermistrz Holgoth z Warowni Wojennej Pieśni chce, żebyś $gużył:użyła; wiązki bomb głębinowych z seaforium do zniszczenia zapadlisk Nerub\'ar na południe, wschód, zachód i północ od Warowni Wojennej Pieśni.', '', 'Wróć do kwatermistrza Holgotha w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', 'Zniszczono południowe zapadlisko Nerub\'ar', 'Zniszczono wschodnie zapadlisko Nerub\'ar', 'Zniszczono zachodnie zapadlisko Nerub\'ar', 'Zniszczono północne zapadlisko Nerub\'ar', 0),
(11609, 'plPL', 'Zbieranie kawałków', 'Skoro duchy zamordowanych rzemieślników i szamanów zaznały spokoju, możemy dokończyć obrzędy przerwane przez napaść. Musisz odegrać rolę zwykle zastrzeżoną dla szamana kiełzarów i musisz mieć wszystkie potrzebne przedmioty rytualne.$B$BNie ma czasu na wykonanie nowych, więc musisz przeszukać kamieniołom i odnaleźć te, które zostawiły ofiary napaści. Obchodź się z nimi ostrożnie, $N, bo niektóre mają po kilkaset lat. Być może trzeba będzie wyrwać je z rąk najeźdźców.', 'Zanieś 6 rytualnych przedmiotów kiełzarów starszemu Atkanokowi, który stoi przed Kamieniołomem Zimnej Skały.', '', 'Wróć do starszego Atkanoka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', '', '', '', '', 0),
(11610, 'plPL', 'Prowadzenie przodków do domu', 'Dzięki twojej pomocy duchy przodków mogą teraz zostać zaprowadzone do swoich prawowitych domów – posągów pieczołowicie przygotowanych przez rzemieślników i szamanów z Kaskali.$B$BObrzędy tych przodków zostały przerwane podczas napaści na kamieniołom i to ty musisz je dokończyć. Weź ze sobą przedmioty odzyskane z kamieniołomu, stań przed posągami z tablicami z imionami i wyrecytuj tę pieśń.$B$B<Słowa w obcym języku zalewają twój umysł, ale bez trudu je sobie przypominasz.>', 'Starszy Atkanok chce, żebyś $gzaprowadził:zaprowadziła; duchy starszego Kesuka, starszego Saganiego i starszego Takreta do ich kamiennych pomników.', '', 'Wróć do starszego Atkanoka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', 'Obrzęd starszego Kesuka dokończony', 'Obrzęd starszego Saganiego dokończony', 'Obrzęd starszego Takreta dokończony', '', 0),
(11611, 'plPL', 'Porwani przez Plagę', '<Mortuus wzdycha.>$B$BPeoni... Równie dobrze moglibyśmy wywiesić tabliczkę z darmowym posiłkiem dla Nerub\'ar.$B$BWidzisz, z peonami jest taki problem, że: po pierwsze, są głupsi od błota; a po drugie, są słabsi od trędowatego gnoma. Nic dziwnego, że Plaga porywa ich pierwszych!$B$BStawia mnie to w dość kłopotliwym położeniu, rozumiesz. Bez peonów praca fizyczna staje. Nie ma peonów, nie ma budowy.$B$BZnajdź i uwolnij moich peonów. Jeśli żyją, znajdziesz ich w kokonach z pajęczyny w całym Kamieniołomie Kamienia Mocy.$B', 'Brygadzista Mortuus z Warowni Wojennej Pieśni chce, żebyś $guwolnił:uwolniła; 5 peonów Wojennej Pieśni.', '', 'Wróć do brygadzisty Mortuusa w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', 'Uwolnieni peoni Wojennej Pieśni', '', '', '', 0),
(11612, 'plPL', 'Odzyskanie kamieniołomu', 'Dobrze cię widzieć. Nazywam się Etaruk i byłem rzemieślnikiem tu, w Kamieniołomie Zimnej Skały.$B$BRazem z towarzyszami przygotowywaliśmy nowy zestaw posągów do ostatnich obrzędów, kiedy zobaczyliśmy te tajemnicze błękitne platformy nadlatujące nad płaskowyżem.$B$BGdy wylądowały, przywiezieni nimi magowie opanowali kamieniołom, mordując moich towarzyszy i łupiąc wszystko. Jeśli ich nie powstrzymamy, zniszczą nasze posągi i uciekną z naszymi artefaktami. Pomożesz mi pokonać najeźdźców?', 'Etaruk, obozujący przy wejściu do Kamieniołomu Zimnej Skały, chce, żebyś $gzabił:zabiła; 12 poszukiwaczy skarbów z Berylu.', '', 'Wróć do Etaruka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', '', '', '', '', 0),
(11613, 'plPL', 'Przysięga Karuka', 'Nazywają siebie kvaldirami. Mój lud ma o nich legendy; nazywamy ich tuk-hariq – wędrowcami mgły.$B$BMoją wioskę zniszczyli ci olbrzymi ludzie mgły. Zginęli wszyscy, których znałem, także mój ojciec Ariut.$B$BWedług prawa kiełzarów muszę szukać odwetu na tych, którzy przelali krew moich bliskich.$B$BJestem tylko rybakiem i nie przeszedłem jeszcze próby męskości... Nie mogę stanąć twarzą w twarz z nikczemnymi kvaldirami.$B$BJeśli wypełnisz za mnie mój krwawy obowiązek, będę twoim wielkim dłużnikiem.', 'Karuk chce, żebyś $gzabił:zabiła; 6 łupieżców Skadirów i 5 wioślarzy Skadirów.', '', 'Wróć do Karuka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11614, 'plPL', 'Przemilczane prawdy', 'Jesteśmy tu z rozkazu Varimathrasa! Misja skrytotropicieli jest prosta: szpiegować. No, szpiegować, a przy okazji trochę mordować.$B$BZaginął jeden z moich najlepszych agentów terenowych. Od kilku dni nie mam od niego wieści, więc obawiam się najgorszego. Nie, nie śmierci! Śmierć byłaby idealna. Boję się, że wymknął się spod kontroli... może nawet stał się zdrajcą.$B$BOstatnio widziano go w północnej części Kamieniołomu Kamienia Mocy. Zbierał informacje o nerubianach. Znajdź go.$B$BOby nie żył...', 'Odnajdź skrytotropiciela Luthera w Kamieniołomie Kamienia Mocy.', '', '', '', '', '', '', 0),
(11615, 'plPL', 'Tajemnice Nerub\'ar', 'Przeglądasz stronice księgi w poszukiwaniu czegoś ważnego. Na ostatniej stronie odkrywasz coś, co wygląda na gorączkowe bazgroły:$B$BNekrowładcy. Naliczyłem co najmniej tuzin.$B$BFarmy na zachodzie służą Pladze za jakąś okropną wylęgarnię.$B$BRząd za rzędem ofiar.$B$BChyba mnie namierzyli. Rzuciłem się w stronę warowni. Nie dam się złapać żywcem.$B$BHemotoksyna grozojadu. Jeśli zechcą mnie ugryźć, czeka ich niespodzianka.$B$BZanieś te informacje Barthusowi.', 'Zanieś dziennik Luthera skrytotropicielowi Barthusowi w Warowni Wojennej Pieśni.', '', 'Wróć do skrytotropiciela Barthusa w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11616, 'plPL', 'Wiadomość dla Piekłorycza', '<Barthus wyrywa ostatnią stronę i zwija ją w rulon.>$B$BZanieś to natychmiast Piekłoryczowi! Tymczasem wyślę oddział na zwiad na farmy.$B$BKoniecznie powiedz Piekłoryczowi, że będziemy potrzebować posiłków. ', 'Zanieś notatkę Barthusa Garoszowi Piekłoryczowi w Warowni Wojennej Pieśni.', '', 'Porozmawiaj z Garoszem Piekłoryczem w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11617, 'plPL', 'Utrudnić im ucieczkę', 'Na pewno widzisz te niebiesko-białe platformy unoszące się nad kamieniołomem. To nimi łowcy magów przerzucili tu swoje siły, a teraz ładują na nie nasze artefakty i fragmenty naszych posągów.$B$BMusimy ich powstrzymać, zanim opuszczą kamieniołom.$B$BTe małe stworzenia, które kopią w kamieniołomie, noszą przy sobie materiały wybuchowe. Zabierz je i zniszcz nimi trzy unoszące się platformy. Przywódca czuwa na czwartej platformie, która stoi na ziemi, ale nim zajmiemy się później.', 'Etaruk przed Kamieniołomem Zimnej Skały chce, żebyś $gzniszczył:zniszczyła; platformę północną, wschodnią i zachodnią.', '', 'Wróć do Etaruka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', 'Zniszczono platformę wschodnią', 'Zniszczono platformę północną', 'Zniszczono platformę zachodnią', '', 0),
(11618, 'plPL', 'Posiłki nadchodzą...', '<Piekłorycz kręci głową.>$B$BMoże nie $gzauważyłeś:zauważyłaś;, ale próbujemy tu wygrać wojnę. Potrzebuję wszystkich dostępnych żołnierzy w głównych punktach walk. To znaczy, że nie mamy prawdziwych żołnierzy do marnowania na takie drobne wypady.$B$B<Piekłorycz milknie, zastanawiając się.>$B$BSkoro Barthus chce posiłków na farmie...$B$B<Piekłorycz klaszcze w dłonie.>$B$B...to je dostanie! Zgłoś się do zabójców Barthusa na farmach, na zachód stąd. Daj im znać, że posiłki przybyły.', 'Odszukaj skrytotropiciela Ickorisa na Posterunku Farm Wojennej Pieśni na zachód od Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11619, 'plPL', 'Gamel Okrutny', 'Mojego ojca zabił przywódca tej bandy łupieżców, Gamel Okrutny. Zamieszkał w jaskini na plaży.$B$BZ jego ludźmi już się $grozprawiłeś:rozprawiłaś;. Dokończ to, co $gzacząłeś:zaczęłaś;, $N. Pomścij mojego ojca, a podzielę się z tobą tym niewiele, co mi jeszcze zostało.', 'Karuk chce, żebyś $gpokonał:pokonała; Gamela Okrutnego na Wybrzeżu Smagaczy.', '', 'Wróć do Karuka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11620, 'plPL', 'Słowa ojca', 'Jest ktoś, kto może rzucić światło na tę zagadkę. Podobno kvaldirowie trzymają przy życiu kapłankę nag w świątyni po zachodniej stronie wybrzeża.$B$BBez wątpienia ma wiele powodów, by nienawidzić nieproszonych gości. Może mój ojciec liczy na to, że w jakiś sposób będzie z tobą współpracować.', 'Poszukaj Veehji w Kaplicy Łusek na Wybrzeżu Smagaczy.', '', '', '', '', '', '', 0),
(11621, 'plPL', 'Tablica Levirotha', 'Przeglądasz ryty na tablicy w poszukiwaniu jakiegokolwiek tekstu, który zdołasz zrozumieć. W końcu znajdujesz taki fragment:$B$B„Synowie mgły zabiorą tysiąc dusz dla tego, który mieszka w najciemniejszych wodach. Wtedy przebudzi się jego wysłannik”.$B$BTa informacja może zainteresować Karuka.', 'Wróć do Karuka z informacjami, które $gznalazłeś:znalazłaś; na tablicy.', '', '', '', '', '', '', 0),
(11622, 'plPL', 'Tajemnice Smagaczy', 'Jest ktoś, kto może rzucić światło na tę zagadkę. Podobno kvaldirowie trzymają w świątyni przy życiu kilka kapłanek nag.$B$BArcykapłanka, Veehja, bez wątpienia ma wiele powodów, by nienawidzić nieproszonych gości. Może ona powie ci więcej o znaczeniu napisu na tablicy.', 'Odszukaj Veehję w Ruinach Smagaczy w Boreańskiej Tundrze.', '', '', '', '', '', '', 0),
(11623, 'plPL', 'Wizyta u kustosza', 'Przywódcą sił łowców magów jest przerażająca istota zwana kustoszem Insiviusem. Mój lud od niezliczonych pokoleń poluje na stworzenia mórz i lądów, ale nigdy nie widziałem niczego podobnego do tego kustosza.$B$BWylądował jednym z tych latających dysków na górnej krawędzi kamieniołomu i stamtąd nadzoruje całą operację. $N, mogę tylko wierzyć, że to sami przodkowie przysłali cię mi na ratunek, i mam nadzieję, że pomożesz mi raz na zawsze przepędzić łowców magów z kamieniołomu.', 'Etaruk z obrzeży Kamieniołomu Zimnej Skały chce, żebyś $gzabił:zabiła; kustosza Insiviusa.', '', 'Wróć do Etaruka przy Kamieniołomie Zimnej Skały w Boreańskiej Tundrze.', '', '', '', '', 0),
(11624, 'plPL', 'Niebo będzie wiedzieć', 'Muszę się dowiedzieć, co się stało z moim mistrzem, wieszczem Grimwalkerem!$B$BWcześniej obserwował magnataurów w pobliskim Magmoth. Ale właśnie wrócił jeden z jego siepaczy i mówi, że grupa została rozgromiona, a wieszcza zawleczono w głąb tego miejsca.$B$BZanim wyślę cię na samobójczą misję, chcę poradzić się duchów, żeby dowiedzieć się czegoś więcej.$B$BW Ruinach Eldra\'nath na zachodzie przebywa żywiołak powietrza zwany Imperean. Jest mądra i może udzielić ci informacji, których szukamy.', 'Porozmawiaj z Imperean w Ruinach Eldra\'nath.', '', '', '', '', '', '', 0),
(11625, 'plPL', 'Trójząb Naz\'jan', 'Pięćset lat temu Azshara uwięziła w wodach w dole istotę zwaną Levirothem. A teraz ci barbarzyńcy chcą zniweczyć dzieło naszej królowej!$B$BZajęli nasze miasto i zaczęli składać w ofierze moich pobratymców, by go przebudzić! Kiedy skończyły im się nagi, zaczęli brać kiełzarów. Ich duchy nigdy nie zaznają spokoju!$B$BPomogę ci, bo to w dużej mierze ukoi moje pragnienie zemsty. Ich kapitan, Ragnar, przebywa głęboko w północno-wschodniej części Ruin Smagaczy. Ma przy sobie złoty trójząb. Przynieś mi go!', 'Veehja z Ruin Smagaczy chce, żebyś $gudał:udała; się na najdalszy północno-wschodni kraniec Ruin Smagaczy. Tam zabij Ragnara Drakkarlunda i odbierz mu Trójząb Naz\'jan.', '', 'Wróć do Veehji w Kaplicy Łusek w Boreańskiej Tundrze.', '', '', '', '', 0),
(11626, 'plPL', 'Wysłannik', 'Raj Naz\'jan był cesarzem Smagaczy, gdy uwięziono Levirotha. Sama Azshara pobłogosławiła jego trójząb, by zabił bestię, gdyby ta kiedykolwiek się uwolniła.$B$BTeraz ty nim władasz. Choć budzi to we mnie wstręt, dokonam zemsty na tych barbarzyńskich olbrzymach.$B$BZanieś trójząb w głębiny pod Ruinami Smagaczy. Levirotha znajdziesz pod górą lodową najbliżej północnej części ruin.$B$BWbij trójząb w jego ciało i zabij go! Kiedy skończysz, wróć do tego, kto cię przysłał – nie chcę cię więcej widzieć.', 'Znajdź Levirotha w wodach pod górą lodową dryfującą przy północnym skraju Ruin Smagaczy. Zabij go Trójzębem Naz\'jan i wróć do Karuka na północ od Wybrzeża Smagaczy.', '', 'Wróć do Karuka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11627, 'plPL', 'Punkt wrzenia', 'Ach, pragniesz wiedzy: gdzie jest i co się dzieje z twoim „wieszczem”. Nie przewidział dość daleko, by uniknąć kłopotów, które go spotkały.$B$BMimo to dam ci sposób, by zdobyć tę wiedzę. Ale najpierw zrobisz coś dla mnie.$B$BZ pewnością widzisz wojnę ognia i wody na południu. Wrzątek wciąż zagotowuje sadzawkę Kipieli i od wieków toczą ze sobą walkę.$B$BUdaj się na Zwęglone Wzniesienie i do Parzącej Sadzawki i przekonaj oboje, by przestali się kłócić.', 'Imperean chce, żebyś pobiciem $gzmusił:zmusiła; Wrzątek i Kipiel do uległości. Gdy się poddadzą, wróć do niej do Ruin Eldra\'nath.', '', 'Wróć do Imperean w Ruinach Eldra\'nath w Boreańskiej Tundrze.', 'Wrzątek się poddał', 'Kipiel się poddała', '', '', 0),
(11628, 'plPL', 'Całuny Plagi', 'Na północnym wschodzie wznosi się Świątynne Miasto En\'kilah, siedziba Plagi w Boreańskiej Tundrze. Zza jego murów dowódca Plagi posłał swoich nerubian, by nas otoczyli.$B$BTrwanie w obronie oznaczałoby zgubę dla mojego ludu, ale moi doradcy różnią się co do strategii. Durm rzuciłby się do ataku na ślepo, a mędrczyni Aeire woli podstęp.$B$BŚwiątynne Miasto zatruło okoliczne ziemie i żyjące tu stworzenia. Aeire uważa, że futra mamutów Plagi mogą posłużyć za płaszcz, który ukryje zwiadowcę.', 'Wódz Zimowa Wichura z Wioski Taunka\'le chce, żebyś $gprzyniósł:przyniosła; mu 5 futer mamutów Plagi.', '', 'Wróć do wodza Zimowej Wichury w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11629, 'plPL', 'Powrót do rozmówczyni duchów', '$GZrobiłeś:Zrobiłaś;, o co prosiłam, a teraz daję ci to, czego pragniesz.$B$BZanieś tę pierwotną esencję rozmówczyni duchów na waszym Posterunku Bor\'gorok. Jeśli jest mądra, będzie znała rytuał, dzięki któremu zdobędziesz wiedzę, której szukasz.', 'Zanieś Pierwotnego Impereana rozmówczyni duchów Warkokieł na Posterunku Bor\'gorok.', '', 'Wróć do rozmówczyni duchów Warkokieł na Posterunku Bor\'gorok w Boreańskiej Tundrze.', '', '', '', '', 0),
(11630, 'plPL', 'Zła ziemia', 'Mędrczyni Aeire sądzi, że jeśli wyprawi skóry skażoną ziemią spod Świątynnego Miasta, uszyje płaszcz, dzięki któremu większość sług Plagi nie będzie zwracać na ciebie uwagi. Twierdzi, że wtopisz się w otoczenie.$B$BOby miała rację. To nasza jedyna szansa, by zebrać informacje i zaplanować kontratak.$B$BZiemię, której potrzebuje, znajdziesz, grzebiąc na obszarach na południe i zachód od fortecy. Przynieś mi ją, gdy skończysz zbierać.', 'Zanieś 8 grud skażonej przez Plagę ziemi wodzowi Zimowej Wichurze w Wiosce Taunka\'le.', '', 'Wróć do wodza Zimowej Wichury w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11631, 'plPL', 'Wizja powietrza', 'Proszę, $N, dostroiłam pierwotną esencję do ciebie.$B$BOtwórz na nią duszę przy moim totemie powietrza i skup się na losie wieszcza Grimwalkera.$B$BDuch wiatru dotyka wszystkiego; przy odrobinie szczęścia zostanie ci zesłana wizja.', 'Użyj Pierwotnego Impereana, by odprawić rytuał przy Totemie Warkokła na Posterunku Bor\'gorok i dowiedzieć się czegoś o wieszczu Grimwalkerze.$B$BNastępnie porozmawiaj z rozmówczynią duchów Warkokieł.', '', 'Wróć do rozmówczyni duchów Warkokieł na Posterunku Bor\'gorok w Boreańskiej Tundrze.', 'Poznano los wieszcza Grimwalkera', '', '', '', 0),
(11632, 'plPL', 'Co niesie zimny wiatr...', 'Trzymasz fragment pancerza Ith\'rixa Żniwiarza i zdajesz sobie sprawę, że to dopiero początek. Już teraz czujesz, że zwycięstwo jest ulotne. Król Lisz z pewnością ma jeszcze tysiąc bestii takich jak Ith\'rix, gotowych rzucić się na Hordę.$B$BWeź swoje trofeum i pokaż je najwyższemu nadrządcy Zaurzykłowi w Warowni Wojennej Pieśni. Należy go powiadomić o twoim zwycięstwie nad potężnym sługą Plagi.', 'Zanieś stwardniały pancerz Ith\'rixa najwyższemu nadrządcy Zaurzykłowi w Warowni Wojennej Pieśni.', '', 'Wróć do najwyższego nadrządcy Zaurzykła w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11633, 'plPL', 'Wtopić się w tłum', 'Mędrczyni Aeire skończyła całun. Weź go i udaj się do Świątynnego Miasta En\'kilah. Załóż płaszcz w obrębie miasta, żeby ukryć się przed większością tamtejszych sług Plagi. To będzie nasza najlepsza okazja, by zebrać informacje o umocnieniach i przywódcach wroga.$B$BMając na sobie płaszcz, zbadaj trzy wielkie iglice na terenie miasta. Całun osłoni cię przed większością Plagi, ale plugastwa En\'kilah zdołają cię wykryć, jeśli podejdziesz za blisko.', 'Wódz Zimowa Wichura z Wioski Taunka\'le chce, żebyś $gzałożył:założyła; nasycony całun Plagi w Świątynnym Mieście En\'kilah i $gzbadał:zbadała; Iglicę Krwi, Iglicę Bólu i Iglicę Rozkładu.', '', 'Wróć do wodza Zimowej Wichury w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Zbadano Iglicę Rozkładu', 'Zbadano Iglicę Krwi', 'Zbadano Iglicę Bólu', '', 0),
(11634, 'plPL', 'Mistrz wiatru To\'bor', 'Twarda z ciebie sztuka, $N. Myślę, że twoje talenty bardziej przydadzą się gdzie indziej – na przykład u samego źródła tego cholernego problemu!$B$B<Razgor wskazuje na zachód.>$B$BTysiąc sług Plagi, co najmniej cztery pełnowymiarowe latające machiny śmierci i kto wie, co jeszcze.$B$BAle ty się tego dowiesz, a potem się tym zajmiesz... Tak jest, spuścisz lanie armii Plagi, która właśnie wyważa nam drzwi.$B$BWejdź na szczyt Warowni Wojennej Pieśni i zgłoś się do mistrza wiatru To\'bora. Będzie na ciebie czekał.', 'Zgłoś się do mistrza wiatru To\'bora w Warowni Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11635, 'plPL', 'Duch wieszcza Grimwalkera', 'Musisz udać się do Magmoth na wschodzie.$B$BMusisz zejść w głąb ich pieczar.$B$BMusisz porozmawiać z duchem wieszcza Grimwalkera!', 'Porozmawiaj z duchem wieszcza Grimwalkera w Magmoth.', '', '', '', '', '', '', 0),
(11636, 'plPL', 'Przejażdżka na latającym dywanie', 'Czołgi, mon. Ja mówić o machinach oblężniczych! My mieć ciężkie czołgi na Przystani Garosza, na zachodnim wybrzeżu. My cię dostarczyć do czołgu, a ty czołgiem wymierzyć Plagi sprawiedliwość Hordy!$B$BJedyny kłopot to cię tam dostać. Nie ma mowy, żeby my wysłać cię na nasze wiwerny. Za duże ryzyko.$B$BWidzisz tamten skrzat? Ten blond elf? On się nazywać Yanni, mon. On cię bezpiecznie zabrać na wybrzeże. Tam gadać z Gorge Mielacz Trupów!', 'Porozmawiaj z Yannim w Warowni Wojennej Pieśni, żeby zapewnić sobie bezpieczną podróż na wybrzeże. Po dotarciu na Przystań Garosza porozmawiaj z Gorge\'em Mielaczem Trupów.', '', '', '', '', '', '', 0),
(11637, 'plPL', 'Kaganishu', 'Kiedy moi nieliczni siepacze zginęli, zawleczono mnie tutaj i zamordowano w rytuale. Snobold, który to zrobił, nazywa się Kaganishu.$B$BChoć $gpokonałeś:pokonałaś; jego pomocników szamanów, mój duch wciąż jest przykuty do tego miejsca. Po tym, jak mnie zabił, zrobił z mojego ciała fetysz, który mnie tu więzi. Kaganishu używa go, by poznać wszystko, co wiem o szamanizmie.$B$BMusisz mu odebrać fetysz i użyć go na moim duchu. Kaganishu jest niedaleko, w jaskiniach.$B$BTylko wtedy będę naprawdę wolny.', 'Zdobądź fetysz Kaganishu i użyj go na szczątkach wieszcza Grimwalkera.$B$BFetysz musisz oddać duchowi wieszcza Grimwalkera w Magmoth.', '', 'Odszukaj ducha wieszcza Grimwalkera w Magmoth w Boreańskiej Tundrze.', 'Wieszcz Grimwalker uwolniony', '', '', '', 0),
(11638, 'plPL', 'Oddaj moje szczątki', '$N, skoro mój duch został uwolniony, czy zechcesz mi wyświadczyć tę uprzejmość i zanieść moje szczątki rozmówczyni duchów Warkokieł? Leżą na ziemi pode mną.$B$BCzuję, że rozmówczyni duchów wciąż jest na Posterunku Bor\'gorok na zachodzie, gdzie ją ostatnio widziałem.', 'Zanieś szczątki wieszcza Grimwalkera, leżące pod jego duchem, rozmówczyni duchów Warkokieł na Posterunku Bor\'gorok.', '', 'Wróć do rozmówczyni duchów Warkokieł na Posterunku Bor\'gorok w Boreańskiej Tundrze.', '', '', '', '', 0),
(11639, 'plPL', 'Zemsta na Magmoth', 'Nadrządca nie pozwala szamanom uleczyć moich ran. Mówi, że to będzie dla mnie dobra nauczka i czas na przemyślenie mojej porażki.$B$BAle ty możesz pomścić mnie i innych, którzy polegli w Magmoth!$B$BWiem, że rozmówczyni duchów chce, żebyś tam $gposzedł:poszła; ratować wieszcza.$B$BTo tuż na wschód stąd. Idź, $N... zabij magnataurów i ich snoboldzkie sługi. Przywróć posterunkowi honor!', 'Zabij 10 szamanów z Magmoth, 5 zbieraczy z Magmoth, 3 miażdżycieli z Magmoth i 3 partnerki Magmothregara. Następnie wróć do Ortrosha na Posterunku Bor\'gorok.', '', 'Wróć do Ortrosha na Posterunku Bor\'gorok w Boreańskiej Tundrze.', '', '', '', '', 0),
(11640, 'plPL', 'Słowa mocy', 'W opisanych przez ciebie iglicach mieszkają główni zastępcy przywódcy Plagi – arcykapłani. Nie tylko dowodzą siłami Plagi, ale też mają klucz do nekropolii w górze i do ich pana.$B$BJeśli nie znajdziemy i nie pokonamy ich przywódcy, zaleje nas niekończący się strumień sług Plagi. Nie mogę zostawić mojego ludu bez obrony, choćby Durm nie wiem jak chciał ponieść walkę do wroga. To na tobie spoczywa zadanie, $N, by zabić arcykapłanów i zabrać ich zwoje.', 'Zanieś zwój arcykapłana Nafersetu, zwój arcykapłana Talet-Khy i zwój arcykapłana Andoratha wodzowi Zimowej Wichurze w Wiosce Taunka\'le.', '', 'Wróć do wodza Zimowej Wichury w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11641, 'plPL', 'Odważne uderzenie', 'Od początku radziłem, żeby wódz Zimowa Wichura zebrał naszych potężnych wojowników i zaatakował wroga w jego bazie. Moje rady trafiały w próżnię, a wódz pokazał, że woli skradać się na paluszkach według planów mędrczyni Aeire.$B$BDłużej nie będę czekał. Jeśli wódz Zimowa Wichura jest zbyt tchórzliwy, by posłać naszych wojowników do boju, może ty zechcesz mu pokazać, że bezpośredni atak może się powieść. Uderz na Świątynne Miasto En\'kilah i zabij wszystko, co stanie ci na drodze, $N.', 'Zabij 15 ghuli En\'kilah i 5 nekromantów En\'kilah, a potem zgłoś się do Durma Lodoskórego w Wiosce Taunka\'le.', '', 'Wróć do Durma Lodoskórego w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11642, 'plPL', 'Czołg sam się nie naprawi', 'Musimy postawić te czołgi na nogi! Same się nie naprawią. Tym ma się zająć Mobu. Pogadaj z nim i zobacz, czego mu trzeba. Może ci się uda go uciszyć, zanim w końcu wpadnę w szał berserkera i rozrąbię na pół jego małe, gnomie ciałko!$B$BNienawidzę gnomów...', 'Porozmawiaj z Mobu na Przystani Garosza.', '', '', '', '', '', '', 0),
(11643, 'plPL', 'Pneumatyczny transdżygamaryg czołgowy Mobu', 'Te klucze są do niczego, kolego. Potrzebuję mojego pneumatycznego transdżygamaryga czołgowego, żeby uruchomić te maszyny! Niestety zostawiłem go w mojej starej norze, po drugiej stronie przystani. To ta rozwalona chata obok stajni. Musisz tam pójść i mi go przynieść, bo ja za żadne skarby piekielne nie zbliżę się do mgły.$B$BA, właśnie, kolego, uważaj na mgłę. To mgła rozniosła te wybrzeża.$B', 'Mobu na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś $godzyskał:odzyskała; jego pneumatyczny transdżygamaryg czołgowy.$B', '', 'Wróć do Mobu na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11644, 'plPL', 'Superwytrzymałe płyty metalowe!', 'Potrzebuję metalu, żeby załatać te czołgi! Superwytrzymałe płyty metalowe leżą porozrzucane po całej Przystani Garosza i na dnie zatoki.$B$BTylko uważaj, kiedy będziesz ich tam szukać. Mgła jest... eee... AGRESYWNA! To mgła zniszczyła przystań i sąsiednią osadę kiełzarów. Biedne małe kiełzary...', 'Mobu na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś $gzebrał:zebrała; 10 superwytrzymałych płyt metalowych.', '', 'Wróć do Mobu na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11645, 'plPL', 'Brudne, śmierdzące snoboldy!', 'Te brudne, śmierdzące snoboldy... ukradły mi wszystkie zapasy!$B$BPytasz, co to snobold? To jak kobold, tylko że snoboldy służą magnataurom; tak jakby się nimi opiekują. Wiem, dziwne!$B$BW każdym razie, pomożesz mi? Wiem, że te małe gnojki zwiały ze wszystkimi moimi rzeczami. Głupia ja, że myślałam, że będą bezpieczne, spakowane po północnej stronie lądowiska.$B$BMoże zrobisz mi przysługę i pójdziesz na północ do tego ich głupiego Magmoth? Jest nagroda w gotówce, jeśli szybko odniesiesz mi wszystkie rzeczy!', 'Odzyskaj 10 skrzynek z rzeczami Crafty i zanieś je Crafty Wobblesprocket na Lądowisku Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11646, 'plPL', 'Boreańska inkwizycja', 'Słuchaj uważnie, $n, bo nie ma chwili do stracenia.$b$bTwój więzień jest przygotowywany do przesłuchania tu, w naszej wieży. Jeśli nie będzie zbyt rozmowny, może być potrzebna twoja pomoc.$b$bWejdź na górę, tam gdzie jest przetrzymywany, i powiedz bibliotekarzowi Normantisowi, że przysłałem cię do pomocy.', 'Donathan polecił ci zaoferować pomoc bibliotekarzowi Normantisowi w wieży magów na Bursztynowym Występie.', '', '', '', '', '', '', 0),
(11647, 'plPL', 'Zneutralizowanie kotłów', 'Kotły zarazy w Świątynnym Mieście En\'kilah bardzo mnie niepokoją, $N. Widać wyraźnie, że wódz Zimowa Wichura ufa twojemu osądowi i twojej wiedzy o naszym wrogu. Czy pomożesz mi uporać się z kotłami, pomagając jednocześnie wodzowi w realizacji jego planów w Świątynnym Mieście?$B$BPrzygotowałam totem, który zaatakuje i zneutralizuje zawartość kotłów. Musisz tylko odnaleźć kotły i użyć totemu przy każdym z nich. Każda zniszczona broń Plagi przybliża nas do zwycięstwa.', 'Mędrczyni Aeire z Wioski Taunka\'le chce, żebyś $gużył:użyła; jej totemu do zneutralizowania kotła wschodniego, środkowego i zachodniego w Świątynnym Mieście En\'kilah.', '', 'Wróć do mędrczyni Aeire w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Oczyszczono kocioł wschodni', 'Oczyszczono kocioł środkowy', 'Oczyszczono kocioł zachodni', '', 0),
(11648, 'plPL', 'Sztuka perswazji', 'Dobrze się składa, że tu jesteś.$b$bWidzisz, kodeks postępowania Kirin Toru krzywo patrzy na stosowanie przez nas pewnych „skrajnych” środków – nawet w tak rozpaczliwych czasach jak te.$b$bTy jednak, jako osoba z zewnątrz, nie podlegasz takim ograniczeniom i możesz zrobić wszystko, co konieczne, by zdobyć informacje.$b$bRób, co musisz. Musimy natychmiast się dowiedzieć, gdzie przetrzymują lady Evanor!$b$bA ja zajmę się porządkowaniem tych półek. Aha, masz, może ten stary drobiazg ci się przyda...', 'Bibliotekarz Normantis z Bursztynowego Występu chce, żebyś $gużywał:używała; neuronowego szpikulca na uwięzionym czarowniku z Berylu, dopóki nie zdradzi, gdzie jest lady Evanor.', '', 'Wróć do bibliotekarza Normantisa na Bursztynowym Występie w Boreańskiej Tundrze.', 'Więzień przesłuchany', '', '', '', 0),
(11649, 'plPL', 'Drobiny rozwścieczonych', 'Skoro ich mała sprzeczka została załatwiona, pozostaje jeszcze kwestia pomocy tobie i twojej rozmówczyni duchów.$B$BJak widzisz, moich wasali rozwścieczyła nieustająca wojna ognia i wody. To się prędko nie zmieni, ale obróci się na twoją korzyść.$B$BAby ci pomóc, potrzebujemy ich drobin. Wejdź głębiej w ruiny i odbierz je nawałnicom.', 'Zdobądź 5 drobin nawałnicy i dostarcz je Imperean w Ruinach Eldra\'nath.', '', 'Wróć do Imperean w Ruinach Eldra\'nath w Boreańskiej Tundrze.', '', '', '', '', 0),
(11650, 'plPL', 'Jeszcze tylko kilka rzeczy...', 'Jak może $gzauważyłeś:zauważyłaś;, zbudowaliśmy lądowisko na południowej granicy leża magnataurów!$B$B<Crafty mruczy pod nosem coś niezbyt uprzejmego o Fizzcranku.>$B$BStaruszek kazał mi znaleźć... ekhem... twórcze rozwiązanie tej sytuacji: jeśli szybko się z nimi nie rozprawimy, zejdą tu i rozerwą nas na strzępy!$B$BI tu wkraczasz ty. Chcę, żebyś $gzdobył:zdobyła; dla mnie wszystko z tej listy zakupów. Proszę.', 'Zdobądź narzędzia Crafty, przeładowany kondensator i garść żwiru Rocknara. Dostarcz je Crafty Wobblesprocket na Lądowisku Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11651, 'plPL', 'Czołgowe dzięki...', 'Dzięki za całą pomoc, kolego. Możesz powiedzieć Gorge\'owi, że czołgi są gotowe do akcji. Mam nadzieję, że raz na zawsze zrobisz porządek w tej okolicy!$B', 'Porozmawiaj z Gorge\'em Mielaczem Trupów na Wybrzeżu Ech.', '', '', '', '', '', '', 0),
(11652, 'plPL', 'Równiny Nasam', 'Kiedy będziesz $ggotów:gotowa;, wskakuj do jednego z czołgów i jedź na Równiny Nasam, na południowy wschód stąd.$B$BUżyj uzbrojenia czołgu, żeby rozbić armię Plagi. Jak wpadniesz w tarapaty, „Tłuczek do mięsa” ich rozszarpie, a miny ich dobiją! Jeśli znajdziesz któregoś z naszych żołnierzy, zabierz go! I jeszcze jedno: na całym polu znajdziesz zbiorniki z paliwem.$B$BSpróbuj podjechać dość blisko do tej budowli w środku i zobacz, co się tam dzieje.$B$BJeśli zrobisz to wszystko i przeżyjesz, idź do Piekłorycza!', 'Użyj czołgu oblężniczego Hordy, żeby zniszczyć 100 żołnierzy Plagi i uratować 3 rannych żołnierzy Wojennej Pieśni na Równinach Nasam. Musisz też ustalić, kto dowodzi natarciem Plagi.$B$BJeśli ci się uda, zgłoś się do Garosza Piekłorycza w Warowni Wojennej Pieśni.', 'Ustalono przywódcę Plagi', 'Wróć do Garosza Piekłorycza w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', 'Unicestwione oddziały Plagi', 'Uratowani ranni żołnierze Wojennej Pieśni', '', '', 0),
(11653, 'plPL', 'Ha... Już nie jesteś taki wielki!', 'Gotowe, szefie! No to słuchaj, co masz zrobić...$B$BWeź mój blaster i ruszaj na północ do Magmoth. Jeśli mamy mieć z tymi potworami jakiekolwiek szanse, musimy przyciąć je do właściwych rozmiarów... że tak powiem.$B$BŻeby ocenić jego skuteczność, musisz zabić magnataura, póki blaster jeszcze na niego działa. Mogą być miażdżyciele albo partnerki, ale nie zawracaj sobie głowy młodymi... są za małe, żeby się nimi przejmować.', 'Wypróbuj ultrazaawansowany prototypowy blaster skracający Crafty na 5 miażdżycielach z Magmoth lub partnerkach Magmothregara. Potem wróć do niej na Lądowisko Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Blaster Crafty wypróbowany', '', '', '', 0),
(11654, 'plPL', 'Iglica Krwi', 'Oglądając zdobytą fiolkę z krwią, zdajesz sobie sprawę, że jej zawartość jest jeszcze ciepła. Ofiarę musiano dopiero co wykrwawić i być może wciąż żyje.$B$BNa co Pladze krew? Nigdy wcześniej nie interesowała się żywymi więźniami. Może jeśli znajdziesz źródło krwi, odkryjesz, co planuje Plaga.', 'Przeszukaj Iglicę Krwi w poszukiwaniu informacji o fiolce świeżej krwi.', '', 'Wróć do tropiciela śniegu Grumma w Boreańskiej Tundrze.', '', '', '', '', 0),
(11655, 'plPL', 'W głąb mgły', 'Za mgłą na północy znajdziesz Przystań Garosza. Na południu leżą ruiny mojego dawnego domu, Pal\'ea. Oba miejsca spustoszyła pradawna siła zwana kvaldirami.$B$BTe straszliwe dzikusy bez litości wybiły cały mój lud, a twoich pobratymców zepchnęły w głąb lądu.$B$BZ kiełzarów z Pal\'ea zostały tylko nasze rzeczy osobiste, zabrane przez kvaldirów jako relikwie. Nie jesteśmy mściwą rasą, ale sprawiedliwości musi stać się zadość. Relikwie kiełzarów muszą do mnie wrócić. Wejdź w mgłę i odnajdź je...', 'Waltor z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś zabijał kvaldirów i $godzyskał:odzyskała; 8 relikwii kiełzarów.', '', 'Wróć do Waltora z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11656, 'plPL', 'Spalenie in effigie', 'Magia kiełzarów przypomina to, co twój lud nazywa szamanizmem. Choć służymy żywiołom inaczej niż wy, moc, którą potrafimy przywołać, jest potężna.$B$B<Waltor macha przed tobą pałką przypominającą pochodnię.>$B$BZ tą pochodnią kiełzarów wróć w mgłę i uderz na statki kvaldirów. Trzy z nich znajdziesz zacumowane za mgłą przy Przystani Garosza, na północ stąd, a jeden u brzegów Pal\'ea, na południu. Spal ich statki in effigie! Niech wszyscy widzą!', 'Waltor z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś $gużył:użyła; pochodni kiełzarów do spalenia statków kvaldirów przy Pal\'ea i Przystani Garosza. Musisz zniszczyć następujące statki: „Paszczę Węża”, „Kur Drakkar”, „Młot Bora” i „Kowadło Bora”.$B', '', 'Wróć do Waltora z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze.', 'Zniszczono „Paszczę Węża”', 'Zniszczono „Kur Drakkar”', 'Zniszczono „Młot Bora”', 'Zniszczono „Kowadło Bora”', 0),
(11658, 'plPL', 'Plan B', 'Dobra, bez paniki! Blaster może i nie zadziałał, ale mamy jeszcze inne możliwości.$B$B<Crafty pstryka palcami.>$B$BOdciągniemy uwagę od lądowiska! Żeby to się udało, najpierw potrzebujemy paru rzeczy.$B$B<Wobblesprocket mierzy cię oceniającym wzrokiem od stóp do głów.>$B$BKarawana Steeljawa, tuż na zachodzie, głupio poszła na skróty przez cmentarz taunka i została zniszczona przez ich powstałe duchy.$B$BIdź tam i zdejmij z martwych orków trochę strojów. Zabierz też jeden z ich sztandarów!', 'Zbierz 10 strojów Wojennej Pieśni i sztandar Wojennej Pieśni. Zanieś je Crafty Wobblesprocket na Lądowisko Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11659, 'plPL', 'Rozbij kule!', 'Oni... wykrwawiają więźniów... wlewają krew... do tych kul.$B$B<Grumm na chwilę zamyka oczy i odchyla głowę do tyłu.>$B$BKrew... zabierana do nekropolii... by karmić krwawego księcia...$B$B<Grumm łapie powietrze.>$B$BO-obiecaj... że zniszczysz... krwawe kule... przekażesz wieść... Junekowi.$B$B<Tropiciel śniegu traci przytomność.>', 'Zniszcz 5 krwawych kul i zgłoś się do tropiciela śniegu Juneka w Wiosce Taunka\'le.', '', 'Wróć do tropiciela śniegu Juneka w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Rozbite krwawe kule', '', '', '', 0),
(11660, 'plPL', 'Róg starego żeglarza', 'Kvaldirski porucznik zwany Orabusem kierował pierwszym najazdem na mój lud w Pal\'ea. Nadzorował zniszczenie obu wiosek, a potem zniknął we mgle.$B$BW tamtych pierwszych dniach mówiono o rogu, który Orabus podarował kvaldirskim tkaczom mgły. Tym rogiem można go było przywołać w razie potrzeby.$B$BMusimy odebrać ten róg kvaldirskim tkaczom mgły i wezwać Orabusa. Jeśli zostanie zniszczony, te dzikusy może się wycofają.$B$BSzukaj tkaczy mgły w Pal\'ea, na południu.', 'Waltor z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś $gprzyniósł:przyniosła; mu Róg starego żeglarza.', '', 'Wróć do Waltora z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11661, 'plPL', 'Orabus Sternik', 'Weź róg i udaj się na zachód, na Molo Wojennej Pieśni. Dojdź do końca mola i zadmij w róg. Ten dźwięk powinien obudzić Orabusa.$B$BZabij tę plugawą bestię i wróć do mnie!', 'Waltor z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze chce, żebyś $gużył:użyła; Rogu starego żeglarza do przywołania Orabusa Sternika. Gdy się pojawi, zabij Orabusa Sternika.', '', 'Wróć do Waltora z Pal\'ea na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11662, 'plPL', 'Odszukaj Karuka!', 'Inny ocalały z Pal\'ea, zwany Karukiem, dotarł do głównej bazy kvaldirów w Boreańskiej Tundrze – daleko na południu, gdzie niegdyś śniegu było pod dostatkiem. Karuk ukrywa się na urwiskach nad Wybrzeżem Smagaczy.$B$BOdszukaj Karuka i powiedz mu, co $gzrobiłeś:zrobiłaś; dla mojego ludu tu, na Wybrzeżu Ech.$B$BNajbezpieczniejsza droga do Karuka prowadzi przez waszą fortecę. Z Warowni Wojennej Pieśni ruszaj drogą na południe i idź nią, aż dotrzesz do Wybrzeża Smagaczy.', 'Odszukaj Karuka na Wybrzeżu Smagaczy.', '', '', '', '', '', '', 0),
(11663, 'plPL', 'Wymiana informacji', 'Dziękuję, $N! Informacje, które $gwydobyłeś:wydobyłaś;, mają dla Kirin Toru ogromne znaczenie.$b$bWróć natychmiast do Donathana, a my tymczasem zaplanujemy uwolnienie lady Evanor.', 'Normantis poprosił cię, żebyś $gzgłosił:zgłosiła; się do bibliotekarza Donathana na Bursztynowym Występie.', '', '', '', '', '', '', 0),
(11664, 'plPL', 'Ucieczka z mgły', 'Słyszę stwory mgły na zewnątrz. Ich wrzaski doprowadzają mnie do szaleństwa, ale nie śmiem próbować ucieczki. Zresztą dokąd miałabym pójść? Ile by minęło, zanim by mnie dogonili i stracili jak pozostałych?$B$BCiekawe, jak daleko sięgnęła mgła, $gnieznajomy:nieznajoma;? Czy ogarnęła już cały kontynent?$B$BPomożesz mi spróbować uciec z mgły? Chyba zdołam nas zaprowadzić z powrotem do mojego ojca. Wciąż wyczuwam jego ducha życia. Jest blisko.', 'Wyprowadź Mootoo Młodszą z mgły. Jeśli uda ci się ją ocalić, porozmawiaj ze starszym Mootoo.', 'Mootoo ocalona', 'Wróć do starszego Mootoo na Wybrzeżu Ech w Boreańskiej Tundrze.', '', '', '', '', 0),
(11670, 'plPL', 'To orki, słowo daję!', 'Ze wszystkich tych strojów, które, ekhem, $godzyskałeś:odzyskałaś;, zrobiłam przebranie orka z Wojennej Pieśni. Wpadłam na genialny pomysł, żeby połączyć je z paroma starymi rzeczami, które zostały mi z zeszłorocznych Zaduszników, więc powinno być niezawodne!$B$BMasz, w tym worku jest przebranie i sztandar, który $godzyskałeś:odzyskałaś;. Zejdź w trzewia Magmoth i zabij wodza magnataurów, Magmothregara.$B$BJeśli masz ich przekonać, żeby zwrócili uwagę na orki z Wojennej Pieśni, musisz zatknąć sztandar w przebraniu.', 'W przebraniu orka z Wojennej Pieśni zatknij sztandar Wojennej Pieśni w zwłokach Magmothregara. Następnie wróć z przebraniem do Crafty Wobblesprocket na Lądowisku Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Zatknięto sztandar Wojennej Pieśni w Magmothregarze', '', '', '', 0),
(11671, 'plPL', 'Wyścig z czasem', 'A więc to prawda. Mają ją.$b$bJasne jest, co trzeba zrobić. Ona ZOSTANIE uratowana.$b$bMuszę zostać tutaj i pomóc w przygotowaniach do akcji ratunkowej. Znów cię wzywam; tym razem, byś $gzdobył:zdobyła; klucz do więzienia. O tej całej Salrand wiemy tylko tyle, że nie można jej zranić, dopóki jej tarcza jest nienaruszona.$b$bPrzygotowaliśmy specjalny ładunek wybuchowy, który powinien pozbawić ją tej ochrony, byś $gmógł:mogła; wypełnić swoje zadanie. Wróć do mnie, gdy zdobędziesz klucz.$b$bPośpiesz się, $n. Lady Evanor cierpi!', 'Donathan z Bursztynowego Występu zlecił ci użycie detonatora tarczy Berylu, żeby zniszczyć tarczę na Cyplu Berylu. Następnie masz pokonać Salrand i zabrać jej klucz.', '', 'Wróć do bibliotekarza Donathana na Bursztynowym Występie w Boreańskiej Tundrze.', '', '', '', '', 0),
(11672, 'plPL', 'Dzień werbunku', '$GPrzyszedłeś:Przyszłaś; się zaciągnąć, prawda? Normalnie $gmusiałbyś:musiałabyś; stać w kolejce jak inni rekruci. Normalnie $gmiałbyś:miałabyś; pecha, bo zaginął rejestr rekrutów i nie mogę nikogo przyjąć, dopóki nie dotrą nowe księgi.$B$BNa szczęście dla ciebie, $N, słyszałem o tobie i o tym, czego $gdokonałeś:dokonałaś; na Rubieży. Szczerze mówiąc, jesteś o klasę $glepszy:lepsza; od tych biedaków. Kolejki nie są dla ciebie.$B$BIdź do koszar i porozmawiaj z generałem Arlosem. Z największą przyjemnością spotka się z kimś twojego formatu.', 'Spotkaj się z generałem Arlosem w koszarach w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11673, 'plPL', 'Wyciągnij mnie stąd!', 'Wiedziałem, że prędzej czy później ktoś po mnie przyjdzie... Oczywiście wyszło, że później.$B$BPrzyszedłem tu pertraktować ze snoboldami, ale ich główny szaman, Kaganishu, uznał, że zamiast tego będę smaczną przekąską dla Magmothregara.$B$BZaraz... co?! Nie przysłali cię?!$B$BZAPOMNIELI O MNIE?!$B$BDobra, jesteś już tutaj i tylko to się liczy.$B$BGdy tylko rozwalisz ten łańcuch, wracamy na lądowisko. Wtedy powiesz Fizzcrankowi, że cały i zdrowy wróciłem.$B$BO ile w ogóle mnie pamięta.', 'Odprowadź Bonkera Pstrykowolta w bezpieczne miejsce, a potem zgłoś się do Fizzcranka Pełnogaza na Lądowisku Fizzcranka.', 'Bonker Pstrykowolt odprowadzony w bezpieczne miejsce.', 'Wróć do Fizzcranka Pełnogaza na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11674, 'plPL', 'Zaginięcie mędrczyni Wysokiej Mesy', 'Po tych ziemiach krąży teraz wiele nowych tajemnic. Jedna z naszych mędrczyń, Wysoka Mesa, nierozważnie wyruszyła na północ z jednym tylko biegaczem, by zbadać coś dziwnego w pobliżu Nor Umierających.$B$BPytasz, czym są nory? To święte miejsce magnataurów, do którego przychodzą na starość, by umrzeć. Kilka dni temu widziała, jak coś spadło z nieba w ich pobliżu.$B$BJeśli chcesz być $gprzyjacielem:przyjaciółką; taunka, odnajdź ją i pomóż jej. Nie jest aż tak uparta, żeby nie przyjąć twojej pomocy.', 'Odnajdź mędrczynię Wysoką Mesę w pobliżu Nor Umierających.', '', '', '', '', '', '', 0),
(11675, 'plPL', 'Godna śmierć', 'Magnataury w Norach Umierających padły ofiarą zarazy. Musimy znaleźć jej przyczynę, ale najpierw musimy skrócić ich męki.$B$B$N, musisz iść na północ, na zbocza przed nami, i zabić tyle tych biednych stworzeń, ile zdołasz.', 'Zabij 10 zarażonych magnataurów, a potem wróć do mędrczyni Wysokiej Mesy na południe od Nor Umierających.', '', 'Wróć do mędrczyni Wysokiej Mesy w Boreańskiej Tundrze.', '', '', '', '', 0),
(11676, 'plPL', 'Miłosierne wyzwolenie', 'Żołnierze, których nie zabili, są przetrzymywani w klatkach porozrzucanych po tych polach. Trochę kradnąc, zdobyliśmy kilka kluczy, ale nie możemy podejść dość blisko do żadnego więźnia, żeby nas nie zaatakowano.$B$BPotrzebujemy twoich „talentów”, żeby zdobyć te klucze i uwolnić więźniów. Roztrzaskaj łby nekrowładcom i wynaturzeniom i zabierz im klucze. Uwolnij nimi więźniów Plagi.', 'Skrytotropiciel Canarius z Posterunku Farm Wojennej Pieśni chce, żebyś $guwolnił:uwolniła; 5 więźniów Plagi.', '', 'Wróć do skrytotropiciela Canariusa na Posterunku Farm Wojennej Pieśni w Boreańskiej Tundrze.', 'Uwolnieni więźniowie Plagi', '', '', '', 0),
(11677, 'plPL', 'Powstrzymaj zarazę', 'Jestem przekonana, że zarazę wywołuje coś w tamtych jaskiniach w górze.$B$B$N, weź te nasiona. Zwykle używam ich jako ochrony przed Plagą, ale może da się nimi zakłócić to plugastwo, które dzieje się w norach.$B$BZnajdź źródło zarazy i wrzuć je do niego.', 'Mędrczyni Wysoka Mesa, stojąca tuż na południe od Nor Umierających, poprosiła cię, żebyś $gużył:użyła; oczyszczających nasion Wysokiej Mesy przy kotle zarazy w Jamie Umierających w celu jego zneutralizowania.', '', 'Wróć do mędrczyni Wysokiej Mesy w Boreańskiej Tundrze.', 'Zneutralizowano kocioł zarazy', '', '', '', 0),
(11678, 'plPL', 'Odnajdź Szczecinoroga', 'Szczecinoróg powinien już wrócić.$B$BPrzyszliśmy tu także po to, by zbadać tę budowlę Plagi na zachodzie, która spadła z nieba. Jest porywczy i pewnie wpakował się w kłopoty.$B$B$N, idź tam i odnajdź go, proszę.', 'Odnajdź biegacza Szczecinoroga w Talramas.', '', '', '', '', '', '', 0),
(11679, 'plPL', 'Ponowne wykucie klucza', 'Opóźnienia, opóźnienia... jedyne, na co nie możemy sobie teraz pozwolić!$b$bChoć bardzo nie lubię niepokoić lorda Surristrasza, jest naszą jedyną nadzieją na ocalenie naszej ukochanej Evanor.$b$bZanieś mu fragmenty klucza i miej nadzieję, że jest w dobrym nastroju.$b$bPośpiesz się, $N, nasz oddział szturmowy czeka.', 'Donathan chce, żebyś $gporozmawiał:porozmawiała; z Surristraszem na Bursztynowym Występie.', '', 'Wróć do Surristrasza na Bursztynowym Występie w Boreańskiej Tundrze.', '', '', '', '', 0),
(11680, 'plPL', 'Do lotu', 'Klucz jest wykuty na nowo.$b$bA teraz posłuchaj mojej rady. Dopnij swego albo zgiń, próbując, bo jeśli choć jedna łuska spadnie z któregoś z moich smokowców, osobiście pociągnę cię do odpowiedzialności.$b$bA teraz odejdź.', 'Gdy będziesz $ggotów:gotowa; uwolnić Evanor, daj klucz Salrand magowi bojowemu Anzimowi.', '', '', '', '', '', '', 0),
(11681, 'plPL', 'Ratunek dla Evanor', 'Nareszcie atakujemy!$b$bGdy oczyścimy platformę, użyję klucza.$b$bTy masz dopilnować, żeby lady Evanor była bezpieczna po uwolnieniu.$b$bSzybko, ruszajmy!', 'Anzim z Bursztynowego Występu chce, żebyś $gpoleciał:poleciała; z jego magami bojowymi uwolnić lady Evanor na Cyplu Berylu. Następnie masz się zgłosić do niej w wieży magów na Bursztynowym Występie.', '', 'Porozmawiaj z lady Evanor na Bursztynowym Występie w Boreańskiej Tundrze.', '', '', '', '', 0),
(11682, 'plPL', 'Smocza mowa', 'Wiem o twoich niedawnych czynach, $n, i raz jeszcze ci dziękuję.$b$bJeśli chodzi o tutejsze zagrożenie, dowiedzieliśmy się od nich wszystkiego, czego potrzebowaliśmy. Wkrótce się z nimi rozprawimy. A teraz przejdźmy do ważniejszych spraw...$b$bAzeroth cię potrzebuje. Kraina tuż na zachód stąd jest ośrodkiem pilnego kryzysu.$b$bSzczegóły zostawię lordowi Surristraszowi. Musisz natychmiast z nim porozmawiać.$b$bPowodzenia, $gprzyjacielu:przyjaciółko; Dalaranu.', 'Lady Evanor wysłała cię na rozmowę z Surristraszem na Bursztynowym Występie.', '', '', '', '', '', '', 0),
(11683, 'plPL', 'Upadła nekropolia', 'Można tylko przypuszczać, że upadła nekropolia na zachodzie wciąż jest pełna sług Plagi.$B$BSkoro będziesz w Talramas, $N, proszę cię, zgładź wszystkich sług Króla Lisza, jakich znajdziesz w środku i w okolicznych sadzawkach, do których spadła.', 'Zniszcz 20 dowolnych sług Plagi w Talramas i przy Ropiejących Sadzawkach. Następnie wróć do mędrczyni Wysokiej Mesy, tuż na południe od Nor Umierających.', '', 'Wróć do mędrczyni Wysokiej Mesy w Boreańskiej Tundrze.', 'Zniszczeni słudzy Plagi w Talramas', '', '', '', 0),
(11684, 'plPL', 'Zwiad zapadlisk', 'Czujesz te drgania ziemi?$B$BNerubianie Plagi przemieszczają się głęboko pod ziemią. Wyszli na powierzchnię na południowym zachodzie, na Polach Gejzerów, i nękają patrole wysłane przez wodza Zimową Wichurę.$B$B<Starszy taunka podaje ci wysłużoną mapę.>$B$BMoże jednej osobie uda się to, co nie udało się patrolom. Weź to ze sobą na Pola Gejzerów i zaznacz położenie nerubiańskich zapadlisk.', 'Praojciec Mahan z Wioski Taunka\'le chce, żebyś $gużył:użyła; mapy Pól Gejzerów do zaznaczenia położenia zapadliska południowego, północno-zachodniego i północno-wschodniego.', '', 'Wróć do Praojca Mahana w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Zaznacz położenie południowego zapadliska', 'Zaznacz położenie północno-wschodniego zapadliska', 'Zaznacz położenie północno-zachodniego zapadliska', '', 0),
(11685, 'plPL', 'Serce żywiołów', 'Skoro znamy dokładne położenie nerubiańskich zapadlisk, możemy je zawalić, by zatrzymać natarcie Plagi i osłabić jej siły. Poskromicielka wiatru Barah zna sposób, by ujarzmić żywiołaki i zniszczyć nimi tunele, których używają nerubianie, ale będzie potrzebować twojej pomocy.$B$BNa południowy wschód od wioski, przy wybrzeżu za Zamarzniętym Zasięgiem, znajdziesz obszar opanowany przez zamarznięte żywiołaki ziemi. Serca tych żywiołaków to dokładnie to, czego potrzebuje poskramiaczka wiatru Barah.', 'Zanieś 5 serc żywiołaków poskramiaczce wiatru Barah w Wiosce Taunka\'le.', '', 'Wróć do poskramiaczki wiatru Barah w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11686, 'plPL', 'Farmy Wojennej Pieśni', 'Według notatek Luthera Plaga używa teraz tego miejsca jako wylęgarni tych potworów, które widzisz, jak człapią po polu.$B$B<Ickoris wzdryga się.>$B$BTe potwory były kiedyś orkami... taurenami...$B$BZanim da się opracować plan, potrzebujemy więcej informacji. Chcę, żebyś $gzbadał:zbadała; trzy miejsca, przez które przewija się mnóstwo sług Plagi: Spichlerz Wojennej Pieśni na południowy zachód od nas, Farmę Torpa tuż na zachód od nas i starą Rzeźnię Wojennej Pieśni na północ od nas.$B$BWróć do mnie, gdy je rozpoznasz.', 'Skrytotropiciel Ickoris z Posterunku Farm Wojennej Pieśni chce, żebyś $gzbadał:zbadała; Spichlerz Wojennej Pieśni, Farmę Torpa i Rzeźnię Wojennej Pieśni.', '', 'Wróć do skrytotropiciela Ickorisa na Posterunku Farm Wojennej Pieśni w Boreańskiej Tundrze.', 'Zbadaj Spichlerz Wojennej Pieśni', 'Zbadaj Farmę Torpa', 'Zbadaj Rzeźnię Wojennej Pieśni', '', 0),
(11687, 'plPL', 'Doktor i lord lisz', 'Jest dwóch... których trzeba... zabić.$B$BDoktor i... lord lisz... są na górze. Znajdź ich... zniszcz ich... zanim...$B$B...będzie za... późno...', 'Zniszcz doktora Brzytwoszczerza i lorda lisza Mroźną Zimę. Następnie wróć do mędrczyni Wysokiej Mesy, tuż na południe od Nor Umierających.', '', 'Wróć do mędrczyni Wysokiej Mesy w Boreańskiej Tundrze.', '', '', '', '', 0),
(11688, 'plPL', 'Przeklęte, plugawe świnie', 'Tylko na nie popatrz! Moje piękne kodo nie mogą się obronić przed tymi plugawymi świniami! Musisz dać mi trochę czasu. Chyba zdołam wyleczyć kodo z choroby, ale musisz trzymać od nich z daleka nieżywe świnie, bo inaczej nie będzie już czego leczyć!$B$BRuszaj i wyślij te świnie do grobów – na dobre!', 'Rolnik Torp z Posterunku Farm Wojennej Pieśni chce, żebyś $gzabił:zabiła; 10 nieżywych świń.', '', 'Wróć do rolnika Torpa na Posterunku Farm Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11689, 'plPL', 'Powrót ze złymi wieściami', 'Wszechmatka musi się o tym dowiedzieć, $N.$B$BCzy wrócisz, proszę, do Taunka\'le? Powiedz jej, że wkrótce do niej dołączę.', 'Porozmawiaj z Wszechmatką Taigą w Wiosce Taunka\'le.', '', '', '', '', '', '', 0),
(11690, 'plPL', 'Przyprowadź je żywe', 'Weź to wędzidło, $N. Zauważysz, że w ustniku umieściłem malutki dozownik leku. Wyleczy zakażenie, gdy tylko kodo zaciśnie na nim zęby. Kiedy już wyleczysz z nich chorobę, musisz odjechać na nich do domu. Będą osłabione, więc musisz je łagodnie kierować tutaj.$B$BPrzyprowadź moje maleństwa z powrotem, $N!$B$BI jeszcze jedno: masz dziesięć minut! Tak długo antidotum w tym wędzidle zachowa skuteczność.', 'Rolnik Torp z Posterunku Farm Wojennej Pieśni chce, żebyś $guratował:uratowała; 8 zakażonych kodo.', '', 'Wróć do rolnika Torpa na Posterunku Farm Wojennej Pieśni w Boreańskiej Tundrze.', 'Uratowane kodo', '', '', '', 0),
(11692, 'plPL', 'Zajrzyj do Bixie', '$GJesteś sprawdzonym bohaterem:Jesteś sprawdzoną bohaterką;. Mam kolejny problem!$B$BMoja szefowa, Tinky, poszła na wschód z Bixie Kluczonóż, a ja NIE MOGĘ uruchomić nadawania w tym urządzeniu! Tylko Tinky potrafi to naprawić, a naprawdę potrzebujemy, żeby działało w stu procentach.$B$BMyślisz, że zdołasz je znaleźć? Bixie mówiła coś o śledzeniu jakichś starych magnataurów aż do miejsca zwanego Norami Umierających.$B$BPewnie tam je znajdziesz.$B$BMożesz się tam zabrać, jeśli porozmawiasz z Karą Trzygwiazdą na pasie startowym.', 'Mordle Trybokręt poprosił cię, żebyś $godnalazł:odnalazła; Bixie Kluczonóż na południe od Nor Umierających.', '', '', '', '', '', '', 0),
(11693, 'plPL', 'No pięknie... Zarażone magnataury!', 'Przyszłyśmy tu z Tinky, śledząc kilka starych magnataurów. Podobno do tamtych jaskiń w górze przychodzą umierać.$B$BOczywiście nie miałyśmy pojęcia, że kiedy tam wejdą, złapią zarazę. Nie możemy pozwolić, żeby zarażone stwory wałęsały się po okolicy; to niezdrowe.$B$BSłuchaj, może wybijesz trochę tych stworów, a ja w tym czasie wymyślę, co robimy dalej?', 'Zabij 10 zarażonych magnataurów, a potem wróć do Bixie Kluczonóż na południe od Nor Umierających.', '', 'Wróć do Bixie Kluczonóż w Boreańskiej Tundrze.', '', '', '', '', 0),
(11694, 'plPL', 'W tych jaskiniach coś się dzieje', 'No więc, kiedy $gzajmowałeś:zajmowałaś; się tymi zarażonymi bestiami, zajrzałam do tamtych jaskiń w górze.$B$BSą tam kultyści, którzy je zarażają!$B$BWarzą w kotle jakąś trującą miksturę. Mam proszek, którego zwykle używam jako odtrutki, i zmieszałam go z paroma innymi rzeczami. Myślę, że zneutralizuje ich wywar!$B$BZanieś go do którejś z tych jaskiń i zobacz, czy działa.', 'Bixie Kluczonóż, czająca się tuż na południe od Nor Umierających, poprosiła cię, żebyś $gużył:użyła; hamującego proszku Bixie przy kotle zarazy w Jamie Umierających, by go zneutralizować.', '', 'Wróć do Bixie Kluczonóż w Boreańskiej Tundrze.', 'Zneutralizowano kocioł zarazy', '', '', '', 0),
(11695, 'plPL', 'Róg furii żywiołaków', 'Z tych kawałków martwego kamienia potrafię ukształtować podobiznę żywiołaka, ale tchnięcie w nią życia to co innego. Do tego potrzebujemy pomocy i odrobiny szczęścia.$B$BLegenda mówi o pradawnym artefakcie zwanym Rogiem furii żywiołaków, którego szukał pewien wielki bohater. Pożyczę ci zwój z odpisem tej opowieści. Nie wiem, czy legenda jest prawdziwa, ale to nasza największa szansa. Jeśli legenda nie kłamie, części rogu mogą się znajdować na Równinach Zalewowych otaczających wioskę od północy i południowego zachodu.', 'Odbierz dolną połowę rogu i górną połowę rogu wodzowi Burblegoggle\'owi i wodzowi Gurgleboggle\'owi, a następnie zanieś je poskramiaczce wiatru Barah w Wiosce Taunka\'le.', '', 'Wróć do poskramiaczki wiatru Barah w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11697, 'plPL', 'Szlag, Tinky poszła do nekropolii!', 'Mówiłam Tinky, żeby nie szła sama, ale ona po prostu MUSIAŁA obejrzeć tę rozbitą nekropolię na zachodzie.$B$BJestem w 100% pewna, że ci kultyści wyszli z wnętrza tego czegoś, a to znaczy, że jestem teraz w 100% pewna, że Tinky ma kłopoty!$B$BTo najlepsza inżynier na lądowisku. Bez niej jesteśmy zgubieni!$B$BSama bym ją odszukała, ale jeden z tych stworów zdążył mnie drasnąć w nogę, zanim znów zniknęłam. $N, jeśli ktoś może ją stamtąd wyciągnąć, to tylko ty!', 'Odnajdź Tinky Knotogwizd w Talramas.', '', '', '', '', '', '', 0),
(11698, 'plPL', 'Równie dobrze można wybić Plagę', 'Skoro kultyści z tamtych jaskiń przeżyli katastrofę, to upadła nekropolia na zachodzie jest pewnie nadal pełna sług Plagi. Pewnie mnóstwo ich też w sadzawkach przed nią!$B$BSkoro będziesz w Talramas, $N, myślisz, że $gdałbyś:dałabyś; radę zgładzić wszystkich pachołków Króla Lisza, jakich tam znajdziesz?', 'Zniszcz 20 dowolnych sług Plagi w Talramas i przy Ropiejących Sadzawkach. Następnie wróć do Bixie Kluczonóż, tuż na południe od Nor Umierających.', '', 'Wróć do Bixie Kluczonóż w Boreańskiej Tundrze.', 'Zniszczeni słudzy Plagi w Talramas', '', '', '', 0),
(11699, 'plPL', 'Utknęłam w tej przeklętej klatce... ale nie na długo!', 'Kultyści zamknęli mnie czarami w tej klatce i nie ma w niej drzwi. Nie mieli pojęcia, że jestem głównym inżynierem transmaterii na lądowisku!$B$BZ twoją pomocą i odrobiną smaru na łokciach długo tu nie posiedzę.$B$BBędę potrzebować kryształu rdzenia silnika od któregoś z tutejszych ghuli, magicznego żyroskopu od ich doktora i sterującego kamienia Plagi od lorda lisza na górze.$B$BZ tym wszystkim powinnam zdołać zrobić urządzenie teleportacyjne, żeby wrócić do Fizzcranka i uciec po gnomiemu!', 'Zdobądź kryształ rdzenia silnika, magiczny żyroskop i sterujący kamień Plagi. Dostarcz je Tinky Knotogwizd w Talramas.', '', 'Wróć do Tinky Knotogwizd w Boreańskiej Tundrze.', '', '', '', '', 0),
(11700, 'plPL', 'Daj znać Bixie', 'Moja zła bliźniaczka jest teraz gdzieś tam.$B$BJestem prawie pewna, że nie ma jej na lądowisku. Właściwie, gdziekolwiek wylądowała, jest tam zimniej niż tutaj. Ale „czułam” ją tylko przez chwilę.$B$BA, trudno, przekonfiguruję to urządzenie i niedługo przeniosę się z powrotem na lądowisko. Tymczasem czy $gmógłbyś:mogłabyś; pójść na wschód i dać znać Bixie, że spotkamy się na miejscu?$B$BDzięki, $N!', 'Porozmawiaj z Bixie Kluczonóż tuż na południe od Nor Umierających.', '', '', '', '', '', '', 0),
(11701, 'plPL', 'Z powrotem na lądowisko', 'Dobra, chyba też zacznę się zbierać z powrotem na lądowisko. Oczywiście z tą raną nogi pójdzie mi to trochę wolniej.$B$BSłuchaj, może dotrzesz tam przede mną i przekażesz dobre wieści staremu Fizzcrankowi? Założę się o wszystko, że dostaniesz za to nagrodę.$B$BDzięki, $N!', 'Porozmawiaj z Fizzcrankiem Pełnogazem na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', '', '', 0),
(11702, 'plPL', 'Król Mrgl-Mrgl', 'To zabrzmieć dziwnie, ale jest tu murlok, co prosić nas o pomoc!$B$BNazywa się Król Mrgl-Mrgl, przywódca murloków Zimopłetwych. On i jego ludzie zostać wygnani z wioski i chcą, żebyś przyjść ich ratować.$B$BZnajdziesz go, jak pójdziesz na zachód i zejdziesz z klifów. On siedzieć po południowej stronie Ustronia Zimopłetwych.', 'Porozmawiaj z królem Mrgl-Mrglem w Ustroniu Zimopłetwych.', '', '', '', '', '', '', 0),
(11703, 'plPL', 'Do Getry\'ego', 'Agent Plagi, który nadzoruje porywanie żołnierzy Hordy i przemienianie ich w nieumarłe potwory, używa północno-zachodniej farmy jako wylęgarni. Skrytotropiciel Getry od tygodnia śledzi tego potwora i zebrał ważne informacje, dzięki którym być może zdołamy położyć kres temu zagrożeniu.$B$BIdź do Getry\'ego i zobacz, czy zdołasz mu pomóc zatrzymać tę taśmę produkcyjną Plagi. Getry\'ego znajdziesz w opuszczonej wieży na północno-zachodnim skraju tych farm.', 'Odnajdź skrytotropiciela Getry\'ego na Farmach Wojennej Pieśni.', '', '', '', '', '', '', 0),
(11704, 'plPL', 'Król Mrgl-Mrgl', 'To najdziwniejsza rzecz pod słońcem, ale jest tu murlok, który prosi nas o pomoc!$B$BNazywa się Król Mrgl-Mrgl i jest przywódcą murloków Zimopłetwych. Wygląda na to, że on i jego lud zostali wypędzeni z wioski i chcą, żeby ktoś przyszedł ich ratować.$B$BTym kimś jesteś ty!$B$BUstronie Zimopłetwych, a w nim króla, znajdziesz, idąc drogą na zachód aż do klifów. Zejdź nad wodę w pobliżu Parzącej Sadzawki.', 'Porozmawiaj z królem Mrgl-Mrglem w Ustroniu Zimopłetwych.', '', '', '', '', '', '', 0),
(11705, 'plPL', 'Szaleńcze przedsięwzięcie', 'To szaleństwo. Jak oni sobie wyobrażają, że poradzimy sobie z nekrowładcą Plagi i nie wiadomo iloma jego sługami?$B$B<Getry wzdycha.>$B$BSkoro Ickoris cię przysłał, musi uważać, że stać cię na wielkie czyny. Może dziś sprowadzisz na nas cud, co?$B$BKiedy będziesz $ggotów:gotowa;, zejdziemy na dół i zmierzymy się z Varidusem.$B$BJeśli wyjdziemy z tego cało, zamelduj się u Piekłorycza w Warowni Wojennej Pieśni.', 'Pomóż Getry\'emu pokonać Varidusa Oprawcę na Farmach Wojennej Pieśni.$B$BJeśli ci się uda, zgłoś się do Garosza Piekłorycza.$B', 'Varidus Oprawca pokonany', 'Wróć do Garosza Piekłorycza w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11706, 'plPL', 'Zawalenie', 'Stworzyłam i spętałam Alluviusa za pomocą Rogu furii żywiołaków. Odpowie na zew rogu, gdy staniesz przy najbardziej wysuniętym na południe zapadlisku na Polach Gejzerów.$B$BTrzęsienie ziemi, które wywoła Alluvius, powinno zawalić nerubiańskie tunele i położyć kres ich atakom z flanki. Nie zdziwiłabym się, gdyby po trzęsieniu pokazał się nerubiański dowódca. Jeśli zawalenie tuneli nie złamie ich natarcia, to z pewnością zrobi to pokonanie ich przywódcy.', 'Poskromicielka wiatru Barah z Wioski Taunka\'le chce, żebyś $gzawalił:zawaliła; nerubiańskie zapadliska za pomocą Rogu furii żywiołaków i $gpokonał:pokonała; lorda Kryxixa.', '', 'Wróć do poskramiaczki wiatru Barah w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', 'Zawalone nerubiańskie tunele', '', '', 0),
(11707, 'plPL', 'Wezwanie pomocy', 'O, dobrze, jesteś $N, prawda?$B$BPotrzebujemy twojej pomocy na północy, na Lądowisku Fizzcranka, i to na wczoraj! Magnataury, i Plaga... i przepompownia!$B$BTo szaleństwo, mówię ci, szaleństwo!$B$BMusisz tam iść i porozmawiać ze starym Pełnogazem, i to migiem!', 'Porozmawiaj z Fizzcrankiem Pełnogazem na Lądowisku Fizzcranka.', '', '', '', '', '', '', 0),
(11708, 'plPL', 'Mechagnomy', 'Skoro już tu jesteś, pora, żebym opowiedział ci całą historię tego, co się dzieje.$B$BKiedy wysłuchasz mojej opowieści, wyjdź na zewnątrz i znajdź moją zastępczynię, Jinky Nakrętkę. Od tej pory ona wszystkim się zajmie.', 'Wysłuchaj opowieści Fizzcranka Pełnogaza, a potem odnajdź Jinky Nakrętkę na Lądowisku Fizzcranka.', 'Wysłuchano opowieści Fizzcranka.', 'Porozmawiaj z Jinky Nakrętką na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11709, 'plPL', 'Zadanie Norka Krwawego Szału', 'Choć wiele $gzrobiłeś:zrobiłaś;, by umocnić nasz przyczółek na tych zamarzniętych pustkowiach, w cieniu wciąż czają się inne zagrożenia. Chcę, żebyś $gpomógł:pomogła; nadzorcy Norkowi Krwawemu Szałowi, który stacjonuje w obozie internowania tuż przed Warownią Wojennej Pieśni, zaraz na południowy wschód od niej. Odszukaj go i zaoferuj pomoc przy transporcie i wymianie więźniów.$B$BMożesz odejść, $N. ', 'Porozmawiaj z nadzorcą Norkiem Krwawym Szałem w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', '', '', 0),
(11710, 'plPL', 'Co się dzieje z transmaterią?', 'Części zamienne leżą porozrzucane wszędzie na wschodzie, przy Wrzących Sadzawkach, na Polach Gejzerów... do licha, pewnie nawet wciąż w przepompowni. Przynieś ich całe mnóstwo. Może wtedy uda mi się uruchomić w tym urządzeniu teleportację wychodzącą, nie mówiąc już o wyrównaniu przychodzących portali transmaterii.$B$BNie chciałbym zobaczyć kolejnego wypadku...', 'Zbierz 15 części zamiennych Fizzcranka i dostarcz je Mordle\'owi Trybokrętowi na Lądowisku Fizzcranka.', '', 'Wróć do Mordle\'a Trybokręta na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11711, 'plPL', 'Dostawa tchórza... w 30 minut albo gratis', 'Z każdym dniem pod naszymi bramami zjawia się coraz więcej dezerterów. Po prostu nie mamy dość miejsca, żeby trzymać w klatkach wszystkie te robaki. Zwłaszcza jeśli chcemy, żeby świnie były zadowolone.$B$B<Nork parska śmiechem.>$B$BChcę, żebyś $godprowadził:odprowadziła; jednego z tych tchórzy na rozdroże na wschód stąd i $gwystrzelił:wystrzeliła; z tej rakietnicy. Gdy zobaczą flarę, zjawi się jeden z ich kapitanów i zabierze od ciebie tchórza.$B$BGdy dostawa będzie zrobiona, zgłoś się do zwiadowcy Tungoka przy wschodniej drodze.$B', 'Zaprowadź dezertera Przymierza na rozdroże na wschód od Warowni Wojennej Pieśni i wystrzel z rakietnicy Wojennej Pieśni, by dać sygnał Przymierzu.$B$BGdy dostarczysz dezertera Przymierza na miejsce, zgłoś się do zwiadowcy Tungoka.', 'Dezerter Przymierza dostarczony', 'Wróć do zwiadowcy Tungoka na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11712, 'plPL', 'Przeklęci na nowo', 'Jeśli $gsłuchałeś:słuchałaś; staruszka, to wiesz, że mamy tam gnomy, które zostały przemienione. Mistrz trybów Mechazod zaraził je czymś, co odwróciło „Klątwę ciała”, i teraz są robotami!$B$BMyślimy, że mamy sposób, żeby na nowo je przekląć i przywrócić do normalności. Weź to rekursywne wstrzyknięcie transmaterii i użyj go na zwłokach każdego mechagnoma, na jakiego trafisz.$B$BMamy nadzieję, że to je wyleczy i pozwoli nam je namierzyć i przenieść stamtąd teleportem.$B$BCo ty na to, $N?', 'Jinky Nakrętka z Lądowiska Fizzcranka poprosiła cię o użycie rekursywnego wstrzyknięcia transmaterii na 6 mechagnomach Fizzcranka.', '', 'Wróć do Jinky Nakrętki na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Gnomy Fizzcranka przeklęte i przeniesione', '', '', '', 0),
(11713, 'plPL', 'Zwiad zapadlisk', 'Fizzcrank wysłał zespół zwiadu powietrznego, żeby nanieść na mapę nerubiańskie zapadliska w południowej części Pól Gejzerów, ale jeszcze nie wrócili. Nie mogę dłużej czekać na ich informacje, więc potrzebuję kogoś, kto sprawdzi zapadliska pieszo.$B$BRozumiem, jakie to niebezpieczne, i odpowiednio cię wynagrodzę. Weź ze sobą tę mapę i zanotuj najważniejsze informacje o każdym zapadlisku, na które tam trafisz.', 'Abner Syczomoment z Lądowiska Fizzcranka chce, żebyś $gużył:użyła; mapy Pól Gejzerów do zaznaczenia położenia zapadliska południowego, północno-zachodniego i północno-wschodniego.', '', 'Wróć do Abnera Syczomomentu na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Zaznacz położenie południowego zapadliska', 'Zaznacz położenie północno-wschodniego zapadliska', 'Zaznacz położenie północno-zachodniego zapadliska', '', 0),
(11714, 'plPL', 'Tępienie szkodników', 'Może zechcesz mi pomóc oczyścić te pola? Aż się roi na nich od brudnych szczurzych ludków! Kobolty, snoboldy, jak ich zwał, tak zwał, są wszędzie. Już sam smród zamienia mi życie w piekło!$B$BZajmij się tym robactwem, a nie pożałujesz, $N.$B', 'Zwiadowca Tungok z Równin Krwawych Zarodników w Boreańskiej Tundrze chce, żebyś $gzabił:zabiła; 8 zbieraczy krwawych zarodników, 5 podpalaczy krwawych zarodników i 2 prażaczy krwawych zarodników.', '', 'Wróć do zwiadowcy Tungoka na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11715, 'plPL', 'Paliwo dla projektu', 'Planuję zbudować maszynę, która zawali tunele, przez które Plaga wysyła swoich nerubian, ale skoro główna wiertnia nie działa, paliwo do urządzenia musimy zdobyć w inny sposób.$B$BNa Polach Gejzerów na południowym wschodzie, z dala od głównej wiertni, bulgoczą niewielkie sadzawki ropy. Jeśli zbierzesz z nich dość ropy, zrobię z niej surowe paliwo do zasilenia maszyny.$B$BPo prostu rozstaw zbieracz w pobliżu wiertni, a on wypompuje ropę i zgromadzi ją w swoim zbiorniku.', 'Abner Syczomoment z Lądowiska Fizzcranka chce, żebyś $gzebrał:zebrała; 8 baryłek ropy za pomocą przenośnego zbieracza ropy.', '', 'Wróć do Abnera Syczomomentu na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Zebrane baryłki ropy', '', '', '', 0),
(11716, 'plPL', 'Cudowne krwawe zarodniki', 'Jesteśmy świadkami czegoś niezwykłego. Cały nieodkryty ekosystem żyje i oddycha zaledwie kilka kroków od nas! Przypuszczam, że to roślina krwawych zarodników wprawia to środowisko w takie ożywienie.$B$BZebrałam trochę pyłku z pobliskich męskich okazów rośliny krwawych zarodników, ale wciąż brakuje mi żeńskich narządów do zapylenia. Przynieś mi naręcze słupków krwawych zarodników. Znajdziesz je przy większych roślinach wokół nas.$B$BUważaj na ich strażników! Kobolty łatwo ich nie oddadzą!', 'Magini krwi Laurith z Równin Krwawych Zarodników w Boreańskiej Tundrze chce, żebyś $godzyskał:odzyskała; 10 słupków krwawych zarodników.', '', 'Wróć do magini krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11717, 'plPL', 'Pyłek u źródła', 'To oczywiste! Za zapylanie na tych równinach odpowiadają ćmy krwawych zarodników. To musi być coś, co zachodzi wewnątrz organizmu ćmy i działa jak katalizator, dzięki któremu ten pyłek działa. Wszystko zaczyna nabierać sensu, $N. Dlatego kobolty nie zabijają ciem, tylko z takim zaangażowaniem ich chronią! Te głupie małe szczury wszystko sobie wykombinowały!$B$BCóż, po prostu będziemy musieli zdobyć własny pyłek od ciem! Co ty na to? Przyniesiesz mi trochę w imię nauki?', 'Magini krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze chce, żebyś $gzdobył:zdobyła; 5 pyłków ćmy krwawych zarodników.$B', '', 'Wróć do magini krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11718, 'plPL', 'Robot w mamuciej skórze', 'Przerobiłem szkielet starego robota tak, by wywołał trzęsienie ziemi dość silne, żeby zawalić tunele, ale ta maszyneria jest delikatna i wrażliwa na przenikliwe zimno Północnej Grani.$B$BWymyśliłem, jak ją zaizolować najgrubszymi skórami miejscowych mamutów. Wędrują po równinach na południe od lądowiska i przy Polach Gejzerów. Przynieś mi tyle skór, żebym mógł dokończyć maszynę, a wtedy spuścimy ją na nerubian!', 'Abner Syczomoment na Lądowisku Fizzcranka chce, żebyś $gprzyniósł:przyniosła; mu 6 grubych skór mamuta.', '', 'Wróć do Abnera Syczomomentu na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11719, 'plPL', 'Odpowiedni obiekt badań', '<Laurith mierzy cię wzrokiem, jakby cię oceniała.>$B$BMamy więc ten zapylony kwiat krwawych zarodników i nie mamy na kim sprawdzić, jak działa. Słuchaj, może $gchciałbyś:chciałabyś; natrzeć nim skórę i pozwolić mi poobserwować? Co najgorszego mogłoby się stać?$B$BNie martw się, $N! Po prostu weź tę próbkę i natrzyj nią całą twarz.', 'Magini krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze poprosiła, żebyś $gużył:użyła; zapylonego kwiatu krwawych zarodników i $gpozwolił:pozwoliła; jej obserwować skutki.', 'Użyto kwiatu krwawych zarodników', 'Porozmawiaj z maginią krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11720, 'plPL', 'Inwazja na Gammoth', 'Piekłorycz powierzył Mocarogowi i mnie trudne zadanie wytępienia magnataurów na południowym froncie Warowni Wojennej Pieśni. Przybył z nami cały pluton zaprawionych w boju żołnierzy Hordy. Nasz pierwszy wypad do pobliskich legowisk magnataurów zakończył się klęską – obrońcy legowiska wybili cały oddział. Zostaliśmy tylko my...$B$BNie jesteśmy naukowcami ani badaczami. Jesteśmy żołnierzami Hordy, tak jak ty. Żołnierzami na misji, która nie może się nie powieść...$B$BPorozmawiaj teraz z Pierwotnym mocarogiem.', 'Porozmawiaj z Pierwotnym mocarogiem na Równinach Krwawych Zarodników w Boreańskiej Tundrze.$B', '', '', '', '', '', '', 0),
(11721, 'plPL', 'Gammothra Dręczyciel', 'Magnataury żyją w stadach, podobnie jak lwy: jeden czy dwa dominujące samce i kilka samic wraz z potomstwem. W Gammoth, legowisku magnataurów na zachód stąd, przewodzi Gammothra. To Gammothra trzyma w ryzach tę populację magnataurów, więc to Gammothrę trzeba zabić, by zapobiec jakiemukolwiek ich powstaniu.$B$BZanieś tę sakiewkę z utłuczonym kwiatem krwawych zarodników do Gammoth. Użyj proszku z sakiewki, by osłabić Gammothrę, a potem go zabij! Przynieś mi jego głowę jako dowód.', 'Zabij Gammothrę i przynieś głowę Gammothry Pierwotnemu mocarogowi na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', 'Wróć do Pierwotnego mocaroga na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11722, 'plPL', 'Trofea z Gammoth', 'Nie możemy przypisać sobie całej zasługi za to zwycięstwo Hordy, $N. To ty $gryzykowałeś:ryzykowałaś; życie, by wypróbować krwawe zarodniki, i to ty w końcu $gpołożyłeś:położyłaś; kres Gammothrze.$B$BUczyń nam zaszczyt: wróć do Warowni Wojennej Pieśni i wręcz głowę Gammothry lordowi Piekłoryczowi.', 'Zanieś głowę Gammothry Garoszowi Piekłoryczowi w Warowni Wojennej Pieśni.', '', 'Wróć do Garosza Piekłorycza w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(11723, 'plPL', 'Uruchom Wstrząsomat!', 'Oto maszyna, która ocali nas przed nerubiańskim zagrożeniem!$B$B<Abner promienieje z dumy, prezentując ukończonego robota.>$B$BWeź ze sobą ten pilot i idź do najbardziej wysuniętego na południe nerubiańskiego zapadliska na Polach Gejzerów. Uruchom pilotem Wstrząsomat 5000. Resztą zajmie się sam.$B$BNie zdziw się, jeśli wywołany wstrząs zwróci uwagę któregoś z nerubiańskich przywódców. Prawdę mówiąc, to byłaby świetna okazja, by zdusić nerubiańską ofensywę.', 'Abner Syczomoment na Lądowisku Fizzcranka chce, żebyś $gużył:użyła; Wstrząsomatu 5000 do zawalenia nerubiańskich tuneli i $gpokonał:pokonała; lorda Kryxixa.', '', 'Wróć do Abnera Syczomomentu na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', 'Uruchom Wstrząsomat 5000', '', '', 0),
(11724, 'plPL', 'Omlet z olbrzymiej ćmy?', 'To jajo najwyraźniej było dla kogoś ważne, o czym świadczą leżące obok zwłoki. Oglądając je, zauważasz, że już oznaczono je do wysyłki na Równiny Krwawych Zarodników, do rąk własnych maginii krwi Laurith. To tuż na wschód stąd!$B$BWeź jajo i zanieś je wyczekującej maginii krwi.', 'Zanieś ogromne świecące jajo maginii krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', 'Wróć do magini krwi Laurith na Równinach Krwawych Zarodników w Boreańskiej Tundrze.', '', '', '', '', 0),
(11725, 'plPL', 'Odnaleźć pilota Korkociąga', 'Powinienem był sam polecieć na tę misję. Nie chodzi o to, że nie ufam Korkociągowi. Wręcz przeciwnie. Do licha, to był najlepszy skrzydłowy, z jakim latałem.$B$BChodzi o to, że to na mnie spoczywa obowiązek dowodzenia misją tak wielkiej wagi.$B$BWysłałem Korkociąga z naszą najszybszą eskadrą zwiadowczą, żeby zebrał informacje o nerubiańskiej pladze pośrodku Pól Gejzerów.$B$BWedług ostatniego meldunku, jaki dostaliśmy, jego eskadra była przy sadzawkach daleko na południu, tuż na zachód od nerubiańskich zapadlisk.$B$BZnajdź Korkociąga, $N.', 'Odszukaj Iggy\'ego „Korkociąga” Trybopstryka na Polach Gejzerów.', '', '', '', '', '', '', 0),
(11726, 'plPL', 'Szczypta przypraw', 'Od katastrofy wilki grzebią we wraku i obawiam się, że przy okazji zjadły mikrofilm z naszej misji.$B$BMam plan, jak odzyskać ten mikrofilm, ale potrzebuję twojej pomocy.$B$BNa południowy wschód stąd, na Równinach Zalewowych, żyją stworzenia zwane gorlokami. Przyprawiają jedzenie cuchnącymi przyprawami, od których każde inne stworzenie by się pochorowało. Jeśli zbierzesz dość sakiewek z przyprawami od gorloków bekających parą albo człapiących gorloków, zrobię przynętę na wilki.', 'Iggy „Korkociąg” Trybopstryk przy Wrzących Sadzawkach chce, żebyś $gzebrał:zebrała; 4 sakiewki przypraw gorloków.', '', 'Wróć do Iggy\'ego „Korkociąga” Trybopstryka przy Wrzących Sadzawkach w Boreańskiej Tundrze.', '', '', '', '', 0),
(11727, 'plPL', 'Czas bohaterów', 'Dobrze, że jesteś wśród nas, $N. Wszyscy słyszeliśmy o twoich dawnych czynach.$B$BJak wiesz, król Wrynn przerzuca do Północnej Grani wielkie armie, by stawić czoła armiom Arthasa. Ale armie są niczym bez prawdziwych bohaterów, którzy dodają im ducha i je prowadzą.$B$BChcę, żebyś $gbył:była; takim bohaterem dla moich ludzi. Walcz u ich boku z Plagą, która oblega naszą twierdzę.$B$BZgłoś się do sierżanta Hammerhilla przed Wewnętrzną Warownią. Twierdza Walecznych nie może upaść. Od tego zależy przyszłość całej naszej kampanii.', 'Zgłoś się do sierżanta Hammerhilla w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11728, 'plPL', 'Lupus kupus', 'Cokolwiek zrobisz, $gsam:sama; nie jedz tej przynęty. Połóż ją tylko w pobliżu wilka nasiąkniętego ropą. Skoro są na tyle zdesperowane, że zjadają mikrofilm, przybiegną, gdy tylko ją zwęszą.$B$BPotem po prostu poczekaj, aż natura zrobi swoje, a wtedy wystarczy przeszukać ten, eee... produkt uboczny w poszukiwaniu filmu.$B$BPożyczyłbym ci do tej roboty mój specjalny szufelkus lupus kupus, ale zostawiłem go na lądowisku. Obawiam się, że będziesz $gmusiał:musiała;... eee... szukać po staremu.', 'Iggy „Korkociąg” Trybopstryk przy Wrzących Sadzawkach chce, żebyś $gprzyniósł:przyniosła; mu 8 kawałków mikrofilmu.', '', 'Wróć do Iggy\'ego „Korkociąga” Trybopstryka przy Wrzących Sadzawkach w Boreańskiej Tundrze.', '', '', '', '', 0),
(11729, 'plPL', 'Ultradźwiękowy śrubokręt', 'Maszyna, którą właśnie $grozebrałeś:rozebrałaś;, miała to w swoich mechanicznych trzewiach.$B$BWygląda na dość skomplikowane... ktoś na lądowisku z pewnością chciałby na to zerknąć. Może Crafty Wobblesprocket?', 'Dostarcz ultradźwiękowy śrubokręt Crafty Wobblesprocket na Lądowisku Fizzcranka.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11730, 'plPL', 'Pan i sługa', 'Ultradźwiękowy śrubokręt to narzędzie doskonałe. Z mechanicznymi rzeczami potrafi zrobić wszystko!$B$BWróć do sadzawek i rozbierz kilka robotów Mechazoda. Potem wystarczy użyć śrubokręta na ich szczątkach, a założę się, że przejdą na naszą stronę, przynajmniej na chwilę.$B$BJestem prawie pewna, że na mechagnomach to nie zadziała, więc nawet nie próbuj.$B$BAha, jeśli chcesz coś wyjąć z trzewi robota, zrób to przed użyciem śrubokręta!', 'Użyj ultradźwiękowego śrubokręta, by przeprogramować 15 robotów, a następnie wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka.$B$BZanim przeprogramujesz zniszczonego robota, pamiętaj, by go przeszukać.', '', 'Wróć do Crafty Wobblesprocket na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Przeprogramowane roboty', '', '', '', 0),
(11733, 'plPL', 'Przez szczelinę', 'Śledziłem twoje wysiłki, śmiertelniku. Nie udawaj zdziwienia. Z pewnością $gczułeś:czułaś; na sobie moje spojrzenie.$b$bNadszedł czas, by zdjąć zasłonę ciemności z twojego umysłu. Są surowe prawdy, na które jesteś już $ggotów:gotowa;.$b$bZanim usłyszysz tę opowieść, na własne oczy zobaczysz, z czym się mierzymy.$b$bUporządkuj swoje sprawy, $N....', 'Surristrasz chce, żebyś $gudał:udała; się do Mrozarry. Na miejscu porozmawiaj z arcymagiem Berinandem.', '', '', '', '', '', '', 0),
(11788, 'plPL', 'W lewo luzuje, w prawo dokręca', 'Dobra, chyba jesteśmy gotowi do przedostatniego szturmu... zanim pokonasz Mechazoda, musisz rozebrać jego zastępców!$B$BTwonky\'ego, ED-210, Maxa Blasto i Mielacza znajdziesz odpowiednio przy Stacji Zachodniej, Północnej, Środkowej i Południowej.$B$BŻeby się pokazali, po prostu przekręć zawory na stacjach i popsuj im to, co tam robią. Nie przegapisz tych miejsc, wszędzie kręcą się światła.', 'Rozbierz Twonky\'ego, ED-210, Maxa Blasto i Mielacza, a następnie złóż raport Jinky Nakrętce na Lądowisku Fizzcranka.', '', 'Wróć do Jinky Nakrętki na Lądowisku Fizzcranka w Boreańskiej Tundrze.', '', '', '', '', 0),
(11789, 'plPL', 'Żołnierz w potrzebie', 'Hej, ty! Proszę, potrzebuję twojej pomocy. Ten żołnierz umrze od jadu biesów z krypt, jeśli natychmiast czegoś nie zrobimy.$B$BZdołałem spowolnić działanie trucizny, ale bez odpowiedniego zapasu antidotum nie mogę jej zneutralizować.$B$BObiecano mi nową dostawę odtrutki z ostatnim rejsem „Łamacza Burz” z południa. Wejdź do jego ładowni i poszukaj skrzyni ze środkami pierwszej pomocy.$B$BPośpiesz się, $N! Nie możemy sobie pozwolić na niepotrzebną utratę kolejnych ludzi.', 'Medyk Hawthorn przed Twierdzą Walecznych chce, żebyś $gwszedł:weszła; do ładowni „Łamacza Burz” i $gwyjął:wyjęła; odtrutkę Hawthorna ze skrzyni ze środkami pierwszej pomocy.', '', 'Wróć do medyka Hawthorna na Piaskach Nasam w Boreańskiej Tundrze.', '', '', '', '', 0),
(11790, 'plPL', 'Kultyści wśród nas', 'Ten ołtarz nosi wszystkie znamiona Kultu Potępionych. Wygląda na to, że fanatycy z kontynentu przedostali się do Północnej Grani. Rozsądnie byłoby powiadomić kapitana statku.$B$BByć może jest na górnym pokładzie.', 'Porozmawiaj z kapitanem „Mańkutem” Lugsailem na pokładzie „Łamacza Burz” w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11791, 'plPL', 'Zawiadom Arlosa', 'Musimy natychmiast zawiadomić generała Arlosa. Znam kapitana od dawna i, uwierz mi, należy do tych ostrożniejszych.$B$BKto wie, ilu kultystów przemycono do naszych osad w Północnej Grani na innych statkach? To może się skończyć katastrofą.', 'Porozmawiaj z generałem Arlosem w Wewnętrznej Warowni w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11792, 'plPL', 'Wrogowie Światła', 'Nie tak szybko. Nie wiem jak ty, $N, ale mnie słowa generała wcale nie przekonały. Brzmiały niepewnie... jakby nie były jego własne.$B$BCoś tu jest nie tak. Wszystkie nasze próby współpracy są blokowane i odwlekane. Czas działać na własną rękę.$B$BSkoro mamy dowiedzieć się więcej o kultystach w twierdzy... może powinniśmy przyjrzeć się tym poza nią.$B$BWywiad donosi o niewielkiej grupie kultystów, którzy pomagają Pladze na północ stąd. Sprawdź, czy mają przy sobie jakieś wskazówki.', 'Zwiastun Vurenn chce, żebyś $gzaatakował:zaatakowała; kultystów nekrolitów w pobliżu Dalekich Włości, na północ od Twierdzy Walecznych, i $godebrał:odebrała; im komunikat kultystów.', '', 'Wróć do Zwiastuna Vurenna w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11793, 'plPL', 'Dalsze śledztwo', 'Obawiam się, że tę sprawę muszę przekazać jednemu z moich agentów... komuś, kto potrafi działać w ukryciu. Zatrzymaj dowody przy sobie i zanieś je Obrończyni Yaali w gospodzie.$B$BPowiedz jej, że to ja cię przysyłam, i nikomu innemu nie mów o tej sprawie. Nie wiemy, kto może pracować dla kultu.', 'Zanieś komunikat kultystów Obrończyni Yaali w gospodzie w Twierdzy Walecznych.', '', 'Wróć do Obrończyni Yaali w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11794, 'plPL', 'Polowanie czas zacząć', 'Postanowiłam dowiedzieć się jak najwięcej o tym plugawym kulcie śmierci, łącznie z jego tajnym językiem.$B$BVurenn miał rację. Kultyści wspominają o zakamuflowanych agentach w różnych miejscach Twierdzy Walecznych: w dolnych dokach, w więzieniu w Wewnętrznej Warowni i w kuchni gospody.$B$BWeź ten okulus. Użyj go w tych trzech miejscach – każdego, kto niedawno korzystał z nekromancji kultu, spowije mroczna aura. Rozpraw się z kultystami, zanim wydarzy się coś złego.', 'Obrończyni Yaala chce, żebyś $gużył:użyła; okulusa egzorcysty w trzech różnych miejscach Twierdzy Walecznych, by zdemaskować i pokonać członków Kultu Potępionych.', '', 'Wróć do Obrończyni Yaali w Twierdzy Walecznych w Boreańskiej Tundrze.', 'Pokonany kultysta w dokach', 'Pokonany kultysta w więzieniu', 'Pokonany kultysta w kuchni', '', 0),
(11795, 'plPL', 'Procedura awaryjna: sekcja 8.2, akapit C', 'Ranny czy nie, jako dowódca eskadry odpowiadam za odnalezienie i zwrot insygniów wszystkich poległych pilotów pod moim dowództwem. Przez wszystkie lata, które przelatałem z Fizzcrankiem, ani razu nie zdarzyło się, żebyśmy nie zwrócili sygnetu pilota.$B$BPrzez moje rany niebezpiecznie jest mi oddalać się od bezpiecznego wraku, ale może $gzechciałbyś:zechciałabyś; pomóc mi odzyskać insygnia? W tym czasie przygotuję się do wypełnienia mojego ostatniego obowiązku jako dowódcy eskadry.', 'Odzyskaj 6 insygniów pilota Fizzcranka z ciał pilotów zwiadowczych Fizzcranka i zanieś je Iggy\'emu „Korkociągowi” Trybopstrykowi przy Wrzących Sadzawkach.', '', 'Wróć do Iggy\'ego „Korkociąga” Trybopstryka przy Wrzących Sadzawkach w Boreańskiej Tundrze.', '', '', '', '', 0),
(11796, 'plPL', 'Procedura awaryjna: sekcja 8.2, akapit D', 'Zostało mi tylko jedno do zrobienia, zanim będę mógł w końcu wrócić na lądowisko i złożyć raport. Sekcja 8.2, akapit D procedury awaryjnej nakazuje mi zniszczyć jak największą część wraku, by nasza technologia nie wpadła w ręce wroga.$B$BDam ci swój palnik, jeśli zgodzisz się pomóc mi wypełnić ten ostatni obowiązek. Wolę nie myśleć, co zrobią goblińscy sojusznicy Hordy, jeśli te maszyny wpadną w ich ręce.', 'Iggy „Korkociąg” Trybopstryk chce, żebyś $gzniszczył:zniszczyła; wschodni wrak, jeden z południowych wraków i jeden z północno-zachodnich wraków.', '', 'Wróć do Iggy\'ego „Korkociąga” Trybopstryka przy Wrzących Sadzawkach w Boreańskiej Tundrze.', 'Zniszcz wschodni wrak', 'Zniszcz południowy wrak', 'Zniszcz północno-zachodni wrak', '', 0),
(11797, 'plPL', 'Oblężenie', 'No, no, no. Dobrze widzieć, że Arlos wytacza ciężkie działa.$B$BNie zrozum mnie źle – nasi chłopcy robią, co mogą, ale ktoś o twojej sławie walczący u ich boku naprawdę mógłby odwrócić losy bitwy. Nie wiem, jak długo jeszcze wytrzymamy przeciwko tym nieumarłym nerubianom.$B$BCo powiesz na to, żeby wyjść tam i ubić mi trochę tych pełzaczy? Pokaż chłopakom, jak to się robi.', 'Sierżant Hammerhill chce, żebyś $gzabił:zabiła; 6 pełzaczy z krypt na Piaskach Nasam przed Twierdzą Walecznych.', '', 'Wróć do sierżanta Hammerhilla w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11798, 'plPL', 'Mistrz Trybów', 'Mistrz Trybów Mechazod oszalał! Twierdzi, że oferuje nam nieśmiertelność, zdejmując z nas tak zwaną „Klątwę ciała”, ale tak naprawdę tworzy mechanicznych niewolników!$B$B$N, jesteśmy prawie pewni, że wciąż siedzi w przepompowni pośrodku sadzawek na wschodzie.$B$BOstatnio widzieliśmy go w chacie dowodzenia na górze. Idź tam i przejrzyj jego rzeczy.$B$BMusisz stawić czoła Mechazodowi, jeśli gnomy na całym świecie... nie, wszyscy na całym świecie mają przeżyć!', 'Przestudiuj Podręcznik Mistrza Trybów i przynieś głowę Mechazoda Fizzcrankowi Pełnogazowi.', '', 'Wróć do Fizzcranka Pełnogaza na Lądowisku Fizzcranka w Boreańskiej Tundrze.', 'Przestudiowano Podręcznik Mistrza Trybów', '', '', '', 0),
(11864, 'plPL', 'Deklaracja misji', '', '', '', '', '', '', '', '', 0),
(11865, 'plPL', 'Niegodni śmierci', 'Tuż na południe od nas karibu wędrowały kiedyś swobodnie i spokojnie. Potem zjawił się Nesingwary i wszystko się zmieniło. Teraz karibu żyją w nieustannym szale, w ciągłej panice. Tropią je myśliwi i traperzy ukryci na polach.$B$BOprawcy Nesingwary\'ego są niegodni śmierci. Muszą poczuć męki, na które skazują karibu!$B$BWeź ten stos sztucznych futer i połóż go na ich pułapkach na karibu na południu. Patrz, jak myśliwi wpadają we własne śmiercionośne sidła!', 'Zaza w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś za pomocą stosu sztucznych futer $gzłapał:złapała; w pułapki 8 traperów Nesingwary\'ego.$B', '', 'Wróć do Zazy w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', 'Złapani traperzy Nesingwary\'ego', '', '', '', 0),
(11866, 'plPL', 'Uszy naszych wrogów', 'Czy to poszukiwacze skarbów, czy żądni krwi myśliwi z pustkowi – każda istota, która wspiera Nesingwary\'ego i ośmiela się podnieść rękę na naszą ukochaną dziką przyrodę, zostanie uznana za wroga D.E.H.T.A.$B$BJeśli zabijesz tych plugawych popleczników Nesingwary\'ego, przynieś mi dowód ich śmierci, a otrzymasz w nagrodę błogosławieństwo druidów D.E.H.T.A.$B', 'Arcydruid Lathorius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze obiecał cię nagrodzić, jeśli przyniesiesz mu 15 uszu pachołków Nesingwary\'ego.', '', 'Wróć do arcydruida Lathoriusa w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11867, 'plPL', 'Uszu nigdy dość...', 'Czy to poszukiwacze skarbów, czy żądni krwi myśliwi z pustkowi – każda istota, która wspiera Nesingwary\'ego i ośmiela się podnieść rękę na naszą ukochaną dziką przyrodę, zostanie uznana za wroga D.E.H.T.A. Jeśli zabijesz tych plugawych popleczników Nesingwary\'ego, przynieś mi dowód ich śmierci, a otrzymasz w nagrodę błogosławieństwo druidów D.E.H.T.A.$B', 'Arcydruid Lathorius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze obiecał cię nagrodzić, jeśli przyniesiesz mu 15 uszu pachołków Nesingwary\'ego.', '', 'Wróć do arcydruida Lathoriusa w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11868, 'plPL', 'Nadchodzi Odstrzałowa', 'Przy południowym krańcu tego urwiska znajdziesz zdradziecką przywódczynię traperów polujących na karibu. To dzikuska jak żadna inna – urąga truchłom zabitych zwierząt: pije ich krew i wyje do księżyców!$B$BZnajdź tę morderczynię, Karen, i zakończ jej nędzny żywot.$B$BPrzygotuj się należycie, $N. Karen Odstrzałowa opływa w bogactwa, którymi obsypał ją Nesingwary! Będzie dobrze uzbrojona i strzeżona przez pachołków.', 'Zaza w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś $gzabił:zabiła; Karen Odstrzałową.', '', 'Wróć do Zazy w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11869, 'plPL', 'Szczęśliwe jak małże', 'Na zachód od nas znajdziesz Jezioro Kum\'uya. O ile nam wiadomo, to jedyne na świecie słodkowodne siedlisko olbrzymich małży.$B$BRzecz jasna pachołkowie Nesingwary\'ego zrobili sobie teraz z jeziora wielką farmę pereł. Trzeba ich powstrzymać! Trzeba dać nauczkę tym, którym przyszłoby do głowy narażać cały gatunek.$B$BIdź nad Jezioro Kum\'uya i odszukaj nurków w szale łupów. Zabijaj ich, aż woda spłynie czerwienią! Wróć do mnie, gdy dasz im należytą nauczkę!', 'Hierofantka Cenius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś $gzabił:zabiła; 10 nurków w szale łupów.', '', 'Wróć do hierofantki Cenius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11870, 'plPL', 'Opuszczony Zasięg', 'Właśnie dostaliśmy wiadomość od Liandry, że najemnicy wynajęci przez Nesingwary\'ego przenoszą towary z plaży na główny statek transportowy Nesingwary\'ego. Bez wątpienia zamierzają zbić fortunę na tym morderczym procederze!$B$BLiandra prosi, byśmy wysłali pomoc do Opuszczonego Zasięgu, tuż na południe stąd, na wybrzeżu Boreańskiej Tundry.$B$BPośpiesz się, Liandra tam na ciebie czeka!$B', 'Odszukaj hierofantę Liandrę w Opuszczonym Zasięgu.', '', '', '', '', '', '', 0),
(11871, 'plPL', 'Nie na naszej warcie', 'Na całej plaży, wśród szczątków i wyrzuconych przez morze rupieci, walają się skrzynie i worki z częściami zwierząt. Wygląda na to, że Nesingwary zmówił się z Korsarzami z Morza Północnego. Ci parszywi piraci przewożą towary, które mordercze pachołki Nesingwary\'ego zbierają u wybrzeży. Bez wątpienia trafią one do domów i na grzbiety bogatych, pozbawionych skrupułów osób w całym Azeroth.$B$BDo tego nie dojdzie. Nie na naszej warcie. Przynieś mi wszystkie dostawy, jakie znajdziesz na tej plaży. Nigdy ich nie dostaną!', 'Hierofanta Liandra w Opuszczonym Zasięgu w Boreańskiej Tundrze chce, żebyś $godzyskał:odzyskała; 12 dostaw części zwierzęcych.', '', 'Wróć do hierofanty Liandry w Opuszczonym Zasięgu w Boreańskiej Tundrze.', '', '', '', '', 0),
(11872, 'plPL', 'Nikczemny Mistrz Małży...', 'To naprawdę podłe – samozwańczo ogłosić się „Mistrzem Małży”, jakby się władało stworzeniami morza. Nikt nie ma prawa tak twierdzić!$B$BTrzeba odnaleźć i zabić tego „Mistrza Małży”. Ostatnio widziano go przy wraku tuż u wybrzeży Opuszczonego Zasięgu. Znajdź go i zabij.$B$BGdy to zrobisz, wróć do hierofantki Cenius w Obozowisku D.E.H.T.A., na północ stąd, i powiedz jej, że misja się powiodła.', 'Zabij Mistrza Małży K i wróć do hierofantki Cenius w Obozowisku D.E.H.T.A.$B', '', 'Wróć do hierofantki Cenius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11873, 'plPL', 'Przekaż wieści Fizzcrankowi', 'Czy $gzechciałbyś:zechciałabyś; wrócić na lądowisko i dać znać Fizzcrankowi, że wkrótce się zjawię, żeby złożyć oficjalny raport? Muszę jeszcze uporać się z wrakiem mojej latającej maszyny, a potem ruszam.$B$BDopilnuję, żeby Fizzcrank wiedział, że to tobie zawdzięczam przeżycie i akcję ratunkową.$B$BCiekawe tylko, co zrobiłby sam staruszek, gdyby leciał z nami. Tęsknię za tamtymi czasami.', 'Wróć na Lądowisko Fizzcranka i porozmawiaj z Fizzcrankiem Pełnogazem.', '', '', '', '', '', '', 0),
(11876, 'plPL', 'Pomóż tym, którzy nie mogą pomóc sobie sami', 'Majestatyczne zwierzęta, prawda?$B$B<Lathorius wskazuje mamuty na północnej tundrze.>$B$BZ każdym dniem jest ich coraz mniej. Demony, które nazywają siebie myśliwymi, zabijają je dla rozrywki i bogactwa.$B$B<Twarz Lathoriusa wykrzywia gniew.>$B$BDoprowadza mnie do szaleństwa to skomlenie, $N. Słychać je, niesione wiatrem. Młode mamuty, uwięzione w plugawych pułapkach myśliwych, wołają nas.$B$BWeź ten młot i rozbij te pułapki. Uwolnij młode!', 'Arcydruid Lathorius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś za pomocą niszczyciela pułapek D.E.H.T.A. $guwolnił:uwolniła; 8 młodych mamutów.', '', 'Wróć do arcydruida Lathoriusa w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', 'Uwolnione młode mamuty', '', '', '', 0),
(11878, 'plPL', 'Khu\'nok będzie wiedział', 'Choć $gwykazałeś:wykazałaś; się męstwem, uwalniając uwięzione młode, wiele z nich i tak zginie. Widzisz, bez opiekuna muszą same radzić sobie w dziczy.$B$BAle jest sposób! Wciąż jest nadzieja!$B$BNa północ stąd, na polach mamutów graniczących z Wrzącymi Sadzawkami, znajdziesz Khu\'noka Behemota – mamuta równie mądrego, co pradawnego. Weź tego osieroconego mamuta i przedstaw go Khu\'nokowi. On będzie wiedział, co robić.', 'Zanieś osierocone młode mamuta Khu\'nokowi Behemotowi w Boreańskiej Tundrze.', 'Osierocone młode mamuta dostarczone Khu\'nokowi', 'Wróć do Khu\'noka Behemota w Boreańskiej Tundrze.', '', '', '', '', 0),
(11879, 'plPL', 'Kaw Niszczyciel Mamutów', 'Nie pokonasz w pojedynkę istoty odpowiedzialnej za rzeź mego rodzaju. Mamuty z tundry ci pomogą!$B$BRuszaj na równiny i znajdź samca mamuta. Pozwoli ci się dosiąść i kierować swoimi ruchami i czynami. Jedź na jego grzbiecie i odszukaj Kawa na północ stąd, na Grzędzie Kawa. Razem staniecie się narzędziem zguby Kawa.$B$BZniszcz armie Kawa i odbierz mu jego cenną halabardę bojową. Jeśli ci się powiedzie, wróć do Lathoriusa w Obozowisku D.E.H.T.A.', 'Zabij Kawa Niszczyciela Mamutów i odzyskaj halabardę bojową Kawa. Dostarcz ją arcydruidowi Lathoriusowi w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', 'Wróć do arcydruida Lathoriusa w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11881, 'plPL', 'Załaduj ją!', '$GWidziałeś:Widziałaś; te latające maszyny, które tu bzyczą? Gnomia pomysłowość w najlepszym wydaniu.$B$BOd dawna czekałem, żeby dobrać się do ich technologii, i właśnie nadarzyła się doskonała okazja. Jedno z ich skrzydeł zwiadowczych rozbiło się przy Wrzących Sadzawkach, w południowo-zachodniej części Pól Gejzerów.$B$BZadmij w ten gwizdek przy którejś z rozbitych maszyn, a przybiegnie moja wierna mulica, Jenny. Pójdzie za tobą i poniesie złom, ale musisz jej pilnować. Jeśli ktoś ją zaatakuje, zacznie gubić ładunek.', 'Pomóż Jenny dotrzeć z miejsca katastrofy do Fezzixa Skręttryba w Wiosce Taunka\'le, nie tracąc całego ładunku.', '', 'Wróć do Fezzixa Skręttryba w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Doprowadź Jenny w bezpieczne miejsce, nie tracąc ładunku', '', '', '', 0),
(11884, 'plPL', 'Ned, Władca Nosorożców...', 'Na zachód stąd, na wysokich urwiskach nad Jeziorem Kum\'uya, grasuje podła istota zwana Nedarem. Ten samozwańczy „Władca Nosorożców” przeczesuje pustkowia w poszukiwaniu rannych lub młodych nosorożców, niezdolnych obronić się przed tchórzliwymi atakami Neda. Jakby tego było mało, Ned wychował sobie własnego nosorożca na wierzchowca i ochroniarza.$B$BD.E.H.T.A. rzadko wzywa do zabicia zwierzęcia, ale skażonego nosorożca Neda trzeba się pozbyć... Zabij ich obu i wróć do mnie.', 'Killinger Wartownik Nory w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś $gzabił:zabiła; Nedara, Władcę Nosorożców, i jego towarzysza, „Śniadaniówkę”.', '', 'Wróć do Killingera Wartownika Nory w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11887, 'plPL', 'Zapasy awaryjne', 'Przetrząsając rzeczy martwego gnoma, znajdujesz niewielki pakiet z racjami żywnościowymi, narzędziami i poręczną rolką gnomiej taśmy klejącej. Zawartość takich zestawów mogłaby się przydać Fezzixowi Skręttrybowi, gdy przyjdzie mu składać wraki gnomich latających maszyn.$B$BZa kilka takich zestawów Fezzix może wypłacić niezłą premię.', 'Zbierz 7 gnomich awaryjnych zestawów narzędzi z ciał zestrzelonych pilotów zwiadowczych Fizzcranka i zanieś je Fezzixowi Skręttrybowi w Wiosce Taunka\'le.', '', 'Wróć do Fezzixa Skręttryba w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11888, 'plPL', 'Wyprawa do Wioski Taunka\'le', '$N, wódz każe mi czekać... a Taunka\'le nie ma czasu!$B$BSłyszałem o twoich wyczynach. Zamiast czekać, aż Garosz wyśle pomoc, proszę cię, byś $gruszył:ruszyła; na pomoc mojemu ludowi.$B$BWioska Taunka\'le leży daleko na północnym wschodzie. Wyjdź z warowni drogą na wschód i na rozstaju skręć na północ. Wkrótce dotrzesz do kolejnego rozstaju. Tam idź ścieżką na wschód, mijając wielkie sadzawki na równinach zalewowych od południa, a potem od wschodu.$B$BGdy dotrzesz na miejsce, porozmawiaj z Mędrcem Ziemią i Niebem.', 'Porozmawiaj z Mędrcem Ziemią i Niebem w Wiosce Taunka\'le.', '', '', '', '', '', '', 0),
(11889, 'plPL', 'Śmierć z nieba', 'Nieźle trzymamy linię frontu przeciw tym robalom. Niektóre z tych bezczelnych stworów potrafią jednak przelecieć nad rzeczoną linią frontu i dają nieźle w kość naszym wewnętrznym umocnieniom.$B$BZarekwirowałem wzmocnione sieci rybackie z naszych cywilnych statków. Jeśli masz dość mocne ramię do rzucania, pomogą ci strącać wroga z nieba. Przetrzeb ich szeregi, żeby nasza obrona utrzymała twierdzę.', 'Sierżant Hammerhill chce, żebyś za pomocą wzmocnionej sieci $gzabił:zabiła; 6 plujników ognia Plagi przed Twierdzą Walecznych.', '', 'Wróć do sierżanta Hammerhilla w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11890, 'plPL', 'Co oni knują?', 'Gnomy wpakowały się w kłopoty przy sadzawkach na zachodzie. Dobrze im tak, bo zatruwają ziemię swoimi tak zwanymi wynalazkami.$B$BChcę, żebyś $gposzedł:poszła; do ich przepompowni i $gsprawdził:sprawdziła;, co ich spotkało. Potem wróć do mnie.', 'Zbadaj okolice Przepompowni Fizzcranka, a następnie wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le.', 'Zbadano okolice Przepompowni Fizzcranka.', 'Wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11892, 'plPL', 'Zamach na Harolda Lane\'a', 'Wiele $gzrobiłeś:zrobiłaś; dla zwierząt Boreańskiej Tundry, $N. Pachołkowie Nesingwary\'ego zostali odparci i dostali nauczkę, której prędko nie zapomną.$B$BUstaliliśmy, że Harold Lane, główny sprawca masowych rzezi w Nagrandzie, kieruje działaniami Nesingwary\'ego na tundrze. Stacjonuje nad Jeziorem Kum\'uya, na zachód stąd.$B$B<Lathorius wręcza ci misternie rzeźbiony dębowy róg.>$B$BZnajdź Lane\'a i zabij go. Jeśli będziesz potrzebować naszej pomocy, użyj tego rogu.$B', 'Arcydruid Lathorius w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze chce, żebyś $gzabił:zabiła; Harolda Lane\'a.', '', 'Wróć do arcydruida Lathoriusa w Obozowisku D.E.H.T.A. w Boreańskiej Tundrze.', '', '', '', '', 0),
(11893, 'plPL', 'Moc żywiołów', 'Ciągle próbowałem wytłumaczyć temu głupiemu goblinowi, że jego maszyny są zawodne.$B$BAle moc żywiołów – ona jest głęboka i trwała. Gdy skończę naukę, będę władał ich pełną mocą. To, co wiem teraz, powinno jednak wystarczyć, by pomóc naszemu przyjacielowi Fezzixowi.$B$BWeź ten totem duszy wiatru i postaw go w pobliżu któregoś z parowych furiatów na zachód od wioski. Totem zbierze energię zabitych żywiołaków. Przynieś mi w pełni naładowany totem, a resztą zajmę się ja.', 'Dorain Mroźne Kopyto w Wiosce Taunka\'le chce, żebyś za pomocą totemu duszy wiatru $gzebrał:zebrała; energię 10 parowych furiatów.', '', 'Wróć do Doraina Mroźnego Kopyta w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Zebrana energia', '', '', '', 0),
(11894, 'plPL', 'Łatanie', 'Pamiętasz tę gnomią taśmę klejącą, którą mi $gprzyniosłeś:przyniosłaś;?$B$BOtóż znalazłem dla niej zastosowanie. Kadłub tej latającej maszyny jest miejscami tak poobijany, że będę musiał go wzmocnić, jeśli w ogóle mam nadzieję polecieć.$B$BDorain mówi, że taunka robią wodoszczelne pojemniki ze skóry karibu wyprawionej parą. Bagienne karibu żyją wszędzie wokół wioski i na Równinach Zalewowych na południu. Zdobądź najlepsze skóry, jakie znajdziesz, i wypraw je nad otworami parowymi na Polach Gejzerów.', 'Fezzix Skręttryb w Wiosce Taunka\'le chce, żebyś $gprzyniósł:przyniosła; mu 5 skór wyprawionych parą.', '', 'Wróć do Fezzixa Skręttryba w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11895, 'plPL', 'Opanuj burzę', 'Z tego, co opisujesz, z tymi metalowymi stworami łatwo sobie poradzimy. Ale najpierw musisz opanować burzę.$B$BZa mną, w chacie, stoi totem. Gdy będziesz $ggotów:gotowa;, skup na nim swoją wolę, a burza nadejdzie. Musisz pokonać burzę i w ten sposób wchłonąć jej esencję.$B$BJeśli będą tam inni, wystarczy, że pokonacie ją wspólnie. Potem wróć do mnie, $N.', 'Pokonaj burzową nawałnicę, a następnie wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le.', '', 'Wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Burza opanowana', '', '', '', 0),
(11896, 'plPL', 'Słabość do błyskawic', 'Masz teraz w sobie moc burzy. Dam ci środek, by skupić tę moc i osłabić roboty w sadzawkach.$B$BWeź ten piorunochron. Użyj go przeciwko mechanicznym tworom mechagnomów, które znajdziesz w rozległym rejonie sadzawek na zachodzie. Nie przejmuj się używaniem go na samych mechagnomach – Wszechmatka Taiga ma wobec nich inne plany.$B$BGdy moc burzy osłabi roboty, rozbierz je doszczętnie!', 'Gdy roboty będą osłabione Mocą burzy, zniszcz 15 dowolnych maszyn – z wyjątkiem mechagnomów – w rozległym rejonie sadzawek wokół Przepompowni Fizzcranka.$B$BNastępnie wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le.', '', 'Wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Osłabione i zniszczone roboty', '', '', '', 0),
(11897, 'plPL', 'Zatkać zapadliska', 'Plaga ani myśli odpuścić, $N. To przez te przeklęte zapadliska – o ile wiemy, łączą się z tunelami ciągnącymi się aż do Lodowej Korony. Drążą je olbrzymie nieumarłe czerwie, ryjąc pod ziemią.$B$BJeśli czegoś nauczyły mnie lata w kopalni, to tego, że bez belek podporowych tunele po wybuchu łatwo się zawalają.$B$BWeź te materiały wybuchowe i podłóż je u wejść do zapadlisk na grani za plażą na zachodzie. Wróć, gdy je zawalisz.', 'Sierżant Hammerhill chce, żebyś za pomocą zapalających materiałów wybuchowych $gzawalił:zawaliła; zapadliska na południowy zachód i północny zachód od Twierdzy Walecznych.', '', 'Wróć do sierżanta Hammerhilla w Twierdzy Walecznych w Boreańskiej Tundrze.', 'Materiały wybuchowe podłożone w południowym zapadlisku', 'Materiały wybuchowe podłożone w północnym zapadlisku', '', '', 0),
(11898, 'plPL', 'Przełamanie', 'Na najniższym poziomie Świątynnego Miasta stoi szary ołtarz skąpany w świetle. Wejdź w niego, by dostać się do przerażającej nekropolii Naxxanar.$B$BUważaj, $N. Księcia Valanara z pewnością będą bronić jego osobiści słudzy, gotowi oddać życie, by nie dopuścić cię na najwyższy poziom nekropolii.$B$BMusisz przedrzeć się przez nekropolię aż do siedziby księcia. Jeśli go nie pokonasz, $N, obawiam się, że mój lud nigdy nie zazna bezpieczeństwa, jakie daje Lodowa Mgła.', 'Pokonaj księcia Valanara i jego zastępców, Vanthryna Bezlitosnego i Luthiona Nikczemnego, a następnie złóż raport wodzowi Zimowej Wichurze w Wiosce Taunka\'le.', '', 'Wróć do wodza Zimowej Wichury w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11899, 'plPL', 'Dusze uwolnionych od klątwy', 'Mechagnomy w sadzawkach na zachodzie są dla nas wielką zagadką. Pojawiły się niedługo po tym, jak gnomy zniknęły ze swojej przepompowni i jej okolic.$B$BTo nienaturalne zagrożenie i trzeba się z nim rozprawić.$B$BWeź ten łapacz dusz i użyj go na szczątkach mechagnomów, by pochwycić ich dusze. Gdy wrócisz, uwolnimy je, byśmy mogli się dowiedzieć, co się stało.', 'Użyj łapacza dusz Wszechmatki, by pochwycić dusze 10 mechagnomów Fizzcranka. Gdy to zrobisz, wróć do Wszechmatki Taigi w Wiosce Taunka\'le.', '', 'Wróć do Wszechmatki Taigi w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Pochwycona dusza gnoma', '', '', '', 0),
(11900, 'plPL', 'Odczyt przyrządów', 'Miałem nadzieję, że wpływ Nexusa ogranicza się do tego regionu. Ostatnio jednak z całego Azeroth napływają meldunki, według których niestabilność geologiczna rośnie wykładniczo!$b$bPotrzebuję regularnych pomiarów Nexusa, podczas gdy pracuję nad rozwiązaniem.$b$bRozmieściłem w Mrozarze czułe przyrządy, zamaskowane jako wróżebne kule Malygosa. Jeden leży w rowie przy Nexusie, a trzy są ukryte w budowlach na obrzeżach doliny. Odwiedź każdy z nich i przynieś mi ich odczyty.', 'Arcymag Berinand przy Tarczy Transitus poprosił cię, żebyś $gzebrał:zebrała; odczyty z jego przyrządów w Mrozarze.', '', 'Wróć do arcymaga Berinanda przy Tarczy Transitus w Boreańskiej Tundrze.', 'Odczyt geologiczny z Nexusa', 'Odczyt z południowej Mrozarry', 'Odczyt z północnej Mrozarry', 'Odczyt z zachodniej Mrozarry', 0),
(11901, 'plPL', 'Wojsko? Jakie wojsko?', 'Wszędzie jest Plaga, $N. Zorganizowaliśmy rolników i górników w milicję, ale to po prostu nie wystarczy.$B$BJedyny oddział, który przysłała Twierdza Walecznych, broni kopalni. Od kilku dni nie mamy od nich żadnych wieści!$B$BJeśli naprawdę chcesz nam pomóc, może pójdziesz do kopalni i sprawdzisz, co się dzieje? Może uda się nam ściągnąć od nich jakieś posiłki.', 'Gerald Green w Dalekich Włościach chce, żebyś $gwszedł:weszła; do kopalni na północy i $gsprawdził:sprawdziła;, co się stało z oddziałem wojska, który tam wysłano.', '', '', '', '', '', '', 0),
(11902, 'plPL', 'Zgubny dowód', 'Z worków zboża bije ohydny odór, który zdążył ci się już skojarzyć z zarazą. To zapewne wyjaśnia, co spotkało piechurów broniących kopalni.$B$BLepiej zanieś tę wiadomość Geraldowi Greenowi.', 'Wróć do Geralda Greena w Dalekich Włościach.', '', '', '', '', '', '', 0),
(11903, 'plPL', 'Czas działać', 'No cóż, $N. Skoro ostatni żołnierze w Dalekich Włościach nie żyją albo spotkało ich coś gorszego, pozostaje nam tylko jedno: sami musimy walczyć z Plagą.$B$BRozmieściliśmy milicję w tym, co zostało z Dalekich Włości. Bez twojej pomocy mają niewielkie szanse na zwycięstwo. Idź i podaj im pomocną dłoń. Ja z chłopakami będę pilnował tej ścieżki. Nie możemy pozwolić, żeby Plaga się przedarła!', 'Gerald Green w Dalekich Włościach chce, żebyś $gzabił:zabiła; 14 zarażonych padlinożerców.', '', 'Wróć do Geralda Greena w Dalekich Włościach w Boreańskiej Tundrze.', '', '', '', '', 0),
(11904, 'plPL', 'Owoce naszej pracy', 'Plaga wciąż nadciąga... ale nie możemy się poddać! Słuchaj, $N. W tamtej kopalni stoi wózek z ostatnią rudą, jaką Przymierze na długo zobaczy po tej stronie kontynentu.$B$BKłopot w tym, że zwolnienie wózka jest zablokowane. Gdy wojsko tam weszło, kapitan Jacobs zarekwirował cały ważny sprzęt, w tym klucz zwalniający wózek.$B$BZaraza, która dotknęła żołnierzy w kopalni, musiała dopaść także Jacobsa. Zabierz mu klucz i ocal rudę.', 'Idź do kopalni w Dalekich Włościach, zdobądź klucz zwalniający wózek od kapitana Jacobsa i użyj go, by zwolnić wózek z rudą. Gdy to zrobisz, wróć do Geralda Greena w Dalekich Włościach.', '', 'Wróć do Geralda Greena w Dalekich Włościach w Boreańskiej Tundrze.', 'Zwolniony wózek z rudą', '', '', '', 0),
(11905, 'plPL', 'Odwlekanie nieuniknionego', 'Ustaliłem przyczynę niestabilności!$b$bLinie mocy Azeroth są przekierowywane do Nexusa. To fascynujące! Gdybym tylko mógł spędzić resztę swoich dni na badaniu tej anomalii....$b$bNiestety, muszę się skupić na bieżącym kryzysie. Napływ tajemnej energii rozdziera szczelinę między wymiarami.$b$bGłęboko w Nexusie tkanka naszego wszechświata słabnie. Nie mogę tego powstrzymać, ale odkryłem sposób, by to spowolnić.$b$bZanieś to do Nexusa i uruchom w pobliżu powstającej szczeliny.', 'Arcymag Berinand przy Tarczy Transitus chce, żebyś $gużył:użyła; międzywymiarowego refabrykatora w pobliżu szczeliny w Nexusie.', '', 'Wróć do arcymaga Berinanda przy Tarczy Transitus w Boreańskiej Tundrze.', 'Zatrzymana szczelina międzywymiarowa', '', '', '', 0),
(11906, 'plPL', 'Sprzątanie sadzawek', '<Po twarzy Żelaznych Oczu spływa pojedyncza łza.>$B$BSłyszałem, że wracasz do sadzawek na zachodzie. Mam dla ciebie zadanie na czas tej wyprawy, $N.$B$BGnomy, które nie dbają o ziemię, zanieczyściły ją swoimi maszynami. Chcę, żebyś $gzbierał:zbierała; wszystkie części zamienne, na jakie się natkniesz.$B$BPrzynieś je do mnie. Dopilnuję, by pozbyto się ich jak należy, zanim na dobre opuścimy to miejsce.', 'Zbierz 15 części zamiennych Fizzcranka i dostarcz je Żelaznym Oczom w Wiosce Taunka\'le.', '', 'Wróć do Żelaznych Oczu w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11907, 'plPL', 'Podwodzowie', 'Wiadomo, że Mistrz Trybów Mechazod ma czterech podwodzów, którzy zarządzają robotami w sadzawkach.$B$BMusimy z nimi skończyć!$B$BNasi biegacze i tropiciele śniegu mówią, że jeśli przekręcisz zawory przy Stacji Zachodniej, Północnej, Środkowej i Południowej, każdy z jego podwodzów szybko się zjawi, żeby nie dopuścić do sabotażu.$B$BStacje znajdują się tam, gdzie kręcą się światła w sadzawkach wokół przepompowni.$B$BPośpiesz się, $N!', 'Pokonaj Twonky\'ego, ED-210, Maxa Blasto i Mielacza, a następnie złóż raport Mędrcowi Ziemi i Niebu w Wiosce Taunka\'le.', '', 'Wróć do Mędrca Ziemi i Nieba w Wiosce Taunka\'le w Boreańskiej Tundrze.', '', '', '', '', 0),
(11908, 'plPL', 'Materiały źródłowe', 'Odpowiadałem za golemy zbożowe – ważna robota, dopóki Plaga nie zniszczyła większości naszych pól. Mam jednak pomysł, jak sprawić, by golemy znów się do czegoś przydały.$B$BChyba zdołam przerobić zbieracze plonów tak, żeby pomogły nam w walce z Plagą.$B$BNie jestem jeszcze w tym ekspertem, więc będę potrzebował swojego podręcznika. Kłopot w tym, że zostawiłem go w warsztacie... a to akurat ten płonący budynek obok kopalni. Dasz radę go stamtąd wyciągnąć?', 'Jeremiah Hawning chce, żebyś $gwydobył:wydobyła; książkę „Pola, fabryki i warsztaty” z płonącego budynku obok kopalni w Dalekich Włościach.', '', 'Wróć do Jeremiaha Hawninga w Dalekich Włościach w Boreańskiej Tundrze.', '', '', '', '', 0),
(11909, 'plPL', 'Pokonaj Mistrza Trybów', 'Najwyraźniej ten Mistrz Trybów Mechazod postradał zmysły. Jeśli jego obietnica lekarstwa i nieśmiertelności oznacza, że wszyscy staniemy się mechanicznymi niewolnikami, to trzeba go powstrzymać!$B$BWiatry, które mnie prowadzą, szepczą, że jest na szczycie przepompowni pośrodku sadzawek na zachodzie.$B$BNajpewniej znajdziesz go w chacie dowodzenia na szczycie budowli. Wejdź do środka i zbadaj jego dzieła.$B$B$N, musisz stawić czoła Mechazodowi, jeśli mamy przetrwać!', 'Przestudiuj Podręcznik Mistrza Trybów i przynieś głowę Mechazoda Wszechmatce Taidze w Wiosce Taunka\'le.', '', 'Wróć do Wszechmatki Taigi w Wiosce Taunka\'le w Boreańskiej Tundrze.', 'Przestudiowano Podręcznik Mistrza Trybów', '', '', '', 0),
(11910, 'plPL', 'Sekrety Pradawnych', 'Stało się jasne, że niestabilność regionu wpłynęła na tutejsze stworzenia.$b$bSzczególnie zainteresowały mnie lodowcowe pradawne i ich niedawne przystosowania. Podejrzewam, że ich przemiana w pradawnych „spętanych magią” może skrywać wskazówki co do naszego położenia.$b$bDo badań potrzebuję próbek od obu. Pośpiesz się, proszę....', 'Arcymag Berinand przy Tarczy Transitus chce, żebyś $gzebrał:zebrała; 3 lodowcowe drzazgi i 3 drzazgi spętane magią z pradawnych w Mrozarze.', '', 'Wróć do arcymaga Berinanda przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11911, 'plPL', 'Ożywienie', 'Choć być może jesteśmy świadkami końca naszego istnienia, nie mogę się nadziwić. Przez ten krótki czas tutaj nauczyłem się więcej niż przez dziesięciolecia studiów.$b$bTe pradawne są wystawione na niewiarygodne dawki tajemnej energii. To dosłownie przemienia je w coś... innego.$b$bJestem pewien, że ich metamorfoza ma jeszcze jeden etap. Musisz wejść do samego Nexusa, $n, i znaleźć dla mnie dowody na ich ostateczną postać.$b$bUważaj na siebie....', 'Arcymag Berinand przy Tarczy Transitus chce, żebyś $gwszedł:weszła; do Nexusa i $gzebrał:zebrała; 5 tajemnych drzazg z krystalicznych obrońców.', '', 'Wróć do arcymaga Berinanda przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11912, 'plPL', 'Jagodowy szał', 'Och! Co za ulga zobaczyć nową twarz. Zaczynałam już myśleć, że nas opuszczono.$b$bKilka dni temu odcięto nam linie zaopatrzenia i sytuacja wygląda... cóż, ponuro. Prawdę mówiąc, jak dla mnie od początku była to misja samobójcza.$b$bMoże po prostu nie nadaję się do całej tej przemocy – nie wspominając o przenikliwym zimnie! Wolałabym być z powrotem w Dalaranie i studiować starożytne teksty.$b$bDo rzeczy: nasze zapasy żywności prawie się skończyły. Proszę, zbierz, co się da, i przynieś mi.', 'Bibliotekarka Serrah przy Tarczy Transitus chce, żebyś $gzebrał:zebrała; 10 mroźnych jagód z krzaków mroźnych jagód w Mrozarze.', '', 'Wróć do bibliotekarki Serrah przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11913, 'plPL', 'Żadnego ryzyka', 'Słyszałam, co $gpowiedziałeś:powiedziałaś; Geraldowi, i wcale mi się to nie podoba. Skoro kultyści zdołali zatruć zboże w kopalniach swoją plugawą zarazą, równie łatwo mogli zrobić to samo ze zbożem na zewnątrz.$B$BNie mamy czasu oddzielać dobrego ziarna od złego. Musimy działać szybko i spalić wszystko.$B$BWeź tę pochodnię i podpal każdy worek zboża, jaki tu znajdziesz. Byłaby to tragedia, gdybyśmy przetrwali ten atak tylko po to, by potem paść ofiarą zarazy.', 'Wendy Darren chce, żebyś pochodnią Wendy $gspalił:spaliła; 8 worków zboża z Dalekich Włości.', '', 'Wróć do Wendy Darren w Dalekich Włościach w Boreańskiej Tundrze.', 'Spalone zboże z Dalekich Włości', '', '', '', 0),
(11914, 'plPL', 'Strzeż tajemnicy', 'Nasze istnienie tutaj zależy wyłącznie od tego, czy pozostaniemy w ukryciu. Gdyby tarcza zawiodła, choćby na chwilę, sługi Malygosa by nas dopadły.$b$bJednym z moich obowiązków jest odnawianie many magów bojowych, żeby nie osłabło ich skupienie. Odkąd straciliśmy linie zaopatrzenia, muszę improwizować.$b$bPrzydałaby mi się twoja pomoc, $n.$b$bTuż przy Nexusie tajemne węże żywią się obfitą magiczną energią. Po pokonaniu pozostawiają esencję many, z której mogę zrobić użytek.', 'Bibliotekarka Serrah przy Tarczy Transitus potrzebuje, żebyś $gzabił:zabiła; tajemne węże w pobliżu Nexusa i $gzebrał:zebrała; z nich 5 esencji many Nexusa.', '', 'Wróć do bibliotekarki Serrah przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11916, 'plPL', 'Czempion Piekłorycza', '$GStawiłeś:Stawiłaś; czoła każdemu wyzwaniu, jakie przed tobą postawiono, i $gzmiażdżyłeś:zmiażdżyłaś; je obcasem. To dzięki tobie, $N, Horda mocno okopała się w Północnej Grani.$B$BAle nasza praca dopiero się zaczęła. Musimy pomaszerować na Lodową Koronę i zburzyć jej mury!$B$BTwoje następne zadanie zaczyna się na wschodzie, w Wiosce Taunka\'le. Nasi sojusznicy taunka są w rozpaczliwym położeniu i potrzebują pomocy. Załatw sobie transport u stajennego, Durkota Wilczego Brata, i odszukaj wodza Zimową Wichurę w Taunka\'le.', 'Odszukaj wodza Zimową Wichurę w Wiosce Taunka\'le.', '', '', '', '', '', '', 0),
(11918, 'plPL', 'Szkolenie podstawowe', 'To wojna, śmiertelniku, a my jesteśmy grotem włóczni.$b$bWasze drobne sprzeczki o ziemię czy pieniądze bledną wobec tego konfliktu. Stajemy przeciwko aspektowi Malygosowi i całemu jego Błękitnemu Stadu. Musisz wiedzieć tylko tyle, że jeśli zwycięży, ten świat przestanie istnieć.$b$bJest nas tu niewielu, a latamy przeciw wielu. Nasza śmierć jest niemal pewna, a naszym ostatecznym sukcesem jest jedynie opóźnienie wroga.$b$bIdź teraz. Zajmij się czymś, a ja zdecyduję, co z tobą zrobić.', 'Raelorasz przy Tarczy Transitus chce, żebyś $gzabił:zabiła; 10 tkaczek zaklęć z Mrozarry.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11919, 'plPL', 'Polowanie na smoki', 'Błękitni zaczęli pokrywać swoje smoki tajemniczymi runami. Muszę odkryć ich znaczenie.$b$b<Raelorasz nakłuwa sobie dłoń włócznią i pokrywa jej grot swoją krwią.>$b$bWeź to i użyj na jednym z nich. Poczekaj, aż zostanie obezwładniony, a potem przyprowadź go do mnie, zanim wyzionie ducha.$b$bIch pisklęta żerują przy północno-zachodnim skraju doliny.', 'Raelorasz chce, żebyś włócznią Raelorasza $gobezwładnił:obezwładniła; pisklę smoka Nexusa i $gprzyprowadził:przyprowadziła; je do niego przy Tarczy Transitus.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Pojmany smok Nexusa', '', '', '', 0),
(11920, 'plPL', 'Kultyści wśród nas', 'Ten ołtarz nosi wszystkie znamiona Kultu Potępionych. Wygląda na to, że fanatycy z kontynentu przedostali się do Północnej Grani. Rozsądnie byłoby powiadomić kapitana statku.$B$BByć może jest na górnym pokładzie.', 'Porozmawiaj z kapitanem „Mańkutem” Lugsailem na pokładzie „Łamacza Burz” w Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11927, 'plPL', 'Ludzie gadają', 'Hej, $N. W gospodzie jest dziewczyna, która o ciebie wypytuje. Ma na imię Leryssa.$B$BChyba cię nie zna, ale mówiła, że potrzebuje twojej pomocy. Wydawała się naprawdę zrozpaczona.', 'Odszukaj Leryssę w gospodzie w Twierdzy Walecznych', '', '', '', '', '', '', 0),
(11928, 'plPL', 'Dalekie Włości', 'Moi chłopcy powinni już dać sobie radę, $N. Twierdza Walecznych wytrzyma o wiele gorsze lanie. Martwię się jednak o nasze pola i kopalnię w Dalekich Włościach.$B$BTuż przed inwazją wysłaliśmy cały oddział do ochrony naszych kopalń – powinni być w stanie obronić cywilów.$B$BMieszkańcami wioski dowodzi tam Gerald Green. Z północnego muru Twierdzy Walecznych wychodzi przejście, które zaprowadzi cię prosto do niego. Zobacz, jak możesz im pomóc.', 'Udaj się do Dalekich Włości w Boreańskiej Tundrze i porozmawiaj z Geraldem Greenem.', '', '', '', '', '', '', 0),
(11929, 'plPL', 'Upadek Wioski Taunka\'le', 'Jesteśmy zgubieni, $N. To miejsce od wielu pokoleń było naszym domem, ale nie jest już bezpieczne. Została tu tylko śmierć... śmierć i wspomnienie tego, co było.$B$BZarządziłem ewakuację Taunka\'le. Wszyscy pozostali taunka muszą natychmiast wyruszyć do naszej stolicy, Wioski Lodowej Mgły, na Smoczych Pustkowiach.$B$B<Zimowa Wichura wskazuje na wschód.>$B$BMusisz pomóc mojemu ludowi dotrzeć w bezpieczne miejsce, $N. Matka Tauranook czeka na ciebie przy bramie wioski. Pośpiesz się! Plaga nadciąga ze wszystkich stron!', 'Porozmawiaj z Matką Tauranook przed bramą Wioski Taunka\'le.', '', '', '', '', '', '', 0),
(11930, 'plPL', 'Przez Transboreę', 'Droga przez Transboreę, na wschodzie, to jedyny sposób, by dotrzeć na Smocze Pustkowia. W wędrówce przez tundrę czyha na ciebie wiele niebezpieczeństw. Strzeż się Plagi i jej wpływu na tutejsze zwierzęta. Zaczęły krążyć plotki, że nasi bracia i siostry taunka powstają z martwych i napadają na karawany zmierzające na Smocze Pustkowia! Broń swojej karawany i doprowadź ewakuowanych w bezpieczne miejsce!$B$BWartook Zrodzony z Lodu czeka na ciebie za mostem prowadzącym na Smocze Pustkowia.', 'Eskortuj ewakuowanych z Taunka\'le przez Transboreę do Wartooka Zrodzonego z Lodu na granicy Smoczych Pustkowi.$B', 'Zapewnij bezpieczne przejście na Smocze Pustkowia', 'Wróć do Wartooka Zrodzonego z Lodu na Smoczych Pustkowiach.', '', '', '', '', 0),
(11931, 'plPL', 'Łamanie szyfru', 'Wyczuwam w tutejszych smokach wyraźną osobliwość, lecz znaczenie run pokrywających ich ciała wciąż mi umyka.$b$bBez kodeksu ich odczytanie zajmie mi więcej czasu, niż możemy sobie pozwolić.$b$bNiedaleko stąd przebywa zdrajca Kirin Toru, Caleras, który najpewniej ma egzemplarz potrzebnej mi księgi. Jego podwładni mają przy sobie runy, których będę potrzebował do tłumaczenia.$b$bPośpiesz się, śmiertelniku. Malygos z każdą chwilą rośnie w siłę.', 'Raelorasz przy Tarczy Transitus chce, żebyś $gzdobył:zdobyła; Lazurowy kodeks od inkwizytora Calerasa i $gzebrał:zebrała; 3 migoczące runy od jego zaklinaczy z Mrozarry.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11932, 'plPL', 'Tchórze i głupcy', 'Słuchaj, $N. Bez urazy, ale operacja, którą powierzono Thassarianowi, to było czyste samobójstwo.$B$BGarstka naszych ludzi miała przypuścić atak na największe skupisko Plagi w okolicy. Nazwij mnie wariatem, ale szturm na ziggurat Plagi pod zarażonym nerubiańskim miastem z tuzinem ludzi to nie jest moje wyobrażenie dobrej zabawy.$B$BJeśli wciąż chcesz znaleźć Thassariana – mieliśmy załatwić przeprawę na wschód u kiełzara imieniem Ataika w Kaskali, na północnym wschodzie. Powodzenia w tej samobójczej misji.', 'Porozmawiaj z Ataiką w Kaskali, na północny wschód od Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(11936, 'plPL', 'Wylęganie planu', 'Nasze cele tutaj są proste. Mamy pozostać w ukryciu przed Malygosem, obserwować jego potomstwo i w miarę możliwości krzyżować jego plany. W tym celu mam dla ciebie zadanie.$b$bBłękitni składają jaja u podnóża Nexusa. Wystawienie na tak wielką dawkę tajemnej energii z pewnością przyspieszy ich wylęg, a nie wiadomo, jak wpłynie na ich młode.$b$bNie zamierzam się przekonywać. Zabij miejscowych smokorodnych i rozbij jaja ich zamrożonymi toporami.', 'Raelorasz przy Tarczy Transitus chce, żebyś $gzabił:zabiła; smokorodnych z Mrozarry i ich zamrożonymi toporami $grozbił:rozbiła; 5 jaj niebieskich smoków.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Zniszczone smocze jaja', '', '', '', 0),
(11938, 'plPL', 'Na zwłokę', 'Skoro mamy już tę filakterię, nie powinienem mieć kłopotu ze zdobyciem potrzebnych informacji. Plaga w Świątynnym Mieście szybko się jednak zorientuje, że coś jest nie tak.$B$BNie odeprę tu zmasowanego ataku. A może bym odparł... ale wolę się nie przekonywać.$B$BChcę, żebyś $gzszedł:zeszła; tam na dół i $gzadał:zadała; im trochę strat. Miejmy nadzieję, że zajmie ich to na tyle długo, by ci dwaj wyśpiewali wszystko... w przenośni, oczywiście. Weź ze sobą Lurida, może się przydać.', 'Thassarian w Zawodzącym Zigguracie w Boreańskiej Tundrze chce, żebyś $gzadał:zadała; Pladze 20 strat w Świątynnym Mieście En\'kilah. Jeśli potrzebujesz pomocy, użyj kości Lurida.', '', 'Wróć do Thassariana w Zawodzącym Zigguracie w Boreańskiej Tundrze.', 'Straty w En\'kilah', '', '', '', 0),
(11939, 'plPL', '?????', '', '', '', '', '', '', '', '', 0),
(11940, 'plPL', 'Polowanie na smoki', 'Potrzebuję więcej smoczych piskląt, by kontynuować badania nad runami pokrywającymi ich ciała.$b$bMożna je znaleźć przy północno-zachodnim skraju doliny....$b$b<Raelorasz nakłuwa sobie dłoń włócznią i pokrywa jej grot swoją krwią.>$b$bWeź to i użyj na jednym z nich. Poczekaj, aż zostanie obezwładniony, a potem przyprowadź go do mnie, zanim wyzionie ducha.', 'Raelorasz chce, żebyś włócznią o zakrwawionym grocie $gobezwładnił:obezwładniła; pisklę smoka Nexusa i $gprzyprowadził:przyprowadziła; je do niego przy Tarczy Transitus.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Pojmany smok Nexusa', '', '', '', 0),
(11941, 'plPL', 'Zagadkowe...', 'Coś w tym kawałku metalu sprawia, że nie potrafisz go wyrzucić.$b$bMoże Raelorasz rzuci nieco światła na jego przeznaczenie.', 'Zanieś skrzący się odłamek Raeloraszowi przy Tarczy Transitus.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11942, 'plPL', 'Słowa mocy', 'Lisz przemówił, $N. Arcykapłani En\'kilah znają sekret wejścia do Naxxanaru.$B$BUdaj się do Iglicy Krwi, Iglicy Bólu i Iglicy Rozkładu i zabij każdego z kapłanów.$B$BWróć, gdy zdobędziesz wszystkie trzy zwoje.', 'Thassarian w Zawodzącym Zigguracie chce, żebyś $gudał:udała; się do Świątynnego Miasta En\'kilah i $gzdobył:zdobyła; zwój arcykapłana Talet-Khy z Iglicy Bólu, zwój arcykapłana Nafersetu z Iglicy Rozkładu i zwój arcykapłana Andoratha z Iglicy Krwi.', '', 'Wróć do Thassariana w Zawodzącym Zigguracie w Boreańskiej Tundrze.', '', '', '', '', 0),
(11943, 'plPL', 'Cela', '$GOdkryłeś:Odkryłaś; fragment szczególnego więzienia, $n.$b$bSługi Malygosa używają podobnych więzień, by trzymać w nich pojmanych magów i inne tajemne istoty, ale to więzienie zbudowano, by uwięzić coś... potężniejszego.$b$bW nadziei, że wróg naszego wroga okaże się przyjacielem, musisz odszukać pozostałe fragmenty więzienia.$b$bNajpewniej mają je najbardziej zaufani podwładni Malygosa.', 'Raelorasz przy Tarczy Transitus chce, żebyś $gzdobył:zdobyła; obudowę więzienia od generała Ceruleana i rdzeń energii od Siewcy wojny Goredraka.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11944, 'plPL', 'Otoczeni!', 'Nasze położenie jest niemal beznadziejne. Rozkazano nam zdobyć Zawodzący Ziggurat garstką ludzi.$B$BBędziemy mieli szczęście, jeśli utrzymamy tę pozycję przed Plagą. Jest ich więcej, jesteśmy ranni i nie mamy drogi ucieczki.$B$BJeśli zdejmiesz z nas choć część nacisku, może zdołamy umocnić pozycję. Zabij trochę nieumarłych krążących wokół budowli – my powstrzymamy ich natarcie.', 'Kapral Venn w Reducie Śmierci chce, żebyś $gzabił:zabiła; 7 obrońców ziggurata.', '', 'Wróć do kaprala Venna w Reducie Śmierci w Boreańskiej Tundrze.', '', '', '', '', 0),
(11945, 'plPL', 'Na najgorsze', 'Nastały mroczne czasy. Duch Karkuta chodzi po ziemi i zbiera duchy zmarłych kiełzarów.$B$BSynowie mgły zabrali wielu naszych braci. Wkrótce ukochana Kaskala obróci się w popiół.$B$BAle wciąż jest nadzieja. Może nie dla nas, ale wysłaliśmy nasze rodziny do Unu\'pe. Walczymy tutaj, by one miały przyszłość.$B$BBędą potrzebować zapasów, inaczej umrą z głodu. W Unu\'pe nie ma dość jedzenia. Ocal, co się da, zanim będzie za późno dla naszych rodzin.', 'Utaik chce, żebyś $gzebrał:zebrała; 8 zapasów z Kaskali w Kaskali.', '', 'Wróć do Utaika w Kaskali w Boreańskiej Tundrze.', '', '', '', '', 0),
(11946, 'plPL', 'Keristrasza', 'Jestem... wolna?$b$bByło mi pisane przez wieczność błąkać się w pustej otchłani, a teraz jestem ocalona? Nie pojmiesz mojej wdzięczności, śmiertelniku.$b$bGdy odmówiłam poddania się jego woli, Malygos zamknął mnie w tym więzieniu, a potem je roztrzaskał i rozrzucił fragmenty. Choćbym żyła sto waszych żywotów, nie zapomnę tej dobroci.$b$bByć może z czasem znajdę sposób, by ci się odwdzięczyć. Na razie jednak musimy skupić się na Malygosie. Jestem słaba, a jest wiele do zrobienia.$b$bPotrzebuję twojej pomocy, $n.', 'Keristrasza chce, żebyś z nią $gporozmawiał:porozmawiała;, gdy będziesz $ggotów:gotowa; przygotować się do starcia z Malygosem.$b$bJeśli zgubisz wzmocnione tajemne więzienie, porozmawiaj z Raeloraszem przy Tarczy Transitus.', '', '', '', '', '', '', 0),
(11949, 'plPL', 'Nie bez walki!', 'Kaskala to dla nas święte miejsce, $N. Naszych przodków przywiódł tu sam duch Tayutki.$B$BTeraz te plugawe stwory atakują nas z mgieł bez żadnego powodu.$B$BPokażemy im, że nasze włócznie służą nie tylko do polowania na wieloryby. Walcz u naszego boku, przyjacielu. Może kiedyś mój lud zdoła ci się odwdzięczyć.', 'Ataika chce, żebyś $gzabił:zabiła; 12 łupieżców kvaldirów w Kaskali.', '', 'Wróć do Ataiki w Kaskali w Boreańskiej Tundrze.', '', '', '', '', 0),
(11950, 'plPL', 'Mądrość Muahita', 'Słuchaj, $N. Wojowników takich jak ja można zastąpić. Jeśli padnę, moi bracia i kuzyni podniosą moją włócznię i będą walczyć.$B$BAle mój lud nie przetrwa bez mądrych starszych. Uparty Muahit, nasz najczcigodniejszy szaman, nie chce opuścić ołtarza Tayutki na środkowej wyspie. Ponieślibyśmy ogromną stratę, gdyby zabiły go te potwory.$B$BJesteś kimś z zewnątrz, może ciebie posłucha. Przemów mu do rozsądku... poproś, by uciekł do bezpiecznego Unu\'pe, zanim będzie za późno.', 'Odszukaj Starszego Muahita w Kaskali.', '', '', '', '', '', '', 0),
(11951, 'plPL', 'Przynęta i podmiana', 'W niewoli zdołałam wiele się dowiedzieć o Malygosie. Los pozwala nam teraz wykorzystać tę wiedzę przeciwko niemu.$b$bWysoko nad Nexusem krąży wielka błękitna smoczyca, Saragosa. Jest zarówno strażniczką aspektu, jak i jego małżonką. Gdy pojawia się poważne zagrożenie, ostrzega swojego pana.$b$bW niewoli wiele wycierpiałam z ręki Saragosy, a teraz nadszedł czas jej śmierci. Najpierw jednak musimy przygotować idealną przynętę....', 'Keristrasza poprosiła cię, żebyś $gzebrał:zebrała; w Mrozarze 10 odłamków skrystalizowanej many.$b$bJeśli zgubisz wzmocnione tajemne więzienie, porozmawiaj z Raeloraszem przy Tarczy Transitus.', '', 'Porozmawiaj z Keristraszą w Mrozarze w Boreańskiej Tundrze. Jeśli zgubisz wzmocnione tajemne więzienie, porozmawiaj z Raeloraszem przy Tarczy Transitus.', '', '', '', '', 0),
(11956, 'plPL', 'W poszukiwaniu filakterii', 'Nie ma czasu na pogawędki, $N. Wysłano mnie na misję, która miała być samobójcza – zdobyć ten ziggurat. Wypełniłem swój żołnierski obowiązek, teraz czas zdobyć trochę odpowiedzi.$B$BTen lisz ma wiedzę, której szukam, ale nie mogę zadać bólu jego fizycznemu ciału, by ją z niego wydobyć.$B$BLisz umieścił swoją duszę w filakterii, a dopóki ona pozostaje ukryta, nie zdołam wyciągnąć z niego informacji.$B$BWróć do obozu i weź moją klacz, Zmierzch – zaprowadzi cię do filakterii. Przynieś mi ją.', 'Udaj się do Reduty Śmierci i dosiądź Zmierzch, która zawiezie cię do filakterii Tanathala. Zdobądź ją i zanieś Thassarianowi w Zawodzącym Zigguracie.', '', 'Wróć do Thassariana w Zawodzącym Zigguracie w Boreańskiej Tundrze.', '', '', '', '', 0),
(11957, 'plPL', 'Koniec Saragosy', 'Z kryształów many, które mi $gdostarczyłeś:dostarczyłaś;, stworzyłam ten skupiacz mocy.$b$bSaragosa to łakomczuch. Nie oprze się jego pokusie. Kryje się w nim magia, która znacznie osłabi jej moc. Miejmy nadzieję, że nie przejrzy mojego podstępu....$b$bPrzygotuj się, $n, i porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; stawić czoła Saragosie.$B', 'Keristrasza chce, żebyś za pomocą skupiacza mocy $gzwabił:zwabiła; Saragosę, a następnie ją $gpokonał:pokonała;.', '', 'Wróć do Keristraszy w Mrozarze w Boreańskiej Tundrze. Jeśli zgubisz wzmocnione tajemne więzienie, porozmawiaj z Raeloraszem przy Tarczy Transitus.', '', '', '', '', 0),
(11961, 'plPL', 'Duchy czuwają nad nami', 'Nad moim plemieniem czuwają potężne duchy – Kaskala nie zostanie stracona.$B$BIssliruk doda nam odwagi, Tayutka zadba, by ocaleni zawsze mieli jedzenie i schronienie, a Karkut będzie czuwał nad poległymi, by nie zabłądzili.$B$BTeraz najbardziej potrzebujemy przewodnictwa Issliruka. Poprosiłem mojego bratanka, Iruka, by przyniósł mi totem Issliruka, ale włócznie kvaldirów powaliły go, a jego ciało wpadło do wód na północy. Przynieś mi ten totem, $N. Nie pozwól, by śmierć mojego bratanka poszła na marne.', 'Starszy Muahit w Zatoce Oddechu Njorda chce, żebyś $godnalazł:odnalazła; w wodzie ciało Iruka i $godzyskał:odzyskała; totem Issliruka.', '', 'Wróć do Starszego Muahita w Zatoce Oddechu Njorda w Boreańskiej Tundrze.', '', '', '', '', 0),
(11962, 'plPL', 'Ostatnia dostawa', 'No to tyle. Z resztką rudy, którą $gocaliłeś:ocaliłaś;, mamy wreszcie dość, by wysłać ją do Twierdzy Walecznych.$B$BJeśli Dalekie Włości znikną z powierzchni Azeroth, niech przynajmniej zapamiętają nas jako tych, którzy pierwsi stanęli w obronie swojej ziemi i ostatni się poddali.$B$BZanieś tę rudę Hildzie Kamiennej Kuźni – to moja dobra przyjaciółka. Powiedz jej, żeby wykuła z niej porządną broń. W nadchodzących dniach będziemy jej potrzebować mnóstwo.', 'Dostarcz skrzynię rudy z Dalekich Włości Hildzie Kamiennej Kuźni w Twierdzy Walecznych.', '', 'Wróć do Hildy Kamiennej Kuźni w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(11963, 'plPL', 'Broń dla Dalekich Włości', 'Dalekie Włości są opanowane, a Gerald myśli tylko o tym, żeby wysłać mi dostawę rudy? Przysięgam, ten człowiek ma tyle serca co każdy z naszych żołnierzy na froncie.$B$BNie możemy pozwolić, by cywile stracili swoje ziemie, skoro są gotowi o nie walczyć. Może nie mamy wolnych żołnierzy, ale możemy im wysłać broń.$B$BTa była przeznaczona dla nowych rekrutów, ale dla nich wykuję nową z rudy, którą mi $gprzyniosłeś:przyniosłaś;. Daj znać Geraldowi, że broń jest w drodze.', 'Wróć do Geralda Greena w Dalekich Włościach.', '', '', '', '', '', '', 0),
(11965, 'plPL', 'Do broni!', 'Dalekie Włości mają teraz szansę w walce, $N. Tylko o to mogliśmy prosić, a ty to $gumożliwiłeś:umożliwiłaś;.$B$BPotrzebujemy jeszcze tylko miejsca zbiórki. Każę moim ludziom zanieść broń do ratusza. Idź i uderz w dzwon ratusza, żeby ci, którzy przeżyli, wiedzieli, że mają się tam zebrać.$B$BCzas pokazać Pladze, z jakiej gliny jesteśmy ulepieni.', 'Idź do ratusza w Dalekich Włościach i uderz w dzwon, który się w nim znajduje.', '', 'Wróć do Geralda Greena w Dalekich Włościach w Boreańskiej Tundrze.', 'Dzwon Dalekich Włości uderzony', '', '', '', 0),
(11967, 'plPL', 'Zbiórka czerwonych', 'Malygos z pewnością wie, że coś jest nie tak.$b$bZnam go. Jego uwaga jest rozproszona. Jestem pewna, że zdołam wywabić go z bezpiecznego królestwa, gdy dowie się, co spotkało jego ukochaną Saragosę.$b$bZabierz mnie natychmiast do Raelorasza, $n. Musi poderwać do walki z Malygosem każdego smoka pod swoim dowództwem.', 'Keristrasza poprosiła, żebyś $gzaprowadził:zaprowadziła; ją do Raelorasza przy Tarczy Transitus.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(11968, 'plPL', 'Odwrócenie losów', 'Duchy usłyszały nasze wołanie o pomoc, $N. To znak, że Kaskalę wciąż można ocalić.$B$BWykorzystaj zamęt wywołany przez pogodę i zabij przywódcę kvaldirów. Twój czyn przechyli szalę bitwy na naszą korzyść, jestem tego pewien.', 'Starszy Muahit chce, żebyś $gzabił:zabiła; Heigarra Okropnego w Zatoce Oddechu Njorda.', '', 'Wróć do Starszego Muahita w Zatoce Oddechu Njorda w Boreańskiej Tundrze.', '', '', '', '', 0),
(11969, 'plPL', 'Zatrzaśnięcie pułapki', 'Tę szansę w dużej mierze zawdzięczamy twoim wysiłkom, $n.$b$bSłusznie więc, byś to ty $grozpoczął:rozpoczęła; atak na Malygosa.$b$bWeź tę iskrę i rozpal nią ognisko sygnałowe na północny zachód od Nexusa. Dalej pokieruje tobą Keristrasza.', 'Raelorasz chce, żebyś $gużył:użyła; iskry Raelorasza przy ognisku sygnałowym w Mrozarze.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Malygos zwabiony', '', '', '', 0),
(11973, 'plPL', 'Jeniec wojenny', 'Malygos zabrał Keristraszę, by uczynić ją swoją małżonką!? To nie do pomyślenia!$b$bNigdy nie będzie z nim współpracować z własnej woli, ale Malygos to potężny aspekt i w końcu nagnie jej wolę.$b$bDo tego nie może dojść, $n. Nie pozwolę, by spotkało ją takie upokorzenie.$b$bMusisz wejść do Nexusa i zrobić wszystko, co trzeba, by oszczędzić jej tego losu.', 'Raelorasz przy Tarczy Transitus chce, żebyś $gwszedł:weszła; do Nexusa i $guwolnił:uwolniła; Keristraszę.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Keristrasza zaznała spoczynku', '', '', '', 0),
(11992, 'plPL', 'Mapy nawigacyjne (Deprecated)', '$GOdkryłeś:Odkryłaś; pierwszą część mapy nawigacyjnej narysowanej na zdartej smoczej skórze. Gdyby udało ci się ją skompletować, $gmógłbyś:mogłabyś; poznać plany przyszłych ataków kvaldirów.$B$BBrakujące części mogą mieć przy sobie inni żeglarze z Ruin Smagaczy. Karuka zainteresowałyby zawarte w nich informacje.', 'Zdobądź brakujące części mapy nawigacyjnej Skadirów i zanieś ją Karukowi na Wybrzeżu Smagaczy.', '', 'Wróć do Karuka w Boreańskiej Tundrze.', '', '', '', '', 0),
(12019, 'plPL', 'Ostatnie namaszczenie', 'Po śmierci służyłem Arthasowi, bo nie miałem wyboru. Władał moją wolą i moim ciałem. Kult Potępionych służy Arthasowi za życia... z własnej woli.$B$BSkoro znamy już słowa mocy otwierające wejście do Naxxanaru, możemy położyć kres tej kultystowskiej zarazie. Idź do En\'kilah i poszukaj kuli teleportacyjnej pod lewitującą cytadelą.$B$BPrzedrzyj się na górę i spotkaj się ze mną na szczycie. Uzbrój się w całą odwagę, na jaką cię stać, bo możemy nie wyjść z tego żywi.', 'Udaj się do Świątynnego Miasta En\'kilah i znajdź kulę teleportacyjną pod lewitującą cytadelą Plagi, Naxxanarem. Użyj jej, by dostać się na szczyt, i pomóż tam Thassarianowi.', '', 'Odszukaj Thassariana w Naxxanarze w Boreańskiej Tundrze.', 'Ostatnie namaszczenie', '', '', '', 0),
(12035, 'plPL', 'Technologia w nowej roli', 'Dobra, mam to! Przerabianie obwodów jest trochę skomplikowane, ale nic, z czym ktoś tak $gbystry:bystra; jak ty by sobie nie poradził.$B$BWeź moje narzędzia i unieszkodliw kilka zbieraczy plonów. Gdy padną, użyj narzędzi i podłącz wszystkie czerwone przewody do niebieskich gniazd. To przełączy je w tryb samoobrony. Pośpiesz się, $N. Niedługo nie będzie już czego ratować.', 'Jeremiah Hawning w Dalekich Włościach chce, żebyś $gzniszczył:zniszczyła; 5 zbieraczy plonów, a następnie $gprzerobił:przerobiła; ich obwody narzędziami Jeremiaha.', '', 'Wróć do Jeremiaha Hawninga w Dalekich Włościach w Boreańskiej Tundrze.', 'Przerobione zbieracze plonów', '', '', '', 0),
(12086, 'plPL', 'Syn Karkuta', 'Człowiek, którego szukasz, udał się daleko na wschód, do miejsca przy wybrzeżu zwanego Redutą Śmierci, za Unu\'pe.$B$BUważaj, jeśli wyruszysz na jego poszukiwanie, $N. Nosił znak Karkuta... tego, który czuwa nad zmarłymi.', 'Udaj się na wschód do Reduty Śmierci, tuż za Unu\'pe.', '', '', '', '', '', '', 0),
(12087, 'plPL', 'Mała pomoc? DEPRECATED', 'Przysłano nas tu, żebyśmy zajęli Zawodzący Ziggurat, prosto na północ stąd. Nie liczyliśmy, że wrócimy żywi... do diabła, już straciliśmy połowę oddziału.$B$BThassarian szedł na szpicy, a ci na górze... cóż, coś im się w nim nie podobało.$B$BDziś rano gdzieś przepadł... mógł pójść do ziggurata na własną rękę. Ale teraz mamy pilniejsze zmartwienia. Plaga podchodzi coraz bliżej obozu i trzeba się z nią rozprawić – natychmiast!', 'Kapral Venn w Reducie Śmierci chce, żebyś $gzabił:zabiła; 8 obrońców ziggurata.', '', 'Wróć do kaprala Venna w Reducie Śmierci w Boreańskiej Tundrze.', '', '', '', '', 0),
(12088, 'plPL', 'Thassarian, rycerz śmierci', 'No cóż, $N, $gpomogłeś:pomogłaś; nam... więc chyba uczciwie będzie, jeśli my pomożemy tobie.$B$BSzukasz Thassariana? Zniknął dziś rano. Myślimy, że poszedł na północ, do Zawodzącego Ziggurata. Gdybyśmy nie walczyli z nim ramię w ramię, pomyślelibyśmy nawet, że to zdrajca.$B$BWidzisz, on jest rycerzem śmierci... i wiem, że są po naszej stronie i w ogóle... ale jeszcze niedawno służyli Arthasowi.$B$BAle nie Thassarian, to porządny gość. Idź do Zawodzącego Ziggurata i sprawdź, czy wszystko z nim w porządku.', 'Poszukaj Thassariana w Zawodzącym Zigguracie, na północ od Reduty Śmierci.', '', '', '', '', '', '', 0),
(12103, 'plPL', 'DEPRECATED', 'Wiem już dość, $N. Musimy dopilnować, żeby to, co dzieje się w Srebrnym Potoku, nie rozlało się na resztę kontynentu.$B$BNie obchodzi mnie, czy to woda, wysokość, czy starożytna klątwa trolli doprowadziła tych wieśniaków do morderczego obłędu... wróć do Srebrnego Potoku i zrób z nimi porządek.', 'Kapitan Derrick w Chacie Bursztynowej Sosny chce, żebyś $gzabił:zabiła; 8 mieszkańców Srebrnego Potoku i 8 traperów ze Srebrnego Potoku.', '', 'Wróć do porucznika Dumonta we Wzgórzach Grizli.', '', '', '', '', 0),
(12108, 'plPL', 'DEPRECATED', 'Kopczyk ziemi to rzeczywiście pospiesznie wykopany grób. Leżącego w nim ciała nie da się rozpoznać, ale znajdujesz liścik, z którego wynika, że ten człowiek to Mikhail.$B$BW liściku znów pojawia się wzmianka o Kopalni Wydrążonego Kamienia. Może ktoś w Chacie Bursztynowej Sosny zna tę okolicę.', 'Zanieś liścik Mikhaila kartografowi Tobiasowi w Chacie Bursztynowej Sosny.', '', '', '', '', '', '', 0),
(12117, 'plPL', 'Podróż do Portu Moa\'ki', '$N, właśnie nadeszły wieści z Portu Moa\'ki. Dziś rano stało się tam coś bardzo złego!$B$BBardzo nam tu $gpomogłeś:pomogłaś;. Czy $gzechciałbyś:zechciałabyś; popłynąć łodzią z Unu\'pe na wielkie Smocze Pustkowia?$B$BZ tego, co słychać, Starszy Ko\'nani z pewnością przyda się twoja pomoc.', 'Udaj się do Portu Moa\'ki na Smoczych Pustkowiach i porozmawiaj ze Starszym Ko\'nanim.', '', '', '', '', '', '', 0),
(12118, 'plPL', 'Podróż do Portu Moa\'ki', 'Właśnie przyszły wieści z łodzi z Portu Moa\'ki. Stało się tam dziś rano coś bardzo złego!$B$BBardzo nam tu $gpomogłeś:pomogłaś;. Może popłyniesz łodzią na wielkie Smocze Pustkowia?$B$BZ tego, co słychać, Starszemu Ko\'naniemu na pewno przyda się twoja pomoc.', 'Udaj się do Portu Moa\'ki na Smoczych Pustkowiach i porozmawiaj ze Starszym Ko\'nanim.', '', '', '', '', '', '', 0),
(12141, 'plPL', 'Misja dyplomatyczna', 'Widzę, że bardzo chcesz pomóc, $N. Nie po to $gprzebyłeś:przebyłaś; całą drogę do Północnej Grani, żeby siedzieć $gzamkniętym:zamkniętą; w mieście! Mam dla ciebie idealne zadanie... takie, które zaprowadzi cię daleko stąd.$B$BOd dawna zabiegamy o przychylność kiełzarów, rdzennych mieszkańców Północnej Grani. Niedawno przyszedł do nas młody kiełzar z prośbą o pomoc, której wtedy nie mogliśmy mu udzielić.$B$BSkoro jesteś tutaj, może zdołasz mu pomóc. Poszukaj Karuka w pobliżu Wybrzeża Smagaczy, na południowy zachód stąd, i zobacz, co da się zrobić.', 'Porozmawiaj z Karukiem na Wybrzeżu Smagaczy, na południowy zachód od Twierdzy Walecznych.', '', '', '', '', '', '', 0),
(12156, 'plPL', 'DEPRECAED', 'Już jakąś godzinę temu trzeba mi było wyruszyć do Srebrnego Potoku, na północny zachód stąd. Wygląda na to, że moja wojskowa eskorta się spóźnia.$B$BNiech mnie diabli, jeśli ta misja dyplomatyczna zejdzie na boczny tor tylko dlatego, że jakiś świeży rekrut zaspał.$B$BNegocjujemy umowę z miejscowymi i punktualność jest kluczowa. Co ty na to? Jeśli pójdziesz ze mną, twój trud zostanie sowicie wynagrodzony.', 'Eskortuj wysłannika Przymierza do miasteczka Srebrny Potok. Gdy wykonasz zadanie, zamelduj się u porucznika Dumonta w Chacie Bursztynowej Sosny.', '', 'Wróć do porucznika Dumonta we Wzgórzach Grizli.', '', '', '', '', 0),
(12157, 'plPL', 'Zaginiony kurier', 'Mamy szczęście, że w ogóle dotarliśmy tak daleko, $N. Plaga zaatakowała nas z zasadzki, gdy tylko wylądowaliśmy.$B$BJeden z naszych ludzi okazał się szpiegiem Kultu Potępionych. Wygląda na to, że Thassarian ma więcej dowodów na przenikanie kultystów w nasze szeregi. Podobno sięga to samej góry.$B$BWysłałem jednego z moich najlepszych kurierów do naszej placówki w zachodniej części Smoczych Pustkowi, ale jeszcze nie wrócił. Obawiam się, że padł ofiarą Plagi. Czy udasz się na Smocze Pustkowia i go poszukasz? Nazywa się kurier Lanson.$B', 'Porozmawiaj z kurierem Lansonem w Spoczynku Gwiazd na Smoczych Pustkowiach.', '', '', '', '', '', '', 0),
(12426, 'plPL', 'DEPRECATED', '', '', '', '', '', '', '', '', 0),
(12471, 'plPL', 'Okrucieństwo kvaldirów', 'Dziękuję, że mnie $gocaliłeś:ocaliłaś;, $N. Kvaldirowie to zwierzęta!$B$BKazali nam walczyć z innymi więźniami. Litościwiej byłoby po prostu nas wszystkich zabić.$B$BMłody Karuk wciąż żyje – widziałem, jak tu przybył. Powiedz mu, że jego ojciec walczył do końca.', 'Porozmawiaj z Karukiem o pojmanym kiełzarze.', '', '', '', '', '', '', 0),
(12486, 'plPL', 'Szybko do Posterunku Bor\'gorok!', 'Czy ty też to $gpoczułeś:poczułaś;?$B$B<Sauranok na chwilę chwyta się w oszołomieniu za pierś. Gdy odejmuje dłoń, ciągnie się za nią rozgrzana do czerwoności para.>$B$BCoś strasznego spotkało mojego starego przyjaciela, wieszcza Grimwalkera. Właśnie to wyczułem.$B$BMiał uczennicę, którą zabrał ze sobą, gdy wyruszył na północ. Mieli pomóc nadrządcy założyć posterunek na skraju Kotliny Sholazar.$B$BNazywa się Warkokieł. Jest rozmówczynią duchów.$B$BMoże ona będzie wiedziała, co się stało. A przynajmniej pomoże ci się tego dowiedzieć.', 'Porozmawiaj z rozmówczynią duchów Warkokieł w Posterunku Bor\'gorok.', '', '', '', '', '', '', 0),
(12490, 'plPL', 'Zemsta Veehji', 'Dziś mamy wspólnego wroga, $N! Ci kvaldirowie wybili mój lud... moje miasto jest niemal doszczętnie zniszczone. Czas na krwawą zemstę!$B$BW zamian za moją pomoc chcę, żebyś $gzabił:zabiła; te barbarzyńskie potwory, które plugawią ziemie Smagaczy. Zostaniesz sowicie $gnagrodzony:nagrodzona;, $N.', 'Veehja w Kaplicy Łusek chce, żebyś $gzabił:zabiła; 6 żeglarzy Skadirów, 3 tkaczy mgły Skadirów i 2 magów run Skadirów.', '', 'Wróć do Veehji w Kaplicy Łusek w Boreańskiej Tundrze.', '', '', '', '', 0),
(12728, 'plPL', 'Obserwacja rozpadliny: Pieczary Zimopłetwych', 'Muszę zebrać notatki i przygotować wystąpienie dla moich kolegów w Dalaranie.$b$bW tym czasie muszę cię prosić, żebyś $gudał:udała; się do Pieczar Zimopłetwych na północy. Użyj arkanometru, stojąc u wylotu pieczary.$b$bGdy tylko zdobędziesz dane, natychmiast wróć do mnie. Bez nich moja dokumentacja będzie niekompletna.', 'Bibliotekarz Garren na Bursztynowym Występie chce, żebyś $gużył:użyła; arkanometru w Pieczarach Zimopłetwych.', '', 'Wróć do bibliotekarza Garrena na Bursztynowym Występie w Boreańskiej Tundrze.', 'Dokonano odczytu w Pieczarach Zimopłetwych', '', '', '', 0),
(12791, 'plPL', 'Magiczne królestwo Dalaranu', 'Witaj, $N. Być może wiesz, a być może nie, że my, Kirin Tor, przenieśliśmy nasze miasto tutaj, do Północnej Grani.$B$BDalaran nie stoi już pod ochronną kopułą nad brzegiem Jeziora Lordamere. Teraz miasto magicznie unosi się nad Lasem Kryształowej Pieśni.$B$BSądzimy, że jesteś $ggotów:gotowa; do podróży do miasta. Porozmawiaj ze mną ponownie, a rzucę zaklęcie teleportacji, które cię tam przeniesie.$B$BGdy dotrzesz na miejsce, odszukaj arcymaginię Celindrę i daj jej mój sygnet na dowód, że rozmawialiśmy.', 'Dostarcz sygnet Kirin Toru arcymagini Celindrze przy Purpurowej Bramie w Dalaranie.', '', 'Porozmawiaj z arcymaginią Celindrą przy Purpurowej Bramie w Dalaranie.', '', '', '', '', 0),
(12794, 'plPL', 'Magiczne królestwo Dalaranu', 'Witaj, $N. Być może wiesz, a być może nie, że my, Kirin Tor, przenieśliśmy nasze miasto tutaj, do Północnej Grani.$B$BDalaran nie stoi już pod ochronną kopułą nad brzegiem Jeziora Lordamere. Teraz miasto magicznie unosi się nad Lasem Kryształowej Pieśni.$B$BSądzimy, że jesteś $ggotów:gotowa; do podróży do miasta. Porozmawiaj ze mną ponownie, a rzucę zaklęcie teleportacji, które cię tam przeniesie.$B$BGdy dotrzesz na miejsce, odszukaj arcymaginię Celindrę i daj jej mój sygnet na dowód, że rozmawialiśmy.', 'Dostarcz sygnet Kirin Toru arcymagini Celindrze przy Purpurowej Bramie w Dalaranie.', '', 'Porozmawiaj z arcymaginią Celindrą przy Purpurowej Bramie w Dalaranie.', '', '', '', '', 0),
(12796, 'plPL', 'Magiczne królestwo Dalaranu', 'Witaj, $N. Być może wiesz, a być może nie, że my, Kirin Tor, przenieśliśmy nasze miasto tutaj, do Północnej Grani.$B$BDalaran nie stoi już pod ochronną kopułą nad brzegiem Jeziora Lordamere. Teraz miasto magicznie unosi się nad Lasem Kryształowej Pieśni.$B$BSądzimy, że jesteś $ggotów:gotowa; do podróży do miasta. Porozmawiaj ze mną ponownie, a rzucę zaklęcie teleportacji, które cię tam przeniesie.$B$BGdy dotrzesz na miejsce, odszukaj arcymaginię Celindrę i daj jej mój sygnet na dowód, że rozmawialiśmy.', 'Dostarcz sygnet Kirin Toru arcymagini Celindrze przy Purpurowej Bramie w Dalaranie.', '', 'Porozmawiaj z arcymaginią Celindrą przy Purpurowej Bramie w Dalaranie.', '', '', '', '', 0),
(12918, 'plPL', 'Doskonałość klejnotów', 'Zimno tu jak w oddechu lodowego żmija, prawda? Nie dość, że brakuje mi klientów na moje rzemiosło, to jeszcze nie mam zapasu klejnotów na sprzedaż! Jeśli przyniesiesz mi kilka nieoszlifowanych klejnotów, żebym uzupełnił zapasy, mogę nauczyć cię Doskonałości klejnotów. Dzięki niej czasem, szlifując klejnot niepospolitej jakości z Północnej Grani, uzyskasz klejnot doskonały o zwiększonych premiach.', 'Przynieś dwa Ogromne cytryny, dwa Ciemne nefryty i dwa Kryształy cienia Ounhulowi w Valgardzie.', '', 'Wróć do Ounhula w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(12952, 'plPL', 'Doskonałość klejnotów', 'Moje umiejętności marnują się w tym nędznym miejscu. Przez wiele lat uczyłem się szlifować klejnoty do doskonałej postaci, a nie mam nad czym pracować! Wyglądasz na kogoś, kto może znaleźć mi trochę klejnotów, a jeśli to zrobisz, nauczę cię Doskonałości klejnotów. Dzięki niej czasem, szlifując klejnot niepospolitej jakości z Północnej Grani, uzyskasz klejnot doskonały o zwiększonych premiach.', 'Przynieś dwa Ogromne cytryny, dwa Ciemne nefryty i dwa Kryształy cienia Carterowi Tiffensowi w Przystani Zemsty.', '', 'Wróć do Cartera Tiffensa w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(13002, 'plPL', 'Doskonałość klejnotów', 'Witaj w zimnie, mon. To miejsce nie za dobre, żeby grzać moje kości, ale ja się nauczył szlifować idealny klejnot. Trzeba mi tylko trochę klejnotów, żeby robić moją robotę.$B$BPrzynieś mi klejnoty, a ja nauczę cię sztuki doskonałości klejnotów. Dzięki niej czasem oszlifujesz idealny klejnot z większymi premiami, gdy będziesz szlifować niepospolity klejnot z Północnej Grani.', 'Przynieś dwa ogromne cytryny, dwa ciemne nefryty i dwa kryształy cienia Geba\'liemu w Warowni Wojennej Pieśni.', '', 'Wróć do Geba\'liego w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(13004, 'plPL', 'Doskonałość klejnotów', 'Trwa wojna i każdy z nas musi zrobić, co do niego należy! Moja rola to szlifowanie klejnotów – i nie tylko zwykłych, bo potrafię też szlifować klejnoty idealne. Jeśli przyniesiesz mi kilka nieoszlifowanych klejnotów na potrzeby sprawy, nauczę cię doskonałości klejnotów. Dzięki niej czasem oszlifujesz idealny klejnot z większymi premiami, gdy będziesz szlifować niepospolity klejnot z Północnej Grani.', 'Przynieś dwa ogromne cytryny, dwa ciemne nefryty i dwa kryształy cienia Alestosowi w Twierdzy Walecznych.', '', 'Wróć do Alestosa w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(13012, 'plPL', 'Nestor Sardis', '', '', '', '', '', '', '', '', 0),
(13016, 'plPL', 'Nestor Northal', '', '', '', '', '', '', '', '', 0),
(13029, 'plPL', 'Nestor Pamuya', '', '', '', '', '', '', '', '', 0),
(13033, 'plPL', 'Nestor Arp', '', '', '', '', '', '', '', '', 0),
(13087, 'plPL', 'Kuchnia północy', 'To co ty robisz, jak ni masz dla mnie gulaszu? Jestem GŁODNY! Przynieś mi chociaż trochę schłodzonego mięsa, to sam se ugotuję gulasz! Jak przyniesiesz, dam ci przepis i będziesz se go robić na własną rękę. A TERAZ LEĆ PO MIĘSO!', 'Przynieś cztery porcje Schłodzonego mięsa Bromowi Warzypiwowi w Valgardzie. Schłodzone mięso można zdobyć z każdego zwierzęcia w Północnej Grani.', '', 'Wróć do Broma Warzypiwa w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(13088, 'plPL', 'Kuchnia północy', 'Mamy tu mnóstwo nowych rekrutów, a te chłopaki są głodne! Jeśli przyniesiesz mi trochę schłodzonego mięsa na gulasz, nauczę cię, jak go samemu przyrządzić.', 'Przynieś cztery kawałki schłodzonego mięsa Rollickowi MacKreelowi w Twierdzy Walecznych. Schłodzone mięso można zdobyć z każdego zwierzęcia w Północnej Grani.', '', 'Wróć do Rollicka MacKreela w Twierdzy Walecznych w Boreańskiej Tundrze.', '', '', '', '', 0),
(13089, 'plPL', 'Kuchnia północy', 'Nic tak nie rozgrzewa kości jak gulasz z żywych. Przynieś mi trochę schłodzonego mięsa z nędznych bestii tej krainy, a nauczę cię przyrządzać rozgrzewający gulasz.', 'Przynieś cztery porcje Schłodzonego mięsa Thomasowi Kolichio w Przystani Zemsty. Schłodzone mięso można zdobyć z każdego zwierzęcia w Północnej Grani.', '', 'Wróć do Thomasa Kolichio w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(13090, 'plPL', 'Kuchnia północy', 'Wojownicy Ofensywy Wojennej Pieśni muszą mieć pełne brzuchy, żeby nie opaść z sił. Jeśli przyniesiesz trochę schłodzonego mięsa z nosorożców lub innych zwierząt, ugotuję im gulasz. Jeśli zechcesz, chętnie nauczę cię przepisu.', 'Przynieś cztery kawałki schłodzonego mięsa Ornowi Miękkiemu Kopytu w Warowni Wojennej Pieśni. Schłodzone mięso można zdobyć z każdego zwierzęcia w Północnej Grani.', '', 'Wróć do Orna Miękkiego Kopyta w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(13094, 'plPL', 'Czy oni nie mają wstydu?', 'Arcymag Berinand jest największym autorytetem Kirin Toru w sprawie Malygosa. Całe życie poświęcił badaniu aspektu i jego zachowań.$b$bNiedawno pożyczył mi swoje badania nad Arkanomikronem – czymś w rodzaju mapy, którą Malygos próbuje złożyć. Popełniłam błąd, rozmawiając o nim z grupą poszukiwaczy przygód z Hordy, którzy uzupełniali tu zapasy – a teraz zniknął!$b$bTo musieli być oni, $N. Proszę, idź za nimi do Nexusa i odzyskaj księgę, zanim Berinand przyjdzie po nią.', 'Bibliotekarka Serrah chce, żebyś $gwszedł:weszła; do Nexusa i $godzyskał:odzyskała; badania Berinanda.', '', 'Wróć do bibliotekarki Serrah przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(13095, 'plPL', 'Czy oni nie mają wstydu?', 'Arcymag Berinand jest największym autorytetem Kirin Toru w sprawie Malygosa. Całe życie poświęcił badaniu aspektu i jego zachowań.$b$bNiedawno pożyczył mi swoje badania nad Arkanomikronem – czymś w rodzaju mapy, którą Malygos próbuje złożyć. Popełniłam błąd, rozmawiając o nim z grupą poszukiwaczy przygód z Przymierza, którzy uzupełniali tu zapasy – a teraz zniknął!$b$bTo musieli być oni, $N. Proszę, idź za nimi do Nexusa i znajdź księgę, zanim Berinand przyjdzie ją ode mnie odebrać.', 'Bibliotekarka Serrah chce, żebyś $gwszedł:weszła; do Nexusa i $godzyskał:odzyskała; badania Berinanda.', '', 'Wróć do bibliotekarki Serrah przy Tarczy Transitus w Boreańskiej Tundrze.', '', '', '', '', 0),
(13124, 'plPL', 'Walka trwa', 'Bitwa trwa, $n. Jakimś cudem udało się nam uniknąć wykrycia i wciąż próbujemy krzyżować plany Malygosa. Na tym jednak kończą się dobre wieści, a zaczynają złe.$b$bNasze największe wysiłki nie przyniosły prawie żadnego efektu. Malygos i jego słudzy z każdym dniem rosną w siłę. A teraz nasz ostatni oddział szturmowy został pojmany i jest więziony w Okulusie.$b$bMusimy spróbować go odbić! Belgaristrasz i jego towarzysze są dla naszej sprawy bezcenni. Czy możemy na ciebie liczyć, $n?', 'Raelorasz chce, żebyś $gwszedł:weszła; do Okulusa i $guratował:uratowała; Belgaristrasza i jego towarzyszy.', '', '', '', '', '', '', 0),
(13128, 'plPL', 'Na jednym skrzydle i modlitwie', 'Nadszedł czas, by stawić czoła Eregosowi, przyjacielu.$b$bJest przebiegły i silny. To jeden z najbardziej zaufanych sług Malygosa – czerpie siłę z energii, których ma bronić, pijąc ze źródła samego wielkiego aspektu.$b$bNie będzie łatwo....$b$bJednak pokonanie Władcy Magów pozwoliło nam uwolnić pełną moc naszych smoków. Ich umiejętności będą na twoje rozkazy. Wykorzystaj je mądrze, a Eregos z pewnością padnie.$b$bJeśli ci się powiedzie, wróć do Raelorasza i powiadom go o naszym zwycięstwie.', 'Belgaristrasz chce, żebyś $gzabił:zabiła; Eregosa w Okulusie, a następnie $gzłożył:złożyła; raport Raeloraszowi przy Tarczy Transitus w Mrozarze.', '', 'Wróć do Raelorasza przy Tarczy Transitus w Boreańskiej Tundrze.', 'Strażnik Linii Mocy Eregos pokonany', '', '', '', 0),
(13242, 'plPL', 'Ciemność się budzi', 'Ciemność się budzi, $N. Wydarzyła się tragedia, której nikt poza Wiekuistym nie mógł przewidzieć. Wkrótce twój lud ogarnie gniew i nienawiść. Na horyzoncie widać wojnę.$B$BCzerwone Stado zrobiło wszystko, co mogło. To, co wydarzy się dalej, jest w rękach śmiertelnych ras Azeroth.$B$BNiestety, twoja podróż zaczyna się od cierpienia. Ojciec stracił dziś dziecko. To ty musisz przynieść mu tę ponurą wieść. Zbierz rynsztunek Zaurzykła i zanieś go staremu Zaurzykłowi.$B', 'Zbierz zbroję bojową Zaurzykła z pola bitwy i zanieś ją najwyższemu nadrządcy Zaurzykłowi w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', 'Wróć do najwyższego nadrządcy Zaurzykła w Warowni Wojennej Pieśni w Boreańskiej Tundrze.', '', '', '', '', 0),
(13265, 'plPL', 'Zbieranie tkanin', '', '', '', '', '', '', '', '', 0),
(13268, 'plPL', 'Zbieranie tkanin', '', '', '', '', '', '', '', '', 0),
(13269, 'plPL', 'Zbieranie tkanin', '', '', '', '', '', '', '', '', 0),
(13270, 'plPL', 'Zbieranie tkanin', '', '', '', '', '', '', '', '', 0),
(13272, 'plPL', 'Zbieranie tkanin', '', '', '', '', '', '', '', '', 0),
(13279, 'plPL', 'Podstawy chemii', '<Koltira bierze ropiejące kręgosłupy i spuszcza z nich płyn do flaszki.>$b$bMało znana właściwość mięsnych olbrzymów...$b$bIch płyn rdzeniowy reaguje z zarazą w bardzo ciekawy sposób, zamieniając ją w żrący kwas.$b$bKwas wylany z wysokich blanków może nie być mile widziany przez żołnierzy w dole, ale przynajmniej ofiary nie powstaną i nie zasilą szeregów wroga.$b$bWlej zawartość tej flaszki do jednego z kotłów zarazy w zachodniej komnacie Bramy Śmierci.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gużył:użyła; ropiejącego płynu rdzeniowego na kotle zarazy w Mord\'rethar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Zneutralizowano kocioł zarazy', '', '', '', 0),
(13281, 'plPL', 'Neutralizacja zarazy', 'Nie potrzebujesz już mojej pomocy przy neutralizowaniu kotłów zarazy wroga, $N.$b$bPoluj na mięsne olbrzymy przy Bramie Śmierci i używaj płynu z ich kręgosłupów, by unieszkodliwiać porcje zarazy.$b$bUderzasz w samo serce strategii wroga. To ważna misja – kluczowa dla naszej sprawy – i należy ją wykonywać, kiedy tylko czas pozwoli.$b$bPamiętaj, olbrzymy i kotły zarazy znajdziesz w Mord\'rethar.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gużył:użyła; ropiejącego płynu rdzeniowego na kotle zarazy w Mord\'rethar.$b$bRopiejący płyn rdzeniowy uzyskasz, używając kręgosłupa olbrzyma zdobytego z ropiejącej poczwary.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Zneutralizowano kocioł zarazy', '', '', '', 0),
(13297, 'plPL', 'Neutralizacja zarazy', 'Nie potrzebujesz już mojej pomocy przy neutralizowaniu kotłów zarazy wroga, $N.$b$bPoluj na mięsne olbrzymy przy Bramie Śmierci i używaj płynu z ich kręgosłupów, by unieszkodliwiać porcje zarazy.$b$bUderzasz w samo serce strategii wroga. To ważna misja – kluczowa dla naszej sprawy – i należy ją wykonywać, kiedy tylko czas pozwoli.$b$bPamiętaj, olbrzymy i kotły zarazy znajdziesz w Mord\'rethar.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gużył:użyła; ropiejącego płynu rdzeniowego na kotle zarazy w Mord\'rethar.$b$bRopiejący płyn rdzeniowy uzyskasz, używając kręgosłupa olbrzyma zdobytego z ropiejącej poczwary.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Zneutralizowano kocioł zarazy', '', '', '', 0),
(13412, 'plPL', 'Corastrasza', 'Witaj, $N. Czy mogę cię prosić o przysługę?$b$bCorastrasza jest siostrą Raelorasza – czerwonego smoka, który dowodzi tutejszą placówką. Wbrew jego woli wzniosła się na jeden z górnych pierścieni Nexusa, by obserwować przerażająco potężne błękitne smoki.$b$bChoć nigdy tego nie powie, martwi się o nią i ucieszyłby się z każdej wieści o tym, że nic jej nie jest.$b$bProszę, odszukaj ją. Poproś, by odłożyła dumę na bok i przesłała bratu wiadomość.', 'Bibliotekarka Serrah chce, żebyś $gporozmawiał:porozmawiała; z Corastraszą w Mrozarze.', '', '', '', '', '', '', 0),
(13413, 'plPL', 'Asy przestworzy!', 'Masz dość odwagi, by zbliżyć się tak bardzo do leża Malygosa, śmiertelniku? A może to zwykła niewiedza? Wkrótce się przekonamy....$b$bJestem doświadczoną treserką zwinnych smoków Czerwonego Stada. Przybyłam tu, by badać wroga i uczyć moich drogich podopiecznych taktyki, która okaże się najskuteczniejsza, gdy staniemy przed panem błękitnych.$b$bAbyś $gdowiódł:dowiodła; swojej odwagi i umiejętności, pozwolę ci dosiąść jednego z moich smoków i ruszyć na sługi wroga.$b$bWystarczy poprosić...', 'Corastrasza na górnym pierścieniu Nexusa w Mrozarze chce, żebyś $gdosiadł:dosiadła; jej smoka i $gzabił:zabiła; 5 elitarnych zaprzysiężonych łusce.', '', 'Wróć do Corastraszy przy Nexusie w Boreańskiej Tundrze.', 'Zabici elitarni zaprzysiężeni łusce', '', '', '', 0),
(13414, 'plPL', 'Asy przestworzy!', 'Znów się spotykamy, $N. Przyznaję, zaczynam się do ciebie przekonywać.$b$bCzy dobrze zakładam, że $gprzybyłeś:przybyłaś; doskonalić umiejętności walki w powietrzu?$b$bJak zawsze, moi podopieczni są gotowi zasiać wśród wroga ognistą zagładę.$b$bPowiedz słowo, a będą do twojej dyspozycji.', 'Corastrasza na górnym pierścieniu Nexusa w Mrozarze chce, żebyś $gdosiadł:dosiadła; jej smoka i $gzabił:zabiła; 5 elitarnych zaprzysiężonych łusce.', '', 'Wróć do Corastraszy przy Nexusie w Boreańskiej Tundrze.', 'Zabici elitarni zaprzysiężeni łusce', '', '', '', 0),
(13524, 'plPL', 'Ucieczka ze Srebrnego Potoku', 'Ty... nie jesteś jednym z nich? Szybko! Wypuść mnie!$B$BMusimy natychmiast dotrzeć do Chaty Bursztynowej Sosny! Kiedy porucznik Dumont się dowie, kim naprawdę są ci ludzie, z tego miasteczka zostanie kupa gruzu!', 'Otwórz Drewnianą klatkę i pomóż uwolnionemu zwiadowcy Przymierza uciec ze Srebrnego Potoku. Gdy dotrzesz do Chaty Bursztynowej Sosny, zamelduj się u porucznika Dumonta.', '', 'Wróć do porucznika Dumonta we Wzgórzach Grizli.', 'Ucieczka ze Srebrnego Potoku', '', '', '', 0),
(24227, 'plPL', 'DEPRECATED', 'Walka z Hordą nie zna granic, $N. Nawet w Rubieży spory terytorialne i dawne nienawiści wystarczą, by przechylić szalę na stronę wojny.$B$BUdaj się do Oka Cyklonu i dopilnuj, by Przymierze zwyciężyło w Rubieży tak samo, jak zwyciężyło w Azeroth.', 'Wygraj bitwę w Oku Cyklonu i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo w Oku Cyklonu', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11559, 'plPL', 'To dla mnie? Czy to jakiś podstęp? Nie?$B$BNo to dziękuję! Wracaj, kiedy tylko będziesz mieć więcej małży, a zrobimy interes!', 0),
(11560, 'plPL', 'Teraz, bez względu na to, co się stanie, przyszłość murloków Zimopłetwych jest bezpieczna.$b$bZa swoją bezinteresowność zasługujesz na pochwałę i nagrodę, $N!', 0),
(11561, 'plPL', 'Jestem zadowolony. Czuję na twoich rękach miedziany posmak ich krwi.$b$bTo dobry początek.', 0),
(11562, 'plPL', 'Aha, więc to ty jesteś pachołkiem tak zwanego króla Mrgl-Mrgla. Pewnie ten nocny elf przysłał cię, żeby mnie udobruchać?$b$bŚwietnie, mam akurat robotę w sam raz dla kogoś tak potężnego jak ty!', 0),
(11563, 'plPL', 'Nieźle. Będzie z tego niezła uczta!$b$bSkoro król orek nie żyje, ataki na nas powinny osłabnąć, bo wieloryby zaczną walczyć między sobą o władzę.', 0),
(11564, 'plPL', 'O tak, to się świetnie nada.$b$bRzuć to gdziekolwiek. Możesz wziąć trochę gulaszu, który został mi z wczoraj.', 0),
(11565, 'plPL', '<Na widok zapasowego stroju murloka król zaciera przebrane kończyny.>$b$bŚwietna robota. A teraz wróćmy do pilnej sprawy. Mam dla ciebie zadanie wielkiej wagi.', 0),
(11566, 'plPL', 'Szkoda, ale tak trzeba było. Wezmę te szczypce, $N.$b$bDziękuję za całą pomoc, jakiej nam $gudzieliłeś:udzieliłaś;. Skoro Claximus został pokonany, może zdołamy zjednoczyć pozostałe murloki i zamknąć te pieczary.$b$bProszę, przyjacielu, weź to... to najmniej, co mogę zrobić za całą twoją pomoc!', 0),
(11569, 'plPL', 'Szybko, dawaj go!', 0),
(11570, 'plPL', 'To wspaniała wiadomość! Mówisz, że Lurgglbr odkrył, że to emanacje z pieczar wywołały to szaleństwo?$b$bMagia z Mrozarry musi przybierać na sile. Wojna o Nexus... bitwa między Błękitnym Stadem a wszystkimi innymi smokami, przelewa się poza swoje granice.$b$bWkrótce wszyscy zostaniemy w nią wciągnięci!', 0),
(11571, 'plPL', 'Teraz będę mógł użyć esencji Parzącej, żeby przekazać ci moją znajomość języka murloków Zimopłetwych.', 0),
(11574, 'plPL', 'Możesz powiedzieć swojej przyjaciółce, że jej ratunek był dla nas przyjemnością, a zarazem obowiązkiem.$b$bTo, co ją spotkało, jest tylko drobnym elementem, jak sądzę, wielkiej układanki.$b$bDalaran nie szczędzi wysiłków, żeby rozwiązać tę zagadkę, i prawdę mówiąc, przydałaby nam się pomoc...', 0),
(11575, 'plPL', 'Możesz powiedzieć swojej przyjaciółce, że jej ratunek był dla nas przyjemnością, a zarazem obowiązkiem.$b$bTo, co ją spotkało, jest tylko drobnym elementem, jak sądzę, wielkiej układanki.$b$bDalaran nie szczędzi wysiłków, żeby rozwiązać tę zagadkę, i prawdę mówiąc, przydałaby nam się pomoc...', 0),
(11576, 'plPL', 'Fascynujące! To największe zaburzenie jak dotąd.$b$bObawiam się jednak, że najgorsze dopiero przed nami.', 0),
(11582, 'plPL', 'Jak duże?$b$bTo niemożliwe! Muszę natychmiast złożyć raport w Dalaranie!', 0),
(11585, 'plPL', 'Bohater Hordy, co?$b$b<Garosz węszy w powietrzu wokół ciebie.>$b$bStrach...$b$b<Garosz spluwa.>$b$bDługo tu nie pociągniesz.', 0),
(11586, 'plPL', 'Nie myśl, że zapomniałem, co $gzrobiłeś:zrobiłaś; dla mojego ludu w Nagrandzie, $N. Piekłorycz nigdy nie zapomina.$b$bJestem ci za to winien i dlatego daję ci teraz tę szansę: uciekaj. Opuść to miejsce i nigdy się nie oglądaj.$b$bWróć do domu i odmów modlitwę za umierających.', 0),
(11587, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bKirin Tor łaskawie przyjmuje pomoc, której $gudzieliłeś:udzieliłaś;. Wiedz, że żadna przysługa, którą nam wyświadczysz, nie pozostanie bez nagrody.$b$bProszę, przyjmij ten skromny dar jako wyraz wdzięczności Dalaranu.', 0),
(11590, 'plPL', 'Świetna robota, $N.$b$bNatychmiast przygotujemy go do przesłuchania.', 0),
(11591, 'plPL', 'Niedobrze.$b$bBiegacz Dumne Kopyto mówi, że to miejsce pochówku jego czcigodnych przodków.', 0),
(11592, 'plPL', 'Na krew i grom! $GUratowałeś:Uratowałaś; nasze świeżo nawiązane stosunki z taunka.$b$bDzięki, że $gwyprostowałeś:wyprostowałaś; tę sprawę. Aka\'Magosh, $N!', 0),
(11593, 'plPL', 'Dziękuję, $N. Jesteśmy Hordą, nie zostawiamy naszych poległych!$b$bW ogóle nie powinno było do tego dojść. Steeljaw był głupcem!', 0),
(11594, 'plPL', 'Dobra robota, $N! Musisz mieć spore doświadczenie w walce z nieumarłymi. A jeśli wcześniej go nie $gmiałeś:miałaś;, to teraz już masz.$b$bPrzyda ci się, jeśli chcesz przeżyć w Północnej Grani.', 0),
(11595, 'plPL', '<Nadrządca Razgor salutuje.>$b$bTwoja sława cię wyprzedza, $N.', 0),
(11596, 'plPL', 'W samą porę... Nerubian w ciągu zaledwie tygodnia zrobiło się chyba dwa razy więcej. Przyda nam się tu każda pomoc.', 0),
(11598, 'plPL', '$GSpowolniłeś:Spowolniłaś; ich, ale na pewno przybędzie ich więcej. Udało ci się znaleźć w kamieniołomie któryś z ich worków z jajami?', 0),
(11599, 'plPL', 'Zwłoki pasują do opisu Williama Allertona, który dała ci Leryssa. Co dziwne, nie ma na nich śladów ugryzień ani pazurów.', 0),
(11600, 'plPL', 'Myślisz, że William zginął przypadkiem z rąk Plagi? Coś tu śmierdzi.$B$BCoś jest na rzeczy. Musimy odnaleźć Thassariana.', 0),
(11601, 'plPL', 'Nie powiem, żebym mógł ci pomóc, przyjacielu. Ale chyba znam kogoś, kto może.', 0),
(11602, 'plPL', 'Wciąż nadchodzą, mimo wszystkich naszych wysiłków. Coś musi się zmienić, $N.', 0),
(11603, 'plPL', 'Mmmmm... nie za gorzkie... nie za wytrawne... zupełnie jak za dawnych czasów, z chłopakami w koszarach.', 0),
(11604, 'plPL', 'Czego chcesz? Mam dość własnych kłopotów!', 0),
(11605, 'plPL', '<Gdy zbliżasz się do posągu, wita cię głos starszego Atkanoka.>$B$BDobra robota, $N. Znając imiona błąkających się starszych, możemy dokończyć obrzędy przerwane podczas napaści. Zanim jednak duchy starszych będzie można zaprowadzić do ich kamieni, musimy uspokoić duchy zamordowanych rzemieślników i szamanów. Inaczej duchy przodków mogą nigdy nie usłyszeć wezwania obrzędu.', 0),
(11606, 'plPL', 'Jeśli moje obliczenia są poprawne – a często nie są – będziesz potrzebować jakichś 10–20 bomb głębinowych z seaforium.$b$bA, no tak, będziesz wsadzać te cholerstwa do ich zapadlisk.', 0),
(11607, 'plPL', 'Czuję, że zamęt w świecie duchów zaczyna się uspokajać. Dobrze się $gspisałeś:spisałaś;, $N. Duchy przodków mają szczęście, że w tej trudnej chwili mogą liczyć na twoją pomoc.', 0),
(11608, 'plPL', 'To ich zatrzyma – przynajmniej tak mi się wydaje. Tak czy inaczej, $gzrobiłeś:zrobiłaś; swoje. Więcej nie można żądać od nikogo, prawda?', 0),
(11609, 'plPL', '<Unosisz przedmioty przed posągiem starszego Atkanoka.>$B$BWystarczą, choć są w opłakanym stanie. Niektóre przetrwały stulecia używania tylko po to, by zostać poobijane i skradzione przez barbarzyńców.', 0),
(11610, 'plPL', 'Przodkowie odnaleźli swoje posągi, a zawdzięczają to tobie, $N. Rzemieślnicy z Kaskali wrócą do kamieniołomu i dopilnują, by linia przodków trwała nieprzerwanie. Przodkowie zaś nadal będą cię obserwować z zaciekawieniem, bo wygląda na to, że twoja droga dopiero się zaczyna.', 0),
(11611, 'plPL', 'Większość wróciła. A przynajmniej ci, którym starczyło rozumu, żeby wiedzieć, że siedzimy w tym gigantycznym budynku z metalu i kamienia...$B$BTak czy inaczej, dobra robota. Słyszałem, że $guwolniłeś:uwolniłaś; więcej niż paru peonów.$B$BO tak, cała... eee... forteca o tobie mówi.', 0),
(11612, 'plPL', 'Skoro ci dziwni magowie wiedzą już, że lud Kaskali i jego sojusznicy nie oddadzą kamieniołomu tak łatwo, musimy nie ustawać w wysiłkach i rozbić ich doszczętnie.$B$BMoi bracia w Kaskali również zostali zaatakowani i nie będą mogli nas wesprzeć, ale z twoją pomocą, $N, zdołamy pokonać tych łupieżców.', 0),
(11613, 'plPL', '$GWyświadczyłeś:Wyświadczyłaś; mojemu ludowi wielką przysługę, $N. Muszę cię jednak prosić o jeszcze jedno.', 0),
(11614, 'plPL', 'Bardziej martwy już być nie może... Co dziwne, nerubianie nie pożarli zwłok.$b$bPo dokładnych oględzinach widzisz, że Luther sam odebrał sobie życie – śmiertelną trucizną. Sprytne. Nerubianie nie zbliżą się do tak toksycznych zwłok.$b$bZauważasz, że Luther trzyma w dłoni dziennik.', 0),
(11615, 'plPL', '<Barthus przerzuca dziennik na ostatnią stronę i zaczyna czytać.>$b$bTo bardzo złe wieści. Trzeba natychmiast powiadomić Piekłorycza.', 0),
(11616, 'plPL', '<Piekłorycz czyta wpis w dzienniku.>$b$bTo wszystko?', 0),
(11617, 'plPL', 'Łowcy magów przekonają się, że łupienie naszego kamieniołomu i kradzież naszych artefaktów nie idą im tak łatwo, jak sobie wyobrażali. Z twoją pomocą odbijemy kamieniołom i przywrócimy porządek.', 0),
(11618, 'plPL', 'To wszystko? Piekłorycz $gprzysłał jednego chłopaczka:przysłał jedną dziewuszkę;?$B$BGdybym jeszcze miał szczękę, opadłaby mi teraz na ziemię.', 0),
(11619, 'plPL', 'Udało ci się, $N! Duchy zabitych kiełzarów mogą teraz spoczywać w pokoju – ich śmierć została pomszczona!', 0),
(11620, 'plPL', 'Hsssssssssssss! $GPrzyszedłeś:Przyszłaś; ze mnie drwić?', 0),
(11623, 'plPL', 'Kustosz i jego ludzie musieli uważać kamieniołom za łatwy łup, ale $gpokazałeś:pokazałaś; im, że się mylili, $N. Jestem ci głęboko wdzięczny za pomoc i jestem pewien, że przodkowie nadal będą nad tobą czuwać.', 0),
(11624, 'plPL', 'To głupota tu przychodzić, mała istoto.$B$BCzego szukasz?', 0),
(11625, 'plPL', 'Takkkkk! Zabijemy bestię kvaldirów! Pokażę tym prostakom, że nie zadziera się z kapłanką łuski!', 0),
(11626, 'plPL', 'Duchy mojego ludu mogą spoczywać w pokoju. $GPomogłeś:Pomogłaś; mi oddać cześć ojcu... może kiedyś będę tak silny jak ty.', 0),
(11627, 'plPL', 'Jestem zadowolona, choć bez wątpienia jeszcze przez jakiś czas będą się kłócić.$B$BZanim jednak wrócisz do swojej rozmówczyni duchów, musisz zrobić coś jeszcze.', 0),
(11628, 'plPL', 'Choć nie lubię wnosić do wioski tak zarażonych rzeczy, mogą nam dać przewagę nad wrogami.$b$b<Wódz daje znak mędrczyni Aeire i lekceważąco macha ręką w stronę futer.>$b$bPodczas gdy ona będzie przygotowywać futra, potrzebujemy jeszcze jednego składnika, żeby zrobić płaszcz.', 0),
(11629, 'plPL', 'Imperean dała ci swoją pierwotną esencję? Słyszę wyjące w niej wichry!$B$BZnam rytuał, w którym możemy jej użyć. Musimy się śpieszyć, zanim jej pierwotna esencja rozerwie się na strzępy!', 0),
(11630, 'plPL', '<Wódz Zimowa Wichura ostrożnie przyjmuje zebrane przez ciebie grudy ziemi.>$b$bTrzeba jak najszybciej przekazać je mędrczyni Aeire.$b$b<Wódz chrząka, udając, że skażona ziemia wcale go nie niepokoi.>$b$bNigdy nie wiemy, kiedy dowódca Plagi przypuści ostateczny szturm na wioskę.', 0),
(11631, 'plPL', 'Spętali jego ducha. $N, musimy położyć kres jego męczarniom!$B$BMusisz zejść w trzewia Magmoth i znaleźć sposób, by go uwolnić!', 0),
(11632, 'plPL', '<Zaurzykieł uśmiecha się szeroko.>$B$BWygląda znajomo... Potęga Kalimdoru rozdeptała tysiąc takich robali na pustyni Silithusu.$B$BTo inne miejsce – inne otoczenie – ale wynik będzie taki sam.$B$B<Zaurzykieł mierzy cię wzrokiem.>$B$BPrzyniesiesz Hordzie dumę i chwałę w Północnej Grani, $N.$B$B<Zaurzykieł kiwa głową.>', 0),
(11633, 'plPL', '<Wódz Zimowa Wichura słucha, jak opisujesz swoje obserwacje.>$b$bZebrane przez ciebie informacje pomogą nam zaplanować szturm na Świątynne Miasto. Musimy znaleźć sposób, by pokonać wskazanych przez ciebie dowódców i dostać się do tej nekropolii.', 0),
(11634, 'plPL', 'Aj, mon. Ja czekać na ciebie.$B$B<To\'bor wskazuje na zachód.>$B$BZerknij. Za tą tundrą być śmierć, mon... śmierć.', 0),
(11635, 'plPL', 'Dziękuję za wytchnienie. Gdyby tylko prawdziwa wolność była tak łatwa do osiągnięcia.', 0),
(11636, 'plPL', 'ŻADNEJ LITOŚCI DLA UMARŁYCH!$B$BŻaden z nich nie miał odwagi zostać i bronić naszych wspaniałych czołgów, kiedy Piekłorycz uznał wybrzeże za „stracone”. Przeważnie jest tu spokojnie, bo Plaga formuje szeregi do szturmu na Warownię Wojennej Pieśni. Czasem zabłąka się jakiś zombie albo ghul, ale długo nie pociągną.$B$B<Gorge gładzi swój topór.>$B$BNo, jest jeszcze mgła...$B$B<Gorge wzdryga się.>\n', 0),
(11637, 'plPL', 'Jestem wolny. Dziękuję ci, $N.$b$bA teraz mam do ciebie ostatnią prośbę.', 0),
(11638, 'plPL', 'Dziękuję, że $guwolniłeś:uwolniłaś; jego ducha spod władzy Kaganishu i $gwróciłeś:wróciłaś; z jego szczątkami. Niewiele mamy, by cię wynagrodzić, ale weź, co ci wpadnie w oko.$b$bA teraz przywrócę go do świata żywych, gdzie jego miejsce.', 0),
(11639, 'plPL', 'Twoje czyny oddają cześć poległym, $N.$b$b<Ranny ork kiwa głową i powoli wypuszcza powietrze.>$b$bMoże teraz odnajdę drogę do bycia wojownikiem, jakim kiedyś byłem.', 0),
(11640, 'plPL', '<Wódz Zimowa Wichura czyta słowa zapisane na zwojach.>$b$b„Shabtir bakh sokhen”.$b$bSłowa w pradawnym, szorstkim języku nerubian, i to trafne.$b$b„Sługa korzy się przed władzą pana”. To słowa, dzięki którym wejdziesz do nekropolii.', 0),
(11641, 'plPL', '$GDowiodłeś:Dowiodłaś; swojej nieustraszoności i $gpokazałeś:pokazałaś; swoją biegłość w walce. Sądzę, że $gbyłbyś:byłabyś; $gświetnym wojownikiem:świetną wojowniczką; taunka. Szkoda, że wódz tego nie rozumie.$b$bTo dla nas szczęście, że możemy liczyć na twoje wsparcie w walce o ewakuację wioski, zanim zaleje ją Plaga.', 0),
(11642, 'plPL', 'Ty jesteś nowym kierowcą czołgu, kolego? Mnie pasuje! Musimy tylko znowu uruchomić te maszyny. No, spróbuj wyjść na Równiny Nasam bez czołgu, a już po tobie.', 0),
(11643, 'plPL', 'Świetna robota, kolego! No to gdzie ja położyłem te części zamienne...', 0),
(11644, 'plPL', 'Świetna robota, kolego! No to gdzie ja położyłem ten pneumatyczny transdżygamaryg czołgowy.\n', 0),
(11645, 'plPL', 'Och, $N, jesteś po prostu $gnajlepszy:najlepsza;!$b$bOto twoje pieniądze, tak jak obiecałam.', 0),
(11646, 'plPL', 'Donathan mądrze postąpił, przysyłając cię.$b$bJak się okazuje, potrzebuję kogoś spoza Kirin Toru.', 0),
(11647, 'plPL', '<Mędrczyni Aeire odbiera od ciebie totem.>$b$bCzy totem zadziałał? Jego przygotowanie wymagało pradawnej magii, której mędrcy nie używali od pokoleń. Z całej przekazanej wiedzy tylko ułamek jest dziś w użyciu.', 0),
(11648, 'plPL', 'Doskonale! Zdobycie tych informacji było kluczowe.$b$bDobra robota, przyjacielu.', 0),
(11649, 'plPL', 'Żałuję utraty tych nawałnic, ale dane słowo mnie wiąże... nawet wobec śmiertelnika takiego jak ty.$B$BA teraz zobaczmy, czy uda się wykonać coś, co ci się przyda.', 0),
(11650, 'plPL', 'No, to rozumiem! Teraz musimy tylko to wszystko poskładać.$B$BJasne, jakbyś $gmiał:miała; mi w tym pomóc.$B$BWstrzymaj konie, to potrwa tylko sekundkę, skoro mam już z powrotem swoje narzędzia!', 0),
(11651, 'plPL', 'Przy obecnym stanie naszego transportu i szlaków żeglugowych nie udało nam się dostarczyć do Warowni Wojennej Pieśni ani jednej cholernej machiny oblężniczej. Te czołgi to wszystko, co zostało z pierwotnej wyprawy. Skoro już działają, użyjesz ich, żeby zdeptać natarcie Plagi na Równinach Nasam.', 0),
(11652, 'plPL', 'Kel\'Thuzad? A więc to prawda – Naxxramas powraca...$B$BMoże cię nie doceniłem, $N. $GOddałeś:Oddałaś; Hordzie wielką przysługę. Wódz byłby dumny!$B$B<Garosz milknie, zastanawiając się.>$B$BJeśli Kel\'Thuzad dowodzi tą Plagą, nie wiadomo, co jeszcze szykuje dla nas Król Lisz... Potrzebuję czasu, żeby przemyśleć te nowe wieści, $N. Możesz odejść.', 0),
(11653, 'plPL', 'Jak to nie zadziałał?!$b$bAle... ale...$b$b<Crafty zaczyna szlochać.>$b$bDobra, poradzimy sobie z tym. Jestem dużą dziewczynką. Czas pomyśleć nieszablonowo!', 0),
(11654, 'plPL', '<Tropiciel śniegu taunka wygląda na osłabionego i ledwie na ciebie reaguje.>$b$bNie zostało mi... wiele czasu. Może... może ty ich powstrzymasz... zanim...', 0),
(11655, 'plPL', '<Waltora ogarnia smutek.>$B$BRuina... Tylko to po sobie zostawiają. Trzeba dać im nauczkę.', 0),
(11656, 'plPL', 'Pokaz oporu wobec dzikusów kvaldirów może być tym, czego trzeba, by ocalić mój lud w innych obozowiskach. Może kvaldirowie przemyślą swoje czyny, jeśli uwierzą, że czeka ich odwet.', 0),
(11658, 'plPL', 'Nieźle, ale te ciuchy cuchną!$B$BJa za nic w świecie nie pokazałabym się w takich łachmanach. Ale będziemy musieli je przejrzeć i znaleźć coś, co pasuje do twojej, eee... figury.', 0),
(11659, 'plPL', 'Bałem się, że mogli pojmać Grumma, ale nigdy nie sądziłem, że zrobią mu coś tak potwornego. Nigdy nie widziałem, by wojownik przeżył przegraną bitwę z Plagą.$b$bDziękuję, że $gprzyniosłeś:przyniosłaś; wieść o jego losie, $N. Był potężnym wojownikiem i tak go zapamiętamy.', 0),
(11660, 'plPL', 'Musisz wezwać Orabusa Rogiem starego żeglarza.', 0),
(11661, 'plPL', 'Wygląda na to, że utrata porucznika tylko rozdrażniła gniazdo. Są jeszcze bardziej rozwścieczeni i agresywni niż przedtem!$B$B<Waltor wzdycha.>$B$B$GZrobiłeś:Zrobiłaś; tu, co w twojej mocy, przyjacielu. Zasługujesz przynajmniej na jakąś rekompensatę za przetrzebienie ich szeregów.\n', 0),
(11662, 'plPL', 'Waltor mądrze zrobił, przysyłając cię do mnie. Bogowie uśmiechają się do tych, którzy wymierzają sprawiedliwość. To ty wymierzysz karę niegodziwcom!', 0),
(11663, 'plPL', 'Wybacz mi, $N. Wiem, że to była nieprzyjemna robota.$b$bGdyby nie rozpaczliwe położenie, w jakim się znaleźliśmy, nigdy nie prosiłbym cię o taką pomoc.$b$bA więc... czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(11664, 'plPL', 'Wiatry o tym szepczą, przyjacielu. Żywioły znają twoje imię. $GWyświadczyłeś:Wyświadczyłaś; dziś Mootoo wielką przysługę i zostaniesz za to $gnagrodzony:nagrodzona;.', 0),
(11670, 'plPL', 'O rany julek, udało ci się!$B$BDobra, teraz te uciążliwe magnataury i ich snoboldzcy pachołkowie powinni zwrócić uwagę na Hordę.$B$BJak ja ci się odwdzięczę, $N?', 0),
(11671, 'plPL', 'Złamany?$b$bDaj mi rzucić okiem...', 0),
(11672, 'plPL', 'Czekaliśmy na twoje przybycie, $N. Witaj w Północnej Grani.', 0),
(11673, 'plPL', 'Hę? Co?$b$bJaki Bonker?$b$bNie mam pojęcia, o kim mówisz, ale wierzę ci na słowo. Jeśli $guratowałeś:uratowałaś; go albo ją z otchłani Magmoth, to chyba należy ci się nagroda.$b$bZobaczmy, co tu mam pod ręką...', 0),
(11674, 'plPL', 'Przysłała cię Wszechmatka. Musi być mną rozczarowana.$b$bAle kiedy zobaczyłam, jak ten wielki obiekt spada z nieba, nie mogłam czekać, aż towarzyszyć mi będzie pełny oddział biegaczy i tropicieli śniegu. Wiedza na nikogo nie czeka.', 0),
(11675, 'plPL', 'Cóż innego możemy zrobić, jak nie ulżyć ich cierpieniu? Tak czy inaczej, przyszły tu umrzeć, więc ich nie opłakuj. Przynajmniej $gdałeś:dałaś; im trochę godności.$b$bTeraz musimy położyć kres temu, co wywołuje zarazę.', 0),
(11676, 'plPL', 'Każdy uratowany więzień to o jedno nieumarłe wynaturzenie mniej, z którym trzeba się będzie zmierzyć, $N. $GOddałeś:Oddałaś; Hordzie wielką przysługę.', 0),
(11677, 'plPL', '<Mędrczyni zwiesza głowę i z ulgą wzdycha.>$b$bTo dobry początek. Gdyby tylko to był nasz jedyny problem.', 0),
(11678, 'plPL', 'Nie... pożyję... już długo... na tym świecie...', 0),
(11679, 'plPL', 'Wasze błahe gierki nie mają tu żadnego znaczenia...$b$bTy i twoi sojusznicy z Dalaranu skubiecie luźne nitki, podczas gdy tkanina przyszłości tego świata jest rozdzierana na strzępy.$b$bMimo to może to zapewnić moim smokowcom trochę potrzebnej rozrywki.$b$bPokaż mi ten klucz...', 0),
(11680, 'plPL', 'To jest to, klucz jest nasz!', 0),
(11681, 'plPL', 'Twoje bohaterskie wysiłki nie zostaną zapomniane.$b$bProszę, przyjmij to z wyrazami mojej szczerej wdzięczności.', 0),
(11682, 'plPL', 'A więc znów rozmawiamy.$b$bGdy wysłuchasz moich słów, być może pożałujesz, że do tego doszło.', 0),
(11683, 'plPL', 'Dziękuję, $N.$b$bKról Lisz i jego Plaga są zarazą Północnej Grani. Nie możemy przestać, dopóki wszyscy nie będą naprawdę martwi, a jego istnienie nie dobiegnie kresu!', 0),
(11684, 'plPL', '<Praojciec Mahan przyjmuje mapę, ale nawet nie próbuje jej obejrzeć.>$b$bTwoje informacje przydadzą się później, gdy będziemy gotowi wprowadzić plan w życie.', 0),
(11685, 'plPL', 'Tyle powinno wystarczyć, by uformować rdzeń potężnego żywiołaka, ale sam kamień nie tchnie życia w mojego żywiołaka.', 0),
(11686, 'plPL', 'To o wiele gorsze, niż wynikało z dziennika Luthera. Zalali to miejsce Plagą i zarażają wszystko, czego dotkną.$b$b<Ickoris kiwa głową.>$b$bA będzie jeszcze gorzej – o ile to w ogóle możliwe...', 0),
(11687, 'plPL', 'Szczecinoróg nie żyje?!$b$bNie powinnam była pozwolić mu iść tam samemu.', 0),
(11688, 'plPL', 'Chyba mam, $N!', 0),
(11689, 'plPL', 'Jakie wieści przynosisz od Wysokiej Mesy?$b$b<Wyjaśniasz, co wiesz, i przekazujesz Wszechmatce złe wieści o biegaczu Szczecinorogu.>$b$bMój... mój wnuk!$b$b<Wszechmatka walczy, by zapanować nad emocjami.>$b$bZginął honorową śmiercią, jak prawdziwy taunka!$b$bTo ty $gbyłeś:byłaś; z nim na końcu, $N, więc zawsze będzie częścią ciebie. Dziękuję ci, że $gspełniłeś:spełniłaś; jego ostatnią wolę.', 0),
(11690, 'plPL', '$GJesteś prawdziwym bohaterem:Jesteś prawdziwą bohaterką;, $N. Bez ciebie moje kodo by tam zginęły. Dziękuję ci ja i dziękują wszyscy żołnierze i czeladnicy, którzy będą używać tych kodo, by umocnić naszą obecność w Północnej Grani!', 0),
(11692, 'plPL', 'Czego potrzebujesz?', 0),
(11693, 'plPL', 'Niezła robota, ale przy najbliższej okazji weź prysznic.$B$BA teraz naprawdę rozprawmy się z tutejszym problemem.', 0),
(11694, 'plPL', 'Wiedziałam, że dasz radę. A teraz muszę cię poprosić, żebyś $gzajął:zajęła; się czymś jeszcze.', 0),
(11695, 'plPL', '<Barah bierze od ciebie części rogu i próbuje je do siebie dopasować.>$b$bBurzowe Kopyto byłby z ciebie dumny, $N. Może gdy już rozprawimy się z Plagą, zabiorę róg na pielgrzymkę do grobowca Burzowego Kopyta.', 0),
(11697, 'plPL', 'Hej! Kim jesteś?$B$BBixie cię przysłała? Świetnie, wyciągnijmy mnie stąd!', 0),
(11698, 'plPL', 'Dzięki, $N.$B$BKról Lisz i jego Plaga są naprawdę straszni, ale nie możemy przestać, dopóki wszyscy nie będą leżeć nieruchomo w nowych grobach!', 0),
(11699, 'plPL', 'Znakomicie! Teraz tylko mała przeróbka tutaj i poprawka tam...', 0),
(11700, 'plPL', 'Tinky ma złą bliźniaczkę?!$B$BCóż, skoro mówi, że nic jej nie jest i że niedługo sama wróci na lądowisko, to mi wystarczy.', 0),
(11701, 'plPL', 'Niezła historia, $N. Przy tych wszystkich kłopotach aż dziw, że lądowiska jeszcze nie zmiotło z powierzchni ziemi.$B$BAle dzięki tobie mamy o jednego przeciwnika mniej.$B$BOdłożyłem kilka specjalnych rzeczy właśnie na taką okazję. Może coś sobie wybierzesz?', 0),
(11702, 'plPL', 'Nareszcie pomoc! I sądząc po twoim wyglądzie, z Hordy.$B$BNic nie szkodzi... twój lud jest bardzo biegły w sztuce walki. Będziemy tego bardzo potrzebować.', 0),
(11703, 'plPL', '<Getry mierzy cię wzrokiem.>$B$BTylko tyle mógł przysłać Ickoris?', 0),
(11704, 'plPL', 'Nareszcie pomoc! I sądząc po twoim wyglądzie, z Przymierza.$B$BTo dobrze... twój lud jest bardzo biegły w sztuce walki. Będziemy tego bardzo potrzebować.', 0),
(11705, 'plPL', 'I $gwróciłeś:wróciłaś; zwycięsko, tak jak myślałem! Mówiłem Zaurzykłowi, że dasz sobie radę.$B$B<Piekłorycz chrząka porozumiewawczo.>$B$BMoże to pokaże temu staremu psu, że nie zna wszystkich odpowiedzi, co?', 0),
(11706, 'plPL', 'Twoje wysiłki przeciw nerubianom dały nam wytchnienie od przytłaczającego natarcia Plagi. Dzięki twoim dokonaniom możemy uderzyć na fortecę Plagi na północnym wschodzie bez obawy przed atakiem z zachodu.$B$BA róg będę strzec, dopóki znów nie będziemy potrzebować jego mocy. Burzowe Kopyto oddał życie, by zdobyć róg, i nie możemy dopuścić, by znów przepadł.', 0),
(11707, 'plPL', 'Widzę, że Chmuroskok w końcu zabrał się za wysłanie pomocy. I to w ostatniej chwili, dodam!$B$BWitaj, $gbracie:siostro;, bardzo potrzebujemy twojej pomocy!', 0),
(11708, 'plPL', 'Staruszek przysłał cię do mnie, co? Opowiedział ci wszystko, co się tu dzieje?$B$BDobrze... to bierzmy się do roboty!', 0),
(11709, 'plPL', '<Nork prycha z pogardą.>$B$BWięźniowie? To nie są więźniowie. To tchórzliwe psy! Tylko na nich popatrz. Wiesz, że co do jednego każdy z tych bojaźliwych „żołnierzy” przyszedł pod nasze bramy i złożył broń i zbroję?$B$BZ tego, czego zdołaliśmy się dowiedzieć, jeśli ci ludzie wpadną w nasze ręce, zostają zwolnieni ze służby i odesłani do domów.$B$B<Nork spluwa.>$B$BŻałosne...', 0),
(11710, 'plPL', 'Świetnie, $N! Te części wyglądają na całkiem sprawne.$B$BTeraz tylko żebym jeszcze wiedział, jak naprawić to przeklęte ustrojstwo...', 0),
(11711, 'plPL', 'Dobra robota, $N. O jedną plugawą, bezużyteczną szumowinę z Przymierza mniej do utrzymywania...$B$BJeśli szukasz więcej roboty, tauren i krwawa elfka w pobliżu potrzebują pomocy.$B$BNo i oczywiście my też mamy tu swoje problemy...', 0),
(11712, 'plPL', 'Udało ci się... zadziałało!$B$BNie mogę uwierzyć, że $gzdołałeś:zdołałaś; uratować aż tylu. Mamy szczęście, że jesteś w pobliżu!', 0),
(11713, 'plPL', '<Abner bierze od ciebie mapę i uważnie ją ogląda.>$B$BŚwietnie! To wszystkie informacje, których potrzebujemy, by rozpocząć operację. ', 0),
(11714, 'plPL', 'Dobra robota, $N! Dziękuję!', 0),
(11715, 'plPL', '<Abner zabiera się do opróżniania zbiornika paliwa zbieracza.>$B$BRęczna destylacja to będzie brudna robota, ale niedługo się z tym uporam. Tymczasem do ukończenia maszyny potrzebujemy jeszcze jednego materiału.', 0),
(11716, 'plPL', 'Cudownie! Po prostu cudownie!$B$B<Laurith posypuje jeden ze słupków krwawych zarodników szczyptą pyłku i wypowiada zaklęcie.>$B$BHmpf... Nie rozumiem. Chyba że... Ależ oczywiście!', 0),
(11717, 'plPL', 'Aha!$B$B<Laurith posypuje pyłkiem ćmy słupki krwawych zarodników.>$B$BPopatrz tylko!', 0),
(11718, 'plPL', '<Abner ogląda skóry, kaszląc od unoszącego się z nich kurzu.>$B$BCzy te zwierzęta w ogóle nie dbają o czystość? Niektóre są potwornie brudne. No cóż, chyba lepiej od razu zabiorę się do czyszczenia. Przecież nikt tu nie ma wolnego czasu.', 0),
(11719, 'plPL', 'Pierwotny mocaróg będzie zachwycony! Wyszło lepiej, niż sama się spodziewałam!$B$BChyba czas, żebym powiedziała ci prawdę.', 0),
(11720, 'plPL', 'Krwawe zarodniki, które $gzebrałeś:zebrałaś;, mogą wystarczyć, by dać nam przewagę nad magnataurami z Gammoth – oczywiście z twoją pomocą.', 0),
(11721, 'plPL', 'Dobra robota, $N! Czy $gzechciałbyś:zechciałabyś; uhonorować Laurith i mnie, zanosząc głowę tej bestii Piekłoryczowi? Będzie niezmiernie zadowolony.', 0),
(11722, 'plPL', '<Piekłorycz podnosi głowę Gammothry jedną ręką i pluje jej w twarz.>$B$BNauczą się, $N... Wszyscy się nauczą. Z Hordą nie ma żartów...', 0),
(11723, 'plPL', '<Abner z zapałem słucha twojej relacji o sukcesie twoim i Wstrząsomatu 5000.>$B$BFizzcrank ucieszy się z tych wieści! Kto wie, może jeszcze zrobimy z ciebie $gmechanika:mechaniczkę;!', 0),
(11724, 'plPL', 'Alkora już nie ma, co? Szkoda... Co do jaja, właściwie już się nam nie przyda. Mamy teraz znacznie poważniejsze problemy.', 0),
(11725, 'plPL', 'Dzięki niebiosom. To było straszne.$B$BNa ziemi coś jasno błysnęło, a zaraz potem cała eskadra zaczęła spadać! Jestem ciężko ranny, więc nie mogłem przeszukać miejsca katastrofy w poszukiwaniu innych ocalałych, ale coś mi mówi, że nie będzie ich wielu.$B$B<Iggy krzywi się z bólu.>$B$BPomożesz mi dokończyć misję?', 0),
(11726, 'plPL', '<Iggy zatyka nos, opróżniając sakiewki z przyprawami, i mówi do ciebie przez nos.>$B$BSkoro mamy, czego trzeba, połączę to z moimi racjami żywnościowymi i zrobię przynętę na wilki.', 0),
(11727, 'plPL', 'Na brodę Magniego! Wygląda na to, że nadciąga ciężka artyleria.', 0),
(11728, 'plPL', '<Iggy zatyka nos, odbierając od ciebie mikrofilm.>$B$BFuj, no cóż, spełniliśmy wymogi sekcji 8.2, akapitu B procedury awaryjnej i odzyskaliśmy film. Ale nigdzie w procedurze nie jest napisane, że to ja mam go czyścić.', 0),
(11729, 'plPL', 'Mój śrubokręt... $gznalazłeś:znalazłaś; mój śrubokręt! Zastanawiałam się, gdzie on się podział.$B$BHmm, mówisz, że $gznalazłeś:znalazłaś; go w jednym z ich robotów? To podsuwa mi pewien pomysł...', 0),
(11730, 'plPL', 'Hura! I do tego $gprzyniosłeś:przyniosłaś; śrubokręt w jednym kawałku!$B$BPrzeprogramowanie tych robotów da nam ogromną przewagę w walce z Mistrzem Trybów Mechazodem. Chyba $gzasłużyłeś:zasłużyłaś; na coś w nagrodę.', 0),
(11733, 'plPL', 'Witaj w Mrozarze, $N.$b$bPod Tarczą Transitus ukrywamy się o rzut kamieniem od Nexusa, twierdzy wielkiego aspektu Malygosa i jego Błękitnego Stada.$b$bRozgość się.', 0),
(11788, 'plPL', 'Łał, $gprzeżyłeś:przeżyłaś;!$B$BChyba zostało nam już tylko rozprawić się z Mistrzem Trybów Mechazodem.', 0),
(11789, 'plPL', 'Dziękuję ci, $N. Ten człowiek będzie długo dochodził do siebie, ale go nie stracimy.$B$BCo mówisz? $GZnalazłeś:Znalazłaś; kultystów na pokładzie „Łamacza Burz”? Lepiej kogoś zawiadom... i przynieś jakiś dowód.', 0),
(11790, 'plPL', 'Kultyści? Pod pokładem? Powinienem kazać wychłostać całą załogę!$B$BSłuchaj... może niech admirał Cantlebree zajmie się tą... sytuacją?', 0),
(11791, 'plPL', 'Dziękuję za troskę, $N. Dowiedzieliśmy się o tej sytuacji niedawno.$B$BDoradca Talbot zapewnia mnie, że to odosobniony incydent i nie ma powodu do niepokoju ze strony wojska.$B$BNasze władze cywilne dopilnują, by wszyscy zamieszani zostali należycie osądzeni.', 0),
(11792, 'plPL', 'Zachowaj dyskrecję, $N. Nie możemy oglądać tych dowodów na oczach wścibskich.', 0),
(11793, 'plPL', 'Mów szybko, $N. Co wiesz o kulcie?', 0),
(11794, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Nie mogę jednak oprzeć się wrażeniu, że to nie ostatni raz, gdy mamy do czynienia z tymi kultystami śmierci.$B$BCiemność potrafi się ukryć nawet na widoku.', 0),
(11795, 'plPL', 'Jeszcze raz dziękuję, $N. Dzięki twojej pomocy być może jeszcze uda mi się dokończyć tę misję, choć okazała się katastrofą, wrócić do Fizzcranka, złożyć raport i godnie uczcić poległych.', 0),
(11796, 'plPL', 'Jeszcze raz dziękuję, $N. Bez ciebie nie zdołałbym ocalić z tej katastrofy niczego przydatnego.', 0),
(11797, 'plPL', 'Dobra robota, $N. Pokaż chłopakom, jak to się robi. Dobry pełzacz to martwy pełzacz!', 0),
(11798, 'plPL', '<Stary gnom wzdycha z ogromną ulgą.>$B$BA więc to koniec... $gocaliłeś:ocaliłaś; nas! Gdyby nie to, że $gpowstrzymałeś:powstrzymałaś; go tutaj, kto wie, jak daleko rozlałoby się jego szaleństwo?$B$BPrzy zagrożeniu ze strony niebieskich smoków i wojny o Nexus, nie wspominając o Królu Liszu, ostatnie, czego nam trzeba, to szalony twór tytanów na wolności!$B$BDziękuję ci, $N!', 0),
(11864, 'plPL', 'Ten demon ma wiele imion, a każde z nich w swoim czasie miało szczególne znaczenie. Choć szczegóły bywały bez znaczenia, wynik zawsze był ten sam: śmierć.$B$BAle to właśnie teraz, blisko pięćdziesiąt lat po tym, jak wszystko się zaczęło, szczegóły dopadną diabła i doprowadzą do jego upadku.$B$BTym razem go mamy... Nesingwary nie ucieknie.$B$BPółnocna Grań stanie się polem bitwy w naszej wojnie. Myśliwy stanie się zwierzyną!', 0),
(11865, 'plPL', 'Wykonujesz dzieło Matki Ziemi, $N, ale nie ciesz się zbyt długo tym zwycięstwem. Odkryliśmy kryjówkę przywódczyni traperów.', 0),
(11866, 'plPL', 'Zawieszę je sobie na szyi. Niech usłyszą nasze przesłanie i niech te uszy będą naczyniami, które poniosą naszą prawdę!', 0),
(11867, 'plPL', 'Zawieszę je sobie na szyi. Niech usłyszą nasze przesłanie i niech te uszy będą naczyniami, które poniosą naszą prawdę!', 0),
(11868, 'plPL', 'Może jej śmierć będzie przestrogą dla innych, którzy ośmielają się zabijać zwierzęta dla rozrywki i bogactwa.', 0),
(11869, 'plPL', 'Zobaczmy teraz, czy nie zadrżą, gdy zobaczą, co się stało z ich towarzyszami!', 0),
(11870, 'plPL', 'Przysyła cię Cenius? No, w samą porę!', 0),
(11871, 'plPL', 'Dobra robota, $N. Teraz uderzymy w przywódcę piratów!', 0),
(11872, 'plPL', 'Świetna robota, $N. Jesteśmy coraz bliżej Nesingwary\'ego!', 0),
(11873, 'plPL', '<Fizzcrank słucha twojego raportu z wyraźną ulgą.>$B$BPowinienem był z nimi polecieć. Może udałoby się nam wykonać misję bez utraty pilotów.$B$BAle Korkociąg ma rację – to tobie zawdzięczamy to, co udało się ocalić. Twoje wysiłki mogą przesądzić o wyniku walki z nerubianami.', 0),
(11876, 'plPL', '<Arcydruid Lathorius ociera łzy.>$B$BNie miały żadnych szans. Teraz, osierocone, same z pewnością zginą.', 0),
(11878, 'plPL', '<Słyszysz w głowie głos. To Khu\'nok.>$B$BTwoje imię niesie świszczący wiatr, $N. Wiele $gzrobiłeś:zrobiłaś; dla moich pobratymców. Za to uznamy cię za sojusznika. Niestety, nasza udręka nie skończy się bez rozlewu krwi i przemocy.$B$BCeną pokoju dla mamutów będzie śmierć Kawa...', 0),
(11879, 'plPL', '<Lathorius odbiera od ciebie halabardę.>$B$BCzy to jest to, co myślę?$B$B<Lathorius szczerzy zęby w uśmiechu.>$B$BZnakomicie! Wspaniale! Kolejny pachołek Nesingwary\'ego odpowiedział za swoje czyny!', 0),
(11881, 'plPL', '<Fezzix przegląda złom.>$B$BJenny jest trochę poturbowana, ale wyjdzie z tego. Co do złomu, jest go nieco mniej... i bardziej w kawałkach, niż się spodziewałem, ale na pewno znajdę dla niego zastosowanie. Ale to jeszcze nie koniec twojej roboty. Odbudujemy to cacko.', 0),
(11884, 'plPL', 'Przynajmniej na razie nosorożce zaznają spokoju. Dziękuję ci, $N.', 0),
(11887, 'plPL', 'Gnomie narzędzia? Dla mnie? Z nimi odbudowa tej latającej maszyny pójdzie jeszcze łatwiej, niż się spodziewałem.', 0),
(11888, 'plPL', 'Nie dziwi mnie, że orczy wódz nie ma czasu wysłuchać o naszych kłopotach. Starania ambasadora zapewne rozwieją się jak mgła na wietrze.$B$BAle teraz jesteś tutaj. Zobaczymy, czy dobrze wybrał, przysyłając ciebie.', 0),
(11889, 'plPL', 'Pobijemy ich, jeśli przyjdą lądem, i pobijemy ich, jeśli przylecą powietrzem. A jeśli ci nieumarli sukinsyni przypłyną morzem, spuścimy im lanie ich życia.', 0),
(11890, 'plPL', 'To naprawdę niepokojące wieści.$B$BMój lud wkrótce opuści to miejsce. Przebijemy się przez linie Plagi do naszej stolicy, Wioski Lodowej Mgły, na Smoczych Pustkowiach.$B$BAle zanim to zrobimy, musimy uporać się z tym, co gnomy nawyczyniały w swoim szaleństwie.', 0),
(11892, 'plPL', 'Niestety, Nesingwary\'ego już nie ma. Może w ogóle go tu nie było...$B$B<Lathorius wzdycha.>$B$BTen demon jest śliski, ale jego dni są policzone. Znajdziemy go, a wtedy...', 0),
(11893, 'plPL', '<Dorain kiwa głową.>$B$BDobrze. To powinno wystarczyć, by pokazać Fezzixowi dokładnie to, co próbowałem mu wytłumaczyć.', 0),
(11894, 'plPL', 'Fantastycznie! Jeszcze kilka poprawek i będę latającym goblinem!', 0),
(11895, 'plPL', 'Czuję, jak przepływa przez ciebie moc burzy!$B$BJesteś $ggotów:gotowa;, $N. Zaczynajmy.', 0),
(11896, 'plPL', 'Skoro rozprawiliśmy się z ich mechanicznymi sługami, czas zapolować na większą zwierzynę. Niestety, już teraz czuję, jak moc burzy w tobie słabnie.$B$BMimo to spełniła swoje zadanie i myślę, że bez niej też z łatwością zrobisz następny krok.', 0),
(11897, 'plPL', 'Świetna robota, $N. Bez ciebie Twierdza Walecznych mogłaby nie odeprzeć napastników. Dzięki twojej pomocy dożyjemy kolejnej bitwy.', 0),
(11898, 'plPL', 'Po klęsce księcia władza Plagi w Boreańskiej Tundrze została złamana. Nie łudzę się, że długo będą trzymać się z dala, dlatego muszę skupić się na przygotowaniu Durma do poprowadzenia mieszkańców wioski do Lodowej Mgły.$B$B<Wódz powoli kręci głową.>$B$BMimo wszystkich sporów, jakie miałem z Durmem, ufam jego osądowi i umiejętnościom. Nie potrafię się zmusić, by porzucić Taunka\'le, więc będę jej bronił aż do śmierci.', 0),
(11899, 'plPL', 'Teraz musimy uwolnić dusze, które $gpochwyciłeś:pochwyciłaś;.', 0),
(11900, 'plPL', 'Jest gorzej, niż się spodziewałem.$b$bMalygos ściąga w to miejsce zbyt wiele mocy. Jeśli nikt go nie powstrzyma, Azeroth stanie się drugą Rubieżą!$b$bNa szczęście chyba opracowałem tymczasowe rozwiązanie....', 0),
(11901, 'plPL', 'Gdy zbliżasz się do zboża, w żołądku czujesz niepokój. Smród jest niemal nie do zniesienia.', 0),
(11902, 'plPL', 'Biedne chłopaki... nie mieli żadnych szans!$B$BTo z pewnością robota kogoś od środka. Pewnie jakiegoś agenta Kultu Potępionych. Niech szlag trafi tych szaleńców!', 0),
(11903, 'plPL', '$GPrzemówiłeś:Przemówiłaś; do Plagi jedynym językiem, jaki rozumie: przemocą i śmiercią. Niestety, oni wciąż nadciągają!', 0),
(11904, 'plPL', 'Dziękuję ci, $N. Ta ruda będzie miała dla Przymierza ogromne znaczenie w nadchodzących czasach. Chciałbym wierzyć, że dziś coś zmieniliśmy.', 0),
(11905, 'plPL', 'Świetna robota, $N. Wstrząsy już zaczęły słabnąć.$b$bPrzy odrobinie szczęścia twoje wysiłki dały nam dość czasu, by znaleźć sposób na pokrzyżowanie planów Malygosa.', 0),
(11906, 'plPL', 'Taunka mają w zwyczaju zostawiać ziemię nieskalaną, zanim ruszą dalej.$B$BJuż wkrótce wyruszymy do naszej stolicy, Wioski Lodowej Mgły. Dzięki tobie możemy odejść o wiele szybciej.$B$BDziękuję.', 0),
(11907, 'plPL', 'Dziękuję, $N.$B$BSkoro te dziwaczne stwory zostały zniszczone, uporanie się z resztą sadzawek powinno być teraz proste.$B$BMamy wobec ciebie dług wdzięczności.', 0),
(11908, 'plPL', 'Świetnie! Informacje, których potrzebuję, powinny tu być.', 0),
(11909, 'plPL', '<Wszechmatka wzdycha z ogromną ulgą.>$B$BA więc to koniec... $gocaliłeś:ocaliłaś; nas! Gdyby nie to, że $gpowstrzymałeś:powstrzymałaś; go tutaj, kto wie, jak daleko rozlałby się ten błąd gnomów?$B$BPrzy zagrożeniu ze strony niebieskich smoków i wojny o Nexus, nie wspominając o Królu Liszu, ostatnie, czego nam trzeba, to szalony twór tytanów na wolności!$B$BDziękuję ci, $N.', 0),
(11910, 'plPL', 'Tak, tak. Świetnie się nadadzą.$b$bDziękuję ci, $N.', 0),
(11911, 'plPL', 'Fascynujące!$B$BI mówisz, że są do tego agresywne. To by sugerowało, że za tymi manipulacjami stoi jakaś inteligencja. Może w tym wcale nie ma nic naturalnego....$B$BProszę, $N, przyjmij to jako wyraz naszej wdzięczności za twoje wysiłki. Dalaran usłyszy o twojej służbie.', 0),
(11912, 'plPL', 'No cóż, to niewiele, ale powinno utrzymać nas przy życiu przez kolejny dzień.$b$bMyślę, że uznasz to za uczciwą zapłatę za twoje wysiłki.', 0),
(11913, 'plPL', 'Dziękuję ci, $N. Nie chciałabym, żeby ci, którzy przeżyli atak na Dalekie Włości, natknęli się na zarażone zboże.', 0),
(11914, 'plPL', 'Twoja służba dla Dalaranu nie przejdzie niezauważona, $N.$b$bMam nadzieję, że ta zapłata ci wystarczy.', 0),
(11916, 'plPL', 'Obawiam się, że możesz się spóźnić, $gczempionie:czempionko;. Wielu moich braci i sióstr już opuściło Taunka\'le, szukając schronienia na Smoczych Pustkowiach, daleko na wschodzie.$B$BZostało tu wiele do zrobienia, a niewielu chce użyczyć nam swojej siły...', 0),
(11918, 'plPL', 'Dobrze, $N, skoro już $gpoznałeś:poznałaś; wroga, czas zabrać się do pracy.', 0),
(11919, 'plPL', 'Los tych młodych smoków nie musi ciążyć na twoim sumieniu, $N. Odpowiada za niego wyłącznie Malygos.$b$bBez wytchnienia pracuję nad odkryciem tajemnic tych run. Nie odbierzemy więcej żyć, niż to konieczne.', 0),
(11920, 'plPL', 'Kultyści? Pod pokładem? Powinienem kazać wychłostać całą załogę!$B$BSłuchaj... może niech admirał Cantlebree zajmie się tą... sytuacją?', 0),
(11927, 'plPL', 'Dziękuję, że $gprzyszedłeś:przyszłaś;. Nie wiedziałam, do kogo innego się zwrócić.', 0),
(11928, 'plPL', '$GPrzyszedłeś:Przyszłaś; pomóc? To w samą porę!', 0),
(11929, 'plPL', '<Matka Tauranook ociera łzy.>$B$BKiedyś, gdy wędrowałam przez tę tundrę, śnieg wypełniał mi widok, jak okiem sięgnąć.$B$BAle śnieg nas opuścił – to znak, że nasz czas tutaj dobiegł końca. Zostawiamy Wioskę Taunka\'le i Boreańską Tundrę z wieloma szczęśliwymi wspomnieniami...$B$B<Matka Tauranook pochlipuje.>$B$BMoże przyszłość powita nasz powrót – razem ze śniegiem.', 0),
(11930, 'plPL', '<Wartook patrzy na ciebie ponuro.>$B$BWioski Lodowej Mgły już nie ma...', 0),
(11931, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bMiejmy nadzieję, że znajdziemy wskazówkę, którą zdołamy wykorzystać przeciw Malygosowi.', 0),
(11932, 'plPL', 'Pamiętam człowieka, o którym mówisz. Nosił znaki Karkuta.$B$BNiech Karkut chroni naszych poległych.', 0),
(11936, 'plPL', 'Z bólem nakazuję niszczyć smocze jaja, czy to wroga, czy nie.$b$bOby cel tej wojny uświęcił środki....', 0),
(11938, 'plPL', 'To powinno dać nam trochę czasu. Isidorus chętnie współpracuje, ale naprawdę potrzebowałem chwili sam na sam z liszem.', 0),
(11940, 'plPL', 'Los tych młodych smoków nie musi ciążyć na twoim sumieniu, $N. Odpowiada za niego wyłącznie Malygos.$b$bBez wytchnienia pracuję nad odkryciem tajemnic tych run.$b$bBądź $gspokojny:spokojna;, nie odbierzemy więcej żyć, niż to konieczne.', 0),
(11941, 'plPL', 'Mądrze $gzrobiłeś:zrobiłaś;, przynosząc mi to, $N.$b$b<Raelorasz przygląda się odłamkowi i powoli kiwa głową.>$b$bJeśli naprawdę pragniesz przyczynić się do naszych wysiłków, bez względu na ryzyko, zdradzę ci jego znaczenie.', 0),
(11942, 'plPL', 'Świetna robota, $N. Teraz jeszcze ostatnia informacja.', 0),
(11943, 'plPL', '<Zebrane przez ciebie fragmenty zaczynają jasno świecić w dłoniach Raelorasza.>$b$bGotowe.$b$bWyczuwam w tym więzieniu potężną obecność. Miejmy nadzieję, że okaże się sojusznikiem.', 0),
(11944, 'plPL', 'To powinno dać nam trochę czasu, $N. Wbrew wszystkiemu będziemy liczyć na posiłki z Twierdzy Walecznych.', 0),
(11945, 'plPL', 'Dziękuję ci, $N. Te zapasy wykarmią naszych krewnych i dzieci. Nawet jeśli Kaskala padnie, nasze plemiona muszą przetrwać.', 0),
(11946, 'plPL', 'Nie możemy czekać, aż odzyskam siły.$b$bW przygotowaniach muszę polegać na tobie....', 0),
(11949, 'plPL', 'Dziękuję ci, $N. Jeśli kiedykolwiek wyjdziemy stąd żywi, będę twoim wielkim dłużnikiem.', 0),
(11950, 'plPL', 'Przysłał cię Ataika, prawda? Nie dam się przekonać.$B$BNie wszystko stracone. Duchy wciąż są z nami.', 0),
(11951, 'plPL', 'Dziękuję ci, $N.$b$bNiewola wyczerpała mnie, a siły wracają do mnie bardzo powoli.$b$bMądrze wykorzystam moc tych kryształów. To produkt uboczny niecnych knowań Malygosa. Przy odrobinie szczęścia przyczynią się do jego upadku.', 0),
(11956, 'plPL', 'W samą porę, $N. Przyszpilenie lisza nie jest takie proste, na jakie wygląda.', 0),
(11957, 'plPL', 'Świat jest lepszym miejscem, odkąd Saragosy już nie ma, ale nasza praca jeszcze się nie skończyła.$b$bNadszedł czas, by uderzyć w samego Malygosa!', 0),
(11961, 'plPL', 'Czujesz obecność Issliruka, $N? Nie chce, by jego dzieci zginęły z rąk kroczących we mgle.', 0),
(11962, 'plPL', 'Ruda z Dalekich Włości? Dostawa miała przyjść dopiero później. Czy coś się stało?', 0),
(11963, 'plPL', 'Hilda przysyła nam broń? To świetne wieści, $N. Już miałem kazać chłopakom się pakować.', 0),
(11965, 'plPL', 'Jeszcze raz dziękuję za pomoc, $N. Mieszkańcy Dalekich Włości zawsze będą cię pamiętać.', 0),
(11967, 'plPL', 'Doszły mnie wieści o uwolnieniu Keristraszy. Należą ci się wyrazy uznania.$b$bNie mogę się doczekać, by znów z nią porozmawiać.', 0),
(11968, 'plPL', '$GWyświadczyłeś:Wyświadczyłaś; nam wielką przysługę, $N. Walka nie jest jeszcze wygrana, ale mój lud ma teraz szansę.', 0),
(11969, 'plPL', 'Zadaliśmy Malygosowi cios, ale zapłaciliśmy za to wysoką cenę.', 0),
(11973, 'plPL', 'A więc stało się....$B$BNasz ród nigdy nie zapomni ofiary, jaką Keristrasza złożyła w tej sprawie. Nie zapomnimy też twojego udziału, $N.$B$BNiech to tragiczne wydarzenie jeszcze bardziej zahartuje naszą determinację wobec zagrożenia, któremu stawiamy czoła.$B$BW imieniu Czerwonego Stada przyjmij, proszę, ten dar jako wyraz naszej wdzięczności.', 0),
(12019, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Miałem nadzieję trzymać moją siostrę z dala od tego wszystkiego. Dzięki tobie żyje i nic jej nie jest.$B$BWypełniłem swoje zobowiązania wobec króla i armii. Najwyraźniej moi towarzysze broni nie chcą mnie już wśród siebie. Będę musiał pójść własną drogą, nie toczyć żadnych wojen poza własnymi i nie słuchać żadnych rozkazów poza głosem serca.$B$BMoże jeszcze się spotkamy, $N. Do tego czasu przyjmij to jako wyraz mojej wdzięczności.', 0),
(12035, 'plPL', 'Dobra robota! W końcu znowu czuję się do czegoś potrzebny... a to już coś.', 0),
(12086, 'plPL', 'Thassarian? Tak, był tutaj... a co? Mamy teraz pilniejsze problemy, $gprzyjacielu:przyjaciółko;.', 0),
(12088, 'plPL', 'Leryssa... mnie szuka? Musisz mi pomóc, $N. Musimy to zakończyć, zanim stanie jej się krzywda.', 0),
(12117, 'plPL', 'Co mówisz, $N? Przysłał cię Hotawa?$B$BDobrze, dobrze... jest mnóstwo do zrobienia. Przyda nam się każda pomoc!', 0),
(12141, 'plPL', '$GPrzybyłeś:Przybyłaś; mi na pomoc? Dziękuję ci, $N.', 0),
(12157, 'plPL', 'Gdy przeprawiałem się przez most na Smocze Pustkowia, z zasadzki zaatakowała mnie niewielka grupa Anub\'ar! Otoczyli mnie! Te potwory wiedziały, że nadchodzę. Ledwie uszedłem stamtąd z życiem. Tę listę, którą mam przy sobie, trzeba dostarczyć do Twierdzy Zimowej Straży, ale jestem zbyt ciężko ranny, by odbyć tę podróż.', 0),
(12471, 'plPL', 'Dziękuję ci, $N. $GOkazałeś:Okazałaś; mojemu klanowi wiele dobrej woli.', 0),
(12486, 'plPL', 'Mistyk wie? Mówisz, że wyczuł, że wieszcza Grimwalkera spotkało coś strasznego?$B$BTego się obawiałam!', 0),
(12728, 'plPL', 'Świetnie, to uzupełnia mój raport.$b$bNa pewno wspomnę radzie o twojej uprzejmości, $N.', 0),
(12791, 'plPL', 'Witaj w Dalaranie.$b$bDopilnuję, żeby pierścień wrócił do właściciela.', 0),
(12794, 'plPL', 'Witaj w Dalaranie.$b$bDopilnuję, żeby pierścień wrócił do właściciela.', 0),
(12796, 'plPL', 'Witaj w Dalaranie.$b$bDopilnuję, żeby pierścień wrócił do właściciela.', 0),
(13002, 'plPL', 'One idealne, mon. Masz tu sztukę doskonałego szlifowania klejnotów.', 0),
(13004, 'plPL', 'Dziękuję. Nauczę cię doskonałego szlifowania klejnotów, a do tego dam ci idealny klejnot, który sam oszlifowałem.', 0),
(13088, 'plPL', 'Tym nakarmimy naszych rekrutów! A oto jak to się przyrządza.', 0),
(13090, 'plPL', 'Dziękuję ci.', 0),
(13094, 'plPL', '$GZnalazłeś:Znalazłaś; je!? Tak, tak, wszystko jest.$b$bProszę, przyjmij to w podzięce. I jeśli to nie za wiele, wolałabym, żeby Berinand nigdy się o tym nie dowiedział.', 0),
(13095, 'plPL', '$GZnalazłeś:Znalazłaś; je!? Tak, tak, wszystko jest.$b$bProszę, przyjmij to w podzięce. I jeśli to nie za wiele, wolałabym, żeby Berinand nigdy się o tym nie dowiedział.', 0),
(13124, 'plPL', 'Słuchaj uważnie, $N.$b$bTwoja praca tutaj dopiero się zaczęła!', 0),
(13128, 'plPL', '<Raelorasz uważnie słucha twojego raportu.>$b$b$N, to bardzo pożądane wieści.$b$bOd początku tego konfliktu nie zadaliśmy Władcy Magii ciosu tej miary.$b$bProszę, przyjacielu, przyjmij wdzięczność naszych zjednoczonych stad.', 0),
(13242, 'plPL', '<Zaurzykieł spogląda w niebo.>$b$bJak Brox, mój syn zginął jak bohater. Nie opłakuj go, $N. Dla orka nie ma lepszego końca! Nie ma większego zaszczytu! W tej chwili moje serce przepełnia duma.$b$bDziękuję, że $gzwróciłeś:zwróciłaś; naszą zbroję bojową. Zostanie złożona na jego stosie pogrzebowym na Ziemiach Przodków w Nagrandzie.$b$bMusimy skupić całą uwagę na pilniejszych sprawach.', 0),
(13265, 'plPL', 'Obyś $gzabijał:zabijała; wielu humanoidów i $gzabierał:zabierała; ich tkaniny.', 0),
(13269, 'plPL', 'Obyś $gzabijał:zabijała; wielu humanoidów i $gzabierał:zabierała; ich tkaniny.', 0),
(13270, 'plPL', 'Obyś $gzabijał:zabijała; wielu humanoidów i $gzabierał:zabierała; ich tkaniny.', 0),
(13272, 'plPL', 'Obyś $gzabijał:zabijała; wielu humanoidów i $gzabierał:zabierała; ich tkaniny.', 0),
(13412, 'plPL', 'Nie sądzisz, że to dość zuchwałe mieszać się w osobiste sprawy smoka, $N?$b$bPomijając to, nie byłoby w porządku, gdybym nie dała bratu znać, że nic mi nie jest. Możesz przekazać swojej wścibskiej przyjaciółce, że będę informować brata o swoich poczynaniach.', 0),
(13413, 'plPL', 'Mój smok mówi, że po odpowiednim treningu możesz stać się $gzdolnym wojownikiem:zdolną wojowniczką;.$b$bNiech więc tak będzie. W interesie naszej wojny z Malygosem pozwolę ci ćwiczyć z moimi podopiecznymi, kiedy tylko zechcesz.$b$bPrzygotuj się, $N, bo to zaciekły i bezlitosny przeciwnik.', 0),
(13414, 'plPL', 'Zauważyłam dziś pewną poprawę, $N. Chwilami wyglądało to tak, jakbyś $gstanowił:stanowiła; ze smokiem jedność.$b$bMożesz ćwiczyć z moimi drogimi podopiecznymi, kiedy tylko zechcesz.', 0),
(13440, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Boreańskiej Tundrze!', 0),
(13441, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Boreańskiej Tundrze!', 0),
(13485, 'plPL', 'Uczcij płomień Boreańskiej Tundry!', 0),
(13493, 'plPL', 'Uczcij płomień Boreańskiej Tundry!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11559, 'plPL', 'Co to? Kim jesteś?$B$BPrzecież to jeden z tych... $r! Jak to możliwe, że mówisz w naszym języku?', 0),
(11560, 'plPL', 'Jeśli nie uratujemy więcej kijanek, wszystko, co robimy, straci sens: murloki Zimopłetwych nie będą miały żadnej przyszłości!', 0),
(11561, 'plPL', 'Skoro $gzabiłeś:zabiłaś; tylu zdrajców Zimopłetwych, to dlaczego, gdy patrzę na drugi brzeg, wciąż widzę ich za wielu?', 0),
(11563, 'plPL', 'Jeśli nie masz głowy Glrggla, nie marnuj mojego czasu!', 0),
(11564, 'plPL', 'Masz cały tłuszcz orek, którego potrzebuję?', 0),
(11565, 'plPL', 'Masz mój zapasowy strój, $n?', 0),
(11566, 'plPL', 'Udało ci się, $N? Claximus nie żyje?', 0),
(11569, 'plPL', 'Masz klucz?$b$bNie, nic mnie nie obchodzą ci pozostali. Chcę się tylko stąd wydostać!', 0),
(11570, 'plPL', 'Tak, $N, co mogę dla ciebie zrobić?', 0),
(11571, 'plPL', 'Udało ci się napełnić konchę parą Parzącej?', 0),
(11576, 'plPL', '$GWykonałeś:Wykonałaś; pomiary, o które prosiłem, $N?', 0),
(11582, 'plPL', 'No i jak?$b$bUdało ci się zlokalizować anomalię?', 0),
(11587, 'plPL', 'Ufam, że pilnie pracujesz nad uwolnieniem uwięzionego maga...', 0),
(11590, 'plPL', '$GSchwytałeś:Schwytałaś; już czarownika z Berylu, $n?', 0),
(11593, 'plPL', 'Właśnie się rozglądałam i widzę, że ciała naszych poległych wciąż tam leżą.$B$BWypełnij swój obowiązek wobec Hordy, $N!', 0),
(11594, 'plPL', 'Skoro tak dobrze się $gspisałeś:spisałaś;, to dlaczego wciąż ich tam widzę?', 0),
(11598, 'plPL', 'To nie my postawiliśmy fort na nerubiańskich tunelach, to te potwory przekopały się do nas!', 0),
(11600, 'plPL', '$GRozmawiałeś:Rozmawiałaś; z Williamem, $N?', 0),
(11602, 'plPL', 'Musisz zniszczyć te worki z jajami!', 0),
(11603, 'plPL', '<Starzec podnosi na ciebie wzrok, a jego twarz nie wyraża niczego.>', 0),
(11605, 'plPL', '<Odległy głos powraca.>$b$bUdało ci się poznać imiona błąkających się starszych?', 0),
(11606, 'plPL', 'Kończy nam się czas, $N.', 0),
(11607, 'plPL', 'Co z duchami niewinnych?', 0),
(11609, 'plPL', 'Udało ci się odzyskać pełen komplet przedmiotów rytualnych?', 0),
(11610, 'plPL', 'Czy $gdokończyłeś:dokończyłaś; obrzędy przodków?', 0),
(11612, 'plPL', 'Czy $gzacząłeś:zaczęłaś; już oczyszczać kamieniołom z naszych wrogów?', 0),
(11613, 'plPL', 'Udało ci się? Kvaldirowie to okrutni wojownicy. Nie spodziewaj się po nich litości.', 0),
(11615, 'plPL', 'Nie żyje?', 0),
(11616, 'plPL', 'Co ma znaczyć to wtargnięcie? Nie zawracaj mi głowy bzdurami!', 0),
(11617, 'plPL', 'Udało ci się zniszczyć latające platformy łowców magów?', 0),
(11619, 'plPL', '$GPokonałeś:Pokonałaś; Gamela?', 0),
(11623, 'plPL', 'Czy $gzałatwiłeś:załatwiłaś; już kustosza?', 0),
(11625, 'plPL', 'Masz trójząb?', 0),
(11628, 'plPL', '$GPrzyniosłeś:Przyniosłaś; futra mamutów?', 0),
(11629, 'plPL', '$N, $gwróciłeś:wróciłaś;. Czego się $gdowiedziałeś:dowiedziałaś;?$B$BCo to za dźwięk?', 0),
(11630, 'plPL', 'Masz ziemię, której mędrczyni Aeire potrzebuje do ukończenia płaszcza?', 0),
(11631, 'plPL', 'Kiedy uznasz, że $gzobaczyłeś:zobaczyłaś; dość, oddaj mi pierwotną esencję.', 0),
(11633, 'plPL', 'Czy $gskończyłeś:skończyłaś; zwiad świątyń w twierdzy Plagi?', 0),
(11637, 'plPL', 'Pośpiesz się, $N, użyj na mnie fetyszu, zanim będzie za późno.', 0),
(11638, 'plPL', 'Wracasz szybciej, niż się spodziewałam. Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(11639, 'plPL', 'Lok\'tar, $N. Niemożliwe, żeby udało ci się w tak krótkim czasie wybić wszystko w Magmoth!', 0),
(11640, 'plPL', 'Musimy dostać się do tej nekropolii, jeśli mamy przebić się przez Plagę i utorować drogę mieszkańcom wioski.', 0),
(11641, 'plPL', 'Nie zawracaj mi głowy, chyba że przychodzisz zameldować o udanej misji.', 0),
(11643, 'plPL', '$GZnalazłeś:Znalazłaś; P.T.C.?', 0),
(11644, 'plPL', 'Pamiętaj, mgła jest zła!', 0),
(11645, 'plPL', 'Masz wszystkie moje zapasy? Bez moich rzeczy nie mogę zrobić NIC!', 0),
(11647, 'plPL', 'Czy $gużyłeś:użyłaś; totemu przy wszystkich kotłach zarazy?', 0),
(11648, 'plPL', 'I jak? Wiesz już, gdzie przetrzymują lady Evanor?', 0),
(11649, 'plPL', 'Gdy zdobędziesz potrzebne drobiny, połączę część mojej esencji z ich esencją. To, co powstanie, da ci to, czego potrzebujesz.', 0),
(11650, 'plPL', 'Czemu jakoś nie wierzę, że $gzebrałeś:zebrałaś; wszystko z mojej listy?', 0),
(11652, 'plPL', 'No i? Co się stało?', 0),
(11653, 'plPL', 'Na pewno $gwypróbowałeś:wypróbowałaś; blaster na dość wielu tych potwornych bestiach?', 0),
(11654, 'plPL', 'Jak... jak mnie $gznalazłeś:znalazłaś;?', 0),
(11655, 'plPL', 'Na krew i honor musisz służyć... Zwróć relikwie kiełzarów.', 0),
(11656, 'plPL', 'Stało się? Statki płoną?', 0),
(11658, 'plPL', 'Będziemy potrzebować mnóstwa ich ciuchów, żeby to zadziałało. Krawcową nie jestem... po prostu musimy znaleźć coś, co na ciebie pasuje!$B$BA potem dodam szczyptę mojego inżynierskiego geniuszu i puf, będziesz wyglądać jak trzeba do tej roli.', 0),
(11660, 'plPL', 'Znajdź Róg starego żeglarza!', 0),
(11661, 'plPL', 'Orabus musi zostać zniszczony!', 0),
(11670, 'plPL', 'To już koniec? $GZrobiłeś:Zrobiłaś; swoje i $gzrzuciłeś:zrzuciłaś; winę na orki z Posterunku Bor\'gorok?', 0),
(11671, 'plPL', 'Czy $gzdobyłeś:zdobyłaś; klucz Salrand?', 0),
(11676, 'plPL', 'Ratuj tych więźniów!', 0),
(11679, 'plPL', 'Śmiesz się do mnie zbliżać, śmiertelniku?$b$bPrzez wzgląd na swoje nienarodzone dzieci módl się, żeby twoja sprawa była tego warta.', 0),
(11683, 'plPL', 'Chyba nie $gzdołałeś:zdołałaś; zgładzić tylu sług Plagi w tak krótkim czasie?', 0),
(11684, 'plPL', 'Czy $gzaznaczyłeś:zaznaczyłaś; położenie zapadlisk?', 0),
(11685, 'plPL', 'Praojciec Mahan mówi, że $gzgodziłeś:zgodziłaś; się pomóc w zawaleniu tuneli.', 0),
(11686, 'plPL', 'Czy $gprzeszukałeś:przeszukałaś; farmy?', 0),
(11687, 'plPL', '$N, $gwróciłeś:wróciłaś;!', 0),
(11688, 'plPL', 'Potrzebuję więcej czasu! Trzymaj te świnie z dala od moich kodo!', 0),
(11690, 'plPL', 'Wyprowadź je z tych opanowanych przez Plagę pól!', 0),
(11695, 'plPL', 'Udało ci się znaleźć róg? Legenda była prawdziwa?', 0),
(11699, 'plPL', 'Masz to wszystko?', 0),
(11705, 'plPL', '<Piekłorycz unosi brew, patrząc na ciebie.>$B$BCo ja słyszę o jakimś nekrowładcy Plagi?', 0),
(11706, 'plPL', 'Czy $guwolniłeś:uwolniłaś; Alluviusa i $grozbiłeś:rozbiłaś; natarcie nerubian?', 0),
(11708, 'plPL', 'Witaj.', 0),
(11710, 'plPL', 'Żeby to ustrojstwo działało, potrzeba mnóstwa części zamiennych.$B$BPowiedz, proszę, że $gwróciłeś:wróciłaś; ze wszystkim, czego potrzebujemy.', 0),
(11711, 'plPL', '<Tungok chrząka.>$B$B$GZałatwiłeś:Załatwiłaś; sprawę dezertera?', 0),
(11712, 'plPL', 'Ile mechagnomów udało ci się przekląć na nowo? ', 0),
(11713, 'plPL', 'Czy $gzaznaczyłeś:zaznaczyłaś; położenie zapadlisk?', 0),
(11714, 'plPL', 'Śmierdząca robota...', 0),
(11715, 'plPL', 'Masz to paliwo?', 0),
(11716, 'plPL', 'Testy muszą trwać!', 0),
(11717, 'plPL', 'Pyłek to klucz do wszystkiego!', 0),
(11718, 'plPL', 'Przynieś te skóry jak najszybciej! Bez nich nie dokończę maszyny!', 0),
(11721, 'plPL', 'Proszkiem można osłabić każdego magnataura. Dlatego tutejsi szczuroludzie tak pilnie go strzegą.', 0),
(11723, 'plPL', 'No i jak, $guruchomiłeś:uruchomiłaś; już Wstrząsomat 5000?', 0),
(11724, 'plPL', 'Witaj!', 0),
(11726, 'plPL', 'Masz te sakiewki z przyprawami?', 0),
(11728, 'plPL', '$GOdzyskałeś:Odzyskałaś; mikrofilm?', 0),
(11729, 'plPL', 'Hej!', 0),
(11730, 'plPL', 'Ile robotów udało ci się przeprogramować?', 0),
(11788, 'plPL', 'Czy zastępcy Mistrza Trybów Mechazoda są już załatwieni?', 0),
(11789, 'plPL', 'Odtrutka... masz ją?', 0),
(11792, 'plPL', '$GWróciłeś:Wróciłaś;, $N.', 0),
(11793, 'plPL', 'Przysyła cię Zwiastun Vurenn?', 0),
(11794, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(11795, 'plPL', 'Masz te insygnia?', 0),
(11796, 'plPL', '$GZniszczyłeś:Zniszczyłaś; już wrak?', 0),
(11797, 'plPL', '$GWróciłeś:Wróciłaś;. Mam nadzieję, że $gprzetrzebiłeś:przetrzebiłaś; szeregi wroga.', 0),
(11798, 'plPL', 'Jinky uprzedziła mnie, że przyjdziesz. Załatwione?', 0),
(11865, 'plPL', 'Nie lituj się nad nimi, $N.', 0),
(11866, 'plPL', 'Uszy w zupełności wystarczą...', 0),
(11867, 'plPL', 'Czy to poszukiwacze skarbów, czy żądni krwi myśliwi z pustkowi – każda istota, która wspiera Nesingwary\'ego i ośmiela się podnieść rękę na naszą ukochaną dziką przyrodę, zostanie uznana za wroga D.E.H.T.A.$B$BJeśli zabijesz tych plugawych popleczników Nesingwary\'ego, przynieś mi dowód ich śmierci, a otrzymasz w nagrodę błogosławieństwo druidów D.E.H.T.A.', 0),
(11868, 'plPL', 'Natura domaga się sprawiedliwości!', 0),
(11869, 'plPL', 'Wykonujemy makabryczną robotę, $N.', 0),
(11871, 'plPL', 'Pochowamy te zwierzęta, jak należy.', 0),
(11872, 'plPL', 'Przynosisz dobre wieści?', 0),
(11876, 'plPL', 'Trzeba je uwolnić!', 0),
(11879, 'plPL', 'Co się stało?', 0),
(11881, 'plPL', 'Nie zawiedź! Liczę na ciebie.', 0),
(11884, 'plPL', 'Już po nich?', 0),
(11889, 'plPL', '$GWróciłeś:Wróciłaś;. Mam nadzieję, że z dobrymi wieściami?', 0),
(11890, 'plPL', 'Czego się $gdowiedziałeś:dowiedziałaś;, $N?', 0),
(11892, 'plPL', 'Czy Boreański Rzeźnik nie żyje?', 0),
(11893, 'plPL', '$GNaładowałeś:Naładowałaś; totem?', 0),
(11894, 'plPL', 'Masz dla mnie tę wyprawioną skórę karibu?', 0),
(11895, 'plPL', '$GOpanowałeś:Opanowałaś; już burzę?', 0),
(11896, 'plPL', '$GRozpętałeś:Rozpętałaś; już moc burzy na tych nienaturalnych tworach?', 0),
(11897, 'plPL', 'Udało się, $N? Musimy spowolnić Plagę, inaczej zaleje Twierdzę Walecznych.', 0),
(11898, 'plPL', '$GPokonałeś:Pokonałaś; księcia Valanara?', 0),
(11899, 'plPL', 'Jak ci idzie?', 0),
(11900, 'plPL', '$GOdczytałeś:Odczytałaś; wszystkie moje przyrządy, $N?', 0),
(11903, 'plPL', 'Mam nadzieję, że porządnie tłuczesz te ghule?', 0),
(11904, 'plPL', 'Ruda, $N... jest bezpieczna?', 0),
(11905, 'plPL', '$GByłeś:Byłaś; przy szczelinie w Nexusie?', 0),
(11906, 'plPL', 'Jeśli nie zadbamy o ziemię, nie pozwoli nam długo żyć.', 0),
(11907, 'plPL', 'Czy podwodzowie zostali pokonani?', 0),
(11908, 'plPL', '$GOdzyskałeś:Odzyskałaś; moją książkę?', 0),
(11909, 'plPL', 'Czy to już koniec? Czy zagrożenie ze strony Mistrza Trybów Mechazoda zostało usunięte?', 0),
(11910, 'plPL', '$GZebrałeś:Zebrałaś; próbki, o które prosiłem?', 0),
(11911, 'plPL', 'Krystaliczne pradawne... Czy one istnieją?', 0),
(11912, 'plPL', 'Udało ci się znaleźć jakieś jedzenie?', 0),
(11914, 'plPL', 'Masz esencje many, o które prosiłam?', 0),
(11918, 'plPL', '$GZapoznałeś:Zapoznałaś; się z naszym wrogiem, $N?', 0),
(11919, 'plPL', 'Udało ci się pojmać któregoś ze smoków Nexusa?', 0),
(11931, 'plPL', 'Pośpiesz się, śmiertelniku.$b$bMalygos z każdą chwilą rośnie w siłę.', 0),
(11936, 'plPL', '$GZniszczyłeś:Zniszczyłaś; jaja błękitnych, $N?', 0),
(11940, 'plPL', '$GZdobyłeś:Zdobyłaś; smocze pisklę do moich badań?', 0),
(11941, 'plPL', 'Co $gznalazłeś:znalazłaś;, $N?', 0),
(11942, 'plPL', 'Nie śpieszysz się, co? Nie wiem, jak długo jeszcze zdołam utrzymać tego lisza w ryzach.', 0),
(11943, 'plPL', '$GOdnalazłeś:Odnalazłaś; jakieś inne fragmenty więzienia?', 0),
(11944, 'plPL', 'Udało ci się coś zdziałać? Jesteśmy tu w potrzasku.', 0),
(11945, 'plPL', 'Udało ci się, $N? Nasi krewni w Unu\'pe liczą na twoje wysiłki.', 0),
(11949, 'plPL', 'Walczymy zębami i pazurami, $N. Nie oddamy tym kvaldirom ani piędzi ziemi, nie każąc im słono za to zapłacić.', 0),
(11951, 'plPL', '$GZebrałeś:Zebrałaś; odłamki many, których potrzebuję?', 0),
(11956, 'plPL', '$GWróciłeś:Wróciłaś;, $N. Masz filakterię?', 0),
(11957, 'plPL', 'Saragosa nie może przeżyć!', 0),
(11961, 'plPL', 'Totem, $N. Masz go?', 0),
(11962, 'plPL', 'Co tam masz?', 0),
(11965, 'plPL', '$GZebrałeś:Zebrałaś; ocalałych, $N?', 0),
(11967, 'plPL', 'Masz dla mnie wieści, $n?', 0),
