INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3040, 'plPL', '<HTML>\n<BODY>\n<BR/>\n<P>Dobra, $N, oto lista wszystkich rzeczy, których potrzebuję do naszej nowej superściśle tajnej, eee..., superbroni. Na razie nazwijmy ją po prostu „Ultrazaawansowany prototypowy blaster skracający Crafty”.</P>\n<BR/>\n<P>Uwierz mi, będzie o wiele bardziej rewolucyjny niż ten stary, tandetny powiększacz świata!</P>\n<BR/>\n<P>W każdym razie nie zastanawiaj się teraz nad tym za bardzo. Po prostu zdobądź mi te rzeczy, a wszystko będzie cacy!</P>\n</BODY>\n</HTML>', 0),
(3041, 'plPL', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Moje narzędzia</H1>\n<BR/>\n<P>Najpierw najważniejsze... potrzebuję moich narzędzi. Przy tak skomplikowanym projekcie żadne inne się nie nadadzą!</P>\n<BR/>\n<P>Kiedy musieliśmy uciekać, ratując życie, z przepompowni – to zupełnie inna historia – nie miałam czasu ich zabrać. No weź, uciekałam, żeby ratować życie! Ale pamiętam, że zostawiłam je pod przepompownią na wschodzie.</P>\n</BODY>\n</HTML>', 0),
(3042, 'plPL', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Przeładowany kondensator</H1>\n<BR/>\n<P>Każdy inżynier, który choć trochę zna się na rzeczy, powinien ci go sklecić, jeśli sam nie potrafisz go zrobić. Do licha, sama bym ci go zrobiła, ale przecież nie mam teraz narzędzi, pamiętasz?</P>\n<BR/>\n<P>Rób więc, co trzeba, ale mi go zdobądź. Bez niego projekt stoi w miejscu. Jeśli będzie trzeba, wróć na południowe kontynenty i przeszukaj dom aukcyjny!</P>\n</BODY>\n</HTML>', 0),
(3043, 'plPL', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Garść żwiru Rocknara</H1>\n<BR/>\n<P>Ostatnią rzecz może być trochę trudno zdobyć, ale jest niezbędna, żeby wykonać soczewkę blastera z najlepszego piasku. A to znaczy, że trzeba go wziąć od żywiołaka najwyższej klasy.</P>\n<BR/>\n<P>Rocknar świetnie się nada. Widziano go na południowym wschodzie, w Zamarzniętym Zasięgu, między Unu\'pe a Zawodzącym Zigguratem. Rozbij jego lodową skorupę, dostań się do skalnego rdzenia i przynieś mi garść.</P>\n</BODY>\n</HTML>', 0),
(3054, 'plPL', 'Od dawna przy ogniskach taunka opowiadano legendę o Rogu furii żywiołaków. Pokolenia wojowników dorastały, słuchając tych opowieści, i na próżno szukały kryjówki rogu. Jak inni, potężny Burzowe Kopyto przysiągł odnaleźć róg i opuścił swoją wioskę i rodzinę.$B$BStawiając czoła przenikliwemu zimnu i dzikim żywiołakom Szczytu Mroźnego Ostrza, Burzowe Kopyto samotnie wspiął się na górę. Gdy dotarł na szczyt, powitał go sam Wiatr Północny. Wiedząc, że wiatr nie odda rogu bez walki, potężny wojownik rzucił mu wyzwanie.', 0),
(3055, 'plPL', 'Przez pięć dni Burzowe Kopyto zmagał się z wiatrem. O świcie szóstego dnia przegnał wiatr ze Szczytu Mroźnego Ostrza i zdobył róg. Poobijany i ranny, Burzowe Kopyto zszedł z góry i ruszył do swojej wioski.$B$BWiatr Północny zebrał zastęp pomniejszych żywiołaków i zaatakował Burzowe Kopyto, gdy ten zbliżał się do domu. Osłabiony wojownik nie zdołał obronić się przed natarciem i Wiatr Północny dokonał zemsty. Złamał róg na dwie części, zamknął je w błyszczących świecidełkach i dał je dwóm potężnym wodzom gorloków jako oznaki ich władzy.$B$B<Pierwotny tekst urywa się nagle, ale ktoś, może Poskromicielka wiatru Barah, dopisał poniżej uzupełnienie.>$B$BZgodnie z poleceniem Wiatru Północnego wodzowie gorloków przekazywali te cenne relikwie synom i wnukom. Do dziś części rogu pozostają w rękach Wodza Burblegobble\'a i Wodza Gurgleboggle\'a.', 0),
(3057, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">POSZUKIWANY: HEMET NESINGWARY</H1>\n<H1 align="center">ZA ZBRODNIE PRZECIWKO NATURZE!</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\obj_nesingwary_256" align="center"/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<H1 align="center">Wizja artysty: „Wytępiciel” w swoim naturalnym środowisku – piekielnym ogniu zaświatów.</H1>\n<BR/>\n<H1 align="left">Miejsce ostatniej rzezi dzikiej przyrody: Nagrand, Rubież</H1>\n<BR/>\n<H1 align="left">Znany również jako: Wielki Łowca Grubej Zwierzyny, Rzeźnik z Bezludzia, Rozpruwacz z Cierniodławów, Dziadek Śmierć, Hemet, Nessie, Stary Brudas, Stary Brudas D, Ojciec Nagród, Wytępiciel</H1>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(3077, 'plPL', 'Ah\'tusa skradała się bezszelestnie ogromnym podziemnym tunelem, nerwowo zerkając przez ramię w oczekiwaniu na pędzący wagonik kolejki. „Gdzie on jest...” – mruknęła gniewnie i zatrzymała się nagle, gdy coś poruszyło się za jej plecami. Jej oczy groźnie się zwęziły, a sztylet wysunął się z pochwy.\n\nChrapliwy głos poniósł się echem po pustej komnacie: „Myślałem, że łotrzyki lubią zachodzić cel od tyłu”. Obróciła się błyskawicznie i wbiła ostrze w tarczę nieprzeniknionej mocy. „A ja myślałam, że paladyni mają żyć w czystości” – odparła z pewnym siebie uśmieszkiem.', 0),
(3078, 'plPL', 'Pochyliła się i liczyła na głos, aż niewidzialna bańka rozpłynęła się z wyraźnym pyknięciem. „Dwanaście sekund? Wiem, że masz zdolności, które trwają dłużej”.\n\nKościste palce bez trudu wsunęły się pod jego zbroję, odpięły napierśnik i wystawiły go na zimne powietrze. „Nie martw się, mój słodki Marcusie, to jeszcze nie cios kończący... Dopiero się rozkręcam”. Objął ramionami to, co zostało z jej talii, wywołując podekscytowany chichot, i skubnął zębami kręgi jej szyi.\n\n<Kilka fragmentów książki jest wyraźnie wytartych od wielokrotnego czytania.>', 0),
(3102, 'plPL', 'Na cześć Króla Variana Wrynna $Bzwanego przez niektórych LO\'GOSHEM, „Duchem wilka”$B$BJego cudowny powrót po długich latach wygnania i trudów rozpalił w Przymierzu nowy płomień ducha i odwagi.$B$BWkroczymy śmiało w te niebezpieczne krainy, niosąc w sercach jego męstwo i nieustępliwość.$B$B$B– Najwyższy lord Bolvar Fordragon$B', 0);
