(25210, 0, 0, 'plPL', 'Jestem Klucznikiem. Czy ty jesteś Strażnikiem Bramy?'),
(26126, 0, 0, 'plPL', 'Giń, śmiertelniku!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13925, 'plPL', 'Wszystkich nas nie powstrzymacie!', '', 0),
(13926, 'plPL', 'Wkrótce nadejdzie twoja śmierć...', '', 0),
(17565, 'plPL', 'Czas zabijać!', '', 0),
(22635, 'plPL', 'Schroń się przed zimnem i daj odpocząć zmęczonym kościom. Nasza gościnność jest do twojej dyspozycji.', 'Schroń się przed zimnem i daj odpocząć zmęczonym kościom. Nasza gościnność jest do twojej dyspozycji.', 0),
(22700, 'plPL', 'JAAARRRGH!', 'JAAARRRGH!', 0),
(22814, 'plPL', 'JAAARRRGH!', 'JAAARRRGH!', 0),
(23071, 'plPL', 'Nieudana mikstura rozlewa się po podłodze i zdaje się ożywać!', '', 0),
(23540, 'plPL', 'Mikstura $n jest zniszczona. Trzeba przygotować nową od podstaw.', '', 0),
(24307, 'plPL', 'Mmrrglglglg? Glbmr brmmrggl glmrrbmrgl.$B$BGrglgrlbrr mrgl!!!', '', 0),
(24308, 'plPL', '<Ahlurglgr wygląda na zaskoczonego, że cię rozumie.>', '', 0),
(24310, 'plPL', 'Razem przebijemy się stąd na zewnątrz. Jesteś $ggotowy:gotowa;?', '', 0),
(24312, 'plPL', 'Wystarczy. Dalej dam sobie radę sam.', '', 0),
(24313, 'plPL', 'Dziękuję za ratunek, $r. Proszę, powiedz królowi, że wróciłem.', '', 0),
(24316, 'plPL', 'Nie możecie mnie tu trzymać wbrew mojej woli! Wszystkim wam wyprano mózgi!', '', 0),
(24355, 'plPL', 'Gawurgggl! Blrgl-brgl grgl!', '', 0),
(24356, 'plPL', '$GNauczyłeś:Nauczyłaś; się sztuczki, by z nami rozmawiać, $r, ale nie robi to na mnie wrażenia.$B$BZa wodą są zdrajcy z Zimopłetwych, których trzeba zabić.', '', 0),
(24357, 'plPL', 'Następny!', '', 0),
(24358, 'plPL', 'No tak. Przyda się nam więcej takich jak ty. Zgłoś się do łącznika do spraw cywilnych po przydział pracy.', '', 0),
(24359, 'plPL', 'Mam kilka wolnych miejsc w twoim fachu. Zgłoś się do łącznika do spraw cywilnych.', '', 0),
(24360, 'plPL', 'Myślałem, że mamy dość ludzi w twoim fachu, ale wygląda na to, że są jeszcze wolne miejsca. Zgłoś się do łącznika do spraw cywilnych.', '', 0),
(24361, 'plPL', 'Tak, widać, że znasz się na swoim fachu. Natychmiast zgłoś się do łącznika do spraw cywilnych, potrzebujemy więcej takich jak ty!', '', 0),
(24362, 'plPL', 'Nie jestem ślepy, wiesz? Widzę, co się tu dzieje!', '', 0),
(24363, 'plPL', 'Już nie! Oto twój miecz. Zgłoś się do koszar na służbę!', '', 0),
(24364, 'plPL', 'Ahglrglglrglgrrr!', '', 0),
(24365, 'plPL', 'Obawiam się, że nie, przyjacielu. Oto twój miecz i tarcza. Zgłoś się do koszar na służbę.', '', 0),
(24366, 'plPL', 'Z taką ręką do miecza? Obawiam się, że potrzebujemy cię na pierwszej linii, przyjacielu. Zgłoś się do koszar.', '', 0),
(24367, 'plPL', 'Łamiesz mi serce – wiesz, że mam normy do wyrobienia? Umiesz władać mieczem? Marsz do koszar.', '', 0),
(24368, 'plPL', 'Wygląda na to, że mamy miejsce dla jeszcze jednej osoby... nie, pomyłka. To siódemka, nie jedynka. Mam nadzieję, że dobrze władasz mieczem – zgłoś się do koszar.', '', 0),
(24369, 'plPL', 'Nie stać w miejscu, ludzie.', '', 0),
(24370, 'plPL', 'Następny, proszę!', '', 0),
(24379, 'plPL', 'Przybyłem tu niedawno, by obserwować murloki z Zimopłetwych. Przebrany za jednego z nich trzymałem się na uboczu i notowałem, jak wygląda ich codzienne życie.$B$BJednak wkrótce po moim przybyciu wszystko się zmieniło.$B$BTrzęsienie ziemi w Mrozarze wywołało osuwisko, które odsłoniło pobliskie jaskinie. Wyszedł z nich dziwny makrura i porwał kijanki Zimopłetwych. Kiedy murloki weszły do jaskiń, by ratować swoje młode, wyszły z nich świecące i pod wpływem makrury.$B$BTeraz ci, których to nie dotknęło, wycofali się tutaj, a ja niechętnie objąłem nad nimi przywództwo.', '', 0),
(24382, 'plPL', 'Podaj swój zawód.', '', 0),
(24383, 'plPL', 'No dobrze. Jaki masz fach?', '', 0),
(24384, 'plPL', 'Twój zawód?', '', 0),
(24385, 'plPL', 'Czym się $gzajmowałeś:zajmowałaś; wcześniej, rekrucie?', '', 0),
(24386, 'plPL', 'Co w takim razie $grobiłeś:robiłaś;, zanim $gprzybyłeś:przybyłaś; do Północnej Grani?', '', 0),
(24387, 'plPL', 'Blurg awrurgle mrr?', '', 0),
(24388, 'plPL', 'Moi bracia i siostry oszaleli! Pomożesz mi się stąd wydostać?', '', 0),
(24389, 'plPL', 'Glug bmrgl grggl!', '', 0),
(24390, 'plPL', 'Nie ma czasu na gadanie – mam robotę!', '', 0),
(24391, 'plPL', 'Rozumiesz mnie? Ja rozumiem ciebie!', '', 0),
(24392, 'plPL', '$R, a po co miałbym z tobą rozmawiać? To pewnie twój lud narobił tego bałaganu!', '', 0),
(24393, 'plPL', 'Trzeba zbierać małże i zabijać orki. Pomóż albo zejdź z drogi!', '', 0),
(24394, 'plPL', 'Blurglgr murbrgl... żartowałem, rozumiem cię.', '', 0),
(24395, 'plPL', '$GOdkryłeś:Odkryłaś; już, czemu nasi bracia i siostry w wiosce oszaleli?', '', 0),
(24396, 'plPL', 'Wiedziałem, że nigdy nie powinniśmy wchodzić do tych jaskiń. To nienaturalne!', '', 0),
(24397, 'plPL', 'Coś mi tu śmierdzi rybą z tym nowym Królem Mrgl-Mrglem, ale nie potrafię powiedzieć co.', '', 0),
(24398, 'plPL', 'Mawurrgggl, gurgl lur!', '', 0),
(24399, 'plPL', 'Glumrggl?', '', 0),
(24400, 'plPL', 'Brggl-brggl Mrgl-Mrgl! Gluk!', '', 0),
(24401, 'plPL', 'Blrmrrgl gulrgl grr.', '', 0),
(24402, 'plPL', 'RAWGRLRLRLRRLGLRL!!!', '', 0),
(24403, 'plPL', 'Mrglrglrglrgl... glrgl?', '', 0),
(24404, 'plPL', 'Mrglmrgl Glrggl!', '', 0),
(24428, 'plPL', 'Proszę, $n, teraz będziesz w stanie rozmawiać z murlokami z Zimopłetwych i ich rozumieć.', '', 0),
(24439, 'plPL', '', 'Kończy nam się żelazo, chłopaki! Nie chcę widzieć, żeby choć jedna sztaba się zmarnowała, słyszycie?', 0),
(24443, 'plPL', '', 'Nieźle. Przy hartowaniu stali spróbuj tej sztuczki, o której ci mówiłam.', 0),
(24446, 'plPL', '$G Ta-ta : Ma-ma;?', '', 0),
(24447, 'plPL', 'Alurglgl.', '', 0),
(24448, 'plPL', 'Ja iść dom?', '', 0),
(24449, 'plPL', 'Bawić!', '', 0),
(24450, 'plPL', 'Psst... $r, tutaj! Obok martwego wieloryba.', '', 0),
(24457, 'plPL', 'Ty nie $g ta-ta : ma-ma;!', '', 0),
(24458, 'plPL', 'Zrównanie Orgrimmaru z ziemią nie było tylko atakiem na orków, lecz zniewagą dla Hordy. Zamachem na sam nasz byt!$B$BKról Lisz chciał zasiać ziarno strachu.$B$BTo...$B$B<Garosz wskazuje umocnione mury, które go otaczają.>$B$BTo jest owoc kampanii Arthasa.$B$BHorda nie boi się niczego...\n', '', 0),
(24475, 'plPL', 'Ostatni kufel przed wymarszem na front?', '', 0),
(24476, 'plPL', 'Czemu nie?', '', 0),
(24478, 'plPL', 'Karczmarzu! Podaj swoje najmocniejsze piwo. Wyruszamy na front.', '', 0),
(24479, 'plPL', 'Dla nas zrobisz chyba wyjątek, co? Możemy już nie wrócić.', '', 0),
(24482, 'plPL', 'No to chyba tyle. Ruszamy.', '', 0),
(24483, 'plPL', 'To było najgorsze piwo, jakie w życiu piłem.', '', 0),
(24491, 'plPL', '%s chrząka.', '', 0),
(24492, 'plPL', 'Szlaki żeglugowe... zaopatrzenie... Zanudzasz mnie na śmierć! Nie potrzebujemy niczego poza wojowniczym duchem Hordy, Zaurzykle! Teraz, gdy mocno okopaliśmy się na tym zamarzniętym pustkowiu, nic nas nie powstrzyma!', '', 0),
(24494, 'plPL', 'Co proponuję? Pokażę ci, co proponuję!', '', 0),
(24495, 'plPL', 'Proszę... Teraz mamy szlak żeglugowy.', '', 0),
(24496, 'plPL', 'I tak dla pewności...', '', 0),
(24501, 'plPL', 'Nie mów mi o konsekwencjach, starcze.', '', 0),
(24512, 'plPL', 'Ale chyba nie sądzisz, że te dzieci urodziły się niewinne? Dorosłyby i chwyciły za broń przeciwko nam!', '', 0),
(24518, 'plPL', 'Jak zdołałeś przeżyć tak długo, Zaurzykle? Jak to możliwe, że nie padłeś ofiarą własnych wspomnień?', '', 0),
(24521, 'plPL', 'Tak jest, żołnierzu! Czas startować!', '', 0),
(24522, 'plPL', 'Tak jest!', 'Tak jest!', 0),
(24538, 'plPL', 'Musimy przygotować tę placówkę do natarcia na Kotlinę Sholazar.$B$BNie stój tak, $N. Idź i reprezentuj Hordę z honorem i przelaną krwią!', '', 0),
(24540, 'plPL', '', 'Muszę posprzątać ten bałagan, ale zrobię to bez narzekania.$B$BPomożesz, jeśli masz w sobie choć trochę dumy z Hordy!', 0),
(24547, 'plPL', '', 'Duchy przemawiają wszędzie wokół nas. Słuchasz ich, $r?', 0),
(24549, 'plPL', 'Leżą tu zwłoki jednego ze strażników karawany Steeljawa.', 'Leżą tu zwłoki jednego ze strażników karawany Steeljawa.', 0),
(24550, 'plPL', 'Leżą tu zwłoki jednego z robotników karawany Steeljawa.', 'Leżą tu zwłoki jednego z robotników karawany Steeljawa.', 0),
(24561, 'plPL', '$n dołączy do nas w natarciu. Przynieśmy pokój moim przodkom!', '', 0),
(24562, 'plPL', 'UDERZAMY!', '', 0),
(24563, 'plPL', 'Zasadzka. Odeślijcie ich na spoczynek!', '', 0),
(24564, 'plPL', 'Odzyskajcie siły. Miejsce, w którym padł Steeljaw, jest tuż przed nami.', '', 0),
(24565, 'plPL', 'Tam jest sztandar tego psa, a tam jego zwłoki. Co to? Już na nas naciera!', '', 0),
(24566, 'plPL', 'Dobrze $gwalczyłeś:walczyłaś;. Teraz idź na północ do waszej orkowej placówki i powiadom Nadzorcę Bor\'goroka o naszym sukcesie!', '', 0),
(24579, 'plPL', 'Okryłem się hańbą. Powinienem był zginąć razem z wieszczem w Magmoth.$B$BZostaw mnie z moimi myślami.', '', 0),
(24580, 'plPL', 'Żywioł powietrza jest tu niespokojny. Uważaj... nie pozwolą ci przejść bez szwanku.', '', 0),
(24586, 'plPL', 'Co to ma znaczyć?! Jeszcze nie skończyłem uczty!', 'Co to ma znaczyć?! Jeszcze nie skończyłem uczty!', 0),
(24596, 'plPL', 'Dziękuję za uwolnienie! Niech pływy zawsze ci sprzyjają.', '', 0),
(24598, 'plPL', 'Nie pozwól Kaskali zapomnieć o tym, co się tu wydarzyło.', '', 0),
(24599, 'plPL', 'Dziękuję ci, $N. Niech wiatry i morza zawsze bezpiecznie cię niosą.', '', 0),
(24601, 'plPL', 'Niech przodkowie zawsze ci pomagają, $N, tak jak ty $gpomogłeś:pomogłaś; mnie.', '', 0),
(24612, 'plPL', 'Boli mnie widok przodków wyrwanych z grobów.$B$BMusimy zgładzić przeklętego ducha waszego dowódcy sił, Steeljawa, który w swej głupocie poprowadził karawanę przez te święte ziemie.', '', 0),
(24619, 'plPL', 'Kto śmie przerywać moją medytację?!', 'Kto śmie przerywać moją medytację?!', 0),
(24626, 'plPL', 'Hę? Gdzie ja być? To nie wyglądać dobrze! Ja uciekać!', '', 0),
(24627, 'plPL', 'HURA! JA WOLNY!', '', 0),
(24628, 'plPL', 'Dzięki, kumpel!', '', 0),
(24629, 'plPL', 'Pan Mortuus będzie taki wściekły! Ja iść do dom teraz.', '', 0),
(24630, 'plPL', 'Czemu ono ciągle mówić, żebym wkładać balsam do koszyka? Ja nie lubić balsam!', '', 0),
(24631, 'plPL', 'Popatrz na nich, Ug. Wiesz, co to jest?', '', 0),
(24632, 'plPL', 'Nie, tato. Wyglądają trochę jak świnie. Czy to świnie?', '', 0),
(24633, 'plPL', 'To...', '', 0),
(24634, 'plPL', 'To są tchórze.', '', 0),
(24635, 'plPL', 'To tchórzliwe świnie, tato?', '', 0),
(24637, 'plPL', 'Nie, krwi z mojej krwi, to żołnierze Przymierza. Nasi zaprzysięgli wrogowie.', '', 0),
(24638, 'plPL', 'Ale tato, czego oni się boją? Czemu tu są?', '', 0),
(24639, 'plPL', 'Są tu, bo nie chcą bronić swoich domów... swoich rodzin...', '', 0),
(24640, 'plPL', 'Poddali się i oddali w nasze ręce – z własnej woli.', '', 0),
(24641, 'plPL', 'Ug\'thorze, oni boją się śmierci.', '', 0),
(24642, 'plPL', '%s drapie się po głowie.', '', 0),
(24643, 'plPL', 'Ja... Nie rozumiem, tato.', '', 0),
(24644, 'plPL', '%s wypina pierś i staje na palcach.', '', 0),
(24645, 'plPL', 'Lok\'tar ogar, tato!', '', 0),
(24647, 'plPL', 'Właśnie, Ug. Zwycięstwo albo śmierć!', '', 0),
(24648, 'plPL', '[Łamanym wspólnym] Słyszeć chłopak, tchórze? Chłopak umrzeć! Chłopak umrzeć za wolność!', '', 0),
(24650, 'plPL', 'Etu Magmothregar, cha!', '', 0),
(24651, 'plPL', 'Grr... na su ka Magmoth!', '', 0),
(24652, 'plPL', 'Kada nu batteka, oht!', '', 0),
(24655, 'plPL', 'Spokojnie, żołnierzu!', '', 0),
(24656, 'plPL', 'Będziemy na nich gotowi... Dobra robota z tym ostrzeżeniem.', '', 0),
(24657, 'plPL', 'Strzelcy! Na front! Nadciąga atak Plagi!', '', 0),
(24658, 'plPL', 'KAGANISHU!', '', 0),
(24659, 'plPL', 'Strzelcy, ładuj broń!', '', 0),
(24660, 'plPL', 'Nerub\'ar ponieśli karę za swoje występki!', '', 0),
(24663, 'plPL', 'Żadnych ocalałych! Niech Arthas się z nimi rozlicza...', '', 0),
(24664, 'plPL', 'Za Piekłorycza! Za Hordę!', '', 0),
(24665, 'plPL', 'Tak... Niech pochłonie cię gniew!', '', 0),
(24667, 'plPL', 'Przekaż Impereanowi, że rozważę zawieszenie broni. Ale najpierw Kipiel musi przestać zalewać wodą moje wzniesienie!', '', 0),
(24668, 'plPL', 'Nudzisz mnie. Precz!', '', 0),
(24669, 'plPL', 'CZEKAJ... DOŚĆ!', '', 0),
(24670, 'plPL', 'Ja... się poddaję. Zgadzam się na rozejm, dopóki Wrzątek przestanie gotować moją sadzawkę.', '', 0),
(24671, 'plPL', 'A teraz zejdź mi z oczu. Rozsądnie będzie, jeśli już nigdy się przede mną nie pokażesz.', '', 0),
(24672, 'plPL', 'Z wielką przyjemnością rozerwę siły Hordy na strzępy... kończyna po kończynie, kawałek po kawałku...', '', 0),
(24673, 'plPL', 'Niech siły Króla Lisza spojrzą na truchło tego nędznika i wiedzą, że Horda nie ustąpi!', '', 0),
(24674, 'plPL', 'Zbierać się, żołnierze! Zbierać się i brać trofea z pancerza wroga!', '', 0),
(24675, 'plPL', 'Kto śmie?!', '', 0),
(24683, 'plPL', '', 'O nie... spętali jego ducha!', 0),
(24684, 'plPL', 'Straciliśmy sporo wiwern na zwiadach na zachodzie. Plaga bezlitośnie atakuje każdego, kto choćby wygląda na szpiega.$B$BNa szczęście wymyśliłem rozwiązanie, które naraża tylko życie jeźdźca. Przeżywa 30% tych, których przerzucamy przez Równiny Nasam. To o 30% więcej niż wtedy, gdy używaliśmy wiwern!', '', 0),
(24685, 'plPL', 'Wyślij mnie na Przystań Garosza, Yanni.', 'Wyślij mnie na Przystań Garosza, Yanni.', 0),
(24689, 'plPL', 'Nie krzywdzić dawcy życia!', '', 0),
(24690, 'plPL', 'Nie dotykać zarodniki!', '', 0),
(24691, 'plPL', 'Chronić dawca życia!', '', 0),
(24701, 'plPL', 'Co ja mam zrobić bez narzędzi, Gorge!', '', 0),
(24702, 'plPL', 'Nie da się naprawić czegoś tak skomplikowanego jak czołg bez porządnego sprzętu, kolego!', '', 0),
(24703, 'plPL', 'Słychać coś z Wojennej Pieśni? Dostaniemy wreszcie jakieś zaopatrzenie?', '', 0),
(24704, 'plPL', 'Chcę do domu... Zdjąć ten mundur i odejść z Hordy!', '', 0),
(24713, 'plPL', 'Mgła zmiotła i Przystań Garosza, i Pal\'ea. Tylko my jesteśmy na tyle szaleni, żeby tu zostać, kolego!', '', 0),
(24714, 'plPL', '', 'Jak mam cokolwiek zrobić, kiedy Fizzcrank dyszy mi nad karkiem, a ja nie mam swoich rzeczy?!', 0),
(24716, 'plPL', 'To, co widzisz na tym wybrzeżu, nie jest dziełem Plagi. Wręcz przeciwnie, sądzimy, że Plaga także boi się mgły – może dlatego tu nie przychodzi.$B$BWidzisz, przyjacielu, ta mgła żyje. W jej zwiewnych mackach czai się śmierć...$B$BJeśli wejdziesz w jej objęcia, przepadniesz. Mgła cię zabierze!$B$BNigdy nie widzieliśmy, by ktoś wrócił z mgły żywy.', '', 0),
(24717, 'plPL', 'Płoń, szczurze lądowy! PŁOŃ!', '', 0),
(24718, 'plPL', 'Ujarzmianie tego ludu dopiero się zaczęło... tyle czasu na zabawę.', '', 0),
(24719, 'plPL', 'Obróć się w popiół we mgle!', '', 0),
(24720, 'plPL', 'Odkąd tu wylądowałem, widziałem okropności, które dotąd nawiedzały mnie tylko w najgorszych koszmarach, ale nic nie mogło mnie przygotować na to, co kryje się za mgłą.$B$B<Mootoo kiwa głową.>$B$BZa tą mgłą, nie dalej niż kilka jardów od nas, stoją krwiożercze istoty zwane kvaldirami. Nikt nie wrócił z mgły, a niewielu z tych, którzy byli na przystani, gdy nadciągnęła, zdołało uciec. Piekłorycz uznał ten teren za stracony. Wchodzisz na własne ryzyko...', '', 0),
(24721, 'plPL', '', 'Czy... Czy ty...$B$B<Mootoo drży.>$B$BCzy $gprzyszedłeś:przyszłaś; mnie uratować?', 0),
(24722, 'plPL', '„Paszcza Węża” płonie ogniem kiełzarów!', '', 0),
(24723, 'plPL', '„Kur Drakkar” płonie ogniem kiełzarów!', '', 0),
(24724, 'plPL', '„Młot Bora” płonie ogniem kiełzarów!', '', 0),
(24725, 'plPL', '„Kowadło Bora” płonie ogniem kiełzarów!', '', 0),
(24727, 'plPL', 'Zamrożone i zniszczone. Tylko do tego nadaje się twoje cielesne truchło.', '', 0),
(24728, 'plPL', 'Nie jesteś tu mile $gwidziany:widziana;. Giń!', '', 0),
(24729, 'plPL', 'Twoja obecność zaburza równowagę tej ziemi. Musisz zostać $gusunięty:usunięta;!', '', 0),
(24733, 'plPL', 'Zabierz ich ubrania.', 'Zabierz ich ubrania.', 0),
(24734, 'plPL', 'Sternik po ciebie idzie!', '', 0),
(24735, 'plPL', 'Żałosny głupcze! Sługa Malygosa prędzej umrze, niż pomoże wrogowi...', '', 0),
(24736, 'plPL', 'Aargh! Rób ze mną, co chcesz, $N! NICZEGO ci nie powiem!', '', 0),
(24737, 'plPL', 'Aaaach! Wypuść mnie! Na nic ci się nie przydam. Przysięgam!', '', 0),
(24738, 'plPL', 'Przestań! Błagam, przestań. Proszę...', '', 0),
(24739, 'plPL', 'Dobrze! Poddaję się. Twoja cenna arcymagini jest uwięziona w celi, wysoko i szczelnie zamkniętej. Nawet jeśli zdołasz do niej dotrzeć, klucz ma sama Salrand. Twoja misja to szaleństwo!', '', 0),
(24744, 'plPL', 'Znacie zasady, chłopaki. Żadnego alkoholu dla żołnierzy na służbie. Chcecie, żeby generał osobiście mnie zabił?', '', 0),
(24745, 'plPL', 'No dobra, dobra... ale nie ode mnie to macie!', '', 0),
(24747, 'plPL', '', 'Czuję aurę mojego ojca. Na pewno jest tędy... chodź, $n.', 0),
(24748, 'plPL', '', 'Widzę przed nami przerwę we mgle. Jesteśmy coraz bliżej!', 0),
(24749, 'plPL', '', 'OJCZE! Ojcze, jestem uratowana!', 0),
(24755, 'plPL', 'Nieeee! Te tortury są nieludzkie! Masz już, czego $gchciałeś:chciałaś;... czemu po prostu mnie nie zabijesz?', '', 0),
(24756, 'plPL', 'Już dałem ci informacje, $r! Tracisz czas...', '', 0),
(24758, 'plPL', 'Co jest, $N? Myślisz, że jesteś za $gdobry:dobra;, żeby stać w kolejce z resztą z nas?', 'Co jest, $N? Myślisz, że jesteś za $gdobry:dobra;, żeby stać w kolejce z resztą z nas?', 0),
(24759, 'plPL', 'Crafty, $gzgubiłem:zgubiłam; przebranie orka z Wojennej Pieśni.', 'Crafty, $gzgubiłem:zgubiłam; przebranie orka z Wojennej Pieśni.', 0),
(24760, 'plPL', 'Crafty, potrzebuję kolejnego sztandaru Wojennej Pieśni.', 'Crafty, potrzebuję kolejnego sztandaru Wojennej Pieśni.', 0),
(24762, 'plPL', 'Co za widok dla zmęczonych oczu! Jestem zbyt słaby, żeby rozerwać ogniwa tej zardzewiałej kuli z łańcuchem.$B$BNo, nie stój tak! Uwolnij mnie!', '', 0),
(24771, 'plPL', 'Mam teraz pełne ręce roboty, $N.$B$BCo mogę dla ciebie zrobić?', '', 0),
(24772, 'plPL', 'No dobra, nie ma czasu do stracenia. Zmywajmy się stąd!', '', 0),
(24773, 'plPL', 'No to ruszamy.', '', 0),
(24774, 'plPL', 'Ach, świeże powietrze! Stąd sam dotrę na lądowisko. Koniecznie powiedz Fizzcrankowi, że wróciłem cały i zdrowy. Wielkie dzięki, $n!', '', 0),
(24775, 'plPL', 'Wreszcie lądowisko! Dziękuję, dalej dam sobie radę. Koniecznie powiedz Fizzcrankowi, że wróciłem cały i zdrowy!', '', 0),
(24776, 'plPL', 'Chyba trzeba iść w górę i w lewo. Chodźmy!', '', 0),
(24777, 'plPL', 'Plugawe stworzenie!', '', 0),
(24778, 'plPL', 'Przyszedłem tu porozmawiać, a wy, bezmózgie stwory, zamiast tego próbowaliście mnie zabić!', '', 0),
(24779, 'plPL', 'Już nigdy nie zakujecie mnie w łańcuchy!', '', 0),
(24780, 'plPL', 'NIE JESTEM PRZYSTAWKĄ!', '', 0),
(24787, 'plPL', 'Wystarczy jedno słowo, generale. W ciągu miesiąca oddam do twojej dyspozycji dwa pułki.', '', 0),
(24788, 'plPL', 'Dobrze, generale. Gdybyś zmienił zdanie, mój lud chętnie udzieli wam wsparcia wojskowego.', '', 0),
(24789, 'plPL', 'Nasze oddziały, generale, to głównie wieśniacy i chłopi. Dobrzy ludzie, ale wciąż nie pozbyli się uprzedzeń i przesądów, w których ich wychowano. Nie są gotowi walczyć ramię w ramię z naszymi bardziej egzotycznymi sojusznikami.', '', 0),
(24790, 'plPL', 'Twoja oferta zostanie starannie rozważona, zwiastunie. Tymczasem skorzystamy z twojej delegacji w roli doradczej.', '', 0),
(24791, 'plPL', 'Plaga nas otoczyła. Możemy jeszcze przez jakiś czas utrzymać wioskę, ale jeśli jej nie pokonamy, zaleje nas.', '', 0),
(24792, 'plPL', 'Wybór jest jasny. Musimy zaatakować. Wiem, że szanse są przeciwko nam, ale taunka nie idą potulnie na rzeź.', '', 0),
(24793, 'plPL', 'Zginę z toporami w dłoniach, zbroczony krwią naszych wrogów!', '', 0),
(24798, 'plPL', 'Nie poświęcę moich wojowników dla romantycznych mrzonek o chwalebnej śmierci na polu bitwy. Po co walczyć o przetrwanie, jeśli nikt nie przetrwa?', '', 0),
(24799, 'plPL', 'Przyjdzie czas na bitwę, Durmie. Ale najpierw musimy znaleźć sposób, by wyrównać szanse. Co radzisz, Aeire?', '', 0),
(24800, 'plPL', '', 'Przodkowie znali sposób, by zmylić zmysły wroga. Moglibyśmy wykorzystać tę wiedzę, by odkryć słabość Plagi albo uderzyć w jej dowódców. Bez przywódców Plaga padnie przed naszymi wojownikami.', 0),
(24801, 'plPL', 'Niehonorowy plan.', '', 0),
(24802, 'plPL', 'Ile jest wart twój honor, Durmie? Twoje życie? Moje? Życie ślepego starego Praojca Mahana, który wychował cię od dziecka?', '', 0),
(24803, 'plPL', 'Honor nic nie znaczy dla martwego. Wojownik może rzucić się w bój dla honoru, ale wódz odpowiada za znacznie więcej. Pójdziemy za planem Mędrczyni Aeire i nadal będziemy bronić naszej wioski.', '', 0),
(24804, 'plPL', '', 'Mów powoli, dziecko, dopiero uczę się twojego dziwnego języka.', 0),
(24805, 'plPL', '', 'Proszę, mów ciszej, $r. Hamat jest stara i potrzebuje odpoczynku.', 0),
(24807, 'plPL', 'Nadszedł czas działania. Musimy zdecydować, jak rozprawić się z Plagą, zanim nas pochłonie.', '', 0),
(24810, 'plPL', 'Aeire, $n przynosi twoje skóry. Proszę, weź je, zanim zrobi mi się niedobrze.', '', 0),
(24811, 'plPL', '', 'Wezmę je. Nie możemy pozwolić, by potężny wódz kulił się ze strachu przed kilkoma skórami.', 0),
(24812, 'plPL', '', 'Co to za zamieszanie?!', 0),
(24816, 'plPL', '', 'Zniszczyłam klucz! Wasza ukochana arcymagini należy do Malygosa!', 0),
(24819, 'plPL', 'Może i $gprzeżyłeś:przeżyłaś; dla naszej rozrywki, ale teraz zginiesz z naszych rąk!', 'Może i $gprzeżyłeś:przeżyłaś; dla naszej rozrywki, ale teraz zginiesz z naszych rąk!', 0),
(24820, 'plPL', '', 'Kto śmie przerywać mi pracę?! Pokaż się, tchórzu!', 0),
(24823, 'plPL', 'Dawać następną parę więźniów, niech walczą o to, kto przeżyje!', 'Dawać następną parę więźniów, niech walczą o to, kto przeżyje!', 0),
(24827, 'plPL', 'Niech ktoś... Pomocy...', '', 0),
(24828, 'plPL', 'Nie pozwól, żeby zamienili mnie w jedno z tych plugastw!', '', 0),
(24829, 'plPL', 'Zabij mnie... Zabij mnie teraz!', '', 0),
(24831, 'plPL', 'Dziękuję, przyjacielu.', '', 0),
(24832, 'plPL', 'Nareszcie wolność! Muszę natychmiast wracać do Warowni Wojennej Pieśni!', '', 0),
(24833, 'plPL', 'Dziękuję ci, $gnieznajomy:nieznajoma;.', '', 0),
(24834, 'plPL', 'Jestem ci dozgonnie wdzięczny, przyjacielu.', '', 0),
(24836, 'plPL', 'Ożywię ich wszystkich jako sługi Króla Lisza! Przyprowadźcie ich tutaj...', '', 0),
(24841, 'plPL', 'Majtku, pokaż tej mrówce potęgę kvaldirów!', '', 0),
(24842, 'plPL', 'Majtku, rozszarp tego szczura lądowego na strzępy!', '', 0),
(24845, 'plPL', 'Teraz zmierzysz się z Orabusem, głupcze!', '', 0),
(24846, 'plPL', 'Wciągnę twoją duszę w mgłę!', 'Wciągnę twoją duszę w mgłę!', 0),
(24847, 'plPL', 'JAAARRRGH!', 'JAAARRRGH!', 0),
(24848, 'plPL', 'Niech pochłonie cię mgła!', 'Niech pochłonie cię mgła!', 0),
(24849, 'plPL', 'Patrzcie, co tu zabłądziło...', 'Patrzcie, co tu zabłądziło...', 0),
(24850, 'plPL', 'Sam wrzucę twoje truchło do oceanu!', 'Sam wrzucę twoje truchło do oceanu!', 0),
(24851, 'plPL', 'Nie nadajesz się nawet na karmę dla Levirotha.', 'Nie nadajesz się nawet na karmę dla Levirotha.', 0),
(24852, 'plPL', 'Za daleko $godszedłeś:odeszłaś; od swojej wygodnej ziemi, $r.', 'Za daleko $godszedłeś:odeszłaś; od swojej wygodnej ziemi, $r.', 0),
(24867, 'plPL', 'Odsunąć się!', '', 0),
(24868, 'plPL', 'Żyj, do diabła!', '', 0),
(24869, 'plPL', 'Na nic... najpierw trzeba nad tobą jeszcze popracować.', '', 0),
(24870, 'plPL', 'Doktor przyjmuje!', '', 0),
(24872, 'plPL', 'Ach, dobrze... więcej części!', '', 0),
(24873, 'plPL', 'Zalecam wypatroszenie!', '', 0),
(24874, 'plPL', 'Giń!', '', 0),
(24875, 'plPL', 'Nie powstrzymasz nas!', '', 0),
(24876, 'plPL', 'Plugawa istoto, co jeszcze oddycha!', '', 0),
(24881, 'plPL', 'Oto twoje kodo, Torp!', 'Oto twoje kodo, Torp!', 0),
(24882, 'plPL', 'Kodo z dostawą pod same drzwi!', 'Kodo z dostawą pod same drzwi!', 0),
(24883, 'plPL', 'TAK! Udało się!', '', 0),
(24884, 'plPL', 'Świetna robota!', '', 0),
(24885, 'plPL', '%s został wyleczony!', '', 0),
(24888, 'plPL', '', 'Dobra, $n, zaczynamy. Trzymaj kciuki, krzyżuj palce u stóp, zrób zeza i krzyżuj wszystko, co się da!', 0),
(24889, 'plPL', '', 'O nie, nie zadziałało! Jakoś czuję się... lżejsza.', 0),
(24896, 'plPL', 'Powiedz mi, co się tu dzieje, Fizzcranku.', 'Powiedz mi, co się tu dzieje, Fizzcranku.', 0),
(24897, 'plPL', 'Opowiedz mi jeszcze raz swoją historię, Fizzcranku.', 'Opowiedz mi jeszcze raz swoją historię, Fizzcranku.', 0),
(24898, 'plPL', 'No dobrze, siadaj. To może chwilę potrwać.$B$BKiedy przybyliśmy do tego zamarzniętego piekła, generał Arlos z Twierdzy Walecznych powierzył mojej grupie latających śmiałków i mnie specjalne zadanie: założyć wysuniętą bazę lotniczą dla operacji Przymierza.$B$BTo lądowisko jest jej efektem. Powiem ci, że nie było łatwo, z tymi wszystkimi paskudnymi bestiami i ziemią zamarzniętą na kamień! Ale daliśmy radę, i to szybko!', '', 0),
(24899, 'plPL', 'Mów dalej.', 'Mów dalej.', 0),
(24900, 'plPL', 'Tak czy inaczej, musieliśmy wypompowywać mnóstwo piasku i ropy dla maszyn. Pobliskie sadzawki okazały się do tego idealne.$B$BCzęść piasku miała nawet właściwości magiczne... mówię ci, co za możliwości!? Ale to już inna historia.$B$BWypompowaliśmy więc większość wody i zbudowaliśmy przepompownię w samym środku. Wszystko szło jak po maśle, aż pewnego dnia zatkała się główna rura ssąca.', '', 0),
(24901, 'plPL', 'Czekaj, cofnij się. Co to było to ostatnie?', 'Czekaj, cofnij się. Co to było to ostatnie?', 0),
(24902, 'plPL', 'Uwaga, tej części dowiedziałem się później, bo mnie tam wtedy nie było.$B$BKiedy podkręcili ssanie pompy, wyciągnęło kawałki robota, który wyglądał jak gnom! Oczywiście ci głupcy pracowali dzień i noc, żeby go złożyć, i nic nam nie powiedzieli.$B$BWtedy właśnie straciliśmy łączność z przepompownią.', '', 0),
(24903, 'plPL', 'Po kilku dniach ciszy wysłałem na platformę oddział zwiadowczy. Nigdy nie wrócił.$B$BNastępnego dnia wysłałem kolejną grupę – z takim samym skutkiem – i straciłem kilka maszyn latających podczas zwiadu z powietrza.$B$BWtedy posłałem kogoś na południe po pomoc, a sami okopaliśmy się i szykowaliśmy na najgorsze. Skupiliśmy się całkowicie na robieniu pancerzy, broni i robotów, żeby ruszyć tam w pełnej sile.$B$BKiedy to zrobiliśmy kilka dni temu, nie mogliśmy uwierzyć własnym oczom!', '', 0),
(24904, 'plPL', 'Jak mówiłem, to, co tam zobaczyliśmy, było nie do wyjaśnienia.$B$BPo moich ludziach nie było śladu, a w ich miejscu krzątała się istna armia robotów i androidów!$B$BWszystkie droidy wyglądały jak gnomy i powiedziały, że na nas czekały. Co więcej, na swój dziwny sposób zachowywały się tak, jakby nas znały. Otoczono nas i szybko zabrano na szczyt przepompowni.$B$BTam zobaczyliśmy ich przywódcę i to, co robił z ocalałymi gnomami!', '', 0),
(24905, 'plPL', 'Nazywał siebie Mistrzem Trybów Mechazodem. Kiedy przybyliśmy, był zajęty przemienianiem ocalałych w istoty mechaniczne!$B$BPowitał nas ciepło i wyjaśnił, że był jednym z pierwszych gnomów stworzonych przez kogoś, kogo nazywał „Wielkim Architektem”, strażnika tytanów z sal legendarnego Ulduaru.$B$BNajwyraźniej to on był tym zatorem, który moja ekipa przypadkiem wessała z miejsca, gdzie tysiące lat temu uległ awarii. Akurat mieliśmy takiego pecha, że postawiliśmy przepompownię dokładnie nad nim.', '', 0),
(24906, 'plPL', 'Mechanicy ze stacji złożyli go z powrotem, przywracając go do „życia”.$B$BA teraz, w ramach podziękowania, zamierzał odwdzięczyć się, lecząc nas wszystkich z czegoś, co nazywał „Klątwą ciała”.$B$BWedług Mechazoda to przypadłość, która prędzej czy później dotyka wszystkie twory tytanów! Innymi słowy, podobno wszyscy zaczynamy jako jakieś roboty i przez tysiące lat powoli zmieniamy się w istoty z krwi i kości!$B$BWiem, niedorzeczne.', '', 0),
(24907, 'plPL', 'Nie wyglądało mi to na żadne „leczenie” i nie zamierzałem stać i słuchać jakiegoś szalonego robota, podczas gdy on zarzynał moich ludzi!$B$BZrobiliśmy to, co zrobiłby każdy rozsądny gnom... uciekliśmy! No, właściwie większość z nas zeskoczyła ze spadochronami z krawędzi platformy, ale wiesz, o co chodzi.$B$BNiewielu z nas zdołało tu wrócić, a i tak jesteśmy rozciągnięci do granic, bo musimy radzić sobie ze wszystkim innym – jak magnataury na północy i Plaga na wschodzie. Na domiar złego Horda właśnie rozbiła obóz na północnym zachodzie!', '', 0),
(24908, 'plPL', 'I w takim właśnie jesteśmy położeniu, $n.$B$BNie damy rady poradzić sobie z tym wszystkim sami i szczerze mówiąc, czuję, że trochę mnie to przerasta. Jinky wie, co trzeba zrobić. Idź teraz do niej.$B$BMam tylko nadzieję, że zdołasz wyciągnąć nas z tego bagna, z ciałami w nienaruszonym stanie.', '', 0),
(24909, 'plPL', 'To już, $n. Początek końca świata. A ty jesteś tu, by go pożegnać...', '', 0),
(24910, 'plPL', 'Chodźmy...', '', 0),
(24911, 'plPL', 'To wszystko? Na tyle stać potężną Hordę?', '', 0),
(24913, 'plPL', 'Nigdy nie rozumiałem takich jak ty. Bohaterów...', '', 0),
(24914, 'plPL', 'Czemu po prostu nie odpuścisz? Czemu walczysz z tym, co nieuniknione?', '', 0),
(24915, 'plPL', 'Króla Lisza nie da się powstrzymać. Pogódź się z tym.', '', 0),
(24916, 'plPL', 'Ten świat dobiega końca. Niech. Płonie.', '', 0),
(24917, 'plPL', 'Zabierzcie $gtego:tę; tu i przygotujcie $ggo:ją; do reanimacji.', '', 0),
(24921, 'plPL', 'A to co znowu?', '', 0),
(24926, 'plPL', 'W takim razie jesteś głupcem.', '', 0),
(24928, 'plPL', 'Ty? Samotny ork? Przeciwko mnie i...', '', 0),
(24933, 'plPL', 'Nie... nie mogę w to uwierzyć... Zaurzykieł... To... to dla mnie zaszczyt... zaszczyt, że mogłem walczyć u twego boku, panie.', '', 0),
(24934, 'plPL', 'Lepiej wracaj teraz do Warowni Wojennej Pieśni, przyjacielu. Piekłorycz na pewno zechce usłyszeć o tym, co się tu stało... o Zaurzykle...', '', 0),
(24937, 'plPL', 'Żegnaj...', '', 0),
(24956, 'plPL', 'Głupi niewolniku żywiołów! Ty i twój pan zapłacicie za wtrącanie się!', '', 0),
(24963, 'plPL', '', 'Mocą rogu wiążę cię z wolą tego, kto go dzierży!', 0),
(24967, 'plPL', 'Znów jestem z krwi i kości! Dziękuję, $N!', 'Znów jestem z krwi i kości! Dziękuję, $N!', 0),
(24970, 'plPL', 'Ale... ale... Byłem doskonały!', 'Ale... ale... Byłem doskonały!', 0),
(24971, 'plPL', 'Gdzie jestem? Kim jesteś? Co to za dziwne uczucie?', 'Gdzie jestem? Kim jesteś? Co to za dziwne uczucie?', 0),
(24975, 'plPL', 'Postępek tych dezerterów okrywa hańbą nas wszystkich. To hańba tak wielka, że trzeba ją zobaczyć, by ją zrozumieć. Dlatego Ug\'thor tu jest... Chłopak musi się nauczyć.', '', 0),
(24976, 'plPL', 'Wstyd mi to mówić, Norku, ale mój dezerter zniknął.', 'Wstyd mi to mówić, Norku, ale mój dezerter zniknął.', 0),
(24977, 'plPL', 'Postaraj się nie zgubić tego, $n. Ważne, żebyśmy przynajmniej próbowali zachować pozory wobec Przymierza.', '', 0),
(24979, 'plPL', 'Aktywacja środków zaradczych. Odeprzeć intruza.', '', 0),
(24981, 'plPL', 'Wykryto cię. Zostaniesz $gzasymilowany:zasymilowana; lub $gwyeliminowany:wyeliminowana;.', '', 0),
(24984, 'plPL', 'Przeżyłem i znów jestem z krwi i kości!', 'Przeżyłem i znów jestem z krwi i kości!', 0),
(24992, 'plPL', '', 'Jakie to okropne! $GByłeś:Byłaś; zupełnie $gobezwładniony:obezwładniona;? $GOsłabiony:Osłabiona;? Uderzenia gorąca?', 0),
(24994, 'plPL', 'I pamiętaj, $n, że proszkiem z krwawych zarodników można osłabić wszystkie magnataury w Gammoth.', '', 0),
(24995, 'plPL', '', 'Dziękuję ci, przyjacielu Dalaranu.', 0),
(24996, 'plPL', '', 'Nie możemy tu zwlekać... trzymaj się blisko – zabiorę nas w bezpieczne miejsce.', 0),
(24998, 'plPL', 'Tępy majsterkowiczu, naprawdę myślisz, że twój żałosny wytwór mnie powstrzyma?', '', 0),
(24999, 'plPL', '', 'Uważaj w tych stronach, $r. Tubylcy są bezlitośni.', 0),
(25000, 'plPL', 'Jesteśmy mechagnomami... opór jest daremny.', '', 0),
(25002, 'plPL', 'Ciało jest słabe. Uczynimy cię $glepszym:lepszą;, $gsilniejszym:silniejszą;... $gszybszym:szybszą;.', '', 0),
(25003, 'plPL', 'Możemy zdjąć z ciebie klątwę, mamy technologię.', '', 0),
(25010, 'plPL', 'Prawo kiełzarów zobowiązuje mnie do pomszczenia moich krewnych... ci mordercy puścili Pal\'ea z dymem.', '', 0),
(25011, 'plPL', 'Leczyłem chłopów, szlachciców, kupieckich synów i żebraków. Pozwól, że podzielę się z tobą jedną mądrością – wszyscy jesteśmy tacy sami, gdy patrzymy śmierci w oczy.', '', 0),
(25012, 'plPL', 'Twonky!', '', 0),
(25013, 'plPL', 'ED-210 w trybie online!', '', 0),
(25014, 'plPL', 'Jestem heroldem Mechazoda. Zostaniesz $godklęty:odklęta;!', '', 0),
(25015, 'plPL', 'Twoje wtrącanie się dobiegło końca. Kiedy z tobą skończę, Mechazod zdejmie z ciebie klątwę.', '', 0),
(25016, 'plPL', 'Ciekawe, co Nesingwary da mi za twoją skórę!', 'Ciekawe, co Nesingwary da mi za twoją skórę!', 0),
(25017, 'plPL', 'Stary Hemet na pewno coś zrobi z twoich kości!', 'Stary Hemet na pewno coś zrobi z twoich kości!', 0),
(25018, 'plPL', 'Jeszcze tylko pięćdziesiąt kopyt i będę mieć nową strzelbę!', 'Jeszcze tylko pięćdziesiąt kopyt i będę mieć nową strzelbę!', 0),
(25019, 'plPL', 'ZABIĆ ZABIĆ ZABIĆ!!!!!!!', 'ZABIĆ ZABIĆ ZABIĆ!!!!!!!', 0),
(25020, 'plPL', 'Dziś na kolację będzie cielęcina!', 'Dziś na kolację będzie cielęcina!', 0),
(25022, 'plPL', 'To się nazywa sport!', 'To się nazywa sport!', 0),
(25023, 'plPL', 'Poddaj się, bestyjko!', 'Poddaj się, bestyjko!', 0),
(25028, 'plPL', 'Czy twoja sprawa jest słuszna, a serce szczere? Jeśli tak, witaj wśród nas – druidów na rzecz etycznego i humanitarnego traktowania zwierząt. Dopóki nie zejdziesz na mroczną ścieżkę zepsucia i nie skrzywdzisz zwierząt, które pozwoliły nam współistnieć w ich świecie, D.E.H.T.A. będzie uważać cię za sojusznika.\n', '', 0),
(25029, 'plPL', 'To cud! Zwierzę samo się oskórowało!', 'To cud! Zwierzę samo się oskórowało!', 0),
(25030, 'plPL', 'Głupie bestie!', 'Głupie bestie!', 0),
(25031, 'plPL', 'To ostatni, którego potrzebuję do kompletu noży do steków Nesingwary\'ego!', 'To ostatni, którego potrzebuję do kompletu noży do steków Nesingwary\'ego!', 0),
(25034, 'plPL', 'Główna wygrana!', 'Główna wygrana!', 0),
(25037, 'plPL', 'Matko perłowa!', 'Matko perłowa!', 0),
(25038, 'plPL', 'Koszulo wizytowa ze skóry małży, nadchodzę!', 'Koszulo wizytowa ze skóry małży, nadchodzę!', 0),
(25039, 'plPL', 'Małż oddał skarb!', 'Małż oddał skarb!', 0),
(25040, 'plPL', 'BUM!', 'BUM!', 0),
(25041, 'plPL', 'Ten pilot zwiadowczy nie przeżył katastrofy swojej eskadry.', '', 0),
(25042, 'plPL', 'Poszukaj insygniów pilota.', 'Poszukaj insygniów pilota.', 0),
(25043, 'plPL', '$GOszalałeś:Oszalałaś;? Zaraz wysadzisz nas w powietrze! Zajmę się tym wrakiem, kiedy wszystko inne będzie skończone.', '', 0),
(25046, 'plPL', '%s trąbi z aprobatą!', '', 0),
(25052, 'plPL', 'Masz nas za głupców?! Jesteś $gcały:cała; we krwi zwierząt!', 'Masz nas za głupców?! Jesteś $gcały:cała; we krwi zwierząt!', 0),
(25053, 'plPL', 'RZEŹNIKU! GIŃ!', 'RZEŹNIKU! GIŃ!', 0),
(25054, 'plPL', 'Zabójco cieląt! Morderco! Zapłacisz za to!', 'Zabójco cieląt! Morderco! Zapłacisz za to!', 0),
(25071, 'plPL', 'Wyzywasz Kawa, niszczyciela mamutów?! Więc stań do walki i poczuj mój grzmot!', '', 0),
(25087, 'plPL', 'Halabarda Kawa pęka na dwoje i spada na ziemię!', 'Halabarda Kawa pęka na dwoje i spada na ziemię!', 0),
(25102, 'plPL', 'Śmiesz wyzywać Nedara, władcę tundry?!', '', 0),
(25103, 'plPL', 'Twoja porywczość będzie twoim końcem!', '', 0),
(25104, 'plPL', 'Nie masz szans!', '', 0),
(25112, 'plPL', 'Przeszukaj ciało w poszukiwaniu awaryjnego zestawu narzędzi pilota.', 'Przeszukaj ciało w poszukiwaniu awaryjnego zestawu narzędzi pilota.', 0),
(25116, 'plPL', 'Niemożliwe! Hełm z głową nosorożca w niskiej, niskiej cenie trzydziestu głów nosorożca? W takiej cenie biorę dwa!', 'Niemożliwe! Hełm z głową nosorożca w niskiej, niskiej cenie trzydziestu głów nosorożca? W takiej cenie biorę dwa!', 0),
(25117, 'plPL', 'Nesingwary zbankrutuje, jeśli dalej będzie tak robił! Lane pewnie nie ma pojęcia, co wyprawia!', 'Nesingwary zbankrutuje, jeśli dalej będzie tak robił! Lane pewnie nie ma pojęcia, co wyprawia!', 0),
(25120, 'plPL', 'Chcesz mnie ogłuszyć? Żałosne... Chwila... Co to za dźwięk?', '', 0),
(25131, 'plPL', 'Choć zapędy Nesingwary\'ego wobec dzikiej przyrody Północnej Grani zostały powstrzymane, to tylko kwestia czasu, zanim spróbuje kolejnego najazdu. Musisz zachować czujność, $n!$B$BPrzede wszystkim nie ulegaj żadnym pokusom, które mogą zostać przed tobą postawione... Demon spróbuje cię zauroczyć. Gdy to nastąpi, musisz się oprzeć!', '', 0),
(25132, 'plPL', 'Fezzixie, chyba rozwiązaliśmy twój mały problem z silnikiem.', '', 0),
(25133, 'plPL', 'Pilnuj, żeby były gorące, ty wielki tępaku!', '', 0),
(25134, 'plPL', 'Ta broń sama się nie wykuje! Szybciej!', '', 0),
(25135, 'plPL', 'To ma być uderzenie młotem? Z jakimi amatorami ja tu pracuję?', '', 0),
(25136, 'plPL', 'Jeśli dalej będziesz odwalał taką fuszerkę, odeślę cię do mamusi w skrzyni z kartką przypiętą do piersi: PORAŻKA.', '', 0),
(25137, 'plPL', 'A CO niby nasi żołnierze mają zrobić z tym tandetnym złomem?', '', 0),
(25138, 'plPL', 'Przynosisz wstyd całej tej operacji! Pakuj manatki i wynocha!', '', 0),
(25143, 'plPL', 'Tym razem naprawdę zadziała... prawda?', '', 0),
(25148, 'plPL', 'Działa, Dorainie! Patrz! Naprawdę działa...', '', 0),
(25149, 'plPL', 'Nie ujarzmisz mnie, $r! Jesteś na to za $gsłaby:słaba;!', '', 0),
(25150, 'plPL', 'No to leeeeeeeeeeeecę!', '', 0),
(25151, 'plPL', 'AUĆ!', '', 0),
(25152, 'plPL', 'Poddaję się! Tyle w temacie goblińskiej pomysłowości!', '', 0),
(25204, 'plPL', '', 'A teraz, $n, uwolnijmy ich dusze i posłuchajmy, co mają do powiedzenia.', 0),
(25211, 'plPL', '', 'To naprawdę złe wieści!', 0),
(25212, 'plPL', '', 'Niech mnie diabli, jeśli ta przeklęta Plaga nas stąd przepędzi! My, osadnicy, porzuciliśmy wszystko, żeby zacząć nowe życie w Północnej Grani.$B$BMożesz być $gpewien:pewna;, że będziemy walczyć zębami i pazurami.', 0),
(25215, 'plPL', 'Za tobą rozlega się jakiś hałas!', '', 0),
(25216, 'plPL', 'Witaj, $n. Jestem Durkot Wilczy Brat, obrońca watahy.', '', 0),
(25218, 'plPL', 'Połóż dłoń na kamieniu.', 'Połóż dłoń na kamieniu.', 0),
(25219, 'plPL', 'Plaga jest wszędzie! To jest... koszmar!', '', 0),
(25230, 'plPL', 'Arthas myśli, że kilka jego nieumarłych robali przegoni nas z powrotem do Wschodnich Królestw... Grubo się myli.', '', 0),
(25231, 'plPL', 'W tej krainie działają mroczne siły, $n. Miej oczy otwarte i nie trać odwagi.', '', 0),
(25235, 'plPL', 'Niektórzy z nas mogą uniknąć służby wojskowej. Dobry rybak zawsze się przyda... nawet generałowie muszą jeść.', '', 0),
(25237, 'plPL', 'Co wiesz o Kulcie Potępionych?', 'Co wiesz o Kulcie Potępionych?', 0),
(25239, 'plPL', 'Mam powody sądzić, że bierzesz udział w działalności kultystów.', 'Mam powody sądzić, że bierzesz udział w działalności kultystów.', 0),
(25240, 'plPL', 'Kolejny dzień w kuchni. Z czasem robi się nudno.', '', 0),
(25241, 'plPL', 'Moja zmiana prawie się skończyła. Nie mogę się doczekać, aż się zdrzemnę, rozumiesz?', '', 0),
(25242, 'plPL', 'Od jak dawna pracujesz dla Kultu Potępionych?', 'Od jak dawna pracujesz dla Kultu Potępionych?', 0),
(25243, 'plPL', 'No cóż...', '', 0),
(25244, 'plPL', 'To chyba koniec, co? Nie dam się tak łatwo!', '', 0),
(25245, 'plPL', 'Nareszcie! Koniec tej maskarady... Arthasie, daj mi siłę!', '', 0),
(25246, 'plPL', 'Nie wiesz, z kim zadzierasz, $N! Śmierć wzywa!', '', 0),
(25264, 'plPL', '', 'Arthas był kiedyś ludzkim księciem. Armię, którą poprowadził do Północnej Grani, spotkał straszny los.$B$BMój brat, Thassarian, był częścią tej armii.', 0),
(25265, 'plPL', 'Jestem $ggotowy:gotowa; do drogi, Durkocie.', 'Jestem $ggotowy:gotowa; do drogi, Durkocie.', 0),
(25267, 'plPL', '$G Panie:Pani;, oddam życie za Hordę!', '$G Panie:Pani;, oddam życie za Hordę!', 0),
(25268, 'plPL', 'Witaj z powrotem, czempionie.', 'Witaj z powrotem, czempionie.', 0),
(25269, 'plPL', 'To zaszczyt służyć u twego boku, $g panie:pani;.', 'To zaszczyt służyć u twego boku, $g panie:pani;.', 0),
(25270, 'plPL', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 0),
(25271, 'plPL', 'Throm-Ka, $gbohaterze:bohaterko;!', 'Throm-Ka, $gbohaterze:bohaterko;!', 0),
(25272, 'plPL', 'Z twoją siłą i determinacją nie możemy przegrać!', 'Z twoją siłą i determinacją nie możemy przegrać!', 0),
(25273, 'plPL', 'Oto idzie $gbohater:bohaterka;!', 'Oto idzie $gbohater:bohaterka;!', 0),
(25274, 'plPL', 'To $n! Pochylcie głowy!', 'To $n! Pochylcie głowy!', 0),
(25275, 'plPL', '%s wiwatuje na twoją cześć.', '%s wiwatuje na twoją cześć.', 0),
(25276, 'plPL', 'Jesteśmy górnikami, rolnikami i rzemieślnikami – nie żołnierzami. Ale jeśli trzeba, będziemy bronić naszej ziemi gołymi pięściami.', '', 0),
(25308, 'plPL', 'Podać ci coś? Wybór mam trochę ograniczony, ale tego należało się spodziewać... biorąc wszystko pod uwagę.', '', 0),
(25310, 'plPL', 'Śmierć za ojczyznę to obowiązek żołnierza. Ale jeśli nazywanie tej wojny szaleństwem to zdrada, to jestem zdrajcą.', '', 0),
(25316, 'plPL', '', 'Jestem teraz bardzo zajęta, $r. Proszę, zostaw mnie w spokoju.', 0),
(25321, 'plPL', 'Mów, liszu! Nieżycie nie uchroni cię przed tym, co ci zgotuję!', '', 0),
(25323, 'plPL', 'Śpij teraz, maleńki...', '', 0),
(25324, 'plPL', 'Wspaniały okaz.', '', 0),
(25325, 'plPL', 'Spokojnie, smoczku.', '', 0),
(25326, 'plPL', 'Tak, ten powinien ładnie posunąć moje badania naprzód...', '', 0),
(25345, 'plPL', 'Pan... chce... ja zabić marny kapłan? Zrobić bolesne, tak?', '', 0),
(25346, 'plPL', 'Tak, słabeuszu... błagaj Lurida o życie!', '', 0),
(25347, 'plPL', 'Czcisz śmierć, człowieczku? Śmierć tu jest!', '', 0),
(25348, 'plPL', 'Arthasie, ocal nas – jesteśmy zgubieni!', 'Arthasie, ocal nas – jesteśmy zgubieni!', 0),
(25349, 'plPL', 'Ten rycerz śmierci... on oszalał!', 'Ten rycerz śmierci... on oszalał!', 0),
(25350, 'plPL', 'Zigurat stracony! Uciekajcie do świątyni!', 'Zigurat stracony! Uciekajcie do świątyni!', 0),
(25352, 'plPL', 'Skup umysł, śmiertelniku. To pierwsza linia wojny, jakiej jeszcze nie $gwidziałeś:widziałaś;.$b$bJeśli masz się na coś przydać, musisz w pełni panować nad swoimi zmysłami.', '', 0),
(25353, 'plPL', 'Proszę... wszystkie rozkazy przychodzą z Naxxanaru... ja i moi ludzie nic nie wiemy!', '', 0),
(25354, 'plPL', 'Błagam cię, rycerzu śmierci! Trzymaj ode mnie swojego sługę! Zrobię wszystko!', '', 0),
(25355, 'plPL', 'Litości! Kiedyś $gbyłeś jednym:byłaś jedną; z nas! Nie pamiętasz?', '', 0),
(25357, 'plPL', 'Mój panie, przenikanie naszych kultystów do struktur władzy Przymierza i przejmowanie nad nimi kontroli idzie pełną parą.', '', 0),
(25358, 'plPL', 'Moc, którą mnie obdarzyłeś, dała mi wielki wpływ na ludzkie umysły. Przynoszę te dary jako dowód moich postępów.', '', 0),
(25359, 'plPL', 'Leryssa!', '', 0),
(25360, 'plPL', 'Coś ty zrobił mojej siostrze, ty elfi śmieciu bez matki?!', '', 0),
(25361, 'plPL', 'Pozwól mi zająć się intruzami, panie. Nakarmię czerwie ich wnętrznościami.', '', 0),
(25365, 'plPL', 'Tak, mój panie!', '', 0),
(25366, 'plPL', 'Prędzej poderżnę sobie gardło. Zapłacisz za to, co zrobiłeś własnym ludziom, Arthasie... za to, co zrobiłeś mnie! Przysięgam.', '', 0),
(25369, 'plPL', 'Chyba $gzgubiłem:zgubiłam; Wzmocnione tajemne więzienie. Czy nie $gzostawiłem:zostawiłam; go tutaj u ciebie?', 'Chyba $gzgubiłem:zgubiłam; Wzmocnione tajemne więzienie. Czy nie $gzostawiłem:zostawiłam; go tutaj u ciebie?', 0),
(25371, 'plPL', 'Co jest przyczyną tego konfliktu?', 'Co jest przyczyną tego konfliktu?', 0),
(25378, 'plPL', 'Kraina przeżywa wielki wstrząs!$B$BMroczny znów wyrusza ze swoimi San\'layn, smoki walczą w swojej wielkiej wojnie o Nexus, a wrykule przebudzili się na nowo.$B$BWasze ludy płyną na północ drewnianymi statkami, by walczyć z nimi i ze sobą nawzajem, a my, Kalu\'ak, jesteśmy pośrodku.$B$BA teraz dokonano jakiegoś wielkiego zła, przez które ziemia wybucha magiczną mocą świata. Musimy znaleźć bezpieczne schronienie, w którym będziemy mieć szansę przetrwać.$B$BOd tych dwóch ambasadorów boli mnie głowa... może ty pomożesz mojemu ludowi, $r?', '', 0),
(25384, 'plPL', 'Jestem $ggotowy:gotowa; zmierzyć się z Saragosą!', 'Jestem $ggotowy:gotowa; zmierzyć się z Saragosą!', 0),
(25394, 'plPL', '', 'Naprawdę miło cię znowu widzieć, $n.', 0),
(25397, 'plPL', 'Kvaldirowie nie znają litości, $n. Ale nie mogę porzucić świętej Kaskali. Jeśli my nie porzucimy duchów, duchy też nas nie porzucą.', '', 0),
(25398, 'plPL', 'Kaskala jest atakowana! Musimy ich powstrzymać, dopóki nie zdołamy uciec.', '', 0),
(25400, 'plPL', 'Przeklęci olbrzymi ludzie! Jeśli chcą walki, to będą ją mieli!', '', 0),
(25416, 'plPL', 'Wózek z rudą skrzypi o szyny, gdy zostaje zwolniony.', '', 0),
(25421, 'plPL', 'Wygląda na to, że ten młody kiełzar zginął w walce, a nie utonął.', '', 0),
(25422, 'plPL', '<Przeszukaj zwłoki w poszukiwaniu Totemu Issliruka.>', '<Przeszukaj zwłoki w poszukiwaniu Totemu Issliruka.>', 0),
(25441, 'plPL', 'Keristraszo, $gskończyłem:skończyłam; tutaj. Proszę, zabierz mnie z powrotem do Tarczy Transitus.', 'Keristraszo, $gskończyłem:skończyłam; tutaj. Proszę, zabierz mnie z powrotem do Tarczy Transitus.', 0),
(25446, 'plPL', '', '$n! Zastanawiałam się, co u ciebie. Co cię zatrzymało?', 0),
(25447, 'plPL', '', 'Mam nadzieję, że zachowujesz wszelkie środki ostrożności...$b$bTo niebezpieczne miejsce i nie wybaczyłabym sobie, gdyby coś ci się stało.', 0),
(25448, 'plPL', '', 'Musimy się spieszyć, $n. Zgubnych planów Malygosa wkrótce nie da się już odwrócić.', 0),
(25449, 'plPL', '', 'W takich czasach drodzy przyjaciele są bezcenni.$b$bUważaj na siebie, $n. Na ile to możliwe w takim miejscu...', 0),
(25450, 'plPL', '', 'Gdyby nie to, że $gwyrwałeś:wyrwałaś; mnie z tego więzienia, na pewno już bym uległa.$b$bNie zapomniałam o tym...', 0),
(25452, 'plPL', '', 'Gdy nasze zadanie tutaj dobiegnie końca, znajdę sposób, by odwdzięczyć ci się za ratunek.', 0),
(25453, 'plPL', '', 'Siły powoli mi wracają...$b$bMam nadzieję, że wkrótce będę mogła pokazać ci chwałę mojej prawdziwej postaci.', 0),
(25457, 'plPL', '', 'Och...$b$bGdzie ja jestem?', 0),
(25458, 'plPL', 'Jednym słowem: magia.$b$bNieodpowiedzialni śmiertelnicy, żyjący tak krótko, nie myślą o trwałych skutkach swoich czynów.$b$bZ energii tajemnych czerpano zbyt swobodnie, co zaburzyło równowagę świata. Jeśli to się nie skończy, Azeroth wkrótce ulegnie zagładzie.$b$bCo do tego zgadzają się obie strony. Ale zanim zdążono choćby powołać radę, Malygos wcielił w życie własny plan.$b$bNie mieliśmy wyboru, musieliśmy mu się przeciwstawić.', '', 0),
(25459, 'plPL', 'Kim jest Malygos?', 'Kim jest Malygos?', 0),
(25460, 'plPL', 'Robimy postępy, $r, ale o wiele za wolno.', '', 0),
(25461, 'plPL', 'Musimy odnieść sukces! Waży się los Azeroth...', '', 0),
(25462, 'plPL', 'Malygos Tkacz Zaklęć, Władca Magii, Pan Błękitnego Stada. To aspekt błękitnych smoków, jedna z najstarszych istot w Azeroth.$b$bPodobno dochodzi do siebie po szaleństwie, które trwało tysiąclecia, ale jego ostatnie czyny każą mi sądzić, że wciąż daleko mu do zdrowych zmysłów.$b$bJego rozwiązaniem naszego dylematu jest odnalezienie i zniszczenie każdego śmiertelnika w Azeroth, który włada magią.$b$bJako strażników życia zmusiło to Czerwone Stado do działania.$b$bSmok walczy teraz ze smokiem, a los naszego kruchego świata wisi na włosku.', '', 0),
(25463, 'plPL', '', 'Raeloraszu, dobrze cię znowu widzieć.', 0),
(25464, 'plPL', 'Keristraszo! Szkoda, że okoliczności nie pozwalają na godniejsze powitanie. Los okazał się łaskawy, zwracając cię nam.', '', 0),
(25466, 'plPL', '', 'Los, jak się zdaje, był więcej niż łaskawy. Malygos otrzymał cios. Gdy się o nim dowie, jestem pewna, że opuści bezpieczny Nexus.', 0),
(25467, 'plPL', 'Malygos – na otwartej przestrzeni? Nie śmiałem nawet marzyć o takiej okazji. Natychmiast zbiorę naszych braci!', '', 0),
(25468, 'plPL', 'Oczywiście, pani. Do następnego spotkania...', '', 0),
(25469, 'plPL', '', 'Przygotuj ich dobrze, Raeloraszu. Moc Malygosa nie przypomina niczego, co widzieli. Tym manewrem zapewne tylko opóźnimy jego plany.', 0),
(25472, 'plPL', '', 'Żegnaj, Raeloraszu.', 0),
(25474, 'plPL', '', 'Trzymaj się blisko mnie, $n. Nie zniosłabym, gdyby stała ci się krzywda.', 0),
(25475, 'plPL', '', 'MALYGOSIE!!', 0),
(25477, 'plPL', '', 'Przybądź, Władco Magii, i odzyskaj swoją drogocenną małżonkę...', 0),
(25478, 'plPL', '', '...a raczej to, co z niej zostało!', 0),
(25479, 'plPL', '', 'Chodź, $n. Zobaczmy owoce naszych starań.', 0),
(25480, 'plPL', 'Saragoso! Co się z tobą stało?', '', 0),
(25489, 'plPL', '', 'Nigdy!', 0),
(25491, 'plPL', '', 'Szybko, $n! Uciekaj! Przeżyj, by dokończyć to, co tu zaczęliśmy...', 0),
(25685, 'plPL', '', 'Smagacze nigdy nie odzyskają dawnej świetności, ale ta łodziowa hołota zapłaci za swoje czyny – przysięgam!', 0),
(25746, 'plPL', 'Wielki żółw morski Wędrowiec Fal płynie z tej przystani do Portu Moa\'ki na Smoczych Pustkowiach.', '', 0),
(25761, 'plPL', 'Cześć! Tęsknisz za Wschodnimi Królestwami, co? Jeśli naprawdę chcesz wracać, „Kraken” pływa z powrotem do Wichrogrodu. Ja bym się ucieszył z cieplejszej pogody!', '', 0),
(25773, 'plPL', 'Wracasz do domu, $N? Jeśli twój dom jest w Kalimdorze, zabierze cię tam „Potężny Wicher”. Leci stąd prosto do Durotaru.', '', 0),
(25786, 'plPL', '', 'Nigdy!', 0),
(25814, 'plPL', 'Daj mi zgodę na teleporter, jestem $ggotowy:gotowa;!', 'Daj mi zgodę na teleporter, jestem $ggotowy:gotowa;!', 0),
(25832, 'plPL', 'Wszyscy do ratusza! Przywieźliśmy wam broń! Uzbrójcie się i odeprzyjcie Plagę!', '', 0),
(25833, 'plPL', 'Czas zabijać!', '', 0),
(25834, 'plPL', 'Najwyższy czas! Lurid już się nudzić.', '', 0),
(25835, 'plPL', 'Ty piesek Arthasa? Ty umrzeć!', '', 0),
(25836, 'plPL', 'To się nie... skończyć dobrze dla ciebie!', '', 0),
(25837, 'plPL', 'Lurid mógłby się przyzwyczaić... do pracy z tobą.', '', 0),
(25838, 'plPL', 'Pragnąłem tylko znów służyć mojemu królowi. Dla ludzkości, przeciwko wspólnemu wrogowi.$B$BZamiast tego odkrywam, że w nasze szeregi wkradła się kultystowska hołota... a wszystko wskazuje na to, że źródłem tej zgnilizny jest Naxxanar.', '', 0),
(25839, 'plPL', 'To stąd kultyści dostają rozkazy. Ich przywódca na pewno wkrótce się zjawi.$B$BNie przegapmy tej okazji.', '', 0),
(25840, 'plPL', 'Zróbmy to, Thassarianie. Teraz albo nigdy.', 'Zróbmy to, Thassarianie. Teraz albo nigdy.', 0),
(25841, 'plPL', 'Co... co się ze mną stało?', '', 0),
(25842, 'plPL', '', 'Thassarianie! Żyjesz!', 0),
(25843, 'plPL', '', 'Myślałam... myślałam, że nie... żyjesz.', 0),
(25844, 'plPL', 'Leryssa... ty... nic ci nie jest!', '', 0),
(25845, 'plPL', 'Nie mogę jeszcze wrócić z tobą do domu, Leryssa. Nie skończyłem jeszcze z Plagą.', '', 0),
(25846, 'plPL', 'Może masz rację, siostro. Spełniłem już obowiązki wobec mojej ziemi i króla. Ale jest coś, co wciąż jestem winien samemu sobie.', '', 0),
(25847, 'plPL', 'Uch! Głowa mi się ciągle kręci...', '', 0),
(25848, 'plPL', '', 'Nie zostawiaj mnie znowu! Chcesz walczyć za swój kraj, a oni nawet cię nie chcą! Wysłali cię tu na śmierć!', 0),
(25849, 'plPL', '', 'Znam to spojrzenie... Nie zdołam ci tego wyperswadować. Jeśli znowu mi zginiesz...', 0),
(25850, 'plPL', 'Nie martw się, Leryssa. Kiedy skończę, wrócę do ciebie. Nic na świecie nie powstrzyma mnie przed powrotem do domu, do jedynej rodziny, jaka mi została.', '', 0),
(25900, 'plPL', 'Witaj! Jeśli potrzebujesz miejsca na odpoczynek, mogę temu zaradzić.', 'Witaj! Jeśli potrzebujesz miejsca na odpoczynek, mogę temu zaradzić.', 0),
(25966, 'plPL', 'Cześć! Piloci Fizzcranka to najlepsi z najlepszych. I tacy pozostajemy dzięki ciągłemu szkoleniu. Również spadochronowemu. Nigdy nie wiadomo, kiedy trzeba będzie użyć spadochronu, ale wiadomo, że pewnego dnia trzeba będzie.$b$bMamy tu więc teleporter na szczyt tej iglicy. Kiedy już się tam znajdziesz, prawdziwy żołnierz ma tylko jeden sposób na zejście – ze spadochronem. Na górze stacjonuje drugi żołnierz, który czeka ze spadochronami.$b$bJeśli masz ochotę spróbować, $N, dam ci zgodę na użycie teleportera. Potem po prostu wejdź na teleporter.', 'Cześć! Piloci Fizzcranka to najlepsi z najlepszych. I tacy pozostajemy dzięki ciągłemu szkoleniu. Również spadochronowemu. Nigdy nie wiadomo, kiedy trzeba będzie użyć spadochronu, ale wiadomo, że pewnego dnia trzeba będzie.$b$bMamy tu więc teleporter na szczyt tej iglicy. Kiedy już się tam znajdziesz, prawdziwy żołnierz ma tylko jeden sposób na zejście – ze spadochronem. Na górze stacjonuje drugi żołnierz, który czeka ze spadochronami.$b$bJeśli masz ochotę spróbować, $N, dam ci zgodę na użycie teleportera. Potem po prostu wejdź na teleporter.', 0),
(26155, 'plPL', 'Czemu mi przeszkadzasz?', '', 0),
(26156, 'plPL', 'Chcę się dostać do Tarczy Transitus.', 'Chcę się dostać do Tarczy Transitus.', 0),
(26163, 'plPL', 'Tylko opóźniacie nieuniknione! Na wschodzie wznosi się straszliwa cytadela, a armie umarłych maszerują z serca Lodowej Korony!', '', 0),
(26164, 'plPL', 'Siemasz. Jak czegoś potrzebujesz, to daj znać.', '', 0),
(26165, 'plPL', 'Plugastwa Plagi... Wkrótce dostaną to, na co zasłużyły.', '', 0),
(26171, 'plPL', '%s uzupełnia paliwo.', '', 0),
(26173, 'plPL', 'Obronię cię, przyjacielu!', 'Obronię cię, przyjacielu!', 0),
(26174, 'plPL', 'Dziękuję, przyjacielu. Teraz te bestie poczują gniew Słonecznej Studni!', 'Dziękuję, przyjacielu. Teraz te bestie poczują gniew Słonecznej Studni!', 0),
(26176, 'plPL', '', 'Chronić? Po co? Nie ma w tym prawdy. Nie, nie, nie... jest tylko w braniu! Teraz to widzę!', 0),
(26184, 'plPL', 'Wejdź, ogrzej się przy ogniu i odpocznij, $r. Mam nadzieję, że nie przeszkadza ci zapach ryb.', 'Wejdź, ogrzej się przy ogniu i odpocznij, $r. Mam nadzieję, że nie przeszkadza ci zapach ryb.', 0),
(26192, 'plPL', 'Witaj! Czegoś potrzebujesz?', '', 0),
(26274, 'plPL', 'Hę?', '', 0),
(26276, 'plPL', '<Kiełzar przygląda ci się podejrzliwie.>$b$bNie zostawaj długo. Nie rozumiesz naszego ludu, a ja nie chcę kłopotów.', '<Kiełzar przygląda ci się podejrzliwie.>$b$bNie zostawaj długo. Nie rozumiesz naszego ludu, a ja nie chcę kłopotów.', 0),
(26284, 'plPL', 'Kolejna bestia uratowana od pewnej śmierci!', 'Kolejna bestia uratowana od pewnej śmierci!', 0),
(26285, 'plPL', 'Plaga nie ma ze mną szans, Torp!', 'Plaga nie ma ze mną szans, Torp!', 0),
(26286, 'plPL', 'Dostarczone zgodnie z obietnicą, Torp!', 'Dostarczone zgodnie z obietnicą, Torp!', 0),
(26296, 'plPL', 'Powiedz, jeśli boli.', 'Powiedz, jeśli boli.', 0),
(26297, 'plPL', 'Chyba tym razem mi się udało...', 'Chyba tym razem mi się udało...', 0),
(26298, 'plPL', 'Wypróbujmy to...', 'Wypróbujmy to...', 0),
(26299, 'plPL', 'Jak to było?', 'Jak to było?', 0),
(26300, 'plPL', 'Myślisz, że to da nam jakieś odpowiedzi?', 'Myślisz, że to da nam jakieś odpowiedzi?', 0),
(26302, 'plPL', 'Czy to było dość mocne?', 'Czy to było dość mocne?', 0),
(26305, 'plPL', 'Potrzebujesz więcej zadziorności. Nie okazuj wrogom litości.', 'Potrzebujesz więcej zadziorności. Nie okazuj wrogom litości.', 0),
(26306, 'plPL', 'Im więcej bólu zadamy, tym szybciej poznamy odpowiedzi.', 'Im więcej bólu zadamy, tym szybciej poznamy odpowiedzi.', 0),
(26317, 'plPL', '', 'Rozpaczliwe czasy wymagają rozpaczliwych środków, $N.', 0),
(26318, 'plPL', 'Masz jakieś przedmioty, które mogę przetestować?', 'Masz jakieś przedmioty, które mogę przetestować?', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(26319, 'plPL', 'To prawda, ale jak daleko możemy się posunąć? W którym momencie przestajemy być lepsi od naszych wrogów?', 'To prawda, ale jak daleko możemy się posunąć? W którym momencie przestajemy być lepsi od naszych wrogów?', 0),
(26320, 'plPL', 'To prawda, nasi wrogowie nie okazaliby nam litości.', 'To prawda, nasi wrogowie nie okazaliby nam litości.', 0),
(26333, 'plPL', '', 'Brakuje nam jedzenia i picia. Obawiam się, że nie mam ci nic do zaoferowania.', 0),
(26334, 'plPL', '', 'Dziękuję za pomoc, $n. Te mroźne jagody to dosłownie owoce twojej pracy.', 0),
(26428, 'plPL', 'Hej, Celidh! Masz jakieś zwierzęta, które mam zaprowadzić do stajni?', '', 0),
(26432, 'plPL', 'Chodź, koniku.', '', 0),
(26460, 'plPL', '', 'Witaj, $N.$B$BW czym mogę pomóc?', 0),
(26463, 'plPL', 'Tak? O co chodzi?', '', 0),
(26478, 'plPL', 'Gdybym był królem, miałbym takiego konia jak ty. Pilnowałbym, żebyś się nie zgubił, a ty na pewno pilnowałbyś, żebym ja nigdy się nie zgubił.', '', 0),
(26479, 'plPL', 'Bylibyśmy najlepszymi przyjaciółmi. Założę się, że ja i Anduin też bylibyśmy najlepszymi przyjaciółmi. Przyjaciele są ważni.', '', 0),
(26486, 'plPL', 'Zaprowadzę cię do innych koni. Pewnie tęsknisz za innymi końmi. Oni też mogą być twoimi przyjaciółmi.', '', 0),
(26487, 'plPL', 'Dobrze to wyglądało?', 'Dobrze to wyglądało?', 0),
(26488, 'plPL', 'To trudniejsze, niż się wydaje.', 'To trudniejsze, niż się wydaje.', 0),
(26489, 'plPL', 'To nie jest łatwe.', 'To nie jest łatwe.', 0),
(26490, 'plPL', 'Chyba zaczynam łapać, o co w tym chodzi.', 'Chyba zaczynam łapać, o co w tym chodzi.', 0),
(26491, 'plPL', 'Ręka zaczyna mnie boleć.', 'Ręka zaczyna mnie boleć.', 0),
(26492, 'plPL', 'Hmm...', 'Hmm...', 0),
(26493, 'plPL', 'Po prostu się denerwuję. Przepraszam.', 'Po prostu się denerwuję. Przepraszam.', 0),
(26494, 'plPL', 'Po prostu nie chcę nikogo zawieść.', 'Po prostu nie chcę nikogo zawieść.', 0),
(26495, 'plPL', 'Muszę czymś zająć ręce.', 'Muszę czymś zająć ręce.', 0),
(26497, 'plPL', 'Nie dasz mi spać, co?', 'Nie dasz mi spać, co?', 0),
(26500, 'plPL', '$GMógłbyś:Mogłabyś; być trochę ciszej?', '$GMógłbyś:Mogłabyś; być trochę ciszej?', 0),
(26502, 'plPL', 'Długo jeszcze będziesz to robić?', 'Długo jeszcze będziesz to robić?', 0),
(26522, 'plPL', '', 'Wszyscy ci ludzie nie dają mi chwili wytchnienia. Zaprowadź tego konia do stajni.', 0),
(26590, 'plPL', 'Co? Nie widzisz, że jestem zajęty?$B$BMyślisz, że ta transmateria sama się naprawi?!', '', 0),
(26618, 'plPL', '', 'Oblężenie nerubian na zewnątrz mrozi krew w żyłach, Sagai. Końca nie widać.', 0),
(26619, 'plPL', 'No. To przez te zapadliska. Widzisz je? Gada się, żeby je wysadzić, zawalić.', '', 0),
(26620, 'plPL', '', 'Właśnie... Wczoraj przyniosłam z kamieniołomu amunicję w tym celu.', 0),
(26621, 'plPL', '', 'Oby ładunki szybko założono. Wszystkim przydałoby się wytchnienie.', 0),
(26622, 'plPL', 'Święta prawda.', '', 0),
(26623, 'plPL', '', 'Zaurzykieł tu jest, Sagai! Zaurzykieł! Brat samego Broxigara przybył wesprzeć nasze wysiłki!', 0),
(26635, 'plPL', '', 'Mów ciszej. Nie chcemy zwrócić uwagi tych bestyjek!', 0),
(26688, 'plPL', 'No. Piekłorycz to zawzięty gość, ale moim zdaniem za bardzo chce się wykazać. Dobrze, że Zaurzykieł tu jest, na pewno.', '', 0),
(26937, 'plPL', 'Dziękuję za uwolnienie nas, śmiertelnicy. Strzeżcie się, błękitne stado wie o waszej obecności. Nawet teraz Malygos wysyła Varosa Obłokokroczącego i strażników pierścieni, by bronili Okulusa. Bez naszej pomocy nie macie szans.', '', 0),
(27243, 'plPL', '', 'Jak pokonamy mgłę?', 0),
(27245, 'plPL', '', 'Co to było?! $gWidziałeś:Widziałaś; to?', 0),
(27346, 'plPL', 'Teleportuj mnie na Bursztynowy Występ, proszę.', 'Teleportuj mnie na Bursztynowy Występ, proszę.', 0),
(27349, 'plPL', 'Czy mogę polecieć smokiem gdzie indziej?', 'Czy mogę polecieć smokiem gdzie indziej?', 0),
(27350, 'plPL', 'Jak mogę ci pomóc, dziecko?', 'Jak mogę ci pomóc, dziecko?', 0),
(27389, 'plPL', 'Największe wyzwanie dopiero przed wami. Strażnik Linii Mocy Eregos to błękitny smok o ogromnej mocy. Znajdziecie go lecącego nad najwyższym pierścieniem.', '', 0),
(27776, 'plPL', '%s chrząka.', '', 0),
(27818, 'plPL', '', 'Jeśli musisz się gdzieś dostać, mogę cię tam zabrać.', 0),
(27819, 'plPL', 'Myślisz, że $gmógłbym:mogłabym; się przelecieć jedną z tych latających maszyn?', 'Myślisz, że $gmógłbym:mogłabym; się przelecieć jedną z tych latających maszyn?', 0),
(27820, 'plPL', 'Karo, muszę polecieć do Nor Umierających, żeby odnaleźć Bixie.', 'Karo, muszę polecieć do Nor Umierających, żeby odnaleźć Bixie.', 0),
(27827, 'plPL', 'Bg\'grrml brgl brm!', '', 0),
(27828, 'plPL', 'Wypuść mnie stąd, $r!', '', 0),
(27829, 'plPL', 'Na razie, frajerzy. Spadam stąd!', '', 0),
(27839, 'plPL', 'Nadlatuje $r! Zestrzelić $g go : ją;!', '', 0),
(28079, 'plPL', 'Trzeciego pierścienia strzeże podstępny Władca Magów Urom. Pojawi się sam i bezbronny, ale nie dajcie się zwieść pozorom! Urom to potężny zaklinacz, który rozkazuje menażerii fantasmagorycznych stworzeń. Szukajcie go wyżej.', '', 0),
(29209, 'plPL', 'Co mogę dla ciebie zrobić, $r?', '', 0),
(29212, 'plPL', 'Potrzebuję oddychania pod wodą, Garrenie.', 'Potrzebuję oddychania pod wodą, Garrenie.', 0),
(29490, 'plPL', '', 'Nie sądzę, byś $gmiał:miała; dość bystrości umysłu, by pojąć naturę magii portali.$B$BMożesz jednak użyć kryształu za mną, by teleportować się do ruin pod Dalaranem w Lesie Kryształowej Pieśni.', 0),
(29491, 'plPL', '', 'Jako mag należysz do wąskiego grona tych, którzy potrafią wyczarować portal, by przenieść się z powrotem dokładnie w to miejsce. Mogę cię tego nauczyć, jeśli jesteś $ggotowy:gotowa;.$B$BI pamiętaj, że zawsze możesz użyć kryształu za mną, by teleportować się do ruin pod Dalaranem w Lesie Kryształowej Pieśni.', 0),
(29494, 'plPL', 'Jestem $ggotowy:gotowa; do teleportacji do Dalaranu.', 'Jestem $ggotowy:gotowa; do teleportacji do Dalaranu.', 0),
(29537, 'plPL', 'Trzeciego pierścienia strzeże podstępny Władca Magów Urom. Pojawi się sam i bezbronny, ale nie dajcie się zwieść pozorom! Urom to potężny zaklinacz, który rozkazuje menażerii fantasmagorycznych stworzeń. Szukajcie go wyżej.', 'Trzeciego pierścienia strzeże podstępny Władca Magów Urom. Pojawi się sam i bezbronny, ale nie dajcie się zwieść pozorom! Urom to potężny zaklinacz, który rozkazuje menażerii fantasmagorycznych stworzeń. Szukajcie go wyżej.', 0),
(29538, 'plPL', 'Największe wyzwanie dopiero przed wami. Strażnik Linii Mocy Eregos to błękitny smok o ogromnej mocy. Znajdziecie go lecącego nad najwyższym pierścieniem.', 'Największe wyzwanie dopiero przed wami. Strażnik Linii Mocy Eregos to błękitny smok o ogromnej mocy. Znajdziecie go lecącego nad najwyższym pierścieniem.', 0),
(29618, 'plPL', '', 'Zostań. Ciesz się ostatnimi chwilami.', 0),
(29619, 'plPL', '', 'Skończ to! Skończ to! Zabij mnie albo przysięgam na Smoczą Królową, że już nigdy nie ujrzysz światła dnia!', 0),
(29620, 'plPL', '', 'Teraz dotarliśmy do prawdy!', 0),
(29621, 'plPL', '', 'Smocza Królowo... Życiodajna... chroń... mnie.', 0),
(29685, 'plPL', '', 'Nigdy nie zapomnę, co $gzrobiłeś:zrobiłaś; dla Thassariana. Zawsze będę twoją dłużniczką.', 0),
(30954, 'plPL', 'Jak leci, mon?', '', 0),
(31252, 'plPL', 'Gdzie jest Nestor Arp?', 'Gdzie jest Nestor Arp?', 0),
(31253, 'plPL', 'Nestor Arp przebywa w obozie D.E.H.T.A. w Boreańskiej Tundrze.', 'Nestor Arp przebywa w obozie D.E.H.T.A. w Boreańskiej Tundrze.', 0),
(31254, 'plPL', 'Nestor Pamuya przebywa tuż pod Warownią Wojennej Pieśni.', 'Nestor Pamuya przebywa tuż pod Warownią Wojennej Pieśni.', 0),
(31255, 'plPL', 'Gdzie jest Nestor Pamuya?', 'Gdzie jest Nestor Pamuya?', 0),
(31266, 'plPL', 'Gdzie jest Nestor Igasho?', 'Gdzie jest Nestor Igasho?', 0),
(31267, 'plPL', 'Nestora Igasho widziano ostatnio, jak przemierza Nexus.', 'Nestora Igasho widziano ostatnio, jak przemierza Nexus.', 0),
(31268, 'plPL', 'Gdzie jest Nestor Northal?', 'Gdzie jest Nestor Northal?', 0),
(31269, 'plPL', 'Nestora Northala znajdziesz wewnątrz Tarczy Transitus w Mrozarze.', 'Nestora Northala znajdziesz wewnątrz Tarczy Transitus w Mrozarze.', 0),
(31270, 'plPL', 'Gdzie jest Nestor Sardis?', 'Gdzie jest Nestor Sardis?', 0),
(31271, 'plPL', 'Według ostatnich wieści Nestor Sardis jest w drodze do Twierdzy Walecznych.', 'Według ostatnich wieści Nestor Sardis jest w drodze do Twierdzy Walecznych.', 0),
(31272, 'plPL', 'Gdzie jest Nestor Niebieski Wilk?', 'Gdzie jest Nestor Niebieski Wilk?', 0),
(31273, 'plPL', 'Nestor Niebieski Wilk tkwi w potrzasku pośród bitwy o Zimościsk.', 'Nestor Niebieski Wilk tkwi w potrzasku pośród bitwy o Zimościsk.', 0),
(31358, 'plPL', 'Kolejny głodny rekrut?', '', 0),
(31360, 'plPL', 'Co cię do mnie sprowadza?', '', 0),
(31493, 'plPL', 'Podglądając wiele błahych spraw w Lodowej Koronie, trafiasz na coś interesującego...', 'Podglądając wiele błahych spraw w Lodowej Koronie, trafiasz na coś interesującego...', 0),
(31650, 'plPL', 'Wszystkich nas nie powstrzymacie!', 'Wszystkich nas nie powstrzymacie!', 0),
(31841, 'plPL', 'Prostacy! Nie pojmujecie sił, które wprawiliście w ruch. Kanał linii mocy nie zostanie przerwany! Wasza klęska będzie całkowita!', '', 0),
(31873, 'plPL', 'Zuchwali intruzi, nie jesteście w swoim żywiole! Sprowadzę was na ziemię!', '', 0),
(31874, 'plPL', 'Taka zuchwałość... taka arogancja... musi zostać UKARANA!', '', 0),
(31875, 'plPL', 'Teraz nie pomoże wam żadna magia natury!', '', 0),
(31876, 'plPL', 'To my władamy tajemną mocą! Nie zostanie użyta przeciwko nam!', '', 0),
(31877, 'plPL', 'Zgaszenie waszego ognia to drobnostka!', '', 0),
(31878, 'plPL', 'Daleko do ziemi...', '', 0),
(31879, 'plPL', 'Wracaj na ziemię!', '', 0),
(31880, 'plPL', 'Miłego spadania!', '', 0),
(31881, 'plPL', 'Nacieszcie się tym drobnym zwycięstwem, głupie stworzonka. Wy i wasi smoczy sojusznicy wygraliście tę bitwę, ale to my wygramy... wojnę o Nexus.', '', 0),
(32322, 'plPL', '', 'W czym mogę ci pomóc?', 0),
(32807, 'plPL', 'Witamy!', 'Witamy!', 0),
(32936, 'plPL', 'Witamy.', 'Witamy.', 0),
(32986, 'plPL', '', 'Większość smoków bałaby się tu zapuścić, $r.$b$bCóż mogło sprowadzić śmiertelnika w tak zdradliwe miejsce?', 0),
(32987, 'plPL', '', 'Czy masz dość odwagi, by zmierzyć się z elitarnymi smokami Malygosa w ich własnej domenie, $r?', 0),
(32988, 'plPL', 'Ja... Chyba tak...', 'Ja... Chyba tak...', 0),
(32989, 'plPL', '', 'Moje smoki niecierpliwie czekały na twój powrót, $N.$b$bJesteś $ggotowy:gotowa; wzbić się w powietrze?', 0),
(32990, 'plPL', 'Jestem $ggotowy:gotowa;, pani Corastraszo.', 'Jestem $ggotowy:gotowa;, pani Corastraszo.', 0),
(34617, 'plPL', 'Chcesz zobaczyć, co umiem?', '', 0),
(34619, 'plPL', 'A teraz tańczymy razem!', '', 0),
(40198, 'plPL', 'Hę?', 'Hę?', 0),
(53514, 'plPL', 'Giń!', '', 0);
